# Stash Toolkit v5.1.300
# Filename: Stash-Toolkit-v5.1.300.ps1
# Toolkit for searching, auditing, reporting on and exploring a Stash library.
# Requires Windows PowerShell 5.1+; reopens itself in PowerShell 7 when installed.
# Settings (Stash location, URL, export folders) are remembered in
# %LOCALAPPDATA%\StashToolkit\settings.json.

# Prefer PowerShell 7. When started in Windows PowerShell 5.1 (for example with
# right-click > Run with PowerShell), reopen in PowerShell 7 if it is installed.
# Set the environment variable STASH_TOOLKIT_NO_PWSH=1 to stay in 5.1.
if($PSVersionTable.PSEdition -ne 'Core' -and -not $env:STASH_TOOLKIT_NO_PWSH -and $PSCommandPath){
 $pwshPath=''
 $pwshCommand=Get-Command pwsh.exe -ErrorAction SilentlyContinue | Select-Object -First 1
 if($pwshCommand){$pwshPath=[string]$pwshCommand.Source}
 if(-not $pwshPath){
  foreach($candidate in @((Join-Path $env:ProgramFiles 'PowerShell\7\pwsh.exe'),(Join-Path $env:ProgramFiles 'PowerShell\7-preview\pwsh.exe'))){
   if(Test-Path -LiteralPath $candidate -PathType Leaf){$pwshPath=$candidate;break}
  }
 }
 if($pwshPath){
  try{
   Write-Host "Opening Stash Toolkit in PowerShell 7..." -ForegroundColor Cyan
   Start-Process -FilePath $pwshPath -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',('"'+$PSCommandPath+'"')) -WorkingDirectory (Split-Path -Parent $PSCommandPath) -ErrorAction Stop
   exit
  }catch{
   Write-Host "PowerShell 7 could not be started, so the toolkit will open in Windows PowerShell." -ForegroundColor Yellow
  }
 }
}

Write-Host "Stash Toolkit is opening. Please wait for the window to appear..." -ForegroundColor Cyan

