using System;
using System.Drawing;
using System.Windows.Forms;
public class ToolkitDialogWindow : Form {
 public bool ShowOutline { get; set; }
 public ToolkitDialogWindow(){ShowOutline=true;DoubleBuffered=true;}
 protected override void OnLoad(EventArgs e) {
  bool canClose=ControlBox; FormBorderStyle=FormBorderStyle.None;
  base.OnLoad(e);
  if(canClose){var close=new Button{Text="×",Size=new Size(28,26),Anchor=AnchorStyles.Top|AnchorStyles.Right,Location=new Point(ClientSize.Width-32,4),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(31,92,125),ForeColor=Color.White};close.Click+=(s,a)=>Close();Controls.Add(close);close.BringToFront();}
 }
 private Panel[] edges;
 private void UpdateBorder(){
  if(edges==null)return;
  int w=ClientSize.Width,h=ClientSize.Height;
  edges[0].SetBounds(0,0,w,2);edges[1].SetBounds(0,Math.Max(0,h-2),w,2);
  edges[2].SetBounds(0,0,2,h);edges[3].SetBounds(Math.Max(0,w-2),0,2,h);
  foreach(var edge in edges)edge.BringToFront();
 }
 protected override void OnShown(EventArgs e){
  base.OnShown(e);
  if(!ShowOutline)return;
  if(edges==null){edges=new Panel[4];for(int i=0;i<4;i++){edges[i]=new Panel{BackColor=Color.FromArgb(142,203,230),TabStop=false};Controls.Add(edges[i]);}}
  UpdateBorder();
 }
 protected override void OnResize(EventArgs e){base.OnResize(e);UpdateBorder();}
}
public static class ToolkitPosterText {
 public static void Draw(Graphics graphics,string text,Font source,Brush brush,RectangleF bounds,StringFormat format){
  using(var fittedFormat=(StringFormat)format.Clone()){
   fittedFormat.Trimming=StringTrimming.None;
   float size=source.Size;
   Font fitted=new Font(source.FontFamily,size,source.Style);
   try{
    for(int attempt=0;attempt<100;attempt++){
     SizeF measured=graphics.MeasureString(text??"",fitted,new SizeF(bounds.Width,bounds.Height*1000),fittedFormat);
     if(measured.Width<=bounds.Width && measured.Height<=bounds.Height)break;
     float ratio=Math.Min(bounds.Width/Math.Max(1,measured.Width),bounds.Height/Math.Max(1,measured.Height));
     size=Math.Max(0.1f,size*Math.Min(0.95f,ratio*0.98f));
     fitted.Dispose();fitted=new Font(source.FontFamily,size,source.Style);
    }
    graphics.DrawString(text??"",fitted,brush,bounds,fittedFormat);
   }finally{fitted.Dispose();}
  }
 }
}
public static class ToolkitMessageDialog {
 public static DialogResult Show(params object[] args){
  int start=(args.Length>0 && args[0] is IWin32Window)?1:0;
  string text=args.Length>start?Convert.ToString(args[start]):"";
  string title=args.Length>start+1?Convert.ToString(args[start+1]):"Stash Toolkit";
  MessageBoxButtons buttons=MessageBoxButtons.OK;MessageBoxDefaultButton def=MessageBoxDefaultButton.Button1;
  if(args.Length>start+2)Enum.TryParse(Convert.ToString(args[start+2]),out buttons);
  if(args.Length>start+4)Enum.TryParse(Convert.ToString(args[start+4]),out def);
  using(var f=new ToolkitDialogWindow()){
   f.ControlBox=false;f.StartPosition=FormStartPosition.CenterScreen;f.BackColor=Color.FromArgb(16,45,62);f.ForeColor=Color.White;f.Font=new Font("Segoe UI",11);f.ClientSize=new Size(600,300);
   MessageBoxIcon icon=MessageBoxIcon.Information;
   if(args.Length>start+3)Enum.TryParse(Convert.ToString(args[start+3]),out icon);
   var measured=TextRenderer.MeasureText(text,f.Font,new Size(550,int.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPrefix);
   int bodyHeight=Math.Max(90,measured.Height+24);
   int maxHeight=Screen.FromPoint(Cursor.Position).WorkingArea.Height-80;
   f.ClientSize=new Size(600,Math.Min(maxHeight,bodyHeight+190));
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),RowCount=4,ColumnCount=1};
   layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));
   string symbol=icon==MessageBoxIcon.Error?"!":icon==MessageBoxIcon.Warning?"⚠":icon==MessageBoxIcon.Question?"?":"ⓘ";
   Color accent=icon==MessageBoxIcon.Error?Color.FromArgb(255,130,130):icon==MessageBoxIcon.Warning?Color.FromArgb(255,194,90):Color.FromArgb(142,203,230);
   layout.Controls.Add(new Label{Text=symbol,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",30,FontStyle.Bold),ForeColor=accent},0,0);
   layout.Controls.Add(new Label{Text=title,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",17,FontStyle.Bold)},0,1);
   var messagePanel=new Panel{Dock=DockStyle.Fill,AutoScroll=true};
   var message=new Label{Text=text,TextAlign=ContentAlignment.MiddleCenter,UseMnemonic=false};
   if(bodyHeight+190<=maxHeight){message.Dock=DockStyle.Fill;}else{message.AutoSize=true;message.MaximumSize=new Size(530,0);}
   messagePanel.Controls.Add(message);layout.Controls.Add(messagePanel,0,2);
   var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};layout.Controls.Add(bar,0,3);f.Controls.Add(layout);
   DialogResult[] results;
   switch(buttons){case MessageBoxButtons.YesNo:results=new[]{DialogResult.Yes,DialogResult.No};break;case MessageBoxButtons.YesNoCancel:results=new[]{DialogResult.Yes,DialogResult.No,DialogResult.Cancel};break;case MessageBoxButtons.OKCancel:results=new[]{DialogResult.OK,DialogResult.Cancel};break;case MessageBoxButtons.RetryCancel:results=new[]{DialogResult.Retry,DialogResult.Cancel};break;case MessageBoxButtons.AbortRetryIgnore:results=new[]{DialogResult.Abort,DialogResult.Retry,DialogResult.Ignore};break;default:results=new[]{DialogResult.OK};break;}
   bar.Padding=new Padding(0,4,Math.Max(0,(550-results.Length*116)/2),0);
   Button defaultButton=null;
   for(int i=results.Length-1;i>=0;i--){var b=new Button{Text=results[i].ToString(),DialogResult=results[i],Size=new Size(110,34),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(31,92,125),ForeColor=Color.White};bar.Controls.Add(b);if(i==(int)def/256)defaultButton=b;if(results[i]==DialogResult.Cancel||results[i]==DialogResult.No)f.CancelButton=b;}
   f.AcceptButton=defaultButton;
   return start==1?f.ShowDialog((IWin32Window)args[0]):f.ShowDialog();
  }
 }
}

'@
}


