function Resolve-ToolkitExportFolder([string]$Path,[string]$FallbackName){
 # Keep the saved folder when its drive exists; otherwise use Pictures.
 try{
  $root=[IO.Path]::GetPathRoot($Path)
  if($root -and (Test-Path -LiteralPath $root)){return $Path}
 }catch{}
 $pictures=[Environment]::GetFolderPath('MyPictures');if(-not $pictures){$pictures=$env:USERPROFILE}
 return (Join-Path $pictures ('Stash Toolkit\'+$FallbackName))
}
function ConvertTo-ToolkitLikePattern([string]$Text){
 # Square brackets in titles are matched literally; * and ? still work as wildcards.
 return ([System.Management.Automation.WildcardPattern]::Escape($Text)).Replace('`*','*').Replace('`?','?')
}
function Expand-ToolkitJsonItems($Value){
 if($Value -is [System.Array]){foreach($item in $Value){Expand-ToolkitJsonItems $item}}
 elseif($null -ne $Value){$Value}
}
function ConvertFrom-ToolkitJsonArray([string]$Json){
 # Windows PowerShell 5.1 returns a JSON array as one object, so @(...) wrapped
 # it in a second array and each save nested the file deeper. Flatten instead.
 if([string]::IsNullOrWhiteSpace($Json)){return @()}
 $parsed=ConvertFrom-Json -InputObject $Json -ErrorAction Stop
 return @(Expand-ToolkitJsonItems $parsed)
}
