  $format.Alignment='Center';$format.LineAlignment='Center'
  $graphics.DrawString($Text,$font,[System.Drawing.Brushes]::LightGray,(New-Object System.Drawing.RectangleF(16,16,448,238)),$format)
 }finally{$format.Dispose();$font.Dispose();$graphics.Dispose()}
 return $bitmap
