function Convert-ToolkitImageWithFfmpeg([string]$Executable,[string]$InputPath,[string]$OutputPath){
 $si=New-Object Diagnostics.ProcessStartInfo;$si.FileName=$Executable;$si.Arguments='-hide_banner -loglevel error -i "'+$InputPath+'" -frames:v 1 -y "'+$OutputPath+'"';$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardError=$true
 $process=New-Object Diagnostics.Process;$process.StartInfo=$si
 try{[void]$process.Start();$read=$process.StandardError.ReadToEndAsync();if(-not $process.WaitForExit(15000)){$process.Kill();throw 'Image conversion timed out.'};$errorText=$read.GetAwaiter().GetResult();return [pscustomobject]@{ExitCode=$process.ExitCode;Error=$errorText}}finally{$process.Dispose()}
}
function Get-StashUrl { $txtUrl.Text.Trim().TrimEnd('/') }
function Get-StashKey { $txtKey.Text.Trim() }

function Invoke-StashGraphQL {
    param([string]$Query, [hashtable]$Variables = @{})
    $url = (Get-StashUrl) + "/graphql"
    $headers = @{ "ApiKey" = (Get-StashKey) }
    $body = @{ query=$Query; variables=$Variables } | ConvertTo-Json -Depth 20
    # Send and read UTF-8 explicitly. Windows PowerShell 5.1 otherwise assumes
    # ISO-8859-1, which garbles accented and non-Latin names both ways.
    # Hiding the console progress bar also makes large library reads much faster.
    $ProgressPreference = 'SilentlyContinue'
    $response = Invoke-WebRequest -Uri $url -Method Post -Headers $headers -Body ([System.Text.Encoding]::UTF8.GetBytes($body)) -ContentType "application/json; charset=utf-8" -UseBasicParsing
    $r = [System.Text.Encoding]::UTF8.GetString($response.RawContentStream.ToArray()) | ConvertFrom-Json
    if ($r.errors) { throw (($r.errors | ForEach-Object {$_.message}) -join "`r`n") }
    return $r.data
}

