function Load-AllPerformers {
    $q = @"
query ToolkitPerformers(`$filter: FindFilterType) {
 findPerformers(filter:`$filter) {
  count
  performers { $PerformerFields }
 }
}
"@
    $d = Invoke-StashGraphQL $q @{filter=@{per_page=-1;sort="name";direction="ASC"}}
    $script:AllPerformers = @($d.findPerformers.performers)
    return $d.findPerformers.count
}

function Load-AllPerformersWithProgress {
    $cacheForm=New-Object ToolkitDialogWindow
    $cacheForm.Text="Building Stash Toolkit Cache"
    $cacheForm.Size=New-Object System.Drawing.Size(610,285)
    $cacheForm.StartPosition="Manual"
    $cacheForm.Location=New-Object System.Drawing.Point(
        ($form.Left+[int](($form.Width-$cacheForm.Width)/2)),
        ($form.Top+120)
    )
    $cacheForm.FormBorderStyle="FixedDialog"
    $cacheForm.MaximizeBox=$false
    $cacheForm.MinimizeBox=$false
    $cacheForm.ControlBox=$false
    $cacheForm.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)

    $cacheTitle=New-Object System.Windows.Forms.Label
    $cacheTitle.Text="UPDATING LIBRARY CACHE"
    $cacheTitle.Location=New-Object System.Drawing.Point(25,20)
    $cacheTitle.Size=New-Object System.Drawing.Size(545,46)
    $cacheTitle.Font=New-Object System.Drawing.Font("Comic Sans MS",15,[System.Drawing.FontStyle]::Bold)
    $cacheTitle.ForeColor=[System.Drawing.Color]::White

    $cacheCurrent=New-Object System.Windows.Forms.Label
    $cacheCurrent.Text="1 of 4  •  Caching Performers..."
    $cacheCurrent.Location=New-Object System.Drawing.Point(28,76)
    $cacheCurrent.Size=New-Object System.Drawing.Size(535,26)
    $cacheCurrent.Font=New-Object System.Drawing.Font("Segoe UI",10,[System.Drawing.FontStyle]::Bold)
    $cacheCurrent.ForeColor=[System.Drawing.Color]::FromArgb(255,88,181)

    $cacheProgress=New-Object System.Windows.Forms.ProgressBar
    $cacheProgress.Location=New-Object System.Drawing.Point(30,112)
    $cacheProgress.Size=New-Object System.Drawing.Size(530,24)
    $cacheProgress.Style="Marquee"
    $cacheProgress.MarqueeAnimationSpeed=25

    $cacheResults=New-Object System.Windows.Forms.Label
    $cacheResults.Text="Reading performers from Stash..."
    $cacheResults.Location=New-Object System.Drawing.Point(30,151)
    $cacheResults.Size=New-Object System.Drawing.Size(530,75)
    $cacheResults.Font=New-Object System.Drawing.Font("Segoe UI",9.5)
    $cacheResults.ForeColor=[System.Drawing.Color]::FromArgb(188,211,226)

    [void]$cacheForm.Controls.AddRange(@($cacheTitle,$cacheCurrent,$cacheProgress,$cacheResults))
    $cacheForm.Show($form)
    [System.Windows.Forms.Application]::DoEvents()

    try {
        $status.Text="Caching performers..."
        [System.Windows.Forms.Application]::DoEvents()

        $n=Load-AllPerformers

        $cacheProgress.Style="Blocks"
        $cacheProgress.Minimum=0
        $cacheProgress.Maximum=100
        $cacheProgress.Value=100
        $cacheCurrent.Text="PERFORMER CACHE READY"
        $cacheResults.Text="$n performers cached"
        $status.Text="$n performers cached"
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 700
        return $n
    } catch {
        $cacheProgress.Style="Blocks"
        $cacheProgress.Value=0
        $cacheCurrent.Text="PERFORMER CACHE FAILED"
        $cacheResults.Text=$_.Exception.Message
        $status.Text="Performer cache failed"
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 1000
        throw
    } finally {
        $cacheForm.Close()
        $cacheForm.Dispose()
    }
}

function Ensure-Loaded {
    if ($script:AllPerformers.Count -eq 0) {
        $status.Text = "Loading performers..."
        [System.Windows.Forms.Application]::DoEvents()
        [void](Load-AllPerformers)
        $status.Text = "Loaded $($script:AllPerformers.Count) performers."
    }
}

function Add-GridColumns($grid, $columns) {
    $grid.Columns.Clear()
    foreach ($c in $columns) {
        $col = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
        $col.Name=$c[0]; $col.HeaderText=$c[1]; $col.FillWeight=$c[2]
        [void]$grid.Columns.Add($col)
    }
}

function New-Grid {
    $g=New-Object System.Windows.Forms.DataGridView
    $g.Dock="Fill"; $g.ReadOnly=$true; $g.AllowUserToAddRows=$false
    $g.AllowUserToDeleteRows=$false; $g.SelectionMode="FullRowSelect"
    $g.MultiSelect=$false; $g.AutoSizeColumnsMode="Fill"
    return $g
}

function Get-PerformerById([string]$id) {
    return $script:AllPerformers | Where-Object {[string]$_.id -eq $id} | Select-Object -First 1
}

function Format-Value($v) {
    if ($null -eq $v) { return "" }
    if ($v -is [array]) { return ($v -join ", ") }
    return [string]$v
}

function Get-AgeText($p) {
    if ([string]::IsNullOrWhiteSpace([string]$p.birthdate)) { return "" }
    try {
        $b=[datetime]::Parse($p.birthdate)
        $end=Get-Date
        if (-not [string]::IsNullOrWhiteSpace([string]$p.death_date)) {$end=[datetime]::Parse($p.death_date)}
        $age=$end.Year-$b.Year
        if ($end.Date -lt $b.AddYears($age).Date) {$age--}
        return [string]$age
    } catch { return "" }
}

function Show-PerformerDetails($p) {
    if ($null -eq $p) { return }
    $script:CurrentPerformer=$p
    $props = [ordered]@{
        "ID"=$p.id; "Name"=$p.name; "Disambiguation"=$p.disambiguation
        "Aliases"=($p.alias_list -join ", "); "Gender"=$p.gender
        "Birthdate"=$p.birthdate; "Age"=(Get-AgeText $p); "Death date"=$p.death_date
        "Country"=$p.country; "Ethnicity"=$p.ethnicity; "Hair colour"=$p.hair_color
        "Eye colour"=$p.eye_color; "Height (cm)"=$p.height_cm; "Weight"=$p.weight
        "Measurements"=$p.measurements; "Fake tits"=$p.fake_tits
        "Penis length"=$p.penis_length; "Circumcised"=$p.circumcised
        "Career length"=$p.career_length; "Tattoos"=$p.tattoos; "Piercings"=$p.piercings
        "Favourite"=$p.favorite; "Rating / 100"=$p.rating100
        "Scenes"=$p.scene_count; "Images"=$p.image_count; "Galleries"=$p.gallery_count
        "Movies / Groups"=$p.movie_count
        "Tags"=(($p.tags | ForEach-Object {$_.name}) -join ", ")
        "URL"=$p.url; "Twitter"=$p.twitter; "Instagram"=$p.instagram
        "Stash IDs"=(($p.stash_ids | ForEach-Object {"$($_.stash_id) [$($_.endpoint)]"}) -join "`r`n")
        "Created"=$p.created_at; "Updated"=$p.updated_at
        "Details"=$p.details
    }
    $detailsGrid.Rows.Clear()
    foreach($k in $props.Keys){[void]$detailsGrid.Rows.Add($k,(Format-Value $props[$k]))}
    $pic.Image=$null
    if (-not [string]::IsNullOrWhiteSpace([string]$p.image_path)) {
        try {
            $wc=New-Object System.Net.WebClient
            if (-not [string]::IsNullOrWhiteSpace((Get-StashKey))) {$wc.Headers.Add("ApiKey",(Get-StashKey))}
            $bytes=$wc.DownloadData($p.image_path)
            $ms=New-Object System.IO.MemoryStream(,$bytes)
            $tmp=[System.Drawing.Image]::FromStream($ms)
            $pic.Image=New-Object System.Drawing.Bitmap($tmp)
            $tmp.Dispose();$ms.Dispose();$wc.Dispose()
        } catch {}
    }
}

function Open-CurrentInStash {
    if ($null -eq $script:CurrentPerformer) { return }
    Open-StashToolkitLink ((Get-StashUrl)+"/performers/"+$script:CurrentPerformer.id)
}

function Get-ToolkitCsvRows($Grid) {
    $columns=@($Grid.Columns | Where-Object {$_.Visible} | Sort-Object DisplayIndex)
    foreach($row in $Grid.Rows){
        if($row.IsNewRow){continue}
        $record=[ordered]@{}
        foreach($column in $columns){
            $heading=[string]$column.HeaderText
            if([string]::IsNullOrWhiteSpace($heading)){$heading=[string]$column.Name}
            $base=$heading;$suffix=2
            while($record.Contains($heading)){$heading="$base ($suffix)";$suffix++}
            $value=$row.Cells[$column.Index].Value
            if($null -eq $value -or $value -is [System.DBNull]){$value=''}
            elseif($value -is [System.Array]){$value=($value | ForEach-Object {[string]$_}) -join '; '}
            $record[$heading]=[string]$value
        }
        if($record.Count){[pscustomobject]$record}
    }
}

function Write-ToolkitCsv($Rows,[string]$Path) {
    # Identical quoting, delimiter, line endings and Excel-friendly encoding on
    # Windows PowerShell 5.1 and PowerShell 7, independent of regional defaults.
    $lines=@($Rows | ConvertTo-Csv -NoTypeInformation -Delimiter ',')
    $encoding=New-Object System.Text.UTF8Encoding($true)
    [System.IO.File]::WriteAllText($Path,($lines -join "`r`n")+"`r`n",$encoding)
}

function Export-GridCsv($grid,$defaultName) {
    $rows=@(Get-ToolkitCsvRows $grid)
    if(-not $rows.Count){[void][ToolkitMessageDialog]::Show('There are no results to export yet. Show some results first, then export them.','Export CSV','OK','Information');return}
    $dialog=New-Object System.Windows.Forms.SaveFileDialog
    $dialog.Filter='CSV files (*.csv)|*.csv';$dialog.FileName=$defaultName
    $dialog.DefaultExt='csv';$dialog.AddExtension=$true
    try {
        if($dialog.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK){return}
        Write-ToolkitCsv $rows $dialog.FileName
        $status.Text="CSV exported: $($dialog.FileName)"
        Show-ExportSuccess 'CSV'
    } catch {
        [void][ToolkitMessageDialog]::Show($_.Exception.Message,'Export CSV','OK','Error')
    } finally {$dialog.Dispose()}
}


function Get-ToolkitHtmlContextCore($Grid,[string]$DefaultName,[string]$Title){
 $subject='Performers';$operation='Results';$view=$null;$filters=[ordered]@{}
 foreach($entry in $script:SubjectViews.Values){if([object]::ReferenceEquals($Grid,$entry.Grid)){$subject=$entry.Subject;$operation=$entry.Operation;$view=$entry;break}}
 if(-not $view){foreach($entry in $script:ReplacementGroupsViews.Values){if([object]::ReferenceEquals($Grid,$entry.Grid)){$subject='Groups';$operation=$entry.Operation;$view=$entry;break}}}
 if(-not $view -and $script:PerformerSearchView -and [object]::ReferenceEquals($Grid,$script:PerformerSearchView.Grid)){$subject='Performers';$operation='Search';$view=$script:PerformerSearchView}
 if(-not $view){
  if($DefaultName -match '^stash-scenes-' -or $Grid.Columns.Contains('SceneID')){$subject='Scenes'}
  elseif($DefaultName -match '^stash-groups'){$subject='Groups'}
  elseif($DefaultName -match '^stash-studios'){$subject='Studios'}
  $text=$Title+' '+$DefaultName
  $operation=switch -Regex($text){'Missing[- ]Pictures'{'Missing Pictures';break};'Missing[- ]Information'{'Missing Information';break};'Duplicate'{'Duplicate Finder';break};'Recently|recent'{'Recently Added';break};'Tag|by-tag'{'Tag Search';break};'by-performer'{'By Performer';break};'by-studio'{'By Studio';break};'Browser'{'Browser';break};'Search'{'Search';break};default{'Results'}}
  if($Grid -eq $sceneSearchGrid){$operation='Search';$filters['Search']=$sceneSearchBox.Text;$filters['Search field']=[string]$sceneFilter.SelectedItem}
  elseif($Grid -eq $tagSceneRelationGrid){$operation='Tag Search';$filters['Tag']=[string]$tagSceneCombo.SelectedItem}
  elseif($Grid -eq $byPerformerGrid){$operation='By Performer';$filters['Performer']=[string]$byPerformerCombo.SelectedItem}
  elseif($Grid -eq $byStudio.Grid){$operation='By Studio';$filters['Studio']=[string]$byStudio.Combo.SelectedItem}
  elseif($Grid -eq $sceneRecentGrid){$operation=[string]$recentMode.SelectedItem;$filters['Period']=[string]$recentDays.SelectedItem}
  elseif($Grid -eq $sceneMissingGrid){$operation='Missing Information';$filters['Checked fields']=@($sceneMissingOptions.Keys | Where-Object {$sceneMissingOptions[$_].Checked} | Sort-Object) -join ', '}
 }
 if($view){
  if($view.Query){$filters['Search']=$view.Query.Text}
  if($view.Choice){$filters[$(switch($operation){'Tag Search'{'Tag'};'By Performer'{'Performer'};'By Studio'{'Studio'};'By Parent Studio'{'Parent studio'};'Recently Added'{'Period'};default{'Search field'}})]=[string]$view.Choice.SelectedItem}
  if($view.Mode){$operation=[string]$view.Mode.SelectedItem}
  if($operation -eq 'Missing Information'){
   $boxes=if($view.Checks -is [System.Collections.IDictionary]){@($view.Checks.Values)}else{@($view.Checks)}
   $filters['Checked fields']=@($boxes | Where-Object {$_.Checked} | ForEach-Object {$_.Text} | Sort-Object) -join ', '
  }
 }
 if($script:BrowserSearchViews){foreach($browser in $script:BrowserSearchViews.Values){if([object]::ReferenceEquals($Grid,$browser.Grid)){$filters['Search']=$browser.Query.Text;$filters['Search field']=[string]$browser.Choice.SelectedItem;break}}}
 if($script:UtilityTagView -and [object]::ReferenceEquals($Grid,$script:UtilityTagView.Grid)){
  $subject='Scenes';$operation='Tag Search'
  $filters['Tags']=$script:UtilityTagView.Names -join ', '
  $filters['Match']=if($script:UtilityTagView.MatchAll){'ALL'}else{'ANY'}
 }
 if($script:SingleFileFinder -and [object]::ReferenceEquals($Grid,$script:SingleFileFinder.Grid)){
  $subject='Files';$operation='Single File Finder'
  $filters['Folders']=$script:SingleFileFinder.Roots.Lines -join '; '
  $filters['Scan mode']=if($script:SingleFileFinder.Recursive.Checked){'Includes nested subfolders'}else{'Immediate subfolders only'}
 }
 $description=switch -Regex($operation){
  '^Single File Finder$' {'Files in folders containing exactly one file. Unavailable folders are identified in the Status column.';break}
  '^Search$' {"$subject matching the search criteria shown below.";break}
  'Recently Updated' {"$subject updated during the selected period.";break}
  'Recently Added' {"$subject added during the selected period.";break}
  'Missing Pictures' {"$subject without a picture in Stash.";break}
  'Missing Information' {"$subject missing one or more of the checked fields. The Missing column identifies the gaps for each record.";break}
  'Duplicate' {"Possible duplicate $($subject.ToLower()). The match and reason columns explain each result; these are candidates for review.";break}
  'Tag Search' {"$subject associated with the selected tag.";break}
  '^By ' {"$subject associated with the selected $($operation.Substring(3).ToLower()).";break}
  'Browser' {"$subject displayed in the browser when this report was exported.";break}
  default {"$subject displayed when this report was exported."}
 }
 return @{Subject=$subject;Operation=$operation;Title=($subject+' — '+$operation);Description=$description;Filters=$filters}
}

function Get-ToolkitHtmlRecord($Grid,$Row,$Subject){
 $id=''
 foreach($name in @('SubjectID','GroupID','PerformerID','SceneID','ID','ID1')){if($Grid.Columns.Contains($name)){$id=[string]$Row.Cells[$name].Value;break}}
 $items=switch($Subject){'Scenes'{$script:SceneCache};'Groups'{$script:GroupCache};'Studios'{$script:StudioCache};default{$script:AllPerformers}}
 $record=$items | Where-Object {[string]$_.id -eq $id} | Select-Object -First 1
 return @{Id=$id;Record=$record}
}

function Get-ToolkitHtmlPicture([string]$Path,[string]$Label){
 if(-not $Path){return ''}
 if($Path.StartsWith('/')){$Path=(Get-StashUrl).TrimEnd('/')+$Path}
 $client=New-Object System.Net.WebClient
 try{
  $uri=$null;if(-not [uri]::TryCreate($Path,[UriKind]::Absolute,[ref]$uri) -or $uri.Scheme -notin @('http','https')){return ''}
  $key=Get-StashKey;if($key){$client.Headers.Add('ApiKey',$key)}
  $bytes=$client.DownloadData($uri)
  $mime=''
  if($bytes.Length -ge 12){
   if($bytes[0] -eq 255 -and $bytes[1] -eq 216){$mime='image/jpeg'}
   elseif($bytes[0] -eq 137 -and $bytes[1] -eq 80 -and $bytes[2] -eq 78 -and $bytes[3] -eq 71){$mime='image/png'}
   elseif([Text.Encoding]::ASCII.GetString($bytes,0,3) -eq 'GIF'){$mime='image/gif'}
   elseif([Text.Encoding]::ASCII.GetString($bytes,0,4) -eq 'RIFF' -and [Text.Encoding]::ASCII.GetString($bytes,8,4) -eq 'WEBP'){$mime='image/webp'}
  }
  if(-not $mime){return ''}
  $safeLabel=[Net.WebUtility]::HtmlEncode($Label)
  return "<figure><img loading='lazy' src='data:$mime;base64,$([Convert]::ToBase64String($bytes))' alt='$safeLabel'></figure>"
 }catch{return ''}finally{$client.Dispose()}
}

function New-ToolkitHtmlReport($Grid,[string]$DefaultName,[string]$Title,$RowWriter=$null){
 $context=Get-ToolkitHtmlContext $Grid $DefaultName $Title
 $enc={param($value) [Net.WebUtility]::HtmlEncode([string]$value)}
 $columns=@($Grid.Columns | Where-Object {$_.Visible} | Sort-Object DisplayIndex)
 $dataRows=@($Grid.Rows | Where-Object {-not $_.IsNewRow})
 $headers=@(foreach($column in $columns){"<th scope='col'>$(& $enc $column.HeaderText)</th>"})
 $recent=$context.Operation -like 'Recently*'
 $dateFields=@()
 if($recent){foreach($pair in @(@('created_at','Created'),@('updated_at','Updated'))){if(@($columns.HeaderText) -notcontains $pair[1]){$dateFields+=,$pair;$headers+="<th scope='col'>$($pair[1])</th>"}}}
 $includePictures=$context.Operation -ne 'Missing Pictures' -and $context.Subject -ne 'Files'
 if($includePictures){$label=switch($context.Subject){'Groups'{'Front / back covers'};'Scenes'{'Screenshot'};'Studios'{'Logo'};default{'Picture'}};$headers+="<th scope='col'>$label</th>"}
 $base=(Get-StashUrl).TrimEnd('/');$baseUri=$null;$validBase=[uri]::TryCreate($base,[UriKind]::Absolute,[ref]$baseUri) -and $baseUri.Scheme -in @('http','https')
 $hasStashRecordLinks=$false
 $rows=foreach($row in $dataRows){
  $resolved=Get-ToolkitHtmlRecord $Grid $row $context.Subject;$record=$resolved.Record
  $cells=foreach($column in $columns){
   $value=$row.Cells[$column.Index].Value;$text=& $enc (Format-Value $value)
   if($column.Name -in @('Title','Name','Name1') -and $resolved.Id -and $validBase){$hasStashRecordLinks=$true;$href=$base+'/'+$context.Subject.ToLower()+'/'+[uri]::EscapeDataString($resolved.Id);$text="<a href='$(& $enc $href)' target='_blank' rel='noopener noreferrer'>$text</a>"}
   "<td>$text</td>"
  }
  foreach($pair in $dateFields){$cells+="<td>$(& $enc $record.($pair[0]))</td>"}
  if($includePictures){
   $pictures=switch($context.Subject){
    'Groups' {(Get-ToolkitHtmlPicture ([string]$record.front_image_path) 'Front cover')+(Get-ToolkitHtmlPicture ([string]$record.back_image_path) 'Back cover')}
    'Scenes' {Get-ToolkitHtmlPicture ([string]$record.paths.screenshot) 'Scene screenshot'}
    'Studios' {Get-ToolkitHtmlPicture ([string]$record.image_path) 'Studio logo'}
       default {
     $portrait=Get-ToolkitHtmlPicture ([string]$record.image_path) ([string]$record.name)
     if($context.Operation -eq 'Duplicate Finder'){
      $match=@(Get-ToolkitDuplicateMatches @($script:AllPerformers) 'Performers' | Where-Object {[string]$_.Item.id -eq [string]$resolved.Id} | Select-Object -First 1)
      if($match.Count){$portrait+=Get-ToolkitHtmlPicture ([string]$match[0].Other.image_path) ([string]$match[0].Other.name)}
     }
     $portrait
    }
   }
   if(-not $pictures){$pictures='<span class="muted">No picture available</span>'};$cells+="<td class='pictures'>$pictures</td>"
  }
  $htmlRow="<tr>$($cells -join '')</tr>"
  if($null -ne $RowWriter){
   $RowWriter.WriteLine($htmlRow)
   $script:HtmlExportCompletedRows++
   $status.Text="Exporting HTML: $script:HtmlExportCompletedRows / $($dataRows.Count)"
   $status.Refresh()
   if($script:HtmlExportProgressBar){
    $script:HtmlExportProgressBar.Value=[Math]::Min($script:HtmlExportCompletedRows,$script:HtmlExportProgressBar.Maximum)
    $script:HtmlExportProgressLabel.Text="Creating report: $script:HtmlExportCompletedRows of $($dataRows.Count) rows"
    $script:HtmlExportProgressWindow.Refresh()
   }
  }else{$htmlRow}
 }
 if($null -ne $RowWriter){$rows=@('<!--STASH-TOOLKIT-STREAMED-ROWS-->')}
 $filters=foreach($key in $context.Filters.Keys){$value=[string]$context.Filters[$key];if(-not $value){$value='All'};"<div><dt>$(& $enc $key)</dt><dd>$(& $enc $value)</dd></div>"}
 $countLabel=if($context.Operation -like '*Duplicate*'){'possible matches'}else{$context.Subject.ToLower()}
 $safeTitle=& $enc $context.Title;$description=& $enc $context.Description;$generated=& $enc ((Get-Date).ToString('dd MMM yyyy HH:mm'))
 $safeSubject=& $enc $context.Subject
 $total=switch($context.Subject){'Files'{$dataRows.Count};'Scenes'{@($script:SceneCache).Count};'Groups'{@($script:GroupCache).Count};'Studios'{@($script:StudioCache).Count};default{@($script:AllPerformers).Count}}
 $linkFooter=if($hasStashRecordLinks){' Names link to their records in Stash.'}else{''}
 $designImage='data:image/png;base64,'+$script:ApprovedReportDesignBase64.Trim()
 return @"
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stash — $safeTitle</title>
<style>
