td{vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere}a{color:#5142a7;font-weight:600}.muted{color:#827b93;font-size:12px}caption{text-align:left;padding:12px 14px;background:#f5f1ff;color:#35315f;font-weight:600}.pictures{min-width:140px}.pictures figure{display:inline-block;margin:0 8px 8px 0;vertical-align:top}.pictures img{width:110px;max-height:160px;object-fit:contain;border-radius:10px;border:2px solid white;box-shadow:0 2px 8px rgba(75,54,140,.25)}.pictures figcaption{font-size:11px;color:#716b8c}
