function Write-ToolkitHtmlReport($Grid,[string]$DefaultName,[string]$Title,[string]$Destination){
 $script:HtmlExportProgressWindow=New-Object ToolkitDialogWindow
 $script:HtmlExportProgressWindow.Text='Creating HTML export'
 $script:HtmlExportProgressWindow.ClientSize=New-Object Drawing.Size(560,190)
 $script:HtmlExportProgressWindow.BackColor=[Drawing.Color]::FromArgb(16,45,62)
 $script:HtmlExportProgressWindow.ForeColor=[Drawing.Color]::White
 $script:HtmlExportProgressWindow.StartPosition='CenterScreen'
 $script:HtmlExportProgressWindow.FormBorderStyle='FixedDialog'
 $script:HtmlExportProgressWindow.ControlBox=$false
 $script:HtmlExportProgressLabel=New-Object Windows.Forms.Label
 $script:HtmlExportProgressLabel.Location=New-Object Drawing.Point(20,20)
 $script:HtmlExportProgressLabel.Size=New-Object Drawing.Size(465,38)
 $script:HtmlExportProgressLabel.Text='Preparing report...'
 $script:HtmlExportProgressLabel.Font=New-Object Drawing.Font('Segoe UI',11)
 $script:HtmlExportProgressLabel.ForeColor=[Drawing.Color]::White
 $script:HtmlExportProgressLabel.Location=New-Object Drawing.Point(24,78)
 $script:HtmlExportProgressLabel.Size=New-Object Drawing.Size(512,40)
 $exportHeading=New-Object Windows.Forms.Label;$exportHeading.Text='Creating your report';$exportHeading.Location=New-Object Drawing.Point(24,20);$exportHeading.Size=New-Object Drawing.Size(512,42);$exportHeading.Font=New-Object Drawing.Font('Segoe UI',17,[Drawing.FontStyle]::Bold);$exportHeading.ForeColor=[Drawing.Color]::FromArgb(142,203,230)
 [void]$script:HtmlExportProgressWindow.Controls.Add($exportHeading)
 $script:HtmlExportProgressBar=New-Object Windows.Forms.ProgressBar
 $script:HtmlExportProgressBar.Location=New-Object Drawing.Point(24,136)
 $script:HtmlExportProgressBar.Size=New-Object Drawing.Size(512,26)
 $script:HtmlExportProgressBar.Maximum=[Math]::Max(1,@($Grid.Rows | Where-Object {-not $_.IsNewRow}).Count)
 [void]$script:HtmlExportProgressWindow.Controls.AddRange(@($script:HtmlExportProgressLabel,$script:HtmlExportProgressBar))
 $form.Enabled=$false
 $script:HtmlExportProgressWindow.Show($form)
 $script:HtmlExportProgressWindow.Refresh()
 $rowsFile=[IO.Path]::GetTempFileName()
 $partial=[IO.Path]::GetFullPath($Destination)+'.'+[guid]::NewGuid().ToString()+'.partial'
 $rowWriter=$null;$output=$null;$reader=$null
 try{
  $script:HtmlExportCompletedRows=0
  $rowWriter=New-Object IO.StreamWriter($rowsFile,$false,(New-Object Text.UTF8Encoding($false)))
  $template=New-ToolkitHtmlReport $Grid $DefaultName $Title $rowWriter
  $rowWriter.Dispose();$rowWriter=$null
  $marker='<!--STASH-TOOLKIT-STREAMED-ROWS-->';$position=$template.IndexOf($marker)
  if($position -lt 0){throw 'HTML row placeholder missing'}
  $output=New-Object IO.StreamWriter($partial,$false,(New-Object Text.UTF8Encoding($true)))
  $script:HtmlExportProgressLabel.Text='Writing the final HTML file...'
  $script:HtmlExportProgressBar.Style='Marquee'
  $script:HtmlExportProgressWindow.Refresh()
  $output.Write($template.Substring(0,$position))
  $reader=New-Object IO.StreamReader($rowsFile,[Text.Encoding]::UTF8)
  $buffer=New-Object char[] 65536
  while(($read=$reader.Read($buffer,0,$buffer.Length)) -gt 0){$output.Write($buffer,0,$read)}
  $reader.Dispose();$reader=$null
  $output.Write($template.Substring($position+$marker.Length));$output.Dispose();$output=$null
  Move-Item -LiteralPath $partial -Destination $Destination -Force -ErrorAction Stop
 }finally{
  if($script:HtmlExportProgressWindow){$script:HtmlExportProgressWindow.Close();$script:HtmlExportProgressWindow.Dispose()}
  $script:HtmlExportProgressWindow=$null;$script:HtmlExportProgressBar=$null;$script:HtmlExportProgressLabel=$null
  $form.Enabled=$true
  foreach($resource in @($rowWriter,$output,$reader)){if($null -ne $resource){$resource.Dispose()}}
  foreach($tempFile in @($rowsFile,$partial)){if(Test-Path -LiteralPath $tempFile){Remove-Item -LiteralPath $tempFile -Force}}
 }
}
function Show-ExportSuccess([string]$Format,[string]$Details=$null){
 $window=New-Object ToolkitDialogWindow;$window.Text='Export Complete';$window.ControlBox=$false;$window.ClientSize=New-Object Drawing.Size(560,300);$window.StartPosition='CenterScreen';$window.BackColor=[Drawing.Color]::FromArgb(16,45,62);$window.ForeColor=[Drawing.Color]::White
 $layout=New-Object Windows.Forms.TableLayoutPanel;$layout.Dock='Fill';$layout.Padding=New-Object Windows.Forms.Padding(24);$layout.ColumnCount=1;$layout.RowCount=4
 $bodyHeight=70;if($Details){$bodyHeight=190;$window.ClientSize=New-Object Drawing.Size(600,420)}
 foreach($height in @(70,50,$bodyHeight,62)){[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',$height)))}
 $icon=New-Object Windows.Forms.Label;$icon.Text='✓';$icon.Font=New-Object Drawing.Font('Segoe UI',36,[Drawing.FontStyle]::Bold);$icon.ForeColor=[Drawing.Color]::FromArgb(100,220,140);$icon.Dock='Fill';$icon.TextAlign='MiddleCenter'
 $heading=New-Object Windows.Forms.Label;$heading.Text='Export complete';$heading.Font=New-Object Drawing.Font('Segoe UI',20,[Drawing.FontStyle]::Bold);$heading.Dock='Fill';$heading.TextAlign='MiddleCenter'
 $body=New-Object Windows.Forms.Label;$body.Text=if($Details){$Details}else{"Your $Format export has been saved successfully."};$body.Font=New-Object Drawing.Font('Segoe UI',12);$body.Dock='Fill';$body.TextAlign='MiddleCenter'
 $button=New-UtilityFileButton 'Done';$button.Anchor='None';$button.DialogResult='OK';$window.AcceptButton=$button;$window.CancelButton=$button
 [void]$layout.Controls.Add($icon,0,0);[void]$layout.Controls.Add($heading,0,1);[void]$layout.Controls.Add($body,0,2);[void]$layout.Controls.Add($button,0,3);[void]$window.Controls.Add($layout)
 try{[void]$window.ShowDialog($form)}finally{$window.Dispose()}
}
function Show-HtmlExportNotice([bool]$Confirm=$false) {
 $window=New-Object ToolkitDialogWindow;$window.Text='NSFW HTML Export';$window.ControlBox=$false;$window.ClientSize=New-Object Drawing.Size(640,420);$window.StartPosition='CenterScreen';$window.BackColor=[Drawing.Color]::FromArgb(16,45,62);$window.ForeColor=[Drawing.Color]::White
 $layout=New-Object Windows.Forms.TableLayoutPanel;$layout.Dock='Fill';$layout.Padding=New-Object Windows.Forms.Padding(24);$layout.ColumnCount=1;$layout.RowCount=4
 foreach($height in @(64,56,180,72)){[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',$height)))}
 $icon=New-Object Windows.Forms.Label;$icon.Text='⚠';$icon.Font=New-Object Drawing.Font('Segoe UI',32);$icon.ForeColor=[Drawing.Color]::FromArgb(255,194,90);$icon.Dock='Fill';$icon.TextAlign='MiddleCenter'
 $heading=New-Object Windows.Forms.Label;$heading.Text='NSFW HTML Export';$heading.Font=New-Object Drawing.Font('Segoe UI',19,[Drawing.FontStyle]::Bold);$heading.Dock='Fill';$heading.TextAlign='MiddleCenter'
 $body=New-Object Windows.Forms.Label;$body.Text="Your HTML report includes available NSFW pictures.`r`nThe toolkit’s SFW setting does not hide`r`nimages in exported reports.";$body.Font=New-Object Drawing.Font('Segoe UI',12);$body.Dock='Fill';$body.TextAlign='MiddleCenter'
 $button=New-UtilityFileButton 'Got it';$button.Anchor='None';$button.DialogResult='OK';$window.AcceptButton=$button;$window.CancelButton=$button
 [void]$layout.Controls.Add($icon,0,0);[void]$layout.Controls.Add($heading,0,1);[void]$layout.Controls.Add($body,0,2);[void]$layout.Controls.Add($button,0,3);[void]$window.Controls.Add($layout)
 if($Confirm){
  $button.Text='Continue';$button.DialogResult='Yes'
  $buttons=New-Object Windows.Forms.FlowLayoutPanel;$buttons.Dock='Fill';$buttons.Padding=New-Object Windows.Forms.Padding(80,12,0,0)
  $layout.Controls.Remove($button);[void]$buttons.Controls.Add($button)
  $cancel=New-UtilityFileButton 'Cancel';$cancel.DialogResult='No';[void]$buttons.Controls.Add($cancel);$window.CancelButton=$cancel;[void]$layout.Controls.Add($buttons,0,3)
 }
 try{$result=$window.ShowDialog($form);if($Confirm){return $result}}finally{$window.Dispose()}
}
function Export-GridHtml($grid,$defaultName,$title){
 if(-not @($grid.Rows | Where-Object {-not $_.IsNewRow}).Count){[void][ToolkitMessageDialog]::Show('There are no results to export yet. Show some results first, then export them.','Export HTML','OK','Information');return}
 Show-HtmlExportNotice
 $dialog=New-Object Windows.Forms.SaveFileDialog;$dialog.Filter='HTML files (*.html)|*.html';$dialog.FileName=$defaultName;$dialog.DefaultExt='html';$dialog.AddExtension=$true
 try{
  if($dialog.ShowDialog() -ne [Windows.Forms.DialogResult]::OK){return}
  Write-ToolkitHtmlReport $grid $defaultName $title $dialog.FileName
  $status.Text="HTML exported: $($dialog.FileName)"
  Show-ExportSuccess 'HTML'
 }catch{[void][ToolkitMessageDialog]::Show($_.Exception.Message,'Export HTML','OK','Error')}finally{$dialog.Dispose()}
}

