# Gives a WinForms control soft, pill-like corners by clipping it to a rounded
# rectangle region. $Radius in pixels; pass Height/2 for a full capsule (pill)
# shape, or a small fixed value (e.g. 8) for a gently rounded rectangle.
function Set-ToolkitRoundedRegion([System.Windows.Forms.Control]$Control,[int]$Radius){
 if($null -eq $Control -or $Control.Width -le 1 -or $Control.Height -le 1){return}
 $w=$Control.Width;$h=$Control.Height
 $d=[Math]::Max(2,[Math]::Min($Radius*2,[Math]::Min($w,$h)-1))
 $path=New-Object System.Drawing.Drawing2D.GraphicsPath
 $path.AddArc(0,0,$d,$d,180,90)
 $path.AddArc($w-$d,0,$d,$d,270,90)
 $path.AddArc($w-$d,$h-$d,$d,$d,0,90)
 $path.AddArc(0,$h-$d,$d,$d,90,90)
 $path.CloseFigure()
 if($Control.Region){$Control.Region.Dispose()}
 $Control.Region=New-Object System.Drawing.Region($path)
}

