# Keeps Show/Open Stash/Stop Stash legible while disabled (see the
# $script:BarDisabledBack comment above) -- re-applied automatically whenever
# .Enabled flips, from wherever in the script that happens.
function Set-ToolkitActionButtonLook([System.Windows.Forms.Button]$Button){
 if($Button.Enabled){
  $Button.BackColor=$script:BarActionBack
  $Button.ForeColor=$script:BarActionFore
  $Button.FlatAppearance.BorderColor=$script:BarFieldBorder
 } else {
  $Button.BackColor=$script:BarDisabledBack
  $Button.ForeColor=$script:BarActionFore
  $Button.FlatAppearance.BorderColor=$script:BarDisabledBorder
 }
}
$showKey.Add_EnabledChanged({Set-ToolkitActionButtonLook $this})
$btnOpenStash.Add_EnabledChanged({Set-ToolkitActionButtonLook $this})
$btnStopStash.Add_EnabledChanged({Set-ToolkitActionButtonLook $this})
foreach($dimmableButton in @($showKey,$btnOpenStash,$btnStopStash)){Set-ToolkitActionButtonLook $dimmableButton}

