  $globalSafetyToggle.BackColor=$script:BarSfwBack
 }
})

# Thin vertical rule separating the connection fields from the Stash-app
# buttons, matching the divider in the approved dark-theme mockup.
$topDivider=New-Object System.Windows.Forms.Panel
$topDivider.BackColor=[System.Drawing.Color]::FromArgb(31,78,107)
$topDivider.Width=2

$top.Controls.AddRange(@($lblUrl,$txtUrl,$lblKey,$txtKey,$showKey,$topDivider,$btnConnect,$btnOpenStash,$btnStopStash,$globalSafetyToggle,$status,$libraryCountTable,$btnRescan))

# Every pill-shaped control in the bar gets its rounded corners re-clipped
# whenever its size settles (AutoSize buttons only know their final width
# after the form lays out), mirroring the existing SizeChanged-driven layout.
function Update-ToolkitTopBarRoundedCorners {
 Set-ToolkitRoundedRegion $showKey 8
 foreach($pill in @($btnConnect,$btnOpenStash,$btnStopStash,$btnRescan)){Set-ToolkitRoundedRegion $pill ([int]($pill.Height/2))}
 Set-ToolkitRoundedRegion $globalSafetyToggle ([int]($globalSafetyToggle.Height/2))
}
foreach($pillButton in @($showKey,$btnConnect,$btnOpenStash,$btnStopStash,$globalSafetyToggle,$btnRescan)){$pillButton.Add_SizeChanged({Update-ToolkitTopBarRoundedCorners})}

# Lay the connection bar out from the real window width so every control stays
# visible on smaller or scaled screens, with the SFW switch on the right edge.
function Update-ToolkitTopBarLayout {
 if($null -eq $top -or $top.ClientSize.Width -le 0 -or $script:LayingOutTopBar){return}
 $script:LayingOutTopBar=$true
 try{
  $gap=10;$width=$top.ClientSize.Width
  $buttons=@($showKey,$btnConnect,$btnOpenStash,$btnStopStash)
  $buttonWidth=0;foreach($button in $buttons){$buttonWidth+=$button.Width+$gap}
  $fixed=10+$lblUrl.Width+$gap+$lblKey.Width+$gap+$gap+$gap*2+2+$gap*2+$buttonWidth+$globalSafetyToggle.Width+24
  $spare=[Math]::Max(240,$width-$fixed)
  $urlWidth=[int][Math]::Max(130,[Math]::Min(380,$spare*0.54))
  $keyWidth=[int][Math]::Max(110,[Math]::Min(330,$spare-$urlWidth))
  $x=10
  $lblUrl.Left=$x;$x+=$lblUrl.Width+$gap
  $txtUrl.Left=$x;$txtUrl.Width=$urlWidth;$x+=$urlWidth+$gap*2
  $lblKey.Left=$x;$x+=$lblKey.Width+$gap
  $txtKey.Left=$x;$txtKey.Width=$keyWidth;$x+=$keyWidth+$gap
  $showKey.Left=$x;$x+=$showKey.Width+$gap*2
  $topDivider.Top=10;$topDivider.Height=$top.Height-20;$topDivider.Left=$x;$x+=2+$gap*2
  foreach($button in @($btnConnect,$btnOpenStash,$btnStopStash)){$button.Left=$x;$x+=$button.Width+$gap}
  $globalSafetyToggle.Left=[Math]::Max($x+$gap,$width-12-$globalSafetyToggle.Width)
  $rowWidth=[Math]::Max(400,$width-30)
  $status.Width=$rowWidth
  $libraryCountTable.Width=[Math]::Max(200,$rowWidth-$btnRescan.Width-$gap)
  $btnRescan.Top=$libraryCountTable.Top+[int](($libraryCountTable.Height-$btnRescan.Height)/2)
  $btnRescan.Left=$libraryCountTable.Left+$libraryCountTable.Width+$gap
  Update-ToolkitTopBarRoundedCorners
 }finally{$script:LayingOutTopBar=$false}
}
$top.Add_Resize({Update-ToolkitTopBarLayout})
foreach($topButton in @($showKey,$btnConnect,$btnOpenStash,$btnStopStash,$btnRescan)){$topButton.Add_SizeChanged({Update-ToolkitTopBarLayout})}
$form.Add_Shown({Update-ToolkitTopBarLayout})

