   $pic.Visible=$ShowNSFW
  }
 }
 if($null -ne $script:ImagesCelebrityList){
  Write-ImagesDiagnostic "GLOBAL SAFETY: NSFW=$script:SceneScreenshotNSFW"
  Update-CelebrityImageSelection
 }
 if($null -ne $script:ImagesSlidePicture -and $null -ne $script:ImagesSlidePicture.Tag){
  Set-CelebrityImage $script:ImagesSlidePicture.Tag $script:ImagesSlidePicture
 }
 if($null -ne $script:GroupsTabs){Refresh-GroupCover}
 if($null -ne $script:PerformerSearchView){Refresh-ReplacementPerformerSearchPicture}; if($null -ne $script:SubjectViews){Refresh-SubjectPictures}
}




