$script:PerformerClipSceneMap=@{}

function Load-PerformerClips([string]$PerformerId) {
 $performerClipsGrid.Rows.Clear()
 $script:PerformerClipSceneMap=@{}
 Set-SceneScreenshot $null $performerClipScreenshot
 $lblPerformerClips.Text="Clips / Scenes"
 if([string]::IsNullOrWhiteSpace($PerformerId)){return}
 try{
  $q=@'
query PerformerSearchScenes($filter: FindFilterType, $scene_filter: SceneFilterType) {
 findScenes(filter:$filter, scene_filter:$scene_filter) {
  count
  scenes { id title date files { path size duration video_codec audio_codec width height } paths { screenshot } }
 }
}
'@
  $d=Invoke-StashGraphQL $q @{
   filter=@{per_page=-1;sort="date";direction="DESC"}
   scene_filter=@{performers=@{value=@([string]$PerformerId);modifier="INCLUDES"}}
  }
  foreach($scene in @($d.findScenes.scenes)){
   $script:PerformerClipSceneMap["$($scene.id)"]=$scene
   $title=[string]$scene.title
   if([string]::IsNullOrWhiteSpace($title) -and @($scene.files).Count){
    $title=[System.IO.Path]::GetFileNameWithoutExtension([string]$scene.files[0].path)
   }
   if([string]::IsNullOrWhiteSpace($title)){$title="Untitled scene"}
   [void]$performerClipsGrid.Rows.Add([string]$scene.id,[string]$scene.date,$title)
  }
  $lblPerformerClips.Text="Clips / Scenes ($($d.findScenes.count))"
 }catch{
  $lblPerformerClips.Text="Clips / Scenes (error)"
 }
}

