$script:SyncingDuplicateSelection=$false

function Sync-DuplicateGridSelection {
 param($SourceGrid,$TargetGrid)
 if($script:SyncingDuplicateSelection){return}
 if($SourceGrid.SelectedRows.Count -eq 0){return}
 try{
  $script:SyncingDuplicateSelection=$true
  $field=[string]$SourceGrid.SelectedRows[0].Cells["Field"].Value
  $TargetGrid.ClearSelection()
  foreach($row in $TargetGrid.Rows){
   if([string]$row.Cells["Field"].Value -eq $field){
    $row.Selected=$true
    if($row.Index -ge 0){$TargetGrid.FirstDisplayedScrollingRowIndex=$row.Index}
    break
   }
  }
 } finally {
  $script:SyncingDuplicateSelection=$false
 }
}

$dupLeft.Grid.Add_SelectionChanged({Sync-DuplicateGridSelection $dupLeft.Grid $dupRight.Grid})
$dupRight.Grid.Add_SelectionChanged({Sync-DuplicateGridSelection $dupRight.Grid $dupLeft.Grid})

function Load-PictureIntoBox($p,$box) {
 $box.Image=$null
 if($null -eq $p -or [string]::IsNullOrWhiteSpace([string]$p.image_path)){return}
 try{
  $wc=New-Object System.Net.WebClient
  if(-not [string]::IsNullOrWhiteSpace((Get-StashKey))){$wc.Headers.Add("ApiKey",(Get-StashKey))}
  $bytes=$wc.DownloadData($p.image_path);$ms=New-Object System.IO.MemoryStream(,$bytes)
  $tmp=[System.Drawing.Image]::FromStream($ms);$box.Image=New-Object System.Drawing.Bitmap($tmp)
  $tmp.Dispose();$ms.Dispose();$wc.Dispose()
 }catch{}
}

function Fill-DuplicateDetails($p,$target) {
 $target.Grid.Rows.Clear();$target.Picture.Image=$null
 if($null -eq $p){return}
 $target.Label.Text=$p.name
 Load-PictureIntoBox $p $target.Picture
 $vals=[ordered]@{
  "ID"=$p.id;"Name"=$p.name;"Disambiguation"=$p.disambiguation
  "Aliases"=($p.alias_list -join ", ");"Gender"=$p.gender;"Birthdate"=$p.birthdate
  "Age"=(Get-AgeText $p);"Country"=$p.country;"Ethnicity"=$p.ethnicity
  "Height (cm)"=$p.height_cm;"Measurements"=$p.measurements;"Career"=$p.career_length
  "Tattoos"=$p.tattoos;"Piercings"=$p.piercings;"Favourite"=$p.favorite
  "Rating / 100"=$p.rating100;"Scenes"=$p.scene_count;"Images"=$p.image_count
  "Galleries"=$p.gallery_count;"Tags"=(($p.tags|ForEach-Object{$_.name}) -join ", ")
  "URL"=$p.url;"Stash IDs"=(($p.stash_ids|ForEach-Object{"$($_.stash_id) [$($_.endpoint)]"}) -join "; ")
  "Created"=$p.created_at;"Updated"=$p.updated_at;"Details"=$p.details
 }
 foreach($k in $vals.Keys){[void]$target.Grid.Rows.Add($k,(Format-Value $vals[$k]))}
}


function Format-ByteSize([double]$Bytes) {
    if($Bytes -ge 1TB){return ("{0:N2} TiB" -f ($Bytes/1TB))}
    if($Bytes -ge 1GB){return ("{0:N2} GiB" -f ($Bytes/1GB))}
    if($Bytes -ge 1MB){return ("{0:N1} MiB" -f ($Bytes/1MB))}
    if($Bytes -ge 1KB){return ("{0:N2} KiB" -f ($Bytes/1KB))}
    return ("{0:N0} B" -f $Bytes)
}

function Format-Duration([double]$Seconds) {
    if($Seconds -le 0){return "0s"}
    $ts=[TimeSpan]::FromSeconds($Seconds)
    $parts=@()
    if($ts.Days -gt 0){
        $months=[Math]::Floor($ts.Days/30)
        $days=$ts.Days%30
        if($months -gt 0){$parts+=("${months}mo")}
        $weeks=[Math]::Floor($days/7)
        $days=$days%7
        if($weeks -gt 0){$parts+=("${weeks}w")}
        if($days -gt 0){$parts+=("${days}d")}
    }
    if($ts.Hours -gt 0){$parts+=("$($ts.Hours)h")}
    if($ts.Minutes -gt 0){$parts+=("$($ts.Minutes)m")}
    if($parts.Count -eq 0){$parts+=("$([Math]::Floor($ts.TotalSeconds))s")}
    return ($parts -join " ")
}

function Format-Percent([double]$Have,[double]$Total) {
    if($Total -le 0){return "0.00%"}
    return ("{0:N2}%" -f (($Have/$Total)*100))
}

