function Get-StatAccent([string]$Key) {
    if($Key -match "Performers$|Performer Stash IDs|Performer images"){return [System.Drawing.Color]::FromArgb(255,88,181)}
    if($Key -match "Favorite"){return [System.Drawing.Color]::FromArgb(48,151,255)}
    if($Key -match "Images size"){return [System.Drawing.Color]::FromArgb(61,226,117)}
    if($Key -match "^Images$"){return [System.Drawing.Color]::FromArgb(255,191,45)}
    if($Key -match "Galleries"){return [System.Drawing.Color]::FromArgb(161,92,255)}
    if($Key -match "Studios$"){return [System.Drawing.Color]::FromArgb(255,91,91)}
    if($Key -match "Tags$"){return [System.Drawing.Color]::FromArgb(65,231,173)}
    if($Key -match "Total O-count"){return [System.Drawing.Color]::FromArgb(255,168,42)}
    if($Key -match "Total play count"){return [System.Drawing.Color]::FromArgb(151,83,255)}
    if($Key -match "Scenes played"){return [System.Drawing.Color]::FromArgb(255,80,181)}
    if($Key -match "Total play duration"){return [System.Drawing.Color]::FromArgb(33,218,232)}
    if($Key -match "Markers"){return [System.Drawing.Color]::FromArgb(160,202,244)}
    if($Key -match "Scene Stash IDs|Scenes HD"){return [System.Drawing.Color]::FromArgb(151,87,255)}
    if($Key -match "Studio Stash IDs"){return [System.Drawing.Color]::FromArgb(93,230,121)}
    if($Key -match "Tag images"){return [System.Drawing.Color]::FromArgb(47,148,235)}
    if($Key -match "Studio images"){return [System.Drawing.Color]::FromArgb(26,225,229)}
    if($Key -match "Movie covers"){return [System.Drawing.Color]::FromArgb(35,157,246)}
    if($Key -match "^Scenes$"){return [System.Drawing.Color]::FromArgb(42,154,255)}
    return [System.Drawing.Color]::FromArgb(26,213,235)
}

function New-StatCard([string]$Key,[string]$Caption,[bool]$Completeness=$false) {
    $card=New-Object System.Windows.Forms.Panel
    $card.BackColor=[System.Drawing.Color]::FromArgb(30,48,61)
    $card.BorderStyle=[System.Windows.Forms.BorderStyle]::FixedSingle
    $card.Margin=New-Object System.Windows.Forms.Padding(0)
    $card.Tag=[PSCustomObject]@{Key=$Key;Completeness=$Completeness}

    $accent=Get-StatAccent $Key
    $accentBar=New-Object System.Windows.Forms.Panel
    $accentBar.Name="Accent"
    $accentBar.Dock=[System.Windows.Forms.DockStyle]::Top
    $accentBar.Height=4
    $accentBar.BackColor=$accent

    $icon=New-Object System.Windows.Forms.Label
    $icon.Name="Icon"
    $iconText=switch -Regex ($Key) {
        "^Scenes size$" {"●";break}
        "^Scenes$" {"▣";break}
        "duration" {"◷";break}
        "Performer|Favorite" {"★";break}
        "Image" {"▧";break}
        "Galler" {"▣";break}
        "Studio" {"◆";break}
        "Tag" {"◆";break}
        "play|O-count" {"▶";break}
        "Marker" {"▮";break}
        default {"◆"}
    }
    $icon.Text=[string]$iconText
    $icon.TextAlign=[System.Drawing.ContentAlignment]::MiddleCenter
    $icon.Font=New-Object System.Drawing.Font("Segoe UI Symbol",17,[System.Drawing.FontStyle]::Bold)
    $icon.ForeColor=$accent

    $value=New-Object System.Windows.Forms.Label
    $value.Name="Value"
    $value.Text="—"
    $value.TextAlign=[System.Drawing.ContentAlignment]::BottomCenter
    $value.Font=New-Object System.Drawing.Font("Comic Sans MS",27,[System.Drawing.FontStyle]::Regular)
    $value.ForeColor=[System.Drawing.Color]::FromArgb(247,249,250)

    $label=New-Object System.Windows.Forms.Label
    $label.Name="Caption"
    $label.Text=$Caption.ToUpperInvariant()
    $label.TextAlign=[System.Drawing.ContentAlignment]::TopCenter
    $label.Font=New-Object System.Drawing.Font("Segoe UI Semibold",8.5,[System.Drawing.FontStyle]::Regular)
    $label.ForeColor=[System.Drawing.Color]::FromArgb(190,207,216)

    [void]$card.Controls.Add($icon)
    [void]$card.Controls.Add($value)
    [void]$card.Controls.Add($label)
    [void]$card.Controls.Add($accentBar)

    if($Completeness){
        $track=New-Object System.Windows.Forms.Panel
        $track.Name="Track"
        $track.Height=5
        $track.BackColor=[System.Drawing.Color]::FromArgb(58,73,82)

        $fill=New-Object System.Windows.Forms.Panel
        $fill.Name="Fill"
        $fill.Dock=[System.Windows.Forms.DockStyle]::Left
        $fill.Width=0
        $fill.BackColor=$accent
        [void]$track.Controls.Add($fill)
        [void]$card.Controls.Add($track)
    }

    $statsCards[$Key]=$value
    return $card
}

