function Set-StatCardValue([string]$Key,[string]$Text) {
    if(-not $statsCards.ContainsKey($Key)){return}
    $display=$Text

    # Clean percentage presentation: 100.00% -> 100%, 87.40% -> 87.4%.
    if($display -match '^([0-9]+(?:\.[0-9]+)?)%$'){
        $num=[double]$matches[1]
        if([Math]::Abs($num-[Math]::Round($num)) -lt 0.001){
            $display=("{0:0}%" -f $num)
        }else{
            $display=("{0:0.#}%" -f $num)
        }
    }

    $statsCards[$Key].Text=$display
    if($null -ne $statsDashboard){$statsDashboard.Invalidate()}

    # Long values shrink slightly so they stay balanced inside the card.
    $size=27
    if($display.Length -ge 10){$size=20}
    elseif($display.Length -ge 7){$size=23}
    $statsCards[$Key].Font=New-Object System.Drawing.Font("Comic Sans MS",$size,[System.Drawing.FontStyle]::Regular)

    # Update the mini completion bar where this is a percentage card.
    $card=$statsCards[$Key].Parent
    $track=$card.Controls["Track"]
    if($null -ne $track){
        $pct=0
        if($display -match '^([0-9]+(?:\.[0-9]+)?)%$'){$pct=[double]$matches[1]}
        $pct=[Math]::Max(0,[Math]::Min(100,$pct))
        $fill=$track.Controls["Fill"]
        if($null -ne $fill){
            $fill.Width=[Math]::Floor(($track.ClientSize.Width*$pct)/100)
        }
    }
}

