function New-RoundedPath([System.Drawing.RectangleF]$r,[float]$radius){
    $p=New-Object System.Drawing.Drawing2D.GraphicsPath
    $d=$radius*2
    $p.AddArc($r.X,$r.Y,$d,$d,180,90)
    $p.AddArc($r.Right-$d,$r.Y,$d,$d,270,90)
    $p.AddArc($r.Right-$d,$r.Bottom-$d,$d,$d,0,90)
    $p.AddArc($r.X,$r.Bottom-$d,$d,$d,90,90)
    $p.CloseFigure()
    return $p
}

function Get-StatsDisplay([string]$key){
    if($statsCards.ContainsKey($key)){return [string]$statsCards[$key].Text}
    return "—"
}

$statsDashboard.Add_Paint({
    param($sender,$e)
    $g=$e.Graphics
    $g.SmoothingMode=[System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $g.TextRenderingHint=[System.Drawing.Text.TextRenderingHint]::ClearTypeGridFit
    $g.Clear([System.Drawing.Color]::FromArgb(8,31,47))

    $w=[float]$sender.ClientSize.Width
    $h=[float]$sender.ClientSize.Height
    if($w -lt 50 -or $h -lt 50){return}

    # Preserve the exact proportions of the 1756x864 approved mock-up.
    # On very wide monitors the old renderer stretched only horizontally,
    # making the whole dashboard look short and compressed.
    $designW=1756.0
    $designH=864.0
    $scale=[Math]::Min($w/$designW,$h/$designH)
    $offsetX=($w-($designW*$scale))/2.0
    $offsetY=0.0

    $state=$g.Save()
    $g.TranslateTransform([single]$offsetX,[single]$offsetY)
    $g.ScaleTransform([single]$scale,[single]$scale)

    function X([double]$n){return [float]$n}
    function W([double]$n){return [float]$n}

    $white=[System.Drawing.Color]::FromArgb(247,250,253)
    $muted=[System.Drawing.Color]::FromArgb(169,204,230)
    $line=[System.Drawing.Color]::FromArgb(92,157,194)
    $cardBg=[System.Drawing.Color]::FromArgb(15,43,61)
    $cardBorder=[System.Drawing.Color]::FromArgb(43,91,119)

    $titleFont=New-Object System.Drawing.Font("Comic Sans MS",20,[System.Drawing.FontStyle]::Bold)
    $subFont=New-Object System.Drawing.Font("Comic Sans MS",9,[System.Drawing.FontStyle]::Regular)
    $sectionFont=New-Object System.Drawing.Font("Comic Sans MS",10,[System.Drawing.FontStyle]::Bold)
    $valueFont=New-Object System.Drawing.Font("Comic Sans MS",20,[System.Drawing.FontStyle]::Regular)
    $valueSmall=New-Object System.Drawing.Font("Comic Sans MS",17,[System.Drawing.FontStyle]::Regular)
    $captionFont=New-Object System.Drawing.Font("Segoe UI Symbol",8.5,[System.Drawing.FontStyle]::Regular)
    $iconFont=New-Object System.Drawing.Font("Segoe UI Symbol",18,[System.Drawing.FontStyle]::Bold)

    $sfCenter=New-Object System.Drawing.StringFormat
    $sfCenter.Alignment=[System.Drawing.StringAlignment]::Center
    $sfCenter.LineAlignment=[System.Drawing.StringAlignment]::Center

    $sfLeft=New-Object System.Drawing.StringFormat
    $sfLeft.Alignment=[System.Drawing.StringAlignment]::Near
    $sfLeft.LineAlignment=[System.Drawing.StringAlignment]::Center

    $bWhite=New-Object System.Drawing.SolidBrush($white)
    $bMuted=New-Object System.Drawing.SolidBrush($muted)
    $bCard=New-Object System.Drawing.SolidBrush($cardBg)
    $pBorder=New-Object System.Drawing.Pen($cardBorder,1)
    $pLine=New-Object System.Drawing.Pen($line,1)

    $g.DrawString("STASH LIBRARY OVERVIEW",$titleFont,$bWhite,(X 24),10)
    $g.DrawString("A visual snapshot of your scenes, performers, images, playback and library completeness.",$subFont,$bMuted,(X 24),61)

    $g.DrawString("LIBRARY & ACTIVITY",$sectionFont,$bWhite,(X 24),103)
    $g.DrawLine($pLine,(X 270),118,(X 1732),118)

    $main=@(
        @("Scenes size","SCENES SIZE","●",75,138,322,122),
        @("Scenes","SCENES","▣",510,138,322,122),
        @("Scenes duration","SCENES DURATION","◷",927,138,322,122),
        @("Performers","PERFORMERS","♣",1365,138,318,122),

        @("Images size","IMAGES SIZE","▧",35,279,296,122),
        @("Galleries","GALLERIES","▣",395,279,294,122),
        @("Images","IMAGES","⌂",738,279,288,122),
        @("Studios","STUDIOS","▣",1073,279,293,122),
        @("Tags","TAGS","◆",1425,279,298,122),

        @("Total O-count","TOTAL O-COUNT","☷",31,422,247,122),
        @("Total play count","TOTAL PLAY COUNT","▶",322,422,247,122),
        @("Scenes played","SCENES PLAYED","▣",615,422,247,122),
        @("Total play duration","TOTAL PLAY DURATION","◷",906,422,247,122),
        @("Favorite performers","FAVORITE PERFORMERS","★",1198,422,245,122),
        @("Markers","MARKERS","▮",1484,422,240,122)
    )

    foreach($m in $main){
        $key=[string]$m[0]; $caption=[string]$m[1]; $ico=[string]$m[2]
        $rx=X $m[3]; $ry=[float]$m[4]; $rw=W $m[5]; $rh=[float]$m[6]
        $accent=Get-StatAccent $key
        $r=[System.Drawing.RectangleF]::new([single]$rx,[single]$ry,[single]$rw,[single]$rh)
        $path=New-RoundedPath $r 10
        $g.FillPath($bCard,$path)
        $g.DrawPath($pBorder,$path)
        $accentPen=New-Object System.Drawing.Pen($accent,5)
        $g.DrawLine($accentPen,$rx+7,$ry+2,$rx+$rw-7,$ry+2)

        $ib=New-Object System.Drawing.SolidBrush($accent)
        $g.DrawString($ico,$iconFont,$ib,([System.Drawing.RectangleF]::new([single]$rx,[single]($ry+9),[single]$rw,[single]31)),$sfCenter)

        $val=Get-StatsDisplay $key
        $vf=$valueFont
        if($val.Length -ge 10){$vf=$valueSmall}
        $g.DrawString($val,$vf,$bWhite,([System.Drawing.RectangleF]::new([single]($rx+5),[single]($ry+42),[single]($rw-10),[single]46)),$sfCenter)
        $g.DrawString($caption,$captionFont,$bWhite,([System.Drawing.RectangleF]::new([single]($rx+5),[single]($ry+91),[single]($rw-10),[single]22)),$sfCenter)

        $ib.Dispose();$accentPen.Dispose();$path.Dispose()
    }

    $g.DrawString("LIBRARY COMPLETENESS",$sectionFont,$bWhite,(X 24),566)
    $g.DrawLine($pLine,(X 345),581,(X 1732),581)

    $complete=@(
        @("Scene Stash IDs","SCENE STASH IDS",42,604,311,95),
        @("Studio Stash IDs","STUDIO STASH IDS",385,604,309,95),
        @("Performer Stash IDs","PERFORMER STASH IDS",726,604,309,95),
        @("Tag images","TAG IMAGES",1068,604,313,95),
        @("Studio images","STUDIO IMAGES",1412,604,310,95),
        @("Performer images","PERFORMER IMAGES",320,719,327,95),
        @("Movie covers","MOVIE COVERS",719,719,324,95),
        @("Scenes HD","SCENES HD",1115,719,324,95)
    )

    foreach($m in $complete){
        $key=[string]$m[0];$caption=[string]$m[1]
        $rx=X $m[2];$ry=[float]$m[3];$rw=W $m[4];$rh=[float]$m[5]
        $accent=Get-StatAccent $key
        $r=[System.Drawing.RectangleF]::new([single]$rx,[single]$ry,[single]$rw,[single]$rh)
        $path=New-RoundedPath $r 10
        $g.FillPath($bCard,$path);$g.DrawPath($pBorder,$path)
        $accentPen=New-Object System.Drawing.Pen($accent,5)
        $g.DrawLine($accentPen,$rx+7,$ry+2,$rx+$rw-7,$ry+2)

        $val=Get-StatsDisplay $key
        $g.DrawString($val,$valueSmall,$bWhite,([System.Drawing.RectangleF]::new([single]($rx+5),[single]($ry+16),[single]($rw-10),[single]38)),$sfCenter)
        $g.DrawString($caption,$captionFont,$bWhite,([System.Drawing.RectangleF]::new([single]($rx+5),[single]($ry+53),[single]($rw-10),[single]20)),$sfCenter)

        $trackR=[System.Drawing.RectangleF]::new([single]($rx+16),[single]($ry+78),[single]($rw-32),[single]8)
        $trackPath=New-RoundedPath $trackR 5
        $trackBrush=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(25,65,91))
        $g.FillPath($trackBrush,$trackPath)

        $pct=0.0
        if($val -match '^([0-9]+(?:\.[0-9]+)?)%$'){$pct=[double]$matches[1]}
        $pct=[Math]::Max(0,[Math]::Min(100,$pct))
        if($pct -gt 0){
            $fillW=[float](($rw-32)*$pct/100.0)
            $fillR=[System.Drawing.RectangleF]::new([single]($rx+16),[single]($ry+78),[single]$fillW,[single]8)
            $fillPath=New-RoundedPath $fillR 5
            $fillBrush=New-Object System.Drawing.SolidBrush($accent)
            $g.FillPath($fillBrush,$fillPath)
            $fillBrush.Dispose();$fillPath.Dispose()
        }

        $trackBrush.Dispose();$trackPath.Dispose();$accentPen.Dispose();$path.Dispose()
    }

    $pBorder.Dispose();$pLine.Dispose();$bCard.Dispose();$bWhite.Dispose();$bMuted.Dispose()
    $titleFont.Dispose();$subFont.Dispose();$sectionFont.Dispose();$valueFont.Dispose()
    $valueSmall.Dispose();$captionFont.Dispose();$iconFont.Dispose()
    $sfCenter.Dispose();$sfLeft.Dispose()
    $g.Restore($state)
})

