}
Update-PerformerTagResultHint
$script:TagPerformerMap=@{}
$script:TagSceneMap=@{}

function Load-TagBrowser {
 try{
  if(-not $script:IsConnected){
   $tagList.Items.Clear()
   $tagGrid.Rows.Clear()
   return
  }

  $status.Text="Loading tags from scenes..."
  [System.Windows.Forms.Application]::DoEvents()

  # Stash's performer page "Top Tags" are derived from the tags on scenes
  # containing that performer. Build the browser from scene tags/performers,
  # rather than only the tags assigned directly to Performer objects.
  $q=@'
query ToolkitTagBrowser($filter: FindFilterType) {
 findScenes(filter:$filter) {
  count
  scenes {
   id
   title
   date
   files { path }
   tags { id name }
   performers { id name }
  }
 }
}
'@
  $d=Invoke-StashGraphQL $q @{filter=@{per_page=-1;sort="title";direction="ASC"}}

  $script:TagPerformerMap=@{}
  $script:TagSceneMap=@{}
  foreach($scene in @($d.findScenes.scenes)){
   foreach($tag in @($scene.tags)){
    $tagName=[string]$tag.name
    if([string]::IsNullOrWhiteSpace($tagName)){continue}

    if(-not $script:TagPerformerMap.ContainsKey($tagName)){
     $script:TagPerformerMap[$tagName]=@{}
    }

    foreach($p in @($scene.performers)){
     $performerId=[string]$p.id
     if(-not [string]::IsNullOrWhiteSpace($performerId)){
      $script:TagPerformerMap[$tagName][$performerId]=[string]$p.name

      $mapKey=$tagName+"|"+$performerId
      if(-not $script:TagSceneMap.ContainsKey($mapKey)){
       $script:TagSceneMap[$mapKey]=@{}
      }
      $sceneTitle=[string]$scene.title
      if([string]::IsNullOrWhiteSpace($sceneTitle) -and @($scene.files).Count -gt 0){
       $sceneTitle=[System.IO.Path]::GetFileNameWithoutExtension([string]$scene.files[0].path)
      }
      if([string]::IsNullOrWhiteSpace($sceneTitle)){$sceneTitle="Untitled scene"}
      $script:TagSceneMap[$mapKey][[string]$scene.id]=[PSCustomObject]@{
       ID=[string]$scene.id
       Date=[string]$scene.date
       Title=$sceneTitle
      }
     }
    }
   }
  }

  $tagNames=@($script:TagPerformerMap.Keys | Sort-Object)

  $tagList.BeginUpdate()
  $tagList.Items.Clear()
  foreach($tagName in $tagNames){[void]$tagList.Items.Add($tagName)}
  $tagList.EndUpdate()

  $tagGrid.Rows.Clear()
  $lblTags.Text="Tags ($($tagNames.Count))"
  $lblTagPerformers.Text="Performers"
  Update-PerformerTagResultHint
  $status.Text="Loaded $($tagNames.Count) scene tag(s)."

  if($tagNames.Count -eq 0){
   [ToolkitMessageDialog]::Show(
    "No scene tags were returned by Stash.",
    "Tag Search","OK","Information"
   ) | Out-Null
  }
 }catch{
  [ToolkitMessageDialog]::Show(
   "Could not load tags from Stash.`r`n`r`n$($_.Exception.Message)",
   "Tag Search","OK","Error"
  ) | Out-Null
 }
}

function Show-PerformersForTag([string]$TagName) {
 $tagGrid.Rows.Clear()
 $tagSceneGrid.Rows.Clear()
 $lblTagScenes.Text="Scenes"
 if([string]::IsNullOrWhiteSpace($TagName)){return}
 if(-not $script:TagPerformerMap.ContainsKey($TagName)){return}

 $performers=$script:TagPerformerMap[$TagName]
 foreach($performerId in @($performers.Keys | Sort-Object {$performers[$_]})){
  [void]$tagGrid.Rows.Add([string]$performerId,[string]$performers[$performerId])
 }

 $lblTagPerformers.Text="Performers with '$TagName' ($($tagGrid.Rows.Count))"
 Update-PerformerTagResultHint
 $status.Text="$($tagGrid.Rows.Count) performer(s) appear in scenes tagged '$TagName'."
}

function Show-ScenesForTagPerformer([string]$TagName,[string]$PerformerId,[string]$PerformerName) {
 $tagSceneGrid.Rows.Clear()
 if([string]::IsNullOrWhiteSpace($TagName) -or [string]::IsNullOrWhiteSpace($PerformerId)){return}

 $mapKey=$TagName+"|"+$PerformerId
 if($script:TagSceneMap.ContainsKey($mapKey)){
  $scenes=$script:TagSceneMap[$mapKey]
  foreach($sceneId in @($scenes.Keys | Sort-Object {$scenes[$_].Date} -Descending)){
   $s=$scenes[$sceneId]
   [void]$tagSceneGrid.Rows.Add($s.ID,$s.Date,$s.Title)
  }
 }
 $lblTagScenes.Text="Scenes for $PerformerName ($($tagSceneGrid.Rows.Count))"
 Update-PerformerTagResultHint
}

$tagList.Add_SelectedIndexChanged({
 $tagGrid.Rows.Clear();$tagSceneGrid.Rows.Clear()
 $lblTagPerformers.Text='Performers';$lblTagScenes.Text='Scenes'
 Update-PerformerTagResultHint
})

