# ---------- Shared library caches ----------
# Performers already have their established cache. These caches provide the
# same idea for Scenes, Studios and Groups so later tools can reuse data
# without repeatedly querying Stash.
$script:SceneCache=@()
$script:StudioCache=@()
$script:GroupCache=@()
$script:SceneCacheLoaded=$false
$script:StudioCacheLoaded=$false
$script:GroupCacheLoaded=$false
$script:SceneScreenshotNSFW=$false
$script:ToolkitImages=New-Object System.Collections.Generic.List[System.Windows.Forms.PictureBox]


function Clear-ExtendedLibraryCaches {
 $script:CelebrityImages=@();$script:ToolkitImagesMetadataLoaded=$false
    $script:SceneCache=@()
    $script:StudioCache=@()
    $script:GroupCache=@()
    $script:SceneCacheLoaded=$false
    $script:StudioCacheLoaded=$false
    $script:GroupCacheLoaded=$false
}

function Load-SceneCache {
    if(-not $script:IsConnected){return 0}
    $q=@'
query ToolkitSceneCache($filter: FindFilterType) {
  findScenes(filter:$filter) {
    count
    scenes {
      id
      title
      date
      rating100
      organized
      created_at
      updated_at
      files { path size duration video_codec audio_codec width height }
      paths { screenshot }
      studio { id name }
      performers { id name }
      tags { id name }
      groups { group { id name } scene_index }
    }
  }
}
'@
    try {
        $d=Invoke-StashGraphQL $q @{filter=@{per_page=-1;sort="title";direction="ASC"}}
        $script:SceneCache=@($d.findScenes.scenes)
        $script:SceneCacheLoaded=$true
        return $script:SceneCache.Count
    } catch {
        $script:SceneCacheLoaded=$false
        throw
    }
}

function Load-StudioCache {
    if(-not $script:IsConnected){return 0}
    $q=@'
query ToolkitStudioCache($filter: FindFilterType) {
  findStudios(filter:$filter) {
    count
    studios {
      id
      name
      url
      image_path
      scene_count
      image_count
      gallery_count
      performer_count
      created_at
      updated_at
      parent_studio { id name }
      tags { id name }
      stash_ids { stash_id endpoint }
    }
  }
}
'@
    try {
        $d=Invoke-StashGraphQL $q @{filter=@{per_page=-1;sort="name";direction="ASC"}}
        $script:StudioCache=@($d.findStudios.studios)
        $script:StudioCacheLoaded=$true
        return $script:StudioCache.Count
    } catch {
        $script:StudioCacheLoaded=$false
        throw
    }
}

function Load-GroupCache {
    if(-not $script:IsConnected){
        return 0
    }
    $q=@'
query ToolkitGroupCache($filter: FindFilterType) {
  findGroups(filter:$filter) {
    count
    groups {
      id
      name
      aliases
      duration
      date
      director
      synopsis
      front_image_path
      back_image_path
      scene_count
      created_at
      updated_at
      studio { id name }
      tags { id name }
    }
  }
}
'@
    try {
        $d=Invoke-StashGraphQL $q @{filter=@{per_page=-1;sort="name";direction="ASC"}}
        $script:GroupCache=@($d.findGroups.groups)
        $script:GroupCacheLoaded=$true
        return $script:GroupCache.Count
    } catch {
        $script:GroupCacheLoaded=$false
        throw
    }
}
function Get-ToolkitImageCount {
    try {
        $q=@'
query ToolkitImageCount($filter: FindFilterType) {
  findImages(filter:$filter) { count }
}
'@
        $d=Invoke-StashGraphQL $q @{filter=@{per_page=1}}
        return [int]$d.findImages.count
    } catch {
        return 0
    }
}

