function Load-ExtendedLibraryCaches {
    $cacheForm=New-Object ToolkitDialogWindow
    $cacheForm.Text="Building Stash Toolkit Cache"
    $cacheForm.Size=New-Object System.Drawing.Size(610,350)
    $cacheForm.StartPosition="Manual"
    $cacheForm.Location=New-Object System.Drawing.Point(
        ($form.Left+[int](($form.Width-$cacheForm.Width)/2)),
        ($form.Top+120)
    )
    $cacheForm.FormBorderStyle="FixedDialog"
    $cacheForm.MaximizeBox=$false
    $cacheForm.MinimizeBox=$false
    $cacheForm.ControlBox=$false
    $cacheForm.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)

    $cacheTitle=New-Object System.Windows.Forms.Label
    $cacheTitle.Text="UPDATING LIBRARY CACHE"
    $cacheTitle.Location=New-Object System.Drawing.Point(25,20)
    $cacheTitle.Size=New-Object System.Drawing.Size(545,46)
    $cacheTitle.Font=New-Object System.Drawing.Font("Comic Sans MS",15,[System.Drawing.FontStyle]::Bold)
    $cacheTitle.ForeColor=[System.Drawing.Color]::White

    $cacheCurrent=New-Object System.Windows.Forms.Label
    $cacheCurrent.Location=New-Object System.Drawing.Point(28,76)
    $cacheCurrent.Size=New-Object System.Drawing.Size(535,26)
    $cacheCurrent.Font=New-Object System.Drawing.Font("Segoe UI",10,[System.Drawing.FontStyle]::Bold)
    $cacheCurrent.ForeColor=[System.Drawing.Color]::FromArgb(73,207,232)

    $cacheProgress=New-Object System.Windows.Forms.ProgressBar
    $cacheProgress.Location=New-Object System.Drawing.Point(30,112)
    $cacheProgress.Size=New-Object System.Drawing.Size(530,24)
    $cacheProgress.Minimum=0
    $cacheProgress.Maximum=5
    $cacheProgress.Style="Blocks"

    $cacheResults=New-Object System.Windows.Forms.Label
    $cacheResults.Location=New-Object System.Drawing.Point(30,151)
    $cacheResults.Size=New-Object System.Drawing.Size(530,150)
    $cacheResults.Font=New-Object System.Drawing.Font("Segoe UI",9.5)
    $cacheResults.ForeColor=[System.Drawing.Color]::FromArgb(188,211,226)

    [void]$cacheForm.Controls.AddRange(@($cacheTitle,$cacheCurrent,$cacheProgress,$cacheResults))
    $cacheForm.Show($form)
    [System.Windows.Forms.Application]::DoEvents()

    $performerCount=0;$sceneCount=0;$studioCount=0;$groupCount=0;$imageCount=0
    $failures=@()

    try {
        $steps=@(
            @('Scenes','Load-SceneCache'),
            @('Groups','Load-GroupCache'),
            @('Performers','Load-AllPerformers'),
            @('Studios','Load-StudioCache'),
            @('Images','Load-ToolkitImageCache')
        )
        $results=[ordered]@{Scenes='Waiting';Groups='Waiting';Performers='Waiting';Studios='Waiting';Images='Waiting'}
        $cacheResults.Text=($results.Keys | ForEach-Object {"$($_): $($results[$_])"}) -join "`r`n"
        for($index=0;$index -lt $steps.Count;$index++){
            $subject=$steps[$index][0];$loader=$steps[$index][1]
            $cacheCurrent.Text="$($index+1) of 5  •  Caching $subject..."
            $status.Text="Caching $($subject.ToLower())..."
            $results[$subject]='Loading...'
            $cacheResults.Text=($results.Keys | ForEach-Object {"$($_): $($results[$_])"}) -join "`r`n"
            $cacheResults.Refresh();[System.Windows.Forms.Application]::DoEvents()
            try{
                $count=& $loader
                $results[$subject]="$count cached"
                switch($subject){'Scenes'{$sceneCount=$count};'Groups'{$groupCount=$count};'Performers'{$performerCount=$count};'Studios'{$studioCount=$count};'Images'{$imageCount=$count}}
            }catch{$failures+=$subject;$results[$subject]='Failed'}
            $cacheProgress.Value=$index+1
            $cacheResults.Text=($results.Keys | ForEach-Object {"$($_): $($results[$_])"}) -join "`r`n"
            $cacheResults.Refresh();[System.Windows.Forms.Application]::DoEvents()
        }
        if($failures.Count -eq 0){
            $cacheCurrent.Text="CACHE READY"
            $status.Text="$sceneCount scenes, $groupCount groups, $performerCount performers, $studioCount studios and $imageCount images cached"
        } else {
            $cacheCurrent.Text="CACHE COMPLETED WITH A PROBLEM"
            $status.Text="Cache issue: "+($failures -join ", ")
            $cacheResults.Text += "`r`nCould not cache: "+($failures -join ", ")
        }
        [System.Windows.Forms.Application]::DoEvents()
        $cacheCloseAt=[DateTime]::UtcNow.AddSeconds(3)
        while([DateTime]::UtcNow -lt $cacheCloseAt){
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 50
        }
    } finally {
        $cacheForm.Close()
        $cacheForm.Dispose()
    }
}

# ---------- Universal scene right-click ----------
# Any DataGridView that contains a scene ID now gets the same "Go to Scene"
# context-menu action. This is deliberately generic so new search grids inherit
# the behaviour without each section needing its own custom handler.
function Get-SceneIdFromGridRow([System.Windows.Forms.DataGridView]$Grid,[System.Windows.Forms.DataGridViewRow]$Row) {
    if($null -eq $Grid -or $null -eq $Row){return $null}

    $candidateNames=@("SceneID","Scene ID","SceneId","scene_id","sceneid")
    foreach($name in $candidateNames){
        if($Grid.Columns[$name] -ne $null){
            $v=$Row.Cells[$name].Value
            if($null -ne $v -and "$v".Trim() -ne ""){return "$v".Trim()}
        }
    }

    # Some scene-only result grids simply use ID.
    if($Grid.Columns["ID"] -ne $null){
        $looksSceneGrid=($Grid.Name -match "scene|clip") -or
                        ($Grid.Columns["Scene"] -ne $null) -or
                        ($Grid.Columns["Clip/Scene"] -ne $null) -or
                        ($Grid.Columns["Title"] -ne $null -and $Grid.Name -match "result")
        if($looksSceneGrid){
            $v=$Row.Cells["ID"].Value
            if($null -ne $v -and "$v".Trim() -ne ""){return "$v".Trim()}
        }
    }
    return $null
}

function Enable-SceneContextMenu([System.Windows.Forms.DataGridView]$Grid) {
    if($null -eq $Grid -or $Grid.Tag -eq "SceneContextEnabled"){return}

    $menu=New-Object System.Windows.Forms.ContextMenuStrip
    $go=New-Object System.Windows.Forms.ToolStripMenuItem
    $go.Text="Go to Scene"
    $go.Enabled=$false
    [void]$menu.Items.Add($go)

    $Grid.Add_CellMouseDown({
        param($sender,$e)
        if($e.Button -ne [System.Windows.Forms.MouseButtons]::Right -or $e.RowIndex -lt 0){return}
        $sender.ClearSelection()
        $sender.Rows[$e.RowIndex].Selected=$true
        if($e.ColumnIndex -ge 0){$sender.CurrentCell=$sender.Rows[$e.RowIndex].Cells[$e.ColumnIndex]}
        $sceneId=Get-SceneIdFromGridRow $sender $sender.Rows[$e.RowIndex]
        $go.Enabled=($null -ne $sceneId)
        $go.Tag=$sceneId
    }.GetNewClosure())

    $go.Add_Click({
        $sceneId="$($go.Tag)".Trim()
        if($sceneId -ne ""){
            Open-StashToolkitLink ((Get-StashUrl)+"/scenes/"+$sceneId)
        }
    }.GetNewClosure())

    $Grid.ContextMenuStrip=$menu
    $Grid.Tag="SceneContextEnabled"
}

function Enable-SceneContextMenusRecursive([System.Windows.Forms.Control]$Parent) {
    foreach($control in @($Parent.Controls)){
        if($control -is [System.Windows.Forms.DataGridView]){
            Enable-SceneContextMenu $control
        }
        if($control.HasChildren){
            Enable-SceneContextMenusRecursive $control
        }
    }
}

