# Troubleshooting log for the Images section. Off by default; set this to
# $true to record each image request in the log below.
$script:ImagesDiagnosticsEnabled=$false
$script:ImagesDiagnosticLog=Join-Path $script:ToolkitDataFolder "Logs\Stash-Toolkit-Images-Diagnostic.log"
function Write-ImagesDiagnostic([string]$Stage,[object]$ErrorObject=$null){
 if(-not $script:ImagesDiagnosticsEnabled -and $null -eq $ErrorObject){return}
 try{
  [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($script:ImagesDiagnosticLog))
  $stamp=Get-Date -Format "yyyy-MM-dd HH:mm:ss"
  $detail=if($null -ne $ErrorObject){"$ErrorObject`r`n$($ErrorObject.ScriptStackTrace)"}else{"OK"}
  [IO.File]::AppendAllText($script:ImagesDiagnosticLog,"[$stamp] $Stage`r`n$detail`r`n----------------------------------------`r`n")
 }catch{
  # Logging is optional and must never interrupt the toolkit.
 }
}


function Get-CelebrityImages {
 $q=@'
query ToolkitImageDiagnostic {
 findImages(filter:{per_page:-1}) {
  count
  images {
   id
   title
   date
   created_at
   updated_at
   paths { image thumbnail }
   files { path size width height }
   performers { id name }
   tags { id name }
   studio { id name }
  }
 }
}
'@
 try {
  Write-ImagesDiagnostic "DIAG: requesting images with title/files/performers/tags/studio"
  $d=Invoke-StashGraphQL $q @{}
  if($null -eq $d -or $null -eq $d.findImages){
   Write-ImagesDiagnostic "DIAG: GraphQL returned no findImages object"
   return @()
  }
  $imgs=@($d.findImages.images)
  Write-ImagesDiagnostic "DIAG: Stash reports count=$($d.findImages.count); returned=$($imgs.Count)"

  $sample=@($imgs | Select-Object -First 12)
  $n=0
  foreach($im in $sample){
   $n++
   $filePath=if(@($im.files).Count){"$($im.files[0].path)"}else{"<none>"}
   $performerNames=@($im.performers | ForEach-Object {"$($_.name)"}) -join " | "
   $tagNames=@($im.tags | ForEach-Object {"$($_.name)"}) -join " | "
   $studioName=if($null -ne $im.studio){"$($im.studio.name)"}else{"<none>"}
   $msg=@"
DIAG SAMPLE $n
ID: $($im.id)
TITLE: $($im.title)
FILE: $filePath
PERFORMERS FIELD: $performerNames
TAGS: $tagNames
STUDIO: $studioName
DERIVED CURRENT NAME: $(Get-CelebrityImageName $im)
"@
   Write-ImagesDiagnostic $msg
  }

  $withTitle=@($imgs | Where-Object {-not [string]::IsNullOrWhiteSpace("$($_.title)")}).Count
  $withPerformers=@($imgs | Where-Object {@($_.performers).Count -gt 0}).Count
  $withTags=@($imgs | Where-Object {@($_.tags).Count -gt 0}).Count
  $withFiles=@($imgs | Where-Object {@($_.files).Count -gt 0}).Count
  Write-ImagesDiagnostic "DIAG SUMMARY: title=$withTitle performers=$withPerformers tags=$withTags files=$withFiles total=$($imgs.Count)"
  return $imgs
 } catch {
  Write-ImagesDiagnostic "DIAG GRAPHQL ERROR: full image metadata query failed" $_
  [ToolkitMessageDialog]::Show(
   "Images could not be loaded from Stash.`r`n`r`n$($_.Exception.Message)",
   "Images",
   [Windows.Forms.MessageBoxButtons]::OK,
   [Windows.Forms.MessageBoxIcon]::Error
  ) | Out-Null
  return @()
 }
}
function Get-CelebrityImageName($im){
 $path=if(@($im.files).Count){"$($im.files[0].path)"}else{""}
 if(-not [string]::IsNullOrWhiteSpace($path)){
  try{
   $parent=[IO.Path]::GetFileName([IO.Path]::GetDirectoryName($path))
   if(-not [string]::IsNullOrWhiteSpace($parent)){return $parent.Trim()}
  }catch{}
 }
 $n="$($im.title)".Trim()
 if([string]::IsNullOrWhiteSpace($n) -and $path){$n=[IO.Path]::GetFileNameWithoutExtension($path)}
 if([string]::IsNullOrWhiteSpace($n)){return "Unknown"}
 $n=$n -replace '\s*[-_]\s*\d+$',''
 $n=$n -replace '\s+\d+$',''
 $n=$n -replace '\s*\(\d+\)$',''
 return $n.Trim()
}
function Set-CelebrityImage($im,$pic){
 if($null -eq $pic -or $pic.IsDisposed){Write-ImagesDiagnostic "IMAGE DISPLAY: picture control unavailable";return}
 $pic.Visible=[bool]$script:SceneScreenshotNSFW
 if($null -ne $pic.Image){$o=$pic.Image;$pic.Image=$null;$o.Dispose()}
 $pic.Tag=$im
 if($null -eq $im){Write-ImagesDiagnostic "IMAGE DISPLAY: no image object supplied";return}
 $id=[string]$im.id
 Write-ImagesDiagnostic "IMAGE DISPLAY: requested image id=$id; NSFW=$script:SceneScreenshotNSFW"
 if(-not $script:SceneScreenshotNSFW){Write-ImagesDiagnostic "IMAGE DISPLAY: blocked because global SFW mode is active";return}
 $u="$($im.paths.image)"
 if([string]::IsNullOrWhiteSpace($u)){$u="$($im.paths.thumbnail)"}
 Write-ImagesDiagnostic "IMAGE DISPLAY: raw URL=$u"
 if([string]::IsNullOrWhiteSpace($u)){Write-ImagesDiagnostic "IMAGE DISPLAY: Stash returned no image/thumbnail URL";return}
 try{
  if($u -notmatch '^https?://'){$u=(Get-StashUrl).TrimEnd('/')+'/'+$u.TrimStart('/')}
  Write-ImagesDiagnostic "IMAGE DISPLAY: resolved URL=$u"
  $wc=New-Object Net.WebClient
  try{
   if($txtKey.Text){$wc.Headers.Add('ApiKey',$txtKey.Text.Trim())}
   $b=$wc.DownloadData($u)
   $contentType=[string]$wc.ResponseHeaders['Content-Type']
  }finally{$wc.Dispose()}
  Write-ImagesDiagnostic "IMAGE DOWNLOAD: id=$id; bytes=$($b.Length); contentType=$contentType"
  $isWebP=($contentType -match 'image/webp') -or ($b.Length -ge 12 -and [Text.Encoding]::ASCII.GetString($b,0,4) -eq 'RIFF' -and [Text.Encoding]::ASCII.GetString($b,8,4) -eq 'WEBP')
  Write-ImagesDiagnostic "IMAGE DECODE: id=$id; WebP=$isWebP"
  if($isWebP){
  $webp=Join-Path $env:TEMP ("stash-toolkit-"+$id+"-"+[guid]::NewGuid().ToString("N")+".webp")
  $jpg=Join-Path $env:TEMP ("stash-toolkit-"+$id+"-"+[guid]::NewGuid().ToString("N")+".jpg")
  try{
   [System.IO.File]::WriteAllBytes($webp,$b)
   $ffmpeg=Find-ToolkitFfmpeg
   if([string]::IsNullOrWhiteSpace($ffmpeg)){throw "FFmpeg is needed to show WebP pictures but was not found."}
   $proc=Convert-ToolkitImageWithFfmpeg $ffmpeg $webp $jpg
   if($proc.ExitCode -ne 0 -or -not (Test-Path -LiteralPath $jpg)){throw "WebP conversion failed"}
   $img=[System.Drawing.Image]::FromFile($jpg)
   $pic.Image=New-Object System.Drawing.Bitmap($img)
   $img.Dispose()
   Write-ImagesDiagnostic "IMAGE DECODE: WebP conversion succeeded; id=$id"
  }finally{
   Remove-Item -LiteralPath $webp -Force -ErrorAction SilentlyContinue
   Remove-Item -LiteralPath $jpg -Force -ErrorAction SilentlyContinue
  }

  }else{
   $ms=New-Object IO.MemoryStream(,$b)
   $x=$null
   try{$x=[Drawing.Image]::FromStream($ms,$true,$true);$pic.Image=New-Object Drawing.Bitmap($x)}
   finally{if($null -ne $x){$x.Dispose()};$ms.Dispose()}
  }
  Write-ImagesDiagnostic "IMAGE DISPLAY: decoded successfully; size=$($pic.Image.Width)x$($pic.Image.Height)"
 }catch{
  Write-ImagesDiagnostic "IMAGE DISPLAY ERROR: id=$id; URL=$u" $_
  try{if($null -ne $pic.Image){$o=$pic.Image;$pic.Image=$null;$o.Dispose()};$pic.Image=New-ToolkitPlaceholderImage ("This picture could not be displayed.`r`n`r`n"+$_.Exception.Message)}catch{}
 }
}

