function Add-SceneColumns([System.Windows.Forms.DataGridView]$Grid){
    [void]$Grid.Columns.Add("SceneID","ID")
    $Grid.Columns["SceneID"].Visible=$false
    [void]$Grid.Columns.Add("Title","Scene")
    [void]$Grid.Columns.Add("Date","Date")
    [void]$Grid.Columns.Add("Studio","Studio")
    [void]$Grid.Columns.Add("Performers","Performers")
    [void]$Grid.Columns.Add("Tags","Tags")
}
function Get-SceneTitle($s){
    if($null -ne $s.title -and "$($s.title)".Trim() -ne ""){return "$($s.title)"}
    if(@($s.files).Count -gt 0 -and $s.files[0].path){return [System.IO.Path]::GetFileNameWithoutExtension("$($s.files[0].path)")}
    return "(Untitled scene)"
}
function Get-ScenePerformerText($s){return (@($s.performers)|ForEach-Object {$_.name}) -join ", "}
function Get-SceneTagText($s){return (@($s.tags)|ForEach-Object {$_.name}) -join ", "}
function Get-SceneStudioText($s){if($null -ne $s.studio){return "$($s.studio.name)"};return ""}
function Add-SceneRow([System.Windows.Forms.DataGridView]$Grid,$s){
    [void]$Grid.Rows.Add("$($s.id)",(Get-SceneTitle $s),"$($s.date)",(Get-SceneStudioText $s),(Get-ScenePerformerText $s),(Get-SceneTagText $s))
}
function Find-CachedScene([string]$Id){return @($script:SceneCache|Where-Object {"$($_.id)" -eq "$Id"})|Select-Object -First 1}
function Set-SceneScreenshot($Scene,[System.Windows.Forms.PictureBox]$Picture){
    if($null -eq $Picture){return}
    if($null -ne $Picture.Image){
        $oldImage=$Picture.Image
        $Picture.Image=$null
        try{$oldImage.Dispose()}catch{}
    }
    $Picture.Tag=$(if($null -ne $Scene){"$($Scene.id)"}else{$null})
    if($null -eq $Scene -or $null -eq $Scene.paths -or -not "$($Scene.paths.screenshot)".Trim()){return}
    try{
        $url="$($Scene.paths.screenshot)"
        if($url.StartsWith("/")){$url=(Get-StashUrl).TrimEnd("/")+$url}
        elseif($url -notmatch '^https?://'){$url=(Get-StashUrl).TrimEnd("/")+"/"+$url.TrimStart("/")}
        $wc=New-Object System.Net.WebClient
        if($txtKey -and "$($txtKey.Text)".Trim()){
            $wc.Headers.Add("ApiKey","$($txtKey.Text.Trim())")
        }
        $bytes=$wc.DownloadData($url)
        $wc.Dispose()
        $ms=New-Object System.IO.MemoryStream(,$bytes)
        $tmp=[System.Drawing.Image]::FromStream($ms)
        $Picture.Image=New-Object System.Drawing.Bitmap($tmp)
        $tmp.Dispose();$ms.Dispose()
    }catch{
        $Picture.Image=$null
    }

 if($null -ne $Picture){
  Register-SceneScreenshotPicture $Picture
  $Picture.Visible=$script:SceneScreenshotNSFW
 }
}

function Find-CachedPerformer([string]$Id,[string]$Name){
    $p=$null
    if($script:AllPerformers){
        if($Id){$p=@($script:AllPerformers|Where-Object {"$($_.id)" -eq "$Id"})|Select-Object -First 1}
        if($null -eq $p -and $Name){$p=@($script:AllPerformers|Where-Object {"$($_.name)" -eq "$Name"})|Select-Object -First 1}
    }
    return $p
}
function Show-ScenePerformerPopup($Performer){
 try {

    if($null -eq $Performer){return}
    $f=New-Object ToolkitDialogWindow
    $f.Text="Performer Details - $($Performer.name)"
    $f.Size=New-Object System.Drawing.Size(1050,760)
    $f.MinimumSize=New-Object System.Drawing.Size(900,650)
    $f.StartPosition="CenterParent"
    $f.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)
    $f.ForeColor=[System.Drawing.Color]::White
    $f.ShowIcon=$false

    $root=New-Object System.Windows.Forms.TableLayoutPanel
    $root.Dock="Fill";$root.ColumnCount=2;$root.RowCount=2
    [void]$root.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle("Absolute",280)))
    [void]$root.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle("Percent",100)))
    [void]$root.RowStyles.Add((New-Object System.Windows.Forms.RowStyle("Percent",100)))
    [void]$root.RowStyles.Add((New-Object System.Windows.Forms.RowStyle("Absolute",52)))
    $root.Padding=New-Object System.Windows.Forms.Padding(10)
    [void]$f.Controls.Add($root)

    $pic=New-Object System.Windows.Forms.PictureBox
    Register-ToolkitImage $pic

    $pic.Dock="Fill";$pic.SizeMode="Zoom";$pic.BackColor=[System.Drawing.Color]::FromArgb(5,20,31)
    $pic.BorderStyle="FixedSingle"
    if("$($Performer.image_path)".Trim()){
        try{
            $url="$($Performer.image_path)"
            if($url.StartsWith("/")){$url=(Get-StashUrl).TrimEnd("/")+$url}
            elseif($url -notmatch '^https?://'){$url=(Get-StashUrl).TrimEnd("/")+"/"+$url.TrimStart("/")}
            $wc=New-Object System.Net.WebClient
            if($txtKey -and "$($txtKey.Text)".Trim()){$wc.Headers.Add("ApiKey","$($txtKey.Text.Trim())")}
            $bytes=$wc.DownloadData($url);$wc.Dispose()
            $ms=New-Object System.IO.MemoryStream(,$bytes)
            $tmp=[System.Drawing.Image]::FromStream($ms)
            $pic.Image=New-Object System.Drawing.Bitmap($tmp)
            $tmp.Dispose();$ms.Dispose()
        }catch{}
    }

    $grid=New-SceneDetailsGrid
    $grid.AutoSizeRowsMode=[System.Windows.Forms.DataGridViewAutoSizeRowsMode]::AllCells
    $grid.DefaultCellStyle.WrapMode=[System.Windows.Forms.DataGridViewTriState]::True
    $grid.Columns["Field"].DefaultCellStyle.WrapMode=[System.Windows.Forms.DataGridViewTriState]::False
    $grid.Columns["Value"].DefaultCellStyle.WrapMode=[System.Windows.Forms.DataGridViewTriState]::True
    $grid.Columns["Field"].FillWeight=22
    $grid.Columns["Value"].FillWeight=78
    $fields=@(
      @("Name","$($Performer.name)"),@("ID","$($Performer.id)"),
      @("Disambiguation","$($Performer.disambiguation)"),@("Gender","$($Performer.gender)"),
      @("Birthdate","$($Performer.birthdate)"),@("Country","$($Performer.country)"),
      @("Ethnicity","$($Performer.ethnicity)"),@("Eye colour","$($Performer.eye_color)"),
      @("Hair colour","$($Performer.hair_color)"),@("Height","$($Performer.height_cm) cm"),
      @("Measurements","$($Performer.measurements)"),@("Career","$($Performer.career_length)"),
      @("Scene count","$($Performer.scene_count)"),@("Image count","$($Performer.image_count)"),
      @("Rating","$($Performer.rating100)"),
      @("Aliases",((@($Performer.alias_list)) -join ", ")),
      @("Tags",((@($Performer.tags)|ForEach-Object {$_.name}) -join ", ")),
      @("Details","$($Performer.details)")
    )
    foreach($x in $fields){if("$($x[1])".Trim() -and "$($x[1])" -ne " cm"){[void]$grid.Rows.Add($x[0],$x[1])}}

    $buttons=New-Object System.Windows.Forms.FlowLayoutPanel
    $buttons.Dock="Fill";$buttons.FlowDirection="RightToLeft";$buttons.Padding=New-Object System.Windows.Forms.Padding(4)
    $close=New-Object System.Windows.Forms.Button;$close.Text="Close";$close.Width=90
    $open=New-Object System.Windows.Forms.Button;$open.Text="Open Performer in Stash";$open.Width=245
    foreach($b in @($close,$open)){
        $b.UseVisualStyleBackColor=$false;$b.FlatStyle="Flat"
        $b.BackColor=[System.Drawing.Color]::FromArgb(31,92,125);$b.ForeColor=[System.Drawing.Color]::White
        $b.FlatAppearance.BorderColor=[System.Drawing.Color]::FromArgb(92,157,194)
    }
    $close.Add_Click({$f.Close()})
    $open.Add_Click({param($sender,$e) Open-StashToolkitLink ((Get-StashUrl)+"/performers/"+$Performer.id);$sender.FindForm().Close()})
    [void]$buttons.Controls.Add($close)

    $pic.Cursor=[System.Windows.Forms.Cursors]::Hand
    $pic.Add_MouseClick({param($sender,$e) if($e.Button -ne [Windows.Forms.MouseButtons]::Left){return}
        if($null -eq $pic.Image){return}

        $viewer=New-Object ToolkitDialogWindow
        $viewer.Text="$($Performer.name) - Image"
        $viewer.StartPosition="CenterParent"
        $viewer.Size=New-Object System.Drawing.Size(900,900)
        $viewer.MinimumSize=New-Object System.Drawing.Size(500,500)
        $viewer.BackColor=[System.Drawing.Color]::Black
        $viewer.ShowIcon=$false

        $largePic=New-Object System.Windows.Forms.PictureBox
Register-ToolkitImage $largePic
        $largePic.Dock="Fill"
        $largePic.BackColor=[System.Drawing.Color]::Black
        $largePic.SizeMode=[System.Windows.Forms.PictureBoxSizeMode]::Zoom
        $largePic.Image=New-Object System.Drawing.Bitmap($pic.Image)
        $largePic.Cursor=[System.Windows.Forms.Cursors]::Hand
        $largePic.Add_MouseClick({param($sender,$e) if($e.Button -ne [Windows.Forms.MouseButtons]::Left){return};$viewer.Close()}.GetNewClosure())

        $hint=New-Object System.Windows.Forms.Label
        $hint.Text="Click the image to close"
        $hint.Dock="Bottom"
        $hint.Height=30
        $hint.TextAlign="MiddleCenter"
        $hint.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)
        $hint.ForeColor=[System.Drawing.Color]::FromArgb(169,204,230)
        $hint.Font=New-Object System.Drawing.Font("Segoe UI",9,[System.Drawing.FontStyle]::Italic)

        [void]$viewer.Controls.Add($largePic)
        [void]$viewer.Controls.Add($hint)
        [void]$viewer.ShowDialog($f)
        if($null -ne $largePic.Image){$largePic.Image.Dispose()}
        $viewer.Dispose()
    }.GetNewClosure())
    [void]$root.Controls.Add($pic,0,0);[void]$root.Controls.Add($grid,1,0)
    [void]$root.Controls.Add($buttons,0,1);$root.SetColumnSpan($buttons,2)
    [void]$f.ShowDialog($form)

 } catch {
  [ToolkitMessageDialog]::Show(
   "Performer popup error:`r`n`r`n$($_.Exception.Message)`r`n`r`nLine: $($_.InvocationInfo.ScriptLineNumber)",
   "Performer Popup Diagnostic",
   [System.Windows.Forms.MessageBoxButtons]::OK,
   [System.Windows.Forms.MessageBoxIcon]::Error
  ) | Out-Null
 }
}
function Update-ScenePerformerLinks($Scene){
    $scenePerformerLinks.Rows.Clear()
    if($null -eq $Scene){return}
    foreach($sp in @($Scene.performers)){
        [void]$scenePerformerLinks.Rows.Add("$($sp.name)","$($sp.id)")
    }
}

function Show-SceneDetails([System.Windows.Forms.DataGridView]$Grid,[System.Windows.Forms.DataGridView]$Details){
    $Details.Rows.Clear()
    if($Grid.SelectedRows.Count -eq 0){return}
    $id="$($Grid.SelectedRows[0].Cells["SceneID"].Value)"
    $s=Find-CachedScene $id
    if($null -eq $s){return}

    [void]$Details.Rows.Add("Title",(Get-SceneTitle $s))
    [void]$Details.Rows.Add("Date","$($s.date)")
    [void]$Details.Rows.Add("Studio",(Get-SceneStudioText $s))

    # Each performer is a separate clickable row in the information box.
    foreach($sp in @($s.performers)){
        $rowIndex=$Details.Rows.Add("Performer","$($sp.name)")
        $row=$Details.Rows[$rowIndex]
        $linkCell=New-Object System.Windows.Forms.DataGridViewLinkCell
        $linkCell.Value="$($sp.name)"
        $linkCell.Tag="$($sp.id)"
        $linkCell.LinkColor=[System.Drawing.Color]::FromArgb(99,205,255)
        $linkCell.ActiveLinkColor=[System.Drawing.Color]::White
        $linkCell.VisitedLinkColor=[System.Drawing.Color]::FromArgb(99,205,255)
        $linkCell.TrackVisitedState=$false
        $linkCell.ToolTipText="Click to view $($sp.name)'s details"
        $row.Cells["Value"]=$linkCell
    }
    if(@($s.performers).Count -eq 0){[void]$Details.Rows.Add("Performer","")}

    if(@($s.files).Count){
        $searchFile=$s.files[0]
        [void]$Details.Rows.Add("Quality",(Get-SceneQualityLabel $searchFile.width $searchFile.height))
        [void]$Details.Rows.Add("Resolution",$(if($searchFile.width -and $searchFile.height){"$($searchFile.width) x $($searchFile.height)"}else{""}))
    }

    foreach($p in @(
      @("Tags",(Get-SceneTagText $s)),
      @("Rating","$($s.rating100)"),
      @("Organized","$($s.organized)"),
      @("Created","$($s.created_at)"),
      @("Updated","$($s.updated_at)"),
      @("File",$(if(@($s.files).Count){"$($s.files[0].path)"}else{""})),
      @("Groups",((@($s.groups)|ForEach-Object {$_.group.name}) -join ", "))
    )){[void]$Details.Rows.Add($p[0],$p[1])}
}
function New-SceneDetailsGrid {
    $d=New-SceneGrid
    [void]$d.Columns.Add("Field","Field")
    $valueCol=New-Object System.Windows.Forms.DataGridViewTextBoxColumn
    $valueCol.Name="Value";$valueCol.HeaderText="Value"
    [void]$d.Columns.Add($valueCol)
    $d.Columns["Field"].FillWeight=30;$d.Columns["Value"].FillWeight=70
    return $d
}
function Refresh-SceneSimpleGrid([System.Windows.Forms.DataGridView]$Grid,[object[]]$Scenes){
    $Grid.Rows.Clear()
    foreach($s in @($Scenes)){Add-SceneRow $Grid $s}
}
function Get-SceneAgeDays($s,[string]$Field){
    try {
        $v=$s.$Field
        if(-not $v){return 999999}
        # Whole calendar days, so "Today" means today rather than "the last ~36 hours".
        return [int][Math]::Floor(((Get-Date).Date-(Get-Date $v).Date).TotalDays)
    } catch {return 999999}
}

