$runSceneSearch={
    $q=$sceneSearchBox.Text.Trim();$mode="$($sceneFilter.SelectedItem)"
    $items=@($script:SceneCache)
    $likeQuery='*'+(ConvertTo-ToolkitLikePattern $q)+'*'
    if($q){
      $items=@($items|Where-Object {
        $s=$_
        switch($mode){
          "Title" {(Get-SceneTitle $s) -like $likeQuery}
          "Performer" {(Get-ScenePerformerText $s) -like $likeQuery}
          "Studio" {(Get-SceneStudioText $s) -like $likeQuery}
          "Tag" {(Get-SceneTagText $s) -like $likeQuery}
          "Group" {((@($s.groups)|ForEach-Object {$_.group.name}) -join ", ") -like $likeQuery}
          default {((Get-SceneTitle $s)+" "+(Get-ScenePerformerText $s)+" "+(Get-SceneStudioText $s)+" "+(Get-SceneTagText $s)+" "+((@($s.groups)|ForEach-Object {$_.group.name}) -join " ")) -like $likeQuery}
        }
      })
    }
    Refresh-SceneSimpleGrid $sceneSearchGrid $items
    $status.Text="$($items.Count) scene(s) shown"

    if($q -and $items.Count -eq 0){
        [ToolkitMessageDialog]::Show(
            "No scenes were found matching '$q'.",
            "No Results Found",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        ) | Out-Null
    }
}
$sceneSearchButton.Add_Click($runSceneSearch);$sceneSearchBox.Add_KeyDown({if($_.KeyCode -eq "Enter"){& $runSceneSearch}})
$sceneRefreshButton.Add_Click({$sceneSearchBox.Clear();& $runSceneSearch})
$sceneSearchDetails.Add_CellContentClick({
    param($sender,$e)
    if($e.RowIndex -lt 0 -or $e.ColumnIndex -lt 0){return}
    $cell=$sender.Rows[$e.RowIndex].Cells[$e.ColumnIndex]
    if($cell -isnot [System.Windows.Forms.DataGridViewLinkCell]){return}
    if("$($sender.Rows[$e.RowIndex].Cells["Field"].Value)" -ne "Performer"){return}

    $performerId="$($cell.Tag)"
    $performerName="$($cell.Value)"
    $performer=Find-CachedPerformer $performerId $performerName
    if($null -ne $performer){
        Show-ScenePerformerPopup $performer
    } else {
        [ToolkitMessageDialog]::Show(
            "Details for $performerName are not available in the performer cache.",
            "Performer Details",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        ) | Out-Null
    }
})

