function Format-SceneFileSize($Bytes){
    if($null -eq $Bytes -or "$Bytes" -eq ""){return ""}
    $n=[double]$Bytes
    if($n -ge 1GB){return ("{0:N2} GB" -f ($n/1GB))}
    if($n -ge 1MB){return ("{0:N1} MB" -f ($n/1MB))}
    if($n -ge 1KB){return ("{0:N1} KB" -f ($n/1KB))}
    return ("{0:N0} bytes" -f $n)
}

function Format-SceneDuration($Seconds){
    if($null -eq $Seconds -or "$Seconds" -eq ""){return ""}
    try{
        $ts=[TimeSpan]::FromSeconds([double]$Seconds)
        if($ts.TotalHours -ge 1){return ("{0}:{1:00}:{2:00}" -f [int]$ts.TotalHours,$ts.Minutes,$ts.Seconds)}
        return ("{0}:{1:00}" -f [int]$ts.TotalMinutes,$ts.Seconds)
    }catch{return "$Seconds"}
}

function Get-SceneQualityLabel($Width,$Height){
    if(-not $Width -or -not $Height){return ""}
    $w=[int]$Width;$h=[int]$Height

    # Use both dimensions so portrait/rotated material still gets a sensible label.
    $long=[Math]::Max($w,$h)
    $short=[Math]::Min($w,$h)

    if($long -ge 7680 -or $short -ge 4320){return "8K"}
    if($long -ge 3840 -or $short -ge 2160){return "4K (2160p)"}
    if($long -ge 2560 -or $short -ge 1440){return "1440p"}
    if($long -ge 1920 -or $short -ge 1080){return "1080p"}
    if($long -ge 1280 -or $short -ge 720){return "720p"}
    if($long -ge 854 -or $short -ge 480){return "480p"}
    if($long -ge 640 -or $short -ge 360){return "360p"}
    return "$($w)x$($h)"
}

function Show-SceneBrowserSelection {
    if($sceneBrowserGrid.SelectedRows.Count -eq 0){return}
    $sid="$($sceneBrowserGrid.SelectedRows[0].Cells["SceneID"].Value)"
    $scene=Find-CachedScene $sid
    if($null -eq $scene){return}
    $script:SceneBrowserCurrent=$scene

    $sceneBrowserDetails.Rows.Clear()
    [void]$sceneBrowserDetails.Rows.Add("Title",(Get-SceneTitle $scene))
    [void]$sceneBrowserDetails.Rows.Add("Date","$($scene.date)")
    [void]$sceneBrowserDetails.Rows.Add("Studio",(Get-SceneStudioText $scene))

    foreach($sp in @($scene.performers)){
        $rowIndex=$sceneBrowserDetails.Rows.Add("Performer","$($sp.name)")
        $row=$sceneBrowserDetails.Rows[$rowIndex]
        $linkCell=New-Object System.Windows.Forms.DataGridViewLinkCell
        $linkCell.Value="$($sp.name)";$linkCell.Tag="$($sp.id)"
        $linkCell.LinkColor=[System.Drawing.Color]::FromArgb(99,205,255)
        $linkCell.ActiveLinkColor=[System.Drawing.Color]::White
        $linkCell.VisitedLinkColor=[System.Drawing.Color]::FromArgb(99,205,255)
        $linkCell.TrackVisitedState=$false
        $linkCell.ToolTipText="Click to view $($sp.name)'s details"
        $row.Cells["Value"]=$linkCell
    }
    if(@($scene.performers).Count -eq 0){[void]$sceneBrowserDetails.Rows.Add("Performer","")}

    [void]$sceneBrowserDetails.Rows.Add("Tags",(Get-SceneTagText $scene))
    [void]$sceneBrowserDetails.Rows.Add("Rating","$($scene.rating100)")
    [void]$sceneBrowserDetails.Rows.Add("Organized","$($scene.organized)")
    [void]$sceneBrowserDetails.Rows.Add("Created","$($scene.created_at)")
    [void]$sceneBrowserDetails.Rows.Add("Updated","$($scene.updated_at)")
    [void]$sceneBrowserDetails.Rows.Add("Groups",((@($scene.groups)|ForEach-Object {$_.group.name}) -join ", "))

    # Media information from the first attached media file.
    if(@($scene.files).Count){
        $file=$scene.files[0]
        [void]$sceneBrowserDetails.Rows.Add("File","$($file.path)")
        [void]$sceneBrowserDetails.Rows.Add("File Size",(Format-SceneFileSize $file.size))
        [void]$sceneBrowserDetails.Rows.Add("Duration",(Format-SceneDuration $file.duration))
        [void]$sceneBrowserDetails.Rows.Add("Quality",(Get-SceneQualityLabel $file.width $file.height))
        [void]$sceneBrowserDetails.Rows.Add("Resolution",$(if($file.width -and $file.height){"$($file.width) x $($file.height)"}else{""}))
        [void]$sceneBrowserDetails.Rows.Add("Video Codec","$($file.video_codec)")
        [void]$sceneBrowserDetails.Rows.Add("Audio Codec","$($file.audio_codec)")
    } else {
        [void]$sceneBrowserDetails.Rows.Add("File","")
    }

    Set-SceneScreenshot $scene $browserScreenshot
}

function Refresh-SceneBrowserListCore {
    $keepSceneId=if($sceneBrowserGrid.SelectedRows.Count){[string]$sceneBrowserGrid.SelectedRows[0].Cells["SceneID"].Value}else{''}
    if($script:BrowserSearchViews -and $script:BrowserSearchViews.ContainsKey('Scenes')){Refresh-SceneSimpleGrid $sceneBrowserGrid @(Get-ToolkitBrowserResults 'Scenes')}else{Refresh-SceneSimpleGrid $sceneBrowserGrid @($script:SceneCache)}
    $script:SceneBrowserLoadedKey=$script:ToolkitConnectionId
    if($sceneBrowserGrid.Rows.Count -gt 0){
        $targetRow=$sceneBrowserGrid.Rows[0]
        if($keepSceneId){foreach($row in $sceneBrowserGrid.Rows){if([string]$row.Cells["SceneID"].Value -eq $keepSceneId){$targetRow=$row;break}}}
        $sceneBrowserGrid.ClearSelection()
        $targetRow.Selected=$true
        $sceneBrowserGrid.CurrentCell=$targetRow.Cells["Title"]
        if($targetRow.Index -gt 0){try{$sceneBrowserGrid.FirstDisplayedScrollingRowIndex=$targetRow.Index}catch{}}
        Show-SceneBrowserSelection
    }
}

