$dupBtn.Add_Click({
 $sceneDupGrid.Rows.Clear();$seen=@{}
 foreach($s in @($script:SceneCache)){
   $title=(Get-SceneTitle $s).Trim().ToLowerInvariant()
   $file=$(if(@($s.files).Count){[System.IO.Path]::GetFileName("$($s.files[0].path)").ToLowerInvariant()}else{""})
   foreach($key in @("T|$title","F|$file")){
     if($key -match '\|$'){continue}
     if($seen.ContainsKey($key)){
       $other=$seen[$key];$reason=$(if($key.StartsWith("F|")){"Same filename"}else{"Same title"})
       [void]$sceneDupGrid.Rows.Add("$($s.id)",(Get-SceneTitle $s),(Get-SceneTitle $other),$reason)
     } else {$seen[$key]=$s}
   }
 }
})

# Shared selector-page builder for performer/studio/tag/group scene lists.
# Shared layout helper for scene relation pages.
function New-SceneRelationControls([string]$Title){
 $tab=New-SceneToolTab $Title
 $top=New-Object System.Windows.Forms.FlowLayoutPanel
 $top.Dock="Top";$top.Height=58;$top.Padding=New-Object System.Windows.Forms.Padding(8)

 $combo=New-Object System.Windows.Forms.ComboBox
 $combo.Width=340
 $combo.DropDownStyle=[System.Windows.Forms.ComboBoxStyle]::DropDownList
 $combo.AutoCompleteMode=[System.Windows.Forms.AutoCompleteMode]::None
 $combo.AutoCompleteSource=[System.Windows.Forms.AutoCompleteSource]::None
 # The parent Scenes tab uses white text. ComboBox inherits that ForeColor,
 # while the Windows dropdown popup itself has a white background. That made
 # every unselected entry white-on-white and therefore invisible.
 $combo.BackColor=[System.Drawing.Color]::White
 $combo.ForeColor=[System.Drawing.Color]::Black
 $combo.IntegralHeight=$false
 $combo.DropDownHeight=300
 $combo.MaxDropDownItems=15

 $btn=New-Object System.Windows.Forms.Button
 $btn.Text="Show Scenes";$btn.Width=150;$btn.Height=36
 $btn.UseVisualStyleBackColor=$false;$btn.FlatStyle="Flat"
 $btn.BackColor=[System.Drawing.Color]::FromArgb(31,92,125)
 $btn.ForeColor=[System.Drawing.Color]::White
 $btn.FlatAppearance.BorderColor=[System.Drawing.Color]::FromArgb(92,157,194)
 $btn.FlatAppearance.BorderSize=1

 $grid=New-SceneGrid
 $grid.Name=("scene"+($Title -replace '\W','')+"Grid")
 Add-SceneColumns $grid

 [void]$top.Controls.Add($combo)
 [void]$top.Controls.Add($btn)
 [void]$tab.Controls.Add($grid)
 [void]$tab.Controls.Add($top)

 return [pscustomobject]@{Tab=$tab;Combo=$combo;Button=$btn;Grid=$grid}
}

