$setRelationSceneScreenshot={
 param($Scene,[System.Windows.Forms.PictureBox]$Picture)
 if($null -eq $Picture -or $null -eq $Scene){return}

 if($null -ne $Picture.Image){
  $old=$Picture.Image
  $Picture.Image=$null
  try{$old.Dispose()}catch{}
 }

 $id=[string]$Scene.id
 $url=""
 try{$url=[string]$Scene.paths.screenshot}catch{}
 if([string]::IsNullOrWhiteSpace($url)){return}
 if($url.StartsWith("/")){$url=(Get-StashUrl).TrimEnd("/")+$url}
 elseif($url -notmatch '^https?://'){$url=(Get-StashUrl).TrimEnd("/")+"/"+$url.TrimStart("/")}

 try{
  $req=[System.Net.HttpWebRequest]::Create($url)
  $req.Method="GET"
  $req.AllowAutoRedirect=$true
  $req.Timeout=15000
  $req.Accept="image/jpeg,image/png,image/*;q=0.8,*/*;q=0.5"
  if($txtKey -and -not [string]::IsNullOrWhiteSpace([string]$txtKey.Text)){
   $req.Headers.Add("ApiKey",$txtKey.Text.Trim())
  }
  $resp=$req.GetResponse()
  $contentType=[string]$resp.ContentType
  $stream=$resp.GetResponseStream()
  $buffer=New-Object System.IO.MemoryStream
  $stream.CopyTo($buffer)
  $stream.Dispose();$resp.Dispose()
  $bytes=$buffer.ToArray();$buffer.Dispose()

  if($contentType -notmatch 'image/webp'){
   $ms=New-Object System.IO.MemoryStream(,$bytes)
   $img=[System.Drawing.Image]::FromStream($ms,$true,$true)
   $Picture.Image=New-Object System.Drawing.Bitmap($img)
   $img.Dispose();$ms.Dispose()
   $Picture.Tag=$id
   return
  }

  # Stash returned WebP. Windows PowerShell System.Drawing cannot decode it.
  # Use ffmpeg (already required by this toolkit environment) to convert the
  # downloaded WebP bytes to a temporary JPEG, then load that JPEG normally.
  $webp=Join-Path $env:TEMP ("stash-toolkit-"+$id+"-"+[guid]::NewGuid().ToString("N")+".webp")
  $jpg=Join-Path $env:TEMP ("stash-toolkit-"+$id+"-"+[guid]::NewGuid().ToString("N")+".jpg")
  try{
   [System.IO.File]::WriteAllBytes($webp,$bytes)
   $ffmpeg=Find-ToolkitFfmpeg
   if([string]::IsNullOrWhiteSpace($ffmpeg)){throw "FFmpeg is needed to show WebP pictures but was not found."}
   $proc=Convert-ToolkitImageWithFfmpeg $ffmpeg $webp $jpg
   if($proc.ExitCode -ne 0 -or -not (Test-Path -LiteralPath $jpg)){throw "WebP conversion failed"}
   $img=[System.Drawing.Image]::FromFile($jpg)
   $Picture.Image=New-Object System.Drawing.Bitmap($img)
   $img.Dispose()
   $Picture.Tag=$id
  }finally{
   Remove-Item -LiteralPath $webp -Force -ErrorAction SilentlyContinue
   Remove-Item -LiteralPath $jpg -Force -ErrorAction SilentlyContinue
  }
 }catch{
  $Picture.Image=$null
 }
}.GetNewClosure()

