$byPerformerButton.Add_Click({
 $choice=[string]$byPerformerCombo.Text
 if([string]::IsNullOrWhiteSpace($choice)){return}
 try{
  $q=@'
query ToolkitFindPerformerByName($filter: FindFilterType, $performer_filter: PerformerFilterType) {
 findPerformers(filter:$filter, performer_filter:$performer_filter) {
  performers { id name }
 }
}
'@
  $pd=Invoke-StashGraphQL $q @{
   filter=@{per_page=-1}
   performer_filter=@{name=@{value=$choice;modifier="EQUALS"}}
  }
  $selected=@($pd.findPerformers.performers | Where-Object {
   [string]::Equals(([string]$_.name).Trim(),$choice.Trim(),[System.StringComparison]::OrdinalIgnoreCase)
  } | Select-Object -First 1)
  if($selected.Count -eq 0){
   [ToolkitMessageDialog]::Show("Stash could not resolve performer '$choice'.","By Performer","OK","Error") | Out-Null
   return
  }
  $performerId=[string]$selected[0].id

  $q2=@'
query ToolkitScenesByPerformer($filter: FindFilterType, $scene_filter: SceneFilterType) {
 findScenes(filter:$filter, scene_filter:$scene_filter) {
  count
  scenes {
   id title date rating100 organized created_at updated_at
   files { path size duration video_codec audio_codec width height }
   paths { screenshot }
   studio { id name }
   performers { id name }
   tags { id name }
   groups { group { id name } scene_index }
  }
 }
}
'@
  $d=Invoke-StashGraphQL $q2 @{
   filter=@{per_page=-1;sort="title";direction="ASC"}
   scene_filter=@{performers=@{value=@($performerId);modifier="INCLUDES"}}
  }
  $matches=@($d.findScenes.scenes)
  if($null -eq $script:ByPerformerResultMap){$script:ByPerformerResultMap=@{}}
  else{$script:ByPerformerResultMap.Clear()}
  foreach($s in $matches){
   $script:ByPerformerResultMap[[string]$s.id]=$s
   if($null -eq (Find-CachedScene ([string]$s.id))){$script:SceneCache += $s}
  }
  & $refreshByRelationGrid $byPerformerGrid $matches
  $status.Text="Showing $($matches.Count) scene(s) for performer: $choice"
 }catch{
  [ToolkitMessageDialog]::Show($_.Exception.Message,"By Performer","OK","Error") | Out-Null
 }
})

