function Refresh-ByPerformerStudioSelectors {
    $currentPerformer=[string]$byPerformerCombo.Text
    $currentStudio=[string]$byStudioCombo.Text
    $script:ByPerformerIds=New-Object System.Collections.ArrayList
    $script:ByStudioIds=New-Object System.Collections.ArrayList

    $byPerformerCombo.BeginUpdate()
    try {
        $byPerformerCombo.Items.Clear()
        foreach($p in @($script:AllPerformers | Sort-Object name)){
            if($p -and -not [string]::IsNullOrWhiteSpace([string]$p.name)){
                [void]$byPerformerCombo.Items.Add([string]$p.name)
                [void]$script:ByPerformerIds.Add([string]$p.id)
            }
        }
    } finally {
        $byPerformerCombo.EndUpdate()
    }

    $byStudioCombo.BeginUpdate()
    try {
        $byStudioCombo.Items.Clear()
        foreach($s in @($script:StudioCache | Sort-Object name)){
            if($s -and -not [string]::IsNullOrWhiteSpace([string]$s.name)){
                [void]$byStudioCombo.Items.Add([string]$s.name)
                [void]$script:ByStudioIds.Add([string]$s.id)
            }
        }
    } finally {
        $byStudioCombo.EndUpdate()
    }

    if(-not [string]::IsNullOrWhiteSpace($currentPerformer)){
        $ix=$byPerformerCombo.Items.IndexOf($currentPerformer)
        if($ix -ge 0){$byPerformerCombo.SelectedIndex=$ix}
    }
    if(-not [string]::IsNullOrWhiteSpace($currentStudio)){
        $ix=$byStudioCombo.Items.IndexOf($currentStudio)
        if($ix -ge 0){$byStudioCombo.SelectedIndex=$ix}
    }
}

