function Refresh-SceneTagSelector {
 try{
  $tagQuery=@'
query ToolkitSceneTags($filter: FindFilterType) {
  findTags(filter:$filter) {
    count
    tags { id name scene_count }
  }
}
'@
  $tagData=Invoke-StashGraphQL $tagQuery @{filter=@{per_page=-1;sort="name";direction="ASC"}}
  $current=[string]$tagSceneCombo.Text
  $script:SceneTagIdByName=@{}
  $tagSceneCombo.BeginUpdate()
  try{
   $tagSceneCombo.Items.Clear()
   foreach($tag in @($tagData.findTags.tags)){
    if($tag -and -not [string]::IsNullOrWhiteSpace([string]$tag.name) -and [int]$tag.scene_count -gt 0){
     $tagName=[string]$tag.name
     [void]$tagSceneCombo.Items.Add($tagName)
     $script:SceneTagIdByName[$tagName]=[string]$tag.id
    }
   }
  }finally{$tagSceneCombo.EndUpdate()}

  if(-not [string]::IsNullOrWhiteSpace($current)){
   $ix=$tagSceneCombo.Items.IndexOf($current)
   if($ix -ge 0){$tagSceneCombo.SelectedIndex=$ix}
  }
  if($tagSceneCombo.SelectedIndex -lt 0 -and $tagSceneCombo.Items.Count -gt 0){
   $tagSceneCombo.SelectedIndex=0
  }
 }catch{
  [ToolkitMessageDialog]::Show(
   "Tags could not be loaded from Stash.`r`n`r`n$($_.Exception.Message)",
   "Tags Error","OK","Error"
  ) | Out-Null
 }
}

$tagSceneTab.Add_Enter({
 Refresh-SceneTagSelector
}.GetNewClosure())

$tagSceneButton.Add_Click({
 try{
  $choice=[string]$tagSceneCombo.SelectedItem
  if([string]::IsNullOrWhiteSpace($choice)){return}

  $tagSceneButton.Enabled=$false
  $form.Cursor="WaitCursor"
  $status.Text="Loading scenes tagged '$choice'..."
  [System.Windows.Forms.Application]::DoEvents()

  # Resolve the exact tag in Stash.
  $tagLookup=@'
query ToolkitSelectedTag($filter: FindFilterType) {
  findTags(filter:$filter) {
    count
    tags { id name scene_count }
  }
}
'@
  $tagData=Invoke-StashGraphQL $tagLookup @{filter=@{per_page=-1;sort="name";direction="ASC"}}
  $selectedTag=@(
   @($tagData.findTags.tags) | Where-Object {
    ([string]$_.name).Trim() -eq $choice.Trim()
   } | Select-Object -First 1
  )
  if($selectedTag.Count -eq 0){throw "The selected tag could not be resolved in Stash."}
  $tagId=[string]$selectedTag[0].id
  $tagOwnSceneCount=if($null -ne $selectedTag[0].scene_count){[int]$selectedTag[0].scene_count}else{-1}

  # Query Stash for all scenes. We know this path returns all 1648 scenes.
  # Some Stash setups do not expose scene tags in the returned scene objects
  # as expected, so use the selected tag's own scene_count relationship as
  # the authoritative source by asking Stash for scenes using HAS_TAGS and
  # then confirming the tag ID where available.
  $sceneQuery=@'
query ToolkitTaggedScenes($filter: FindFilterType, $scene_filter: SceneFilterType) {
  findScenes(filter:$filter, scene_filter:$scene_filter) {
    count
    scenes {
      id title date rating100 organized created_at updated_at
      files { path size duration video_codec audio_codec width height }
      paths { screenshot }
      studio { id name }
      performers { id name }
      tags { id name }
      groups { group { id name } scene_index }
    }
  }
}
'@

  # Stash's multi-ID filter modifier for tags is INCLUDES_ALL rather than the
  # generic INCLUDES used by performer/studio filters.
  $sceneData=Invoke-StashGraphQL $sceneQuery @{
   filter=@{per_page=-1;sort="title";direction="ASC"}
   scene_filter=@{tags=@{value=@($tagId);modifier="INCLUDES"}}
  }

  $script:TagSceneResults=@($sceneData.findScenes.scenes)
  $tagResultMap=@{}
  foreach($tagResultScene in @($script:TagSceneResults)){
   $tagResultMap[[string]$tagResultScene.id]=$tagResultScene
  }
  $tagSceneRelationGrid.Tag=$tagResultMap
Refresh-SceneSimpleGrid $tagSceneRelationGrid $script:TagSceneResults
$tagSceneResultNote.Text="$($tagSceneRelationGrid.Rows.Count) scenes. Select a row for details; double-click to open in Stash."
  # Bind each displayed row directly to its live GraphQL scene object.
  for($tagRowIndex=0;$tagRowIndex -lt $tagSceneRelationGrid.Rows.Count;$tagRowIndex++){
   if($tagRowIndex -lt $script:TagSceneResults.Count){
    $tagSceneRelationGrid.Rows[$tagRowIndex].Tag=$script:TagSceneResults[$tagRowIndex]
   }
  }
  $tagSceneDetails.Rows.Clear()
  # Clear the previous display BEFORE selecting the first new result.
  # Selecting the row fires SelectionChanged, which then loads the new details
  # and screenshot. Previously this cleanup happened afterwards and erased it.
  if($tagScenePicture.Image){
   $oldImage=$tagScenePicture.Image
   $tagScenePicture.Image=$null
   try{$oldImage.Dispose()}catch{}
  }
  $tagSceneDetails.Rows.Clear()
  $script:SelectedTagScene=$null

  if($tagSceneRelationGrid.Rows.Count -gt 0){
   $tagSceneRelationGrid.ClearSelection()
   $tagSceneRelationGrid.Rows[0].Selected=$true
   $tagSceneRelationGrid.CurrentCell=$tagSceneRelationGrid.Rows[0].Cells["Title"]
  }
  $status.Text="$($script:TagSceneResults.Count) scene(s) tagged '$choice'"

  if($script:TagSceneResults.Count -eq 0){
   [ToolkitMessageDialog]::Show(
    "Stash resolved '$choice' as tag ID $tagId, but returned no scenes for that tag.",
    "Tags","OK","Information"
   ) | Out-Null
  }
 }catch{
  [ToolkitMessageDialog]::Show(
   "Scenes for this tag could not be loaded from Stash.`r`n`r`n$($_.Exception.Message)",
   "Tags Error","OK","Error"
  ) | Out-Null
 }finally{
  $tagSceneButton.Enabled=$true
  $form.Cursor="Default"
 }
})

$tagSceneRelationGrid.Add_SelectionChanged({
 if($tagSceneRelationGrid.SelectedRows.Count -eq 0){return}
 $selectedTagRow=$tagSceneRelationGrid.SelectedRows[0]
 $sid=[string]$selectedTagRow.Cells["SceneID"].Value
 $scene=$selectedTagRow.Tag
 if($null -eq $scene){return}
 $script:SelectedTagScene=$scene

 # Populate the Tags information pane directly from the selected result.
 # Show-SceneDetails deliberately resolves through SceneCache; tag-search
 # results are live GraphQL results and are not guaranteed to be in that cache.
 $tagSceneDetails.Rows.Clear()
 [void]$tagSceneDetails.Rows.Add("Title",(Get-SceneTitle $scene))
 [void]$tagSceneDetails.Rows.Add("Date","$($scene.date)")
 [void]$tagSceneDetails.Rows.Add("Studio",(Get-SceneStudioText $scene))

 foreach($sp in @($scene.performers)){
  $rowIndex=$tagSceneDetails.Rows.Add("Performer","$($sp.name)")
  $row=$tagSceneDetails.Rows[$rowIndex]
  $linkCell=New-Object System.Windows.Forms.DataGridViewLinkCell
  $linkCell.Value="$($sp.name)"
  $linkCell.Tag="$($sp.id)"
  $linkCell.LinkColor=[System.Drawing.Color]::FromArgb(99,205,255)
  $linkCell.ActiveLinkColor=[System.Drawing.Color]::White
  $linkCell.VisitedLinkColor=[System.Drawing.Color]::FromArgb(99,205,255)
  $linkCell.TrackVisitedState=$false
  $linkCell.ToolTipText="Click to view $($sp.name)'s details"
  $row.Cells["Value"]=$linkCell
 }
 if(@($scene.performers).Count -eq 0){[void]$tagSceneDetails.Rows.Add("Performer","")}

 if(@($scene.files).Count){
  $sceneFile=$scene.files[0]
  [void]$tagSceneDetails.Rows.Add("Quality",(Get-SceneQualityLabel $sceneFile.width $sceneFile.height))
  [void]$tagSceneDetails.Rows.Add("Resolution",$(if($sceneFile.width -and $sceneFile.height){"$($sceneFile.width) x $($sceneFile.height)"}else{""}))
 }

 foreach($p in @(
  @("Tags",(Get-SceneTagText $scene)),
  @("Rating","$($scene.rating100)"),
  @("Organized","$($scene.organized)"),
  @("Created","$($scene.created_at)"),
  @("Updated","$($scene.updated_at)"),
  @("File",$(if(@($scene.files).Count){"$($scene.files[0].path)"}else{""})),
  @("Groups",((@($scene.groups)|ForEach-Object {$_.group.name}) -join ", "))
 )){
  [void]$tagSceneDetails.Rows.Add($p[0],$p[1])
 }

 # Load the selected scene screenshot directly. The diagnostic proved that
 # scene 609 returns a valid JPEG (1200x675), so use System.Drawing directly
 # for normal JPEG/PNG responses and retain the proven WebP helper as fallback.
 try{
  if($null -ne $tagScenePicture.Image){
   $oldTagImage=$tagScenePicture.Image
   $tagScenePicture.Image=$null
   try{$oldTagImage.Dispose()}catch{}
  }

  $tagShotUrl=[string]$scene.paths.screenshot
  if(-not [string]::IsNullOrWhiteSpace($tagShotUrl)){
   if($tagShotUrl.StartsWith("/")){$tagShotUrl=(Get-StashUrl).TrimEnd("/")+$tagShotUrl}
   elseif($tagShotUrl -notmatch '^https?://'){$tagShotUrl=(Get-StashUrl).TrimEnd("/")+"/"+$tagShotUrl.TrimStart("/")}

   $tagReq=[System.Net.HttpWebRequest]::Create($tagShotUrl)
   $tagReq.Method="GET"
   $tagReq.AllowAutoRedirect=$true
   $tagReq.Timeout=15000
   $tagReq.Accept="image/jpeg,image/png,image/*;q=0.8,*/*;q=0.5"
   if($txtKey -and -not [string]::IsNullOrWhiteSpace([string]$txtKey.Text)){
    $tagReq.Headers.Add("ApiKey",$txtKey.Text.Trim())
   }
   $tagResp=$tagReq.GetResponse()
   $tagType=[string]$tagResp.ContentType
   $tagStream=$tagResp.GetResponseStream()
   $tagBuffer=New-Object System.IO.MemoryStream
   $tagStream.CopyTo($tagBuffer)
   $tagStream.Dispose();$tagResp.Dispose()
   $tagBytes=$tagBuffer.ToArray();$tagBuffer.Dispose()

   if($tagType -match 'image/webp'){
    & $setRelationSceneScreenshot $scene $tagScenePicture
   }else{
    $tagImageStream=New-Object System.IO.MemoryStream(,$tagBytes)
    $tagImage=[System.Drawing.Image]::FromStream($tagImageStream,$true,$true)
    $tagScenePicture.Image=New-Object System.Drawing.Bitmap($tagImage)
    $tagImage.Dispose();$tagImageStream.Dispose()
    $tagScenePicture.Tag=[string]$scene.id
    $tagScenePicture.Refresh()
   }
  }
 }catch{
  # Preserve the already-proven WebP-capable loader as a fallback.
  & $setRelationSceneScreenshot $scene $tagScenePicture
 }
})

