$sceneHealthGrid=New-SceneGrid
$sceneHealthGrid.Name="sceneFileHealthGrid"
[void]$sceneHealthGrid.Columns.Add("SceneID","ID")
$sceneHealthGrid.Columns["SceneID"].Visible=$false
[void]$sceneHealthGrid.Columns.Add("Title","Scene")
[void]$sceneHealthGrid.Columns.Add("Issue","Issue")
[void]$sceneHealthGrid.Columns.Add("Path","Path")
$sceneHealthGrid.Columns["Title"].FillWeight=30
$sceneHealthGrid.Columns["Issue"].FillWeight=25
$sceneHealthGrid.Columns["Path"].FillWeight=45
Enable-SceneContextMenu $sceneHealthGrid

