$healthBtn.Add_Click({
 try{
  $healthBtn.Enabled=$false
  $form.Cursor="WaitCursor"
  $sceneHealthGrid.Rows.Clear()
  $status.Text="Checking file health..."
  [System.Windows.Forms.Application]::DoEvents()

  # Query Stash directly. File Health no longer depends on the toolkit's
  # connection/cache flags, which can be stale even while Stash is connected.
  $healthQuery=@'
query ToolkitFileHealth($filter: FindFilterType) {
  findScenes(filter:$filter) {
    count
    scenes {
      id
      title
      files {
        path
        size
        duration
        video_codec
        audio_codec
        width
        height
      }
    }
  }
}
'@
  $healthData=Invoke-StashGraphQL $healthQuery @{filter=@{per_page=-1;sort="title";direction="ASC"}}
  $items=@($healthData.findScenes.scenes)
  $stashSceneCount=[int]$healthData.findScenes.count

  $issues=0
  foreach($s in $items){
   if($null -eq $s){continue}
   $title=if([string]::IsNullOrWhiteSpace([string]$s.title)){"Untitled scene #$($s.id)"}else{[string]$s.title}
   $files=@($s.files)

   if($files.Count -eq 0){
    [void]$sceneHealthGrid.Rows.Add([string]$s.id,$title,"No file attached","")
    $issues++
    continue
   }

   foreach($f in $files){
    $path=[string]$f.path
    if([string]::IsNullOrWhiteSpace($path)){
     [void]$sceneHealthGrid.Rows.Add([string]$s.id,$title,"Blank file path","")
     $issues++
     continue
    }
    if($null -eq $f.size -or [int64]$f.size -le 0){
     [void]$sceneHealthGrid.Rows.Add([string]$s.id,$title,"Missing file size",$path);$issues++
    }
    if($null -eq $f.duration -or [double]$f.duration -le 0){
     [void]$sceneHealthGrid.Rows.Add([string]$s.id,$title,"Missing duration",$path);$issues++
    }
    if([string]::IsNullOrWhiteSpace([string]$f.video_codec)){
     [void]$sceneHealthGrid.Rows.Add([string]$s.id,$title,"Missing video codec",$path);$issues++
    }
    if($null -eq $f.width -or $null -eq $f.height -or [int]$f.width -le 0 -or [int]$f.height -le 0){
     [void]$sceneHealthGrid.Rows.Add([string]$s.id,$title,"Missing resolution",$path);$issues++
    }
   }
  }

  if($stashSceneCount -eq 0){
   [ToolkitMessageDialog]::Show(
    "Stash itself returned a scene count of 0.",
    "File Health",
    "OK",
    "Information"
   ) | Out-Null
  }elseif($issues -eq 0){
   [ToolkitMessageDialog]::Show(
    "Checked $stashSceneCount scenes directly from Stash.`r`n`r`nNo file-health problems were found.",
    "File Health",
    "OK",
    "Information"
   ) | Out-Null
  }else{
   $status.Text="File Health checked $stashSceneCount scenes and found $issues issue(s)."
  }
 }catch{
  [ToolkitMessageDialog]::Show(
   "File Health could not query Stash.`r`n`r`n$($_.Exception.Message)",
   "File Health Error",
   "OK",
   "Error"
  ) | Out-Null
 }finally{
  $healthBtn.Enabled=$true
  $form.Cursor="Default"
 }
}.GetNewClosure())

