# ---------- Unified Performers colour scheme ----------
# Match the Scenes workspace: dark navy page, blue-navy panels/grids,
# white primary text and pale-blue secondary text.
function Set-PerformerScenePalette([System.Windows.Forms.Control]$Parent) {
    foreach($c in @($Parent.Controls)){
        if($c -is [System.Windows.Forms.TabPage]){
            $c.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)
            $c.ForeColor=[System.Drawing.Color]::White
        }
        elseif($c -is [System.Windows.Forms.Button]){
            $c.AutoSize=$false
            $c.AutoSizeMode=[System.Windows.Forms.AutoSizeMode]::GrowOnly
            $c.Height=30
            $c.UseVisualStyleBackColor=$false
            $c.FlatStyle=[System.Windows.Forms.FlatStyle]::Flat
            $c.BackColor=[System.Drawing.Color]::FromArgb(31,92,125)
            $c.ForeColor=[System.Drawing.Color]::White
            $c.FlatAppearance.BorderColor=[System.Drawing.Color]::FromArgb(92,157,194)
            $c.FlatAppearance.BorderSize=1
        }
        elseif($c -is [System.Windows.Forms.DataGridView]){
            $c.BackgroundColor=[System.Drawing.Color]::FromArgb(8,31,47)
            $c.BorderStyle="None"
            $c.EnableHeadersVisualStyles=$false
            $c.ColumnHeadersDefaultCellStyle.BackColor=[System.Drawing.Color]::FromArgb(15,43,61)
            $c.ColumnHeadersDefaultCellStyle.ForeColor=[System.Drawing.Color]::White
            $c.DefaultCellStyle.BackColor=[System.Drawing.Color]::FromArgb(12,37,54)
            $c.DefaultCellStyle.ForeColor=[System.Drawing.Color]::FromArgb(225,236,244)
            $c.DefaultCellStyle.SelectionBackColor=[System.Drawing.Color]::FromArgb(31,92,125)
            $c.DefaultCellStyle.SelectionForeColor=[System.Drawing.Color]::White
            $c.RowHeadersVisible=$false
        }
        elseif($c -is [System.Windows.Forms.FlowLayoutPanel] -or
               $c -is [System.Windows.Forms.TableLayoutPanel] -or
               $c -is [System.Windows.Forms.Panel]){
            $c.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)
        }
        elseif($c -is [System.Windows.Forms.SplitContainer]){
            $c.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)
            $c.Panel1.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)
            $c.Panel2.BackColor=[System.Drawing.Color]::FromArgb(8,31,47)
        }
        elseif($c -is [System.Windows.Forms.Label] -or $c -is [System.Windows.Forms.CheckBox]){
            # Preserve intentionally coloured labels (status/accent labels).
            if($c.ForeColor -eq [System.Drawing.SystemColors]::ControlText -or
               $c.ForeColor -eq [System.Drawing.Color]::Black){
                $c.ForeColor=[System.Drawing.Color]::FromArgb(225,236,244)
            }
        }
        if($c.HasChildren){Set-PerformerScenePalette $c}
    }
}

