function Open-TimelineSceneBrowser([string]$SceneId){
 $scene=Find-CachedScene $SceneId;if(-not $scene){return}
 $tabs.SelectedTab=$tabScenes;$sceneTabs.SelectedTab=$sceneBrowserTab
 if($script:BrowserSearchViews['Scenes']){$script:BrowserSearchViews['Scenes'].Query.Text=''}
 Refresh-SceneBrowserList
 foreach($row in $sceneBrowserGrid.Rows){if([string]$row.Cells['SceneID'].Value -eq $SceneId){$sceneBrowserGrid.ClearSelection();$sceneBrowserGrid.CurrentCell=$row.Cells['Title'];$row.Selected=$true;$sceneBrowserGrid.FirstDisplayedScrollingRowIndex=$row.Index;Show-SceneBrowserSelection;break}}
 if($script:SharedImagePreview -and -not $script:SharedImagePreview.IsDisposed){$script:SharedImagePreview.Close()}
}
function Fit-TimelinePreviewTitle {
 $label=$script:ImagePreviewTitle
 if(-not $label -or $label.IsDisposed -or $label.ClientSize.Width -lt 80 -or $script:FittingPreviewTitle){return}
 $script:FittingPreviewTitle=$true;$g=$null;$font=$null
 try{
  $g=$label.CreateGraphics();$font=New-Object Drawing.Font('Segoe UI',15,[Drawing.FontStyle]::Bold)
  $measure=$g.MeasureString([string]$label.Text,$font)
  $width=[Math]::Max(40,$label.ClientSize.Width-80);$size=[single]15
  if($measure.Width -gt $width){$size=[single][Math]::Max(1,15*$width/$measure.Width*0.96)}
  if([Math]::Abs($label.Font.Size-$size) -gt 0.1){$label.Font=New-Object Drawing.Font('Segoe UI',$size,[Drawing.FontStyle]::Bold)}
 }finally{if($font){$font.Dispose()};if($g){$g.Dispose()};$script:FittingPreviewTitle=$false}
}
function Set-TimelinePreviewLink($Picture,$Source){
 $Picture.Tag=if($Source.Tag -is [System.Collections.IDictionary] -and $Source.Tag.Contains('SceneID')){[string]$Source.Tag.SceneID}else{$null}
 $script:ImagePreviewHint.Visible=-not [string]::IsNullOrWhiteSpace([string]$Picture.Tag)
 $Picture.Cursor=if($Picture.Tag){[Windows.Forms.Cursors]::Hand}else{[Windows.Forms.Cursors]::Default}
 $script:ImagePreviewTitle.Text=[string]$Source.AccessibleName;$script:ImagePreviewTitle.Visible=[bool]$Picture.Tag;if($script:ImagePreviewTitleHeader){$script:ImagePreviewTitleHeader.Visible=[bool]$Picture.Tag}
 $script:ImagePreviewYear.Visible=[bool]$Picture.Tag;$script:ImagePreviewYear.Text=''
 if($Picture.Tag){$scene=Find-CachedScene ([string]$Picture.Tag);$year=if($scene.date){([string]$scene.date).Substring(0,[Math]::Min(4,([string]$scene.date).Length))}else{'Undated'};$script:ImagePreviewYear.Text='('+$year+')'}
 Fit-TimelinePreviewTitle
}
