 $script:ImagePreviewTitle=New-Object Windows.Forms.Label;$script:ImagePreviewTitle.Dock='Top';$script:ImagePreviewTitle.Height=56;$script:ImagePreviewTitle.ForeColor=[Drawing.Color]::White;$script:ImagePreviewTitle.TextAlign='MiddleCenter';$script:ImagePreviewTitle.AutoEllipsis=$false;$script:ImagePreviewTitle.Font=New-Object Drawing.Font('Segoe UI',15,[Drawing.FontStyle]::Bold);$script:ImagePreviewTitle.Padding=New-Object Windows.Forms.Padding(40,8,40,8)
 $titleHeader=New-Object Windows.Forms.Panel;$titleHeader.Dock='Top';$titleHeader.Height=88;$script:ImagePreviewTitleHeader=$titleHeader
