 $script:ImagePreviewTitle.Add_Resize({Fit-TimelinePreviewTitle})
 [void]$titleHeader.Controls.Add($script:ImagePreviewTitle);[void]$titleHeader.Controls.Add($script:ImagePreviewYear);[void]$viewer.Controls.Add($titleHeader);$titleHeader.BringToFront()
 $script:ImagePreviewHint=New-Object Windows.Forms.Label;$script:ImagePreviewHint.Dock='Bottom';$script:ImagePreviewHint.Height=44;$script:ImagePreviewHint.ForeColor=[Drawing.Color]::White;$script:ImagePreviewHint.TextAlign='MiddleCenter';$script:ImagePreviewHint.Text='Click image to open in Scene Browser.'
 [void]$viewer.Controls.Add($script:ImagePreviewHint)
