function Copy-GroupsSceneControl {
 param([Windows.Forms.Control]$Source,[hashtable]$Map)
 $copy=New-Object ($Source.GetType().FullName)
 $Map[$Source]=$copy
 $copy.SuspendLayout()
 # Establish usable size before orientation/minimum sizes or docking are applied.
 $copy.Size=$Source.Size
 foreach($property in @('Font','BackColor','ForeColor','Margin','Padding','Location','MinimumSize','MaximumSize','Anchor','AutoSize','TabIndex')){$copy.$property=$Source.$property}
 $copy.Text=([string]$Source.Text) -replace 'Scenes','Groups' -replace 'scenes','groups' -replace 'Scene','Group' -replace 'scene','group'
 if($copy -is [Windows.Forms.SplitContainer]){
  $copy.Size=New-Object Drawing.Size([Math]::Max(1200,$Source.Width),[Math]::Max(650,$Source.Height))
  $copy.Orientation=$Source.Orientation
  $copy.SplitterWidth=$Source.SplitterWidth
  $copy.Panel1MinSize=$Source.Panel1MinSize;$copy.Panel2MinSize=$Source.Panel2MinSize
  $copy.SplitterDistance=$Source.SplitterDistance
  $copy.FixedPanel=$Source.FixedPanel;$copy.IsSplitterFixed=$Source.IsSplitterFixed
  $copy.Panel1.BackColor=$Source.Panel1.BackColor;$copy.Panel2.BackColor=$Source.Panel2.BackColor
  $Map[$Source.Panel1]=$copy.Panel1;$Map[$Source.Panel2]=$copy.Panel2
  foreach($side in @('Panel1','Panel2')){
   foreach($child in $Source.$side.Controls){$cloned=Copy-GroupsSceneControl $child $Map;[void]$copy.$side.Controls.Add($cloned)}
  }
 }elseif($copy -is [Windows.Forms.DataGridView]){
  foreach($property in @('ReadOnly','AllowUserToAddRows','AllowUserToDeleteRows','AllowUserToResizeRows','SelectionMode','MultiSelect','AutoSizeColumnsMode','AutoSizeRowsMode','BackgroundColor','BorderStyle','CellBorderStyle','GridColor','RowHeadersVisible','ColumnHeadersVisible','EnableHeadersVisualStyles','ColumnHeadersHeightSizeMode','ColumnHeadersHeight','ColumnHeadersBorderStyle','RowHeadersBorderStyle')){$copy.$property=$Source.$property}
  foreach($style in @('DefaultCellStyle','ColumnHeadersDefaultCellStyle','RowHeadersDefaultCellStyle','AlternatingRowsDefaultCellStyle')){$copy.$style=$Source.$style.Clone()}
  $copy.RowTemplate.Height=$Source.RowTemplate.Height
  foreach($column in $Source.Columns){[void]$copy.Columns.Add($column.Clone())}
 }else{
  if($copy -is [Windows.Forms.TableLayoutPanel]){
   $copy.ColumnCount=$Source.ColumnCount;$copy.RowCount=$Source.RowCount
   foreach($style in $Source.ColumnStyles){[void]$copy.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle($style.SizeType,$style.Width)))}
   foreach($style in $Source.RowStyles){[void]$copy.RowStyles.Add((New-Object Windows.Forms.RowStyle($style.SizeType,$style.Height)))}
   $copy.GrowStyle=$Source.GrowStyle;$copy.CellBorderStyle=$Source.CellBorderStyle
  }
  if($copy -is [Windows.Forms.FlowLayoutPanel]){$copy.FlowDirection=$Source.FlowDirection;$copy.WrapContents=$Source.WrapContents;$copy.AutoScroll=$Source.AutoScroll}
  if($copy -is [Windows.Forms.Button]){
   $copy.FlatStyle=$Source.FlatStyle;$copy.UseVisualStyleBackColor=$Source.UseVisualStyleBackColor;$copy.TextAlign=$Source.TextAlign
   foreach($property in @('BorderSize','BorderColor','MouseDownBackColor','MouseOverBackColor')){$copy.FlatAppearance.$property=$Source.FlatAppearance.$property}
  }
  if($copy -is [Windows.Forms.Label]){$copy.TextAlign=$Source.TextAlign;$copy.AutoEllipsis=$Source.AutoEllipsis}
  if($copy -is [Windows.Forms.TextBox]){$copy.BorderStyle=$Source.BorderStyle;$copy.Multiline=$Source.Multiline}
  if($copy -is [Windows.Forms.ComboBox]){
   $copy.DropDownStyle=$Source.DropDownStyle;$copy.IntegralHeight=$Source.IntegralHeight;$copy.DropDownHeight=$Source.DropDownHeight;$copy.MaxDropDownItems=$Source.MaxDropDownItems
   foreach($item in $Source.Items){[void]$copy.Items.Add([string]$item)}
   if($copy.Items.Count){$copy.SelectedIndex=[Math]::Max(0,$Source.SelectedIndex)}
  }
  if($copy -is [Windows.Forms.CheckBox]){$copy.Checked=$Source.Checked}
  if($copy -is [Windows.Forms.PictureBox]){$copy.SizeMode=$Source.SizeMode;$copy.BorderStyle=$Source.BorderStyle}
  foreach($child in $Source.Controls){
   $cloned=Copy-GroupsSceneControl $child $Map
   if($copy -is [Windows.Forms.TableLayoutPanel]){
    $position=$Source.GetPositionFromControl($child)
    [void]$copy.Controls.Add($cloned,$position.Column,$position.Row)
    $copy.SetColumnSpan($cloned,$Source.GetColumnSpan($child));$copy.SetRowSpan($cloned,$Source.GetRowSpan($child))
   }else{[void]$copy.Controls.Add($cloned)}
  }
 }
 $copy.Dock=$Source.Dock
 $copy.ResumeLayout($false)
 return $copy
}
function Get-ReplacementGroupScenes([string]$Id){
 return @($script:SceneCache | Where-Object {@($_.groups | Where-Object {[string]$_.group.id -eq $Id}).Count -gt 0})
}
function Get-ReplacementGroupPerformers($Group){
 return @((Get-ReplacementGroupScenes ([string]$Group.id)) | ForEach-Object {$_.performers} | Where-Object {$null -ne $_} | Sort-Object id -Unique)
}
function Get-ReplacementGroupMissing($Group){
 $missing=New-Object 'Collections.Generic.List[string]'
 if([string]::IsNullOrWhiteSpace([string]$Group.name)){[void]$missing.Add('Name')}
 if([string]::IsNullOrWhiteSpace([string]$Group.date)){[void]$missing.Add('Date')}
 if($null -eq $Group.studio){[void]$missing.Add('Studio')}
 if(@(Get-ReplacementGroupPerformers $Group).Count -eq 0){[void]$missing.Add('Performers')}
 if(@($Group.tags | Where-Object {$null -ne $_}).Count -eq 0){[void]$missing.Add('Tags')}
 if([string]::IsNullOrWhiteSpace([string]$Group.front_image_path)){[void]$missing.Add('Front cover')}
 if([string]::IsNullOrWhiteSpace([string]$Group.back_image_path)){[void]$missing.Add('Back cover')}
 return $missing.ToArray()
}
function Get-ReplacementGroupsResults($View){
 $items=@($script:GroupCache | Where-Object {$null -ne $_})
 switch($View.Operation){
  'Search' {
   $query=$View.Query.Text.Trim();$mode=[string]$View.Choice.SelectedItem
   $likeQuery='*'+(ConvertTo-ToolkitLikePattern $query)+'*'
   if($query){$items=@($items | Where-Object {
    $group=$_;$performers=@((Get-ReplacementGroupPerformers $group).name) -join ', ';$tags=@($group.tags.name) -join ', '
    $text=switch($mode){'Title' {$group.name};'Group' {$group.name};'Performer' {$performers};'Studio' {$group.studio.name};'Tag' {$tags};default {"$($group.name) $performers $($group.studio.name) $tags"}}
    [string]$text -like $likeQuery
   })}
  }
  'Recently Added' {
   $field=if($View.Mode.SelectedIndex -eq 1){'updated_at'}else{'created_at'}
   $period=[string]$View.Choice.SelectedItem
   $cutoff=switch($period){'Today' {(Get-Date).Date};'7 days' {(Get-Date).AddDays(-7)};'30 days' {(Get-Date).AddDays(-30)};default {[datetime]::MinValue}}
   $items=@($items | Where-Object {$date=[datetime]::MinValue;[datetime]::TryParse([string]$_.$field,[ref]$date) -and $date -ge $cutoff} | Sort-Object $field -Descending)
  }
  'Missing Information' {
   $checked=@($View.Checks | Where-Object {$_.Checked} | ForEach-Object {$_.Text})
   $items=@($items | Where-Object {$missing=@(Get-ReplacementGroupMissing $_);@($missing | Where-Object {$checked -contains $_}).Count -gt 0})
  }
  'By Performer' {
   $selected=$View.Choice.SelectedItem
   $items=@($items | Where-Object {$group=$_;@((Get-ReplacementGroupPerformers $group) | Where-Object {[string]$_.id -eq [string]$selected.id}).Count -gt 0})
  }
  'By Studio' {$selected=$View.Choice.SelectedItem;$items=@($items | Where-Object {$null -ne $_.studio -and [string]$_.studio.id -eq [string]$selected.id})}
  'Tag Search' {$selected=$View.Choice.SelectedItem;$items=@($items | Where-Object {@($_.tags | Where-Object {[string]$_.id -eq [string]$selected.id}).Count -gt 0})}
 }
 return $items
}
function Refresh-GroupCover {
 if($null -eq $script:GroupsTabs.SelectedTab){return}
 $view=$script:ReplacementGroupsViews[[string]$script:GroupsTabs.SelectedTab.Name]
 if($null -eq $view -or $null -eq $view.FrontPicture){return}
 foreach($side in @('Front','Back')){
  $group=$view.SelectedGroup;$image=$null
  if($null -ne $group){
   $url=if($side -eq 'Front'){$group.front_image_path}else{$group.back_image_path}
   $image=[pscustomobject]@{id="group-$($group.id)-$side";paths=[pscustomobject]@{image=[string]$url;thumbnail=''}}
   $view[$side+'Picture'].AccessibleName="$($group.name) - $side cover"
   $view[$side+'Label'].Text=if([string]::IsNullOrWhiteSpace([string]$url)){"$side cover (missing)"}else{"$side cover"}
  }else{$view[$side+'Label'].Text="$side cover"}
  Set-CelebrityImage $image $view[$side+'Picture']
 }
}
function Show-ReplacementGroupSelection([string]$Operation){
 $view=$script:ReplacementGroupsViews[$Operation]
 if($null -eq $view){return}
 $view.SelectedGroup=$null
 if($view.Grid.SelectedRows.Count){
  $id=[string]$view.Grid.SelectedRows[0].Cells['GroupID'].Value
  $view.SelectedGroup=$script:GroupCache | Where-Object {[string]$_.id -eq $id} | Select-Object -First 1
 }
 if($null -ne $view.Details){
  $view.Details.Rows.Clear();$group=$view.SelectedGroup
  if($null -ne $group){
   foreach($pair in @(@('Name',$group.name),@('Date',$group.date),@('Studio',$group.studio.name),@('Director',$group.director),@('Synopsis',$group.synopsis),@('Aliases',($group.aliases -join ', ')),@('Tags',(@($group.tags.name) -join ', ')),@('Duration',(Format-SceneDuration $group.duration)),@('Scenes',$group.scene_count),@('Created',$group.created_at),@('Updated',$group.updated_at))){[void]$view.Details.Rows.Add($pair[0],[string]$pair[1])}
   foreach($performer in @(Get-ReplacementGroupPerformers $group)){
    $index=$view.Details.Rows.Add('Performer',[string]$performer.name)
    $cell=New-Object Windows.Forms.DataGridViewLinkCell;$cell.Value=[string]$performer.name;$cell.Tag=[pscustomobject]@{Kind='Performer';Id=[string]$performer.id;Name=[string]$performer.name};$cell.LinkColor=[Drawing.Color]::FromArgb(99,205,255)
    $view.Details.Rows[$index].Cells['Value']=$cell
   }
   foreach($scene in @(Get-ReplacementGroupScenes ([string]$group.id))){
    $index=$view.Details.Rows.Add('Linked scene',(Get-SceneTitle $scene))
    $cell=New-Object Windows.Forms.DataGridViewLinkCell;$cell.Value=Get-SceneTitle $scene;$cell.Tag=[pscustomobject]@{Kind='Scene';Id=[string]$scene.id};$cell.LinkColor=[Drawing.Color]::FromArgb(99,205,255)
    $view.Details.Rows[$index].Cells['Value']=$cell
   }
  }
 }
 Refresh-GroupCover
}
function Initialize-ReplacementGroupSelector($View){
 if($null -eq $View.Choice -or $View.Operation -notin @('By Performer','By Studio','Tag Search')){return}
 $previous=if($null -ne $View.Choice.SelectedItem){[string]$View.Choice.SelectedItem.id}else{''}
 $records=@{}
 foreach($group in $script:GroupCache){
  $entities=switch($View.Operation){'By Performer' {@(Get-ReplacementGroupPerformers $group)};'By Studio' {@($group.studio)};'Tag Search' {@($group.tags)}}
  foreach($entity in $entities){if($null -ne $entity -and $entity.id){$records[[string]$entity.id]=$entity}}
 }
 $View.Choice.Items.Clear();$View.Choice.DisplayMember='Label'
 foreach($entity in @($records.Values | Sort-Object name,id)){
  $item=[pscustomobject]@{id=[string]$entity.id;Label=[string]$entity.name}
  [void]$View.Choice.Items.Add($item)
  if($item.id -eq $previous){$View.Choice.SelectedItem=$item}
 }
 if($View.Choice.SelectedIndex -lt 0 -and $View.Choice.Items.Count){$View.Choice.SelectedIndex=0}
}
function Invoke-ReplacementGroupOperationCore([string]$Operation,[string]$Action='Run'){
 if($script:SubjectViews -and $script:SubjectViews.ContainsKey($Operation)){Invoke-SubjectOperation $Operation $Action;return}
 $view=$script:ReplacementGroupsViews[$Operation]
 if(-not $script:IsConnected){$status.Text='Press Start & Connect first.';return}
 $form.Cursor='WaitCursor'
 try{
  if(-not $script:GroupCacheLoaded){[void](Load-GroupCache)}
  if(-not $script:SceneCacheLoaded){[void](Load-SceneCache)}
  if($Action -eq 'Enter'){
   Initialize-ReplacementGroupSelector $view
   if($Operation -in @('Search','Recently Added','Missing Information','Duplicate Finder','By Performer','By Studio','Tag Search','File Health')){return}
  }
  if($Action -eq 'ShowAll'){$view.Query.Clear()}
  $view.Grid.Rows.Clear()
  if($Operation -eq 'Duplicate Finder'){
   $seen=@{}
   foreach($group in $script:GroupCache){
    foreach($name in @($group.name)+@($group.aliases)){
     $key=([string]$name).Trim().ToLowerInvariant()
     if(-not $key){continue}
     if($seen.ContainsKey($key) -and [string]$seen[$key].id -ne [string]$group.id){[void]$view.Grid.Rows.Add([string]$group.id,[string]$group.name,[string]$seen[$key].name,'Same name or alias')}
     else{$seen[$key]=$group}
    }
   }
  }elseif($Operation -eq 'File Health'){
   foreach($group in $script:GroupCache){
    $scenes=@(Get-ReplacementGroupScenes ([string]$group.id))
    if(-not $scenes.Count){[void]$view.Grid.Rows.Add([string]$group.id,[string]$group.name,'No linked scenes','');continue}
    foreach($scene in $scenes){
     $files=@($scene.files | Where-Object {$null -ne $_})
     if(-not $files.Count){[void]$view.Grid.Rows.Add([string]$group.id,[string]$group.name,('No file metadata: '+(Get-SceneTitle $scene)),'');continue}
     foreach($file in $files){
      $issues=@(if([string]::IsNullOrWhiteSpace([string]$file.path)){'Missing path'};if(-not $file.size){'Missing size'};if(-not $file.duration){'Missing duration'};if(-not $file.width -or -not $file.height){'Missing resolution'};if(-not $file.video_codec){'Missing video codec'})
      if($issues.Count){[void]$view.Grid.Rows.Add([string]$group.id,[string]$group.name,($issues -join ', '),[string]$file.path)}
     }
    }
   }
  }else{
   if($Operation -eq 'Group Browser' -and $script:BrowserSearchViews){$results=@(Get-ToolkitBrowserResults 'Groups')}else{$results=@(Get-ReplacementGroupsResults $view)}
   foreach($group in $results){
    $values=@([string]$group.id,[string]$group.name,[string]$group.date,[string]$group.studio.name,(@((Get-ReplacementGroupPerformers $group).name) -join ', '),(@($group.tags.name) -join ', '))
    if($Operation -eq 'Missing Information'){$values+=(@(Get-ReplacementGroupMissing $group) -join ', ')}
    [void]$view.Grid.Rows.Add([object[]]$values)
   }
   if($Operation -eq 'Search' -and $view.Query.Text.Trim() -and -not $results.Count){[void][ToolkitMessageDialog]::Show("No groups were found matching '$($view.Query.Text.Trim())'.",'No Results Found',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Information)}
  }
  if($null -ne $view.Hint -and $Operation -eq 'Tag Search'){$view.Hint.Text="$($view.Grid.Rows.Count) groups. Select a row for details; double-click to open in Stash."}
  $status.Text="$($view.Grid.Rows.Count) group(s) shown"
  Show-ReplacementGroupSelection $Operation
 }catch{[void][ToolkitMessageDialog]::Show($_.Exception.Message,'Groups',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Error)}
 finally{$form.Cursor='Default'}
}
function Connect-ReplacementGroupsAction($Control,[string]$Operation,[string]$Action){
 $Control.Name='ReplacementGroups|'+$Operation+'|'+$Action
 $Control.Add_Click({
  param($sender,$e)
  $parts=$sender.Name -split '\|';$view=$script:ReplacementGroupsViews[$parts[1]]
  switch($parts[2]){
   'CSV' {Export-GridCsv $view.Grid 'stash-groups.csv'}
   'HTML' {Export-GridHtml $view.Grid 'stash-groups.html' ('Stash Groups - '+$view.Operation)}
   'ToggleChecks' {$checked=@($view.Checks | Where-Object {$_.Checked}).Count -eq $view.Checks.Count;foreach($check in $view.Checks){$check.Checked=-not $checked};$sender.Text=if($checked){'Select All'}else{'Deselect All'}}
   default {Invoke-ReplacementGroupOperation $parts[1] $parts[2]}
  }
 })
}
function Add-ReplacementGroupContextMenu($Control,[string]$Operation){
 $menu=New-Object Windows.Forms.ContextMenuStrip;$menu.Tag=$Operation
 $go=New-Object Windows.Forms.ToolStripMenuItem;$go.Text='Go to Group';$go.Name=$Operation
 [void]$menu.Items.Add($go)
 $go.Add_Click({param($sender,$e) $group=$script:ReplacementGroupsViews[$sender.Name].SelectedGroup;if($null -ne $group){Open-StashToolkitLink ((Get-StashUrl)+'/groups/'+$group.id)}})
 $menu.Add_Opening({param($sender,$e) $sender.Items[0].Enabled=($null -ne $script:ReplacementGroupsViews[[string]$sender.Tag].SelectedGroup)})
 $Control.ContextMenuStrip=$menu
 if($Control -is [Windows.Forms.DataGridView]){
  # The generic scene-menu installer must not replace this Groups menu.
  $Control.Tag='SceneContextEnabled'
  $Control.Add_CellMouseDown({param($sender,$e) if($e.Button -eq [Windows.Forms.MouseButtons]::Right -and $e.RowIndex -ge 0){$sender.ClearSelection();$sender.Rows[$e.RowIndex].Selected=$true}})
 }
}
function New-ReplacementGroupsView {
 param([string]$Operation,$SourcePage,$SourceGrid,$SourceDetails=$null,$SourcePicture=$null)
 $map=@{};$page=Copy-GroupsSceneControl $SourcePage $map
 $page.Text=$Operation;$page.Name=$Operation
 [void]$script:GroupsTabs.TabPages.Add($page)
 $view=@{Operation=$Operation;Page=$page;Grid=$map[$SourceGrid];Details=$null;SelectedGroup=$null;Choice=$null;Query=$null;Mode=$null;Checks=@();Hint=$null;FrontPicture=$null;BackPicture=$null}
 if($null -ne $SourceDetails){$view.Details=$map[$SourceDetails]}
 $grid=$view.Grid;$grid.Name=$Operation
 foreach($column in $grid.Columns){if($column.Name -eq 'SceneID'){$column.Name='GroupID'};if($column.HeaderText -eq 'Scene'){$column.HeaderText='Group'}}
 if($Operation -eq 'Missing Information'){
  foreach($entry in $sceneMissingOptions.GetEnumerator()){
   $check=$map[$entry.Value]
   $check.Text=switch($entry.Key){'Title' {'Name'};'Rating' {'Front cover'};'File' {'Back cover'};default {$entry.Key}}
   $view.Checks+= $check
  }
 }
 if($null -ne $SourcePicture){
  $old=$map[$SourcePicture];$parent=$old.Parent
  $covers=New-Object Windows.Forms.TableLayoutPanel;$covers.Dock=$old.Dock;$covers.Size=$old.Size;$covers.Location=$old.Location;$covers.Margin=$old.Margin;$covers.BackColor=$old.BackColor;$covers.ColumnCount=2;$covers.RowCount=2
  [void]$covers.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle('Percent',50)));[void]$covers.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle('Percent',50)))
  [void]$covers.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',24)));[void]$covers.RowStyles.Add((New-Object Windows.Forms.RowStyle('Percent',100)))
  foreach($side in @('Front','Back')){
   $label=New-Object Windows.Forms.Label;$label.Text="$side cover";$label.Dock='Fill';$label.TextAlign='MiddleCenter';$label.ForeColor=[Drawing.Color]::White
   $picture=New-Object Windows.Forms.PictureBox;$picture.Dock='Fill';$picture.SizeMode='Zoom';$picture.BackColor=$old.BackColor;$picture.BorderStyle=$old.BorderStyle;$picture.Cursor=[Windows.Forms.Cursors]::Hand
   Register-ToolkitImage $picture
   
   Add-ReplacementGroupContextMenu $picture $Operation
   $view[$side+'Picture']=$picture;$view[$side+'Label']=$label
   $column=if($side -eq 'Front'){0}else{1}
   [void]$covers.Controls.Add($label,$column,0);[void]$covers.Controls.Add($picture,$column,1)
  }
  if($parent -is [Windows.Forms.TableLayoutPanel]){$position=$parent.GetPositionFromControl($old);$parent.Controls.Remove($old);[void]$parent.Controls.Add($covers,$position.Column,$position.Row)}
  else{$index=$parent.Controls.GetChildIndex($old);$parent.Controls.Remove($old);[void]$parent.Controls.Add($covers);$parent.Controls.SetChildIndex($covers,$index)}
  $old.Dispose()
 }
 $script:ReplacementGroupsViews[$Operation]=$view
 Add-ReplacementGroupContextMenu $grid $Operation
 if($null -ne $view.Details){$view.Details.Tag='SceneContextEnabled'}
 $grid.Add_SelectionChanged({param($sender,$e) Show-ReplacementGroupSelection $sender.Name})
 $grid.Add_CellDoubleClick({param($sender,$e) if($e.RowIndex -ge 0){Open-StashToolkitLink ((Get-StashUrl)+'/groups/'+$sender.Rows[$e.RowIndex].Cells['GroupID'].Value)}})
 if($null -ne $view.Details){$view.Details.Add_CellContentClick({
  param($sender,$e)
  if($e.RowIndex -lt 0 -or $e.ColumnIndex -lt 0){return};$link=$sender.Rows[$e.RowIndex].Cells[$e.ColumnIndex].Tag
  if($null -eq $link){return}
  if($link.Kind -eq 'Scene'){Open-StashToolkitLink ((Get-StashUrl)+'/scenes/'+$link.Id)}
  elseif($link.Kind -eq 'Performer'){$performer=Find-CachedPerformer $link.Id $link.Name;if($null -ne $performer){Show-ScenePerformerPopup $performer}}
 })}
 switch($Operation){
  'Search' {
   $view.Query=$map[$sceneSearchBox];$view.Choice=$map[$sceneFilter];$view.Hint=$map[$sceneSearchHint]
   Connect-ReplacementGroupsAction $map[$sceneSearchButton] $Operation 'Run';Connect-ReplacementGroupsAction $map[$sceneRefreshButton] $Operation 'ShowAll'
   Connect-ReplacementGroupsAction $map[$sceneSearchExportCsv] $Operation 'CSV';Connect-ReplacementGroupsAction $map[$sceneSearchExportHtml] $Operation 'HTML'
   $view.Query.Name=$Operation;$view.Query.Add_KeyDown({param($sender,$e) if($e.KeyCode -eq 'Enter'){$e.SuppressKeyPress=$true;Invoke-ReplacementGroupOperation $sender.Name}})
  }
  'Recently Added' {$view.Mode=$map[$recentMode];$view.Choice=$map[$recentDays];Connect-ReplacementGroupsAction $map[$recentBtn] $Operation 'Run'}
  'Missing Information' {Connect-ReplacementGroupsAction $map[$missingBtn] $Operation 'Run';Connect-ReplacementGroupsAction $map[$missingSelectAll] $Operation 'ToggleChecks'}
  'Duplicate Finder' {Connect-ReplacementGroupsAction $map[$dupBtn] $Operation 'Run'}
  'By Performer' {$view.Choice=$map[$byPerformerCombo];$view.Choice.Items.Clear();Connect-ReplacementGroupsAction $map[$byPerformerButton] $Operation 'Run';Connect-ReplacementGroupsAction $map[$byPerformerExportCsv] $Operation 'CSV';Connect-ReplacementGroupsAction $map[$byPerformerExportHtml] $Operation 'HTML'}
  'By Studio' {$view.Choice=$map[$byStudio.Combo];$view.Choice.Items.Clear();Connect-ReplacementGroupsAction $map[$byStudio.Button] $Operation 'Run'}
  'Tag Search' {$view.Choice=$map[$tagSceneCombo];$view.Choice.Items.Clear();$view.Hint=$map[$tagSceneResultNote];Connect-ReplacementGroupsAction $map[$tagSceneButton] $Operation 'Run';Connect-ReplacementGroupsAction $map[$tagSceneExportCsv] $Operation 'CSV';Connect-ReplacementGroupsAction $map[$tagSceneExportHtml] $Operation 'HTML'}
  'File Health' {Connect-ReplacementGroupsAction $map[$healthBtn] $Operation 'Run';$map[$healthNote].Text='Checks file metadata for scenes linked to each group and reports missing or incomplete information.'}
 }
 foreach($sourceControl in $map.Keys){
  if($sourceControl -is [Windows.Forms.Label] -and $sourceControl.Text -like '*Right-click the screenshot*'){
   $map[$sourceControl].Text='Click a cover to enlarge; right-click to view this group in Stash'
  }
 }
 if($Operation -in @('By Performer','By Studio')){
  $page.Add_Resize({param($sender,$e) $v=$script:ReplacementGroupsViews[$sender.Name];$v.Grid.Height=[Math]::Max(220,[int](($sender.ClientSize.Height-58)*0.58))})
 }
}
New-ReplacementGroupsView 'Search' $sceneSearchTab $sceneSearchGrid $sceneSearchDetails $sceneScreenshot
New-ReplacementGroupsView 'Recently Added' $sceneRecentTab $sceneRecentGrid $recentSceneDetails $recentScreenshot
New-ReplacementGroupsView 'Missing Information' $sceneMissingTab $sceneMissingGrid $missingSceneDetails $missingScreenshot
New-ReplacementGroupsView 'Group Browser' $sceneBrowserTab $sceneBrowserGrid $sceneBrowserDetails $browserScreenshot
New-ReplacementGroupsView 'Duplicate Finder' $sceneDupTab $sceneDupGrid
New-ReplacementGroupsView 'By Performer' $byPerformerTab $byPerformerGrid $byPerformerDetails $byPerformerPicture
New-ReplacementGroupsView 'By Studio' $byStudio.Tab $byStudio.Grid $byStudioDetails $byStudioPicture
New-ReplacementGroupsView 'Tag Search' $tagSceneTab $tagSceneRelationGrid $tagSceneDetails $tagScenePicture
# File Health is excluded from Groups.
$script:GroupsTabs.SelectedIndex=0
$script:GroupsTabs.Add_SelectedIndexChanged({if($null -ne $script:GroupsTabs.SelectedTab){Invoke-ReplacementGroupOperation $script:GroupsTabs.SelectedTab.Name 'Enter';Refresh-GroupCover}})
$tabGroups.Add_Enter({if($null -ne $script:GroupsTabs.SelectedTab){Invoke-ReplacementGroupOperation $script:GroupsTabs.SelectedTab.Name 'Enter';Refresh-GroupCover}})


# ---------- Not-connected tab warning ----------
# Every working tab shows a clear warning until Stash is connected.
$script:ConnectionWarningLabels=@()

function Add-ConnectionWarning([System.Windows.Forms.TabPage]$Tab) {
    if($null -eq $Tab -or $Tab -eq $tabAbout -or $Tab -eq $tabHome){return}

    $warning=New-Object System.Windows.Forms.Label
    $warning.Text="⚠  NOT CONNECTED TO STASH  —  Use Start & Connect above to begin."
    $warning.Dock=[System.Windows.Forms.DockStyle]::Top
    $warning.Height=38
    $warning.TextAlign=[System.Drawing.ContentAlignment]::MiddleCenter
    $warning.Font=New-Object System.Drawing.Font("Segoe UI",10,[System.Drawing.FontStyle]::Bold)
    $warning.ForeColor=[System.Drawing.Color]::White
    $warning.BackColor=[System.Drawing.Color]::FromArgb(190,55,55)
    $warning.Padding=New-Object System.Windows.Forms.Padding(8,0,8,0)
    $warning.Visible=(-not $script:IsConnected)
    [void]$Tab.Controls.Add($warning)
    $warning.BringToFront()
    $script:ConnectionWarningLabels += $warning
}

function Update-ConnectionWarnings {
    $show=(-not $script:IsConnected)
    foreach($warning in @($script:ConnectionWarningLabels)){
        if($null -ne $warning){
            $warning.Visible=$show
            if($show){$warning.BringToFront()}
        }
    }
}

foreach($toolTab in @($tabs.TabPages)){
    if($toolTab -ne $tabAbout){Add-ConnectionWarning $toolTab}
}
Update-ConnectionWarnings

# ---------- DPI-safe button sizing ----------
# Ensure every button is wide enough for its full caption on Windows
# display scaling while preserving any deliberately larger existing size.
function Set-ButtonCaptionSafeSize {
 param([System.Windows.Forms.Button]$Button)
 if($null -eq $Button){return}
 $Button.AutoSize=$true
 $Button.AutoSizeMode=[System.Windows.Forms.AutoSizeMode]::GrowAndShrink
