# ---------- Connection lock state ----------
$script:ConnectionLocked=$false

function Set-ConnectionLocked([bool]$Locked) {
 $script:ConnectionLocked=$Locked
 $txtUrl.ReadOnly=$Locked
 $txtKey.ReadOnly=$Locked

 if($Locked){

  $btnConnect.FlatStyle=[System.Windows.Forms.FlatStyle]::Flat
  $btnConnect.FlatAppearance.BorderSize=0
  $btnConnect.BackColor=$script:BarConnectedBack
  $btnConnect.ForeColor=[System.Drawing.Color]::White
  $btnOpenStash.Enabled=$true
 } else {
  $btnConnect.Text="●  Start && Connect"
  $btnConnect.FlatStyle=[System.Windows.Forms.FlatStyle]::Flat
  $btnConnect.BackColor=$script:BarActionBack
  $btnConnect.ForeColor=$script:BarActionFore
  $btnConnect.FlatAppearance.BorderSize=1
  $btnConnect.FlatAppearance.BorderColor=$script:BarFieldBorder
  $btnOpenStash.Enabled=$false
  $txtKey.Focus()
  $txtKey.SelectAll()
 }
}

# Load the API key from the local Stash configuration when available.
function Import-StashApiKey {
    $paths = @(Get-ToolkitStashConfigPaths)
    foreach ($path in $paths) {
        if (-not (Test-Path -LiteralPath $path)) { continue }
        try {
            foreach ($line in (Get-Content -LiteralPath $path -ErrorAction Stop)) {
                if ($line -match '^\s*(?:api_key|apiKey)\s*:\s*["'']?([^"''#\s]+)') {
                    $key = $Matches[1].Trim()
                    if ($key) { $txtKey.Text = $key; return $true }
                }
            }
        } catch { continue }
    }
    return $false
}

$btnOpenStash.Add_Click({
    try{
        $url=$txtUrl.Text.Trim()
        if([string]::IsNullOrWhiteSpace($url)){return}
        if($url -notmatch '^https?://'){$url="http://$url"}
        Open-StashToolkitLink $url
        $status.Text="Opened Stash in the Stash tab."
    }catch{
        [ToolkitMessageDialog]::Show($_.Exception.Message,"Unable to open Stash","OK","Error")
    }
})


function Set-ApiKeyRevealEnabled([bool]$Enabled){
 $txtKey.UseSystemPasswordChar=$true
 $showKey.Text='Show'
 $showKey.Enabled=$Enabled
}
Set-ApiKeyRevealEnabled $false
$showKey.Add_Click({
 if(-not $script:IsConnected){Set-ApiKeyRevealEnabled $false;return}
