})

$btnConnect.Add_Click({
 $script:StashStartPressed=$true
 $btnStopStash.Enabled=$true
 if($script:IsConnected){
  $script:IsConnected=$false
if(Get-Command Set-HomeNavigationEnabled -ErrorAction SilentlyContinue){Set-HomeNavigationEnabled $false}
  $btnConnect.Text="●  Start && Connect"
  $btnConnect.BackColor=$script:BarActionBack
  $btnConnect.ForeColor=$script:BarActionFore
  $btnConnect.FlatStyle=[System.Windows.Forms.FlatStyle]::Flat
  $btnConnect.FlatAppearance.BorderSize=1
  $btnConnect.FlatAppearance.BorderColor=$script:BarFieldBorder
  $txtUrl.ReadOnly=$false
  $txtKey.ReadOnly=$false
  $btnOpenStash.Enabled=$false
  $libraryCountTable.Visible=$false
  $btnRescan.Visible=$false
  $status.Visible=$true
  $txtKey.Clear()
  Set-ApiKeyRevealEnabled $false
  $status.Text="Disconnected. Stash is still running."
  return
 }

 try{
  $baseUrl=$txtUrl.Text.Trim().TrimEnd('/')
  if([string]::IsNullOrWhiteSpace($baseUrl)){throw "Enter the Stash URL first."}
  $stashExe=Get-ToolkitStashExecutable

  # A Stash server that already answers (started earlier, running as a service
  # or on another computer) is used as it is; nothing needs to be started.
  $status.Text="Checking Stash...";[System.Windows.Forms.Application]::DoEvents()
  $stashReady=$false
  try{[void](Invoke-WebRequest -Uri $baseUrl -Method Get -TimeoutSec 3 -UseBasicParsing -ErrorAction Stop);$stashReady=$true}catch{}

  if(-not $stashReady){
   # Check whether this Stash executable is already running.
   $stashRunning=$false
   try{
    $stashRunning=@(Get-CimInstance Win32_Process -Filter "Name='stash-win.exe'" -ErrorAction Stop |
     Where-Object {$_.ExecutablePath -eq $stashExe}).Count -gt 0
   }catch{
    # Fallback if CIM cannot expose ExecutablePath.
    $stashRunning=$null -ne (Get-Process -Name "stash-win" -ErrorAction SilentlyContinue)
   }

   if(-not $stashRunning){
    if([string]::IsNullOrWhiteSpace($stashExe) -or -not (Test-Path -LiteralPath $stashExe -PathType Leaf)){
     [void][ToolkitMessageDialog]::Show("Stash is not answering at $baseUrl, and stash-win.exe was not found at:`r`n$stashExe`r`n`r`nChoose stash-win.exe in the next window so the toolkit can start it. The location is remembered.","Locate Stash","OK","Information")
     $stashExe=Select-ToolkitStashExecutable
     if([string]::IsNullOrWhiteSpace($stashExe)){throw "Stash is not answering at $baseUrl, and no Stash program was chosen."}
    }
    $status.Text="Starting Stash..."
    Start-Process -FilePath $stashExe -WorkingDirectory (Split-Path -Parent $stashExe) -WindowStyle Hidden
   }else{
    $status.Text="Stash is already running. Connecting..."
   }

   [System.Windows.Forms.Application]::DoEvents()

   # Wait for Stash's web interface to answer before trying GraphQL.
   for($attempt=0;$attempt -lt 40;$attempt++){
    try{
     [void](Invoke-WebRequest -Uri $baseUrl -Method Get -TimeoutSec 2 -UseBasicParsing -ErrorAction Stop)
     $stashReady=$true
     break
    }catch{
     Start-Sleep -Milliseconds 500
     [System.Windows.Forms.Application]::DoEvents()
    }
   }
   if(-not $stashReady){
    throw "Stash did not become available at $baseUrl."
   }
  }
  $script:ToolkitStashExecutable=$stashExe

  # Read the API key from Stash's local config and fill the API field.
  if (-not (Import-StashApiKey) -and [string]::IsNullOrWhiteSpace($txtKey.Text)) {
   $status.Text="API key not found in local config; attempting connection with current settings."
  }

  $status.Text="Stash is running. Connecting..."
  [System.Windows.Forms.Application]::DoEvents()

  # Confirm the API answers before building caches; a wrong key used to give a
  # "connected" toolkit with empty lists.
  try{[void](Invoke-StashGraphQL 'query { version { version } }')}
  catch{throw "Stash is running, but its API refused the request.`r`n`r`n$($_.Exception.Message)`r`n`r`nCheck the Stash URL and API key."}

    $form.Cursor="WaitCursor";$status.Text="Connecting and building library cache...";[System.Windows.Forms.Application]::DoEvents()
   Clear-ExtendedLibraryCaches
   $script:PerformerDropDownBuilt=$false
   $script:StatisticsLoadedForConnection=$false
   # Scene/Group/Studio cache loaders require IsConnected=True.
   # Keep Home navigation disabled until the unified cache has completed.
   $script:IsConnected=$true
   $script:ToolkitConnectionId=[guid]::NewGuid().ToString()
   Load-ExtendedLibraryCaches
   Hide-StashCommandWindow $stashExe
   $performerAutoComplete.Clear()
   $autoNames=@($script:AllPerformers | ForEach-Object {[string]$_.name} | Where-Object {-not [string]::IsNullOrWhiteSpace($_)} | Sort-Object -Unique)
   if($autoNames.Count -gt 0){$performerAutoComplete.AddRange([string[]]$autoNames)}
   Set-ConnectionLocked $true;
Set-HomeNavigationEnabled $true
Set-TopLevelTabsEnabled $true
Refresh-ByPerformerStudioSelectors
  Refresh-SceneInspectorSelector
  $btnRefreshPerformers.Enabled=$true
  Set-ApiKeyRevealEnabled $true
  $btnConnect.Text="●  Disconnect"
  $btnConnect.BackColor=$script:BarConnectedBack
  $btnConnect.ForeColor=[System.Drawing.Color]::White
  $btnConnect.FlatStyle=[System.Windows.Forms.FlatStyle]::Flat
  $btnConnect.FlatAppearance.BorderSize=0
  $imageCount=Get-ToolkitImageCount
  Set-LibraryStatCardValue $cardScenes "$($script:SceneCache.Count)"
  Set-LibraryStatCardValue $cardGroups "$($script:GroupCache.Count)"
  Set-LibraryStatCardValue $cardPerformers "$($script:AllPerformers.Count)"
  Set-LibraryStatCardValue $cardImages "$imageCount"
  Set-LibraryStatCardValue $cardStudios "$($script:StudioCache.Count)"
  $status.Visible=$false
  $libraryCountTable.Visible=$true
  $libraryCountTable.BringToFront()
  $btnRescan.Visible=$true
  $btnRescan.BringToFront()
  $form.Cursor="Default"
  if($tabs.SelectedTab -eq $tabStats){
   [System.Windows.Forms.Application]::DoEvents()
   $btnStats.PerformClick()
  }
 }catch{
  $form.Cursor="Default"
  $connectError=$_.Exception.Message
  # Leave the toolkit cleanly disconnected rather than half connected.
  $script:IsConnected=$false
  try{Set-HomeNavigationEnabled $false;Set-TopLevelTabsEnabled $false;Set-ConnectionLocked $false}catch{}
  $libraryCountTable.Visible=$false;$btnRescan.Visible=$false;$status.Visible=$true
  [void][ToolkitMessageDialog]::Show($connectError,"Stash Error","OK","Error")
  Set-ApiKeyRevealEnabled $false
  $status.Text="Not connected"
 }
})

# Re-pulls Scenes/Groups/Performers/Images/Studios from Stash and refreshes
# the stat cards, without the full Disconnect -> Start & Connect round trip
# (no re-checking/starting the Stash process, no re-reading the API key).
$btnRescan.Add_Click({
 if(-not $script:IsConnected){return}
 $btnRescan.Enabled=$false
 $form.Cursor="WaitCursor"
 try{
  Clear-ExtendedLibraryCaches
  $script:PerformerDropDownBuilt=$false
  $script:StatisticsLoadedForConnection=$false
  Load-ExtendedLibraryCaches
  $performerAutoComplete.Clear()
  $autoNames=@($script:AllPerformers | ForEach-Object {[string]$_.name} | Where-Object {-not [string]::IsNullOrWhiteSpace($_)} | Sort-Object -Unique)
  if($autoNames.Count -gt 0){$performerAutoComplete.AddRange([string[]]$autoNames)}
  Refresh-ByPerformerStudioSelectors
  Refresh-SceneInspectorSelector
  $imageCount=Get-ToolkitImageCount
  Set-LibraryStatCardValue $cardScenes "$($script:SceneCache.Count)"
  Set-LibraryStatCardValue $cardGroups "$($script:GroupCache.Count)"
  Set-LibraryStatCardValue $cardPerformers "$($script:AllPerformers.Count)"
  Set-LibraryStatCardValue $cardImages "$imageCount"
  Set-LibraryStatCardValue $cardStudios "$($script:StudioCache.Count)"
  if($tabs.SelectedTab -eq $tabStats){
   [System.Windows.Forms.Application]::DoEvents()
   $btnStats.PerformClick()
  }
 }catch{
  [void][ToolkitMessageDialog]::Show($_.Exception.Message,"Rescan Failed","OK","Error")
 }finally{
  $form.Cursor="Default"
  $btnRescan.Enabled=$true
 }
})

$doSearch={
 try{
  Ensure-Loaded
  $q=$txtSearch.Text.Trim().ToLowerInvariant()

  # Blank search = browse every performer.
  if([string]::IsNullOrWhiteSpace($q)){
   $script:CurrentSearchResults=@($script:AllPerformers | Sort-Object name)
  }else{
   $script:CurrentSearchResults=@($script:AllPerformers | Where-Object{
    ([string]$_.name).ToLowerInvariant().Contains($q) -or
    ((@($_.alias_list) -join " ").ToLowerInvariant().Contains($q))
   } | Sort-Object name)
  }

  $searchGrid.Rows.Clear()
  foreach($p in $script:CurrentSearchResults){
   [void]$searchGrid.Rows.Add($p.id,$p.name)
  }

  if([string]::IsNullOrWhiteSpace($q)){
   $status.Text="Showing all $($script:CurrentSearchResults.Count) performers. Click one to view the details."
  }else{
   $status.Text="Found $($script:CurrentSearchResults.Count) performer(s) matching '$($txtSearch.Text.Trim())'."
  }
 }catch{
  [ToolkitMessageDialog]::Show($_.Exception.Message,"Search Error","OK","Error")
 }
}

