 }else{
  $pic.Image=$null
  $detailsGrid.Rows.Clear()
  $performerClipsGrid.Rows.Clear()
  $lblPerformerClips.Text="Clips / Scenes"
 }
}



function Show-PerformerDropDownList {
 if(-not $script:IsConnected){
  [ToolkitMessageDialog]::Show("Please click Start & Connect first.","Performer Search","OK","Information")
  return
 }
 if(-not $script:AllPerformers){return}

 if(-not $script:PerformerDropDownBuilt){
  $progressForm=New-Object ToolkitDialogWindow
  $progressForm.Text="Building Performer List"
  $progressForm.Width=430;$progressForm.Height=125
  $progressForm.StartPosition="CenterParent"
  $progressForm.FormBorderStyle="FixedDialog"
  $progressForm.ControlBox=$false
  $progressLabel=New-Object System.Windows.Forms.Label
  $progressLabel.Text="Building performer list..."
  $progressLabel.Left=15;$progressLabel.Top=15;$progressLabel.Width=390
  $progressBar=New-Object System.Windows.Forms.ProgressBar
  $progressBar.Left=15;$progressBar.Top=45;$progressBar.Width=390;$progressBar.Height=22
  $progressBar.Minimum=0
  $sorted=@($script:AllPerformers|Sort-Object name)
  $progressBar.Maximum=[Math]::Max(1,$sorted.Count)
  [void]$progressForm.Controls.Add($progressLabel)
  [void]$progressForm.Controls.Add($progressBar)
  $progressForm.Show()
  [System.Windows.Forms.Application]::DoEvents()

  $performerDropList.BeginUpdate()
  $performerDropList.Items.Clear()
  $n=0
  foreach($p in $sorted){
   # PSCustomObject displays Name in the ListBox while retaining the ID.
   [void]$performerDropList.Items.Add([pscustomobject]@{Name=[string]$p.name;ID=[string]$p.id})
   $n++
   $progressBar.Value=[Math]::Min($n,$progressBar.Maximum)
   if(($n % 25)-eq 0){[System.Windows.Forms.Application]::DoEvents()}
  }
  $performerDropList.DisplayMember="Name"
  $performerDropList.EndUpdate()
  $progressForm.Close();$progressForm.Dispose()
  $script:PerformerDropDownBuilt=$true
 }

 # Place the real ListBox window directly under the search box.
 $pt=$txtSearch.PointToScreen((New-Object System.Drawing.Point(0,$txtSearch.Height)))
 $performerDropDown.Location=$pt
 $performerDropDown.Show()
 $performerDropDown.Activate()
 $performerDropList.Focus()
}


$btnRefreshPerformers.Add_Click({
 if(-not $script:IsConnected){
  [ToolkitMessageDialog]::Show("Please click Start & Connect first.","Refresh Performers","OK","Information")
  return
 }

 $refreshForm=New-Object ToolkitDialogWindow
 $refreshForm.Text="Refreshing Performers"
 $refreshForm.Width=650
 $refreshForm.Height=210
 $refreshForm.StartPosition="CenterParent"
 $refreshForm.FormBorderStyle="FixedDialog"
 $refreshForm.ControlBox=$false
 $refreshForm.TopMost=$true

 $refreshLabel=New-Object System.Windows.Forms.Label
 $refreshLabel.Text="Getting the latest performer information from Stash..."
 $refreshLabel.AutoSize=$false
 $refreshLabel.Left=20;$refreshLabel.Top=18;$refreshLabel.Width=595;$refreshLabel.Height=42

 $refreshProgress=New-Object System.Windows.Forms.ProgressBar
 $refreshProgress.Left=20;$refreshProgress.Top=68;$refreshProgress.Width=595;$refreshProgress.Height=30
 $refreshProgress.Style=[System.Windows.Forms.ProgressBarStyle]::Marquee
 $refreshProgress.MarqueeAnimationSpeed=25

 $refreshStatus=New-Object System.Windows.Forms.Label
 $refreshStatus.Text="Connecting to Stash..."
 $refreshStatus.Left=20;$refreshStatus.Top=110;$refreshStatus.Width=595;$refreshStatus.Height=42

 [void]$refreshForm.Controls.Add($refreshLabel)
 [void]$refreshForm.Controls.Add($refreshProgress)
 [void]$refreshForm.Controls.Add($refreshStatus)

 try{
  $btnRefreshPerformers.Enabled=$false
  $btnPerformerDrop.Enabled=$false
  $refreshForm.Show($form)
  [System.Windows.Forms.Application]::DoEvents()

  $refreshStatus.Text="Loading performers..."
  [System.Windows.Forms.Application]::DoEvents()

  Load-AllPerformers

  $refreshStatus.Text="Rebuilding performer list..."
  $refreshProgress.Style=[System.Windows.Forms.ProgressBarStyle]::Blocks
  $performerDropList.BeginUpdate()
  $performerDropList.Items.Clear()
  $sorted=@($script:AllPerformers | Sort-Object name)
  $refreshProgress.Minimum=0
  $refreshProgress.Maximum=[Math]::Max(1,$sorted.Count)
  $n=0
  foreach($p in $sorted){
   [void]$performerDropList.Items.Add([pscustomobject]@{Name=[string]$p.name;ID=[string]$p.id})
   $n++
   $refreshProgress.Value=[Math]::Min($n,$refreshProgress.Maximum)
   $refreshStatus.Text="Updating performer list: $n of $($sorted.Count)"
   if(($n % 20)-eq 0){[System.Windows.Forms.Application]::DoEvents()}
  }
  $performerDropList.DisplayMember="Name"
  $performerDropList.EndUpdate()
  $script:PerformerDropDownBuilt=$true

  $refreshStatus.Text="Refresh complete - $($sorted.Count) performers loaded."
  $refreshProgress.Value=$refreshProgress.Maximum
  [System.Windows.Forms.Application]::DoEvents()
  Start-Sleep -Milliseconds 550
  $status.Text="Performer information refreshed - $($sorted.Count) performers loaded."
 }catch{
  try{$performerDropList.EndUpdate()}catch{}
  [ToolkitMessageDialog]::Show("Could not refresh performers.`r`n`r`n$($_.Exception.Message)","Refresh Performers","OK","Error")
 }finally{
  $refreshForm.Close()
  $refreshForm.Dispose()
  $btnRefreshPerformers.Enabled=$script:IsConnected
  $btnPerformerDrop.Enabled=$script:IsConnected
 }
})

