$btnScenes.Add_Click({
 if(-not $script:CurrentPerformer){return}
 try{
  $q=@'
query PerformerScenes($filter: FindFilterType, $scene_filter: SceneFilterType) {
 findScenes(filter:$filter, scene_filter:$scene_filter) { count scenes { id title date } }
}
'@
  $d=Invoke-StashGraphQL $q @{filter=@{per_page=100;sort="date";direction="DESC"};scene_filter=@{performers=@{value=@([string]$script:CurrentPerformer.id);modifier="INCLUDES"}}}
  $lines=@($d.findScenes.scenes|ForEach-Object{"$($_.date)  $($_.title)  [ID $($_.id)]"})
  [ToolkitMessageDialog]::Show($(if($lines.Count){$lines -join "`r`n"}else{"No scenes found."}),"Scenes for $($script:CurrentPerformer.name)","OK","Information")
 }catch{[ToolkitMessageDialog]::Show("Could not load scenes.`r`n`r`n$($_.Exception.Message)","Stash Error","OK","Error")}
})

$btnMissingPic.Add_Click({
 try{
  $q=@'
query MissingImages($filter: FindFilterType, $performer_filter: PerformerFilterType) {
 findPerformers(filter:$filter, performer_filter:$performer_filter) { count performers { id name } }
}
'@
  $d=Invoke-StashGraphQL $q @{filter=@{per_page=-1;sort="name";direction="ASC"};performer_filter=@{is_missing="image"}}
  $script:MissingResults=@($d.findPerformers.performers);$mpGrid.Rows.Clear()
  foreach($p in $script:MissingResults){[void]$mpGrid.Rows.Add($p.id,$p.name)}
  if($script:MissingResults.Count -eq 0){
