$btnDup.Add_Click({
 try{
  Ensure-Loaded
  $btnDup.Enabled=$false
  $btnDupExport.Enabled=$false
  $dupGrid.Rows.Clear()
  $dupProgress.Value=0
  $dupProgressLabel.Text="Starting..."
  $status.Text="Searching for possible duplicate performers..."
  $form.Cursor=[System.Windows.Forms.Cursors]::WaitCursor
  [System.Windows.Forms.Application]::DoEvents()

  $total=$script:AllPerformers.Count
  if($total -lt 2){
   $dupProgress.Value=100
   $dupProgressLabel.Text="Finished - 0 possible duplicates"
   $status.Text="Duplicate finder finished. No possible duplicates found."
   return
  }

  for($i=0;$i -lt $total;$i++){
   $a=$script:AllPerformers[$i]
   $an=($a.name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
   $aa=@($a.alias_list|ForEach-Object{($_ -replace '[^a-zA-Z0-9]','').ToLowerInvariant()})

   for($j=$i+1;$j -lt $total;$j++){
    $b=$script:AllPerformers[$j]
    $bn=($b.name -replace '[^a-zA-Z0-9]','').ToLowerInvariant()
    $reason=$null

    if($an -eq $bn){
     $reason="Same normalized name"
    } else {
     $ba=@($b.alias_list|ForEach-Object{($_ -replace '[^a-zA-Z0-9]','').ToLowerInvariant()})
     if($aa -contains $bn -or $ba -contains $an){$reason="Name matches alias"}
    }

    if($reason){[void]$dupGrid.Rows.Add($a.id,$a.name,$b.id,$b.name,$reason)}
   }

   $pct=[Math]::Min(100,[Math]::Floor((($i+1)/$total)*100))
   if($pct -ne $dupProgress.Value){
    $dupProgress.Value=$pct
    $dupProgressLabel.Text="$pct% - checking performer $($i+1) of $total"
    [System.Windows.Forms.Application]::DoEvents()
   }
  }

  $dupProgress.Value=100
  $dupProgressLabel.Text="Finished - $($dupGrid.Rows.Count) possible duplicate(s)"
  $status.Text="Duplicate finder finished. Found $($dupGrid.Rows.Count) possible pair(s)."
 }
 catch{
  $dupProgressLabel.Text="Stopped due to an error"
  $status.Text="Duplicate finder failed."
  [ToolkitMessageDialog]::Show($_.Exception.Message,"Error","OK","Error")
 }
 finally{
  $btnDup.Enabled=$true
  $btnDupExport.Enabled=$true
  $form.Cursor=[System.Windows.Forms.Cursors]::Default
 }
})
