  $row=$dupGrid.SelectedRows[0]
  $p1=Get-PerformerById ([string]$row.Cells["ID1"].Value)
  $p2=Get-PerformerById ([string]$row.Cells["ID2"].Value)
  Fill-DuplicateDetails $p1 $dupLeft
  Fill-DuplicateDetails $p2 $dupRight
 }
})
