$setStatsProgress={
 param([int]$Percent,[string]$Message)
 $statsProgress.Visible=$true
 $statsProgress.Value=[Math]::Max(0,[Math]::Min(100,$Percent))
 $statsProgressLabel.Text=$Message
 [System.Windows.Forms.Application]::DoEvents()
}

$btnStats.Add_Click({
 try{
    Ensure-Loaded
    $statsGrid.Rows.Clear()
    $status.Text="Loading Stash statistics..."
    $btnStats.Enabled=$false
    & $setStatsProgress 5 "Starting..."
    [System.Windows.Forms.Application]::DoEvents()

    # Stash's own system statistics.
    $qStats=@'
query ToolkitStats {
  stats {
    scene_count
    scenes_size
    scenes_duration
    image_count
    images_size
    gallery_count
    performer_count
    studio_count
    tag_count
    total_o_count
    total_play_count
  }
}
'@
    $s=(Invoke-StashGraphQL $qStats).stats
    & $setStatsProgress 20 "Library totals loaded..."

    # Scene-level values used by the Stash statistics page.
    $qScenes=@'
query ToolkitSceneStats($filter: FindFilterType) {
  findScenes(filter:$filter) {
    scenes {
      play_count
      play_duration
      stash_ids { stash_id endpoint }
      files { height }
    }
  }
}
'@
    $sceneData=(Invoke-StashGraphQL $qScenes @{filter=@{per_page=-1}}).findScenes.scenes
    & $setStatsProgress 45 "Scene statistics loaded..."
    $scenesPlayed=@($sceneData|Where-Object{[int]$_.play_count -gt 0}).Count
    $totalPlayDuration=($sceneData|Measure-Object -Property play_duration -Sum).Sum
    if($null -eq $totalPlayDuration){$totalPlayDuration=0}
    $sceneWithStash=@($sceneData|Where-Object{@($_.stash_ids).Count -gt 0}).Count
    $sceneHD=@($sceneData|Where-Object{
        @($_.files|Where-Object{[int]$_.height -ge 720}).Count -gt 0
    }).Count

    # Marker count, matching the Stash statistics page.
    $markerCount="N/A"
    try{
      $qMarkers=@'
query ToolkitMarkers($filter: FindFilterType) {
  findSceneMarkers(filter:$filter) { count }
}
'@
      $markerCount=[int](Invoke-StashGraphQL $qMarkers @{filter=@{per_page=1}}).findSceneMarkers.count
    }catch{}
    & $setStatsProgress 55 "Markers checked..."

    # Performer values.
    $performerCount=[int]$s.performer_count
    $favoritePerformers=@($script:AllPerformers|Where-Object{$_.favorite}).Count
    $performerWithStash=@($script:AllPerformers|Where-Object{@($_.stash_ids).Count -gt 0}).Count

    $qMissingImage=@'
query MissingPerformerImages($filter: FindFilterType, $performer_filter: PerformerFilterType) {
  findPerformers(filter:$filter, performer_filter:$performer_filter) { count }
}
'@
    $missingPerformerImages=[int](Invoke-StashGraphQL $qMissingImage @{filter=@{per_page=1};performer_filter=@{is_missing="image"}}).findPerformers.count
    $performerWithImage=$performerCount-$missingPerformerImages
    & $setStatsProgress 68 "Performer statistics loaded..."

    # Studio image / Stash ID completeness.
    $studioWithImage="N/A";$studioWithStash="N/A"
    try{
      $qStudios=@'
query ToolkitStudios($filter: FindFilterType) {
  findStudios(filter:$filter) {
    studios { image_path stash_ids { stash_id endpoint } }
  }
}
'@
      $studios=(Invoke-StashGraphQL $qStudios @{filter=@{per_page=-1}}).findStudios.studios
      $studioWithImage=@($studios|Where-Object{-not [string]::IsNullOrWhiteSpace([string]$_.image_path)}).Count
      $studioWithStash=@($studios|Where-Object{@($_.stash_ids).Count -gt 0}).Count
    }catch{}
    & $setStatsProgress 78 "Studio statistics loaded..."

    # Tag image completeness.
    $tagWithImage="N/A"
    try{
      $qTags=@'
query ToolkitTags($filter: FindFilterType) {
  findTags(filter:$filter) { tags { image_path } }
}
'@
      $tags=(Invoke-StashGraphQL $qTags @{filter=@{per_page=-1}}).findTags.tags
      $tagWithImage=@($tags|Where-Object{-not [string]::IsNullOrWhiteSpace([string]$_.image_path)}).Count
    }catch{}
    & $setStatsProgress 86 "Tag statistics loaded..."

    # Group/movie cover completeness. Older Stash versions may not expose
    # front_image_path, so this metric gracefully shows N/A when unavailable.
    $movieCoverPct="N/A"
    try{
      $qGroups=@'
query ToolkitGroups($filter: FindFilterType) {
  findGroups(filter:$filter) { count groups { front_image_path } }
}
'@
      $gr=(Invoke-StashGraphQL $qGroups @{filter=@{per_page=-1}}).findGroups
      $withCover=@($gr.groups|Where-Object{-not [string]::IsNullOrWhiteSpace([string]$_.front_image_path)}).Count
      $movieCoverPct=Format-Percent $withCover ([int]$gr.count)
    }catch{}

    $rows=[ordered]@{
      "Scenes size"=(Format-ByteSize ([double]$s.scenes_size))
      "Scenes"=("{0:N0}" -f [int]$s.scene_count)
      "Scenes duration"=(Format-Duration ([double]$s.scenes_duration)
      )
      "Performers"=("{0:N0}" -f $performerCount)
      "Images size"=(Format-ByteSize ([double]$s.images_size))
      "Galleries"=("{0:N0}" -f [int]$s.gallery_count)
      "Images"=("{0:N0}" -f [int]$s.image_count)
      "Studios"=("{0:N0}" -f [int]$s.studio_count)
      "Tags"=("{0:N0}" -f [int]$s.tag_count)
      "Total O-count"=("{0:N0}" -f [int]$s.total_o_count)
      "Total play count"=("{0:N0}" -f [int]$s.total_play_count)
      "Scenes played"=("{0:N0}" -f $scenesPlayed)
      "Total play duration"=(Format-Duration ([double]$totalPlayDuration))
      "Scene Stash IDs"=(Format-Percent $sceneWithStash ([int]$s.scene_count))
      "Studio Stash IDs"=$(if($studioWithStash -eq "N/A"){"N/A"}else{Format-Percent ([double]$studioWithStash) ([int]$s.studio_count)})
      "Performer Stash IDs"=(Format-Percent $performerWithStash $performerCount)
      "Favorite performers"=("{0:N0}" -f $favoritePerformers)
      "Markers"=$(if($markerCount -eq "N/A"){"N/A"}else{"{0:N0}" -f [int]$markerCount})
      "Tag images"=$(if($tagWithImage -eq "N/A"){"N/A"}else{Format-Percent ([double]$tagWithImage) ([int]$s.tag_count)})
      "Studio images"=$(if($studioWithImage -eq "N/A"){"N/A"}else{Format-Percent ([double]$studioWithImage) ([int]$s.studio_count)})
      "Performer images"=(Format-Percent $performerWithImage $performerCount)
      "Movie covers"=$movieCoverPct
      "Scenes HD"=(Format-Percent $sceneHD ([int]$s.scene_count))
    }

    & $setStatsProgress 94 "Updating dashboard..."
    foreach($k in $rows.Keys){
        [void]$statsGrid.Rows.Add($k,$rows[$k])
        if($statsCards.ContainsKey($k)){Set-StatCardValue $k ([string]$rows[$k])}
    }
    & $setStatsProgress 100 "Statistics loaded"
    $status.Text="Statistics refreshed."
    $script:StatisticsLoadedForConnection=$true
    $btnStats.Enabled=$true
    $statsProgress.Visible=$true
    $statsProgress.Value=0
    $statsProgressLabel.Text=""
 }catch{
    [ToolkitMessageDialog]::Show($_.Exception.Message,"Statistics Error","OK","Error")
    $status.Text="Statistics refresh failed."
    $script:StatisticsLoadedForConnection=$false
    $btnStats.Enabled=$true
    $statsProgress.Visible=$false
    $statsProgressLabel.Text=""
 }
})

