# GUI standard: every button in Stash Toolkit is 30 pixels high.
function Set-ToolkitButtonHeight {
 param([System.Windows.Forms.Control]$Parent)
 foreach($control in @($Parent.Controls)){
  if($control -is [System.Windows.Forms.Button]){$control.Height=30}
  if($control.HasChildren){Set-ToolkitButtonHeight $control}
 }
}
