# --- Top-level tab header lock v5.1.67 ---
# WinForms TabPage.Enabled only darkens the page contents; it does NOT disable
# the tab header. This locks the actual headers and paints them disabled.
$script:TopTabsUnlocked=$false
$tabs.DrawMode=[System.Windows.Forms.TabDrawMode]::OwnerDrawFixed

$tabs.Add_DrawItem({param($sender,$e) Draw-RoundedToolkitTab $sender $e})

# Block mouse clicks on every actual top-level tab header except Home.
$tabs.Add_MouseDown({
 param($sender,$e)
 if(-not $script:TopTabsUnlocked){
   for($i=1;$i -lt $sender.TabPages.Count;$i++){
     if($sender.GetTabRect($i).Contains($e.Location)){
       $sender.SelectedTab=$tabHome
       $status.Text="Connect to Stash before opening Toolkit sections."
       return
     }
   }
 }
})

# Also block keyboard/programmatic selection while disconnected.
$tabs.Add_Selecting({
 param($sender,$e)
 if((-not $script:TopTabsUnlocked) -and ($e.TabPage -ne $tabHome)){
   $e.Cancel=$true
   $status.Text="Connect to Stash before opening Toolkit sections."
 }
})

function Set-TopLevelTabsEnabled {
 param([bool]$Enabled)
 $script:TopTabsUnlocked=$Enabled
 if(-not $Enabled){$tabs.SelectedTab=$tabHome}
 $tabs.Invalidate()
}
Set-TopLevelTabsEnabled $false
