function Get-ReplacementPerformerSearchResults([string]$Query,[string]$Mode){
 $items=@($script:AllPerformers | Where-Object {$null -ne $_})
 $likeQuery='*'+(ConvertTo-ToolkitLikePattern $Query)+'*'
 if($Query){$items=@($items | Where-Object {
  $p=$_;$tags=@($p.tags.name) -join ', '
  $text=switch($Mode){'Name' {$p.name};'Alias' {($p.alias_list -join ', ')};'Country' {$p.country};'Gender' {$p.gender};'Tag' {$tags};default {"$($p.name) $($p.disambiguation) $($p.alias_list -join ' ') $($p.country) $($p.gender) $tags"}}
  [string]$text -like $likeQuery
 })}
 return @($items | Sort-Object name)
}
function Refresh-ReplacementPerformerSearchPicture {
 $v=$script:PerformerSearchView
 if($null -eq $v){return}
 $p=$v.Selected;$image=$null
 if($null -ne $p){
  $image=[pscustomobject]@{id="performer-$($p.id)";paths=[pscustomobject]@{image=[string]$p.image_path;thumbnail=''}}
  $v.Picture.AccessibleName=[string]$p.name
 }
 Set-CelebrityImage $image $v.Picture
}
function Show-ReplacementPerformerSearchSelection {
 $v=$script:PerformerSearchView;$v.Selected=$null;$v.Details.Rows.Clear()
 if($v.Grid.SelectedRows.Count){
  $id=[string]$v.Grid.SelectedRows[0].Cells['PerformerID'].Value
  $v.Selected=$script:AllPerformers | Where-Object {[string]$_.id -eq $id} | Select-Object -First 1
 }
 $p=$v.Selected;$script:CurrentPerformer=$p
 if($null -ne $p){
    $props = [ordered]@{
        "ID"=$p.id; "Name"=$p.name; "Disambiguation"=$p.disambiguation
        "Aliases"=($p.alias_list -join ", "); "Gender"=$p.gender
        "Birthdate"=$p.birthdate; "Age"=(Get-AgeText $p); "Death date"=$p.death_date
        "Country"=$p.country; "Ethnicity"=$p.ethnicity; "Hair colour"=$p.hair_color
        "Eye colour"=$p.eye_color; "Height (cm)"=$p.height_cm; "Weight"=$p.weight
        "Measurements"=$p.measurements; "Fake tits"=$p.fake_tits
        "Penis length"=$p.penis_length; "Circumcised"=$p.circumcised
        "Career length"=$p.career_length; "Tattoos"=$p.tattoos; "Piercings"=$p.piercings
        "Favourite"=$p.favorite; "Rating / 100"=$p.rating100
        "Scenes"=$p.scene_count; "Images"=$p.image_count; "Galleries"=$p.gallery_count
        "Movies / Groups"=$p.movie_count
        "Tags"=(($p.tags | ForEach-Object {$_.name}) -join ", ")
        "URL"=$p.url; "Twitter"=$p.twitter; "Instagram"=$p.instagram
        "Stash IDs"=(($p.stash_ids | ForEach-Object {"$($_.stash_id) [$($_.endpoint)]"}) -join "`r`n")
        "Created"=$p.created_at; "Updated"=$p.updated_at
        "Details"=$p.details
    }

  foreach($key in $props.Keys){[void]$v.Details.Rows.Add($key,(Format-Value $props[$key]))}
  foreach($scene in @($script:SceneCache | Where-Object {@($_.performers | Where-Object {[string]$_.id -eq [string]$p.id}).Count -gt 0})){
   $index=$v.Details.Rows.Add('Linked scene',(Get-SceneTitle $scene))
   $cell=New-Object Windows.Forms.DataGridViewLinkCell;$cell.Value=Get-SceneTitle $scene;$cell.Tag=[string]$scene.id;$cell.LinkColor=[Drawing.Color]::FromArgb(99,205,255)
   $v.Details.Rows[$index].Cells['Value']=$cell
  }
 }
 Refresh-ReplacementPerformerSearchPicture
}
function Invoke-ReplacementPerformerSearch([bool]$ShowAll=$false){
 if(-not $script:IsConnected){$status.Text='Press Start & Connect first.';return}
 $v=$script:PerformerSearchView
 if($ShowAll){$v.Query.Clear()}
 $query=$v.Query.Text.Trim()
 $results=@(Get-ReplacementPerformerSearchResults $query ([string]$v.Choice.SelectedItem))
