 foreach($p in $results){[void]$v.Grid.Rows.Add([string]$p.id,[string]$p.name,[string]$p.country,[string]$p.gender,[string]$p.scene_count,(@($p.tags.name) -join ', '))}
 Show-ReplacementPerformerSearchSelection
 $status.Text="$($results.Count) performer(s) shown"
 if($query -and -not $results.Count){[void][ToolkitMessageDialog]::Show("No performers were found matching '$query'.",'No Results Found',[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Information)}
}
