$v.Grid.Add_SelectionChanged({Show-ReplacementPerformerSearchSelection})
$v.Grid.Add_CellDoubleClick({param($sender,$e) if($e.RowIndex -ge 0){Open-StashToolkitLink ((Get-StashUrl)+'/performers/'+$sender.Rows[$e.RowIndex].Cells['PerformerID'].Value)}})

$v.Details.Add_CellContentClick({param($sender,$e) if($e.RowIndex -ge 0 -and $e.ColumnIndex -ge 0){$cell=$sender.Rows[$e.RowIndex].Cells[$e.ColumnIndex];if($cell -is [Windows.Forms.DataGridViewLinkCell] -and $cell.Tag){Open-StashToolkitLink ((Get-StashUrl)+'/scenes/'+$cell.Tag)}}})


# Remove the Scenes File Health page after its Groups counterpart is built.
$sceneTabs.TabPages.Remove($sceneHealthTab)
# Subject pages share the Scenes control templates and stable script-scoped state.
$script:SubjectViews=@{}
# Get-SubjectItems and Get-SubjectScenes are defined further below, where the
# full Scenes/Groups/Performers/Studios switch versions live (an older,
# Performers/Studios-only pair used to be defined here too, but PowerShell
# only keeps the last definition of a function, so they were dead code).
function Get-SubjectMissing($Item,$Field){
 switch($Field){
  'Name' {return [string]::IsNullOrWhiteSpace([string]$Item.name)}
  'Picture' {return [string]::IsNullOrWhiteSpace([string]$Item.image_path)}
  'Birthdate' {return -not $Item.birthdate}
  'Country' {return -not $Item.country}
  'Gender' {return -not $Item.gender}
  'Aliases' {return -not @($Item.alias_list | Where-Object {$_}).Count}
  'URL' {return -not ($Item.url -or @($Item.urls | Where-Object {$_}).Count)}
  'Details' {return -not $Item.details}
  'Tags' {return -not @($Item.tags | Where-Object {$_}).Count}
  'Stash ID' {return -not @($Item.stash_ids | Where-Object {$_}).Count}
  'Parent Studio' {return -not $Item.parent_studio}
 }
 return $false
}
# Refresh-SubjectPictures is defined further below alongside the current
# Get-SubjectItems/Get-SubjectScenes (see note above); this earlier copy was
# dead code.
function Show-SubjectSelection($Key){
 $v=$script:SubjectViews[$Key];$v.Selected=$null
 if($v.Grid.SelectedRows.Count){$id=[string]$v.Grid.SelectedRows[0].Cells['SubjectID'].Value;$v.Selected=Get-SubjectItems $v.Subject | Where-Object {[string]$_.id -eq $id} | Select-Object -First 1}
 if($v.Details){
  $v.Details.Rows.Clear()
  if($v.Selected){
   foreach($property in $v.Selected.PSObject.Properties){
    if($property.Name -in @('id','image_path')){continue}
    $value=$property.Value
    if($property.Name -eq 'tags'){$value=@($value.name) -join ', '}
    elseif($property.Name -eq 'parent_studio'){$value=$value.name}
    elseif($property.Name -eq 'stash_ids'){$value=@($value | ForEach-Object {$_.stash_id+' ('+$_.endpoint+')'}) -join ', '}
    [void]$v.Details.Rows.Add(($property.Name.Replace('_',' ')),(Format-Value $value))
   }
   if($v.Subject -in @('Scenes','Groups')){
    $performers=if($v.Subject -eq 'Scenes'){@($v.Selected.performers)}else{@(Get-ReplacementGroupPerformers $v.Selected)}
    foreach($performer in $performers){$i=$v.Details.Rows.Add('Performer',[string]$performer.name);$v.Details.Rows[$i].Cells['Value'].Tag=[string]$performer.id}
   }
   foreach($scene in @(Get-SubjectScenes $v.Subject ([string]$v.Selected.id))){
    $index=$v.Details.Rows.Add('Linked scene',(Get-SceneTitle $scene))
    $cell=New-Object Windows.Forms.DataGridViewLinkCell;$cell.Value=Get-SceneTitle $scene;$cell.Tag=[string]$scene.id;$cell.LinkColor=[Drawing.Color]::FromArgb(99,205,255)
    $v.Details.Rows[$index].Cells['Value']=$cell
   }
  }
 }
 Refresh-SubjectPictures
}
function Initialize-SubjectSelector($Key){
 $v=$script:SubjectViews[$Key]
 if($v.Operation -notin @('Tag Search','By Studio','By Performer','By Parent Studio')){return}
 $old=[string]$v.Choice.SelectedItem;$v.Choice.Items.Clear()
 $values=switch($v.Operation){
  'Tag Search' {
   if($v.Subject -eq 'Performers'){
    foreach($scene in @($script:SceneCache)){
     if(@($scene.performers).Count){foreach($tag in @($scene.tags)){if($tag.name){[string]$tag.name}}}
    }
   }else{foreach($item in @(Get-SubjectItems $v.Subject)){foreach($tag in @($item.tags)){if($null -ne $tag -and $tag.name){[string]$tag.name}}}}
  }
  'By Studio' {$script:SceneCache.studio.name}
  'By Performer' {$script:SceneCache.performers.name}
  'By Parent Studio' {$script:StudioCache.parent_studio.name}
 }
 foreach($name in @($values | Where-Object {$_} | Sort-Object -Unique)){[void]$v.Choice.Items.Add([string]$name)}
 if($v.Choice.Items.Contains($old)){$v.Choice.SelectedItem=$old}elseif($v.Choice.Items.Count){$v.Choice.SelectedIndex=0}
}
function Invoke-SubjectOperationCore($Key,$Action='Run'){
 $v=$script:SubjectViews[$Key]
 if(-not $script:IsConnected){$status.Text='Press Start & Connect first.';return}
 try{
  if($v.Subject -eq 'Studios' -and -not $script:StudioCacheLoaded){[void](Load-StudioCache)};if($v.Subject -eq 'Groups' -and -not $script:GroupCacheLoaded){[void](Load-GroupCache)}
  if(-not $script:SceneCacheLoaded){[void](Load-SceneCache)}
  if($Action -eq 'Enter'){Initialize-SubjectSelector $Key;if($v.Operation -notlike '* Browser'){return}}
  if($Action -in @('CSV','HTML')){
   $file='stash-'+$v.Subject.ToLower()+'-'+$v.Operation.ToLower().Replace(' ','-')
   if($Action -eq 'CSV'){Export-GridCsv $v.Grid ($file+'.csv')}else{Export-GridHtml $v.Grid ($file+'.html') ('Stash '+$v.Subject+' - '+$v.Operation)}
   return
  }
  if($Action -eq 'ToggleChecks'){$checked=@($v.Checks.Values | Where-Object {$_.Checked}).Count -ne $v.Checks.Count;foreach($box in $v.Checks.Values){$box.Checked=$checked};$v.Toggle.Text=if($checked){'Deselect All'}else{'Select All'};return}
  if($Action -eq 'ShowAll'){$v.Query.Clear()}
  $items=@(Get-SubjectItems $v.Subject | Where-Object {$null -ne $_} | Sort-Object name)
  $extra=@{}
  switch($v.Operation){
   {$_ -in @('Search','Performer Browser','Studio Browser')} {
    $query=$v.Query.Text.Trim();$mode=[string]$v.Choice.SelectedItem
    $likeQuery='*'+(ConvertTo-ToolkitLikePattern $query)+'*'
    if($query){$items=@($items | Where-Object {
     $p=$_;$text=switch($mode){'Name' {$p.name};'Alias' {$p.alias_list -join ' '};'Country' {$p.country};'Gender' {$p.gender};'Tag' {$p.tags.name -join ' '};'Parent Studio' {$p.parent_studio.name};default {$p.name+' '+($p.alias_list -join ' ')+' '+$p.country+' '+$p.gender+' '+($p.tags.name -join ' ')+' '+$p.parent_studio.name+' '+$p.url}}
     [string]$text -like $likeQuery
    })}
   }
   'Recently Added' {
    $field=if($v.Mode.SelectedIndex -eq 0){'created_at'}else{'updated_at'}
    $days=switch([string]$v.Choice.SelectedItem){'Today'{1};'7 days'{7};'30 days'{30};default{0}}
    if($days){$cutoff=if($days -eq 1){(Get-Date).Date}else{(Get-Date).AddDays(-$days)};$items=@($items | Where-Object {$date=[datetime]::MinValue;[datetime]::TryParse([string]$_.$field,[ref]$date) -and $date -ge $cutoff})}
    $items=@($items | Sort-Object $field -Descending)
   }
   'Missing Pictures' {$items=@($items | Where-Object {Get-SubjectMissing $_ 'Picture'})}
   'Missing Information' {
    $items=@($items | Where-Object {$p=$_;$missing=@(foreach($field in $v.Checks.Keys){if($v.Checks[$field].Checked -and (Get-SubjectMissing $p $field)){$field}});$extra[[string]$p.id]=$missing -join ', ';$missing.Count -gt 0})
   }
   'Duplicate Finder' {
    $matches=@(Get-ToolkitDuplicateMatches $items $v.Subject)
    $items=@($matches | ForEach-Object {$_.Item})
    foreach($match in $matches){$extra[[string]$match.Item.id]=$match.Reason}
   }
   'Tag Search' {
    $tag=[string]$v.Choice.SelectedItem
    if($v.Subject -eq 'Performers'){
     $performerIds=New-Object 'System.Collections.Generic.HashSet[string]'
     foreach($scene in @($script:SceneCache)){
      if($tag -and @($scene.tags.name) -contains $tag){foreach($performer in @($scene.performers)){[void]$performerIds.Add([string]$performer.id)}}
     }
     $items=@($items | Where-Object {$performerIds.Contains([string]$_.id)})
    }else{$items=@($items | Where-Object {$tag -and @($_.tags.name) -contains $tag})}
   }
   'By Studio' {$name=[string]$v.Choice.SelectedItem;$ids=@($script:SceneCache | Where-Object {$name -and $_.studio.name -eq $name} | ForEach-Object {$_.performers.id});$items=@($items | Where-Object {$ids -contains $_.id})}
   'By Performer' {$name=[string]$v.Choice.SelectedItem;$ids=@($script:SceneCache | Where-Object {$name -and @($_.performers.name) -contains $name} | ForEach-Object {$_.studio.id});$items=@($items | Where-Object {$ids -contains $_.id})}
   'By Parent Studio' {$name=[string]$v.Choice.SelectedItem;$items=@($items | Where-Object {$name -and $_.parent_studio.name -eq $name})}
  }
  $v.Grid.Rows.Clear()
  foreach($p in $items){
   if($v.Subject -in @('Scenes','Groups')){
    $name=if($v.Subject -eq 'Scenes'){Get-SceneTitle $p}else{[string]$p.name}
    $performers=if($v.Subject -eq 'Scenes'){@($p.performers)}else{@(Get-ReplacementGroupPerformers $p)}
    $values=@([string]$p.id,$name,[string]$p.date,[string]$p.studio.name,(@($performers.name) -join ', '),(@($p.tags.name) -join ', '))
   }else{
    $values=@([string]$p.id,[string]$p.name);if($v.Subject -eq 'Performers'){$values+=@([string]$p.country,[string]$p.gender)}else{$values+=@([string]$p.parent_studio.name,[string]$p.url)};$values+=@([string]$p.scene_count,(@($p.tags.name) -join ', '))
   }
   if($v.Grid.Columns.Contains('Extra')){$values+=[string]$extra[[string]$p.id]};[void]$v.Grid.Rows.Add([object[]]$values)
  }
  $message="$($items.Count) $($v.Subject.ToLower()). Select a row for details; double-click to open in Stash."
  if($v.Hint){$v.Hint.Text=$message};$status.Text=$message
  if($v.Subject -eq 'Performers' -and $v.Operation -eq 'Missing Pictures' -and $items.Count -eq 0){Show-NoMissingPerformerPictures}
  Show-SubjectSelection $Key
 }catch{[void][ToolkitMessageDialog]::Show($_.Exception.Message,($v.Subject+' - '+$v.Operation),[Windows.Forms.MessageBoxButtons]::OK,[Windows.Forms.MessageBoxIcon]::Error)}
}
function Connect-SubjectButton($Button,$Key,$Action){$Button.Name=$Key+'|'+$Action;$Button.Add_Click({param($sender,$e) $parts=$sender.Name.Split('|');Invoke-SubjectOperation ($parts[0]+'|'+$parts[1]) $parts[2]})}
function New-SubjectView($Subject,$Operation,$Tabs){
 $source=$sceneSearchTab;$grid=$sceneSearchGrid;$details=$sceneSearchDetails;$picture=$sceneScreenshot
 switch($Operation){
  'Recently Added' {$source=$sceneRecentTab;$grid=$sceneRecentGrid;$details=$recentSceneDetails;$picture=$recentScreenshot}
  'Missing Information' {$source=$sceneMissingTab;$grid=$sceneMissingGrid;$details=$missingSceneDetails;$picture=$missingScreenshot}
  'Missing Pictures' {$source=$sceneMissingTab;$grid=$sceneMissingGrid;$details=$missingSceneDetails;$picture=$missingScreenshot}
  'Tag Search' {$source=$tagSceneTab;$grid=$tagSceneRelationGrid;$details=$tagSceneDetails;$picture=$tagScenePicture}
  'By Studio' {$source=$byStudio.Tab;$grid=$byStudio.Grid;$details=$byStudioDetails;$picture=$byStudioPicture}
  'By Performer' {$source=$byPerformerTab;$grid=$byPerformerGrid;$details=$byPerformerDetails;$picture=$byPerformerPicture}
  'By Parent Studio' {$source=$byStudio.Tab;$grid=$byStudio.Grid;$details=$byStudioDetails;$picture=$byStudioPicture}
 }
 $map=@{};$page=Copy-GroupsSceneControl $source $map;$page.Text=$Operation;$key=$Subject+'|'+$Operation;$page.Name=$key;[void]$Tabs.TabPages.Add($page)
 foreach($sourceControl in $map.Keys){if($sourceControl -is [Windows.Forms.Label] -or $sourceControl -is [Windows.Forms.Button]){$map[$sourceControl].Text=$map[$sourceControl].Text.Replace('groups',$Subject.ToLower()).Replace('Groups',$Subject);if($sourceControl.Text -like '*Right-click the screenshot*'){$map[$sourceControl].Text='Click the picture to enlarge; double-click a result to open in Stash'}}}
 $v=@{Subject=$Subject;Operation=$Operation;Page=$page;Grid=$map[$grid];Details=$map[$details];Picture=$map[$picture];Selected=$null;Checks=@{};Hint=$null;Query=$null;Choice=$null;Mode=$null}
 $script:SubjectViews[$key]=$v
 $v.Grid.Columns.Clear();$columns=@(@('SubjectID','ID',1),@('Name',$(if($Subject -eq 'Performers'){'Performer'}else{'Studio'}),30))
 if($Subject -eq 'Performers'){$columns+=@(@('Country','Country',15),@('Gender','Gender',12))}else{$columns+=@(@('Parent','Parent Studio',20),@('URL','URL',20))}
 $columns+=@(@('Count','Scenes',10),@('Tags','Tags',25));if($Operation -in @('Missing Information','Duplicate Finder')){$columns+=,@('Extra',$(if($Operation -eq 'Duplicate Finder'){'Possible match / reason'}else{'Missing'}),35)}
 Add-GridColumns $v.Grid $columns;$v.Grid.Columns['SubjectID'].Visible=$false;$v.Grid.Name=$key;$v.Grid.Tag='SceneContextEnabled';$v.Details.Tag='SceneContextEnabled'
 $v.Grid.Add_SelectionChanged({param($sender,$e) Show-SubjectSelection $sender.Name})
 $v.Grid.Add_CellDoubleClick({param($sender,$e) if($e.RowIndex -ge 0){$v=$script:SubjectViews[$sender.Name];Open-StashToolkitLink ((Get-StashUrl)+'/'+$v.Subject.ToLower()+'/'+$sender.Rows[$e.RowIndex].Cells['SubjectID'].Value)}})
 $menu=New-Object Windows.Forms.ContextMenuStrip;$open=New-Object Windows.Forms.ToolStripMenuItem;$open.Text='View in Stash';$open.Name=$key
 $open.Add_Click({param($sender,$e) $v=$script:SubjectViews[$sender.Name];if($v.Selected){Open-StashToolkitLink ((Get-StashUrl)+'/'+$v.Subject.ToLower()+'/'+$v.Selected.id)}})
 [void]$menu.Items.Add($open);$v.Grid.ContextMenuStrip=$menu;$v.Picture.ContextMenuStrip=$menu
 $v.Grid.Add_CellMouseDown({param($sender,$e) if($e.Button -eq [Windows.Forms.MouseButtons]::Right -and $e.RowIndex -ge 0){$sender.ClearSelection();$sender.Rows[$e.RowIndex].Selected=$true}})
 $v.Details.Add_CellContentClick({param($sender,$e) if($e.RowIndex -ge 0 -and $e.ColumnIndex -ge 0){$cell=$sender.Rows[$e.RowIndex].Cells[$e.ColumnIndex];if($cell -is [Windows.Forms.DataGridViewLinkCell] -and $cell.Tag){Open-StashToolkitLink ((Get-StashUrl)+'/scenes/'+$cell.Tag)}}})
 $v.Picture.Cursor=[Windows.Forms.Cursors]::Hand;Register-ToolkitImage $v.Picture;
 $toolbar=$null;$hasExports=$false
 switch($Operation){
  {$_ -in @('Search','Performer Browser','Studio Browser','Duplicate Finder')} {
   $v.Query=$map[$sceneSearchBox];$v.Choice=$map[$sceneFilter];$v.Hint=$map[$sceneSearchHint];$toolbar=$v.Query.Parent
   $v.Choice.Items.Clear();$choices=if($Subject -eq 'Performers'){@('Everything','Name','Alias','Country','Gender','Tag')}else{@('Everything','Name','Parent Studio','Tag')};[void]$v.Choice.Items.AddRange($choices);$v.Choice.SelectedIndex=0
   Connect-SubjectButton $map[$sceneSearchButton] $key 'Run';Connect-SubjectButton $map[$sceneRefreshButton] $key 'ShowAll'
   if($Operation -eq 'Duplicate Finder'){$v.Query.Visible=$false;$v.Choice.Visible=$false;$map[$sceneSearchLabel].Visible=$false;$map[$sceneRefreshButton].Visible=$false;$map[$sceneSearchButton].Text='Find Possible Duplicates';$map[$sceneSearchButton].Width=270}
   $v.Query.Name=$key;$v.Query.Add_KeyDown({param($sender,$e) if($e.KeyCode -eq 'Enter'){$e.SuppressKeyPress=$true;Invoke-SubjectOperation $sender.Name}})
   Connect-SubjectButton $map[$sceneSearchExportCsv] $key 'CSV';Connect-SubjectButton $map[$sceneSearchExportHtml] $key 'HTML';$hasExports=$true
   $v.Hint.Text=if($Operation -eq 'Duplicate Finder'){'Click Find Possible Duplicates to compare names and aliases.'}else{'Enter a search and click Search, or press Enter, to show '+$Subject.ToLower()+'.'}
  }
  'Recently Added' {$v.Mode=$map[$recentMode];$v.Choice=$map[$recentDays];$toolbar=$v.Mode.Parent;Connect-SubjectButton $map[$recentBtn] $key 'Run'}
  {$_ -in @('Missing Information','Missing Pictures')} {
   $toolbar=$map[$missingBtn].Parent
   foreach($entry in $sceneMissingOptions.GetEnumerator()){$toolbar.Controls.Remove($map[$entry.Value])}
   $fields=if($Operation -eq 'Missing Pictures'){@('Picture')}elseif($Subject -eq 'Performers'){@('Name','Picture','Birthdate','Country','Gender','Aliases','URL','Details','Tags','Stash ID')}else{@('Name','Picture','URL','Parent Studio','Tags','Stash ID')}
   foreach($field in $fields){$box=New-Object Windows.Forms.CheckBox;$box.Text=$field;$box.Checked=$true;$box.AutoSize=$true;$box.ForeColor=$sceneSearchLabel.ForeColor;[void]$toolbar.Controls.Add($box);$toolbar.Controls.SetChildIndex($box,0);$v.Checks[$field]=$box}
   $v.Toggle=$map[$missingSelectAll];Connect-SubjectButton $v.Toggle $key 'ToggleChecks';Connect-SubjectButton $map[$missingBtn] $key 'Run'
  }
  'Tag Search' {$v.Choice=$map[$tagSceneCombo];$toolbar=$v.Choice.Parent;$v.Choice.Items.Clear();$v.Hint=$map[$tagSceneResultNote];$v.Hint.Text='Select a tag and click Show '+$Subject+'.';$map[$tagSceneButton].Text='Show '+$Subject;Connect-SubjectButton $map[$tagSceneButton] $key 'Run';Connect-SubjectButton $map[$tagSceneExportCsv] $key 'CSV';Connect-SubjectButton $map[$tagSceneExportHtml] $key 'HTML';$hasExports=$true}
  'By Performer' {$v.Choice=$map[$byPerformerCombo];$toolbar=$v.Choice.Parent;$v.Choice.Items.Clear();$map[$byPerformerButton].Text='Show '+$Subject;Connect-SubjectButton $map[$byPerformerButton] $key 'Run';Connect-SubjectButton $map[$byPerformerExportCsv] $key 'CSV';Connect-SubjectButton $map[$byPerformerExportHtml] $key 'HTML';$hasExports=$true}
  default {$v.Choice=$map[$byStudio.Combo];$toolbar=$v.Choice.Parent;$v.Choice.Items.Clear();$map[$byStudio.Button].Text='Show '+$Subject;Connect-SubjectButton $map[$byStudio.Button] $key 'Run'}
 }
 if(-not $hasExports){foreach($action in @('CSV','HTML')){$sourceButton=if($action -eq 'CSV'){$sceneSearchExportCsv}else{$sceneSearchExportHtml};$button=Copy-GroupsSceneControl $sourceButton @{};Connect-SubjectButton $button $key $action;[void]$toolbar.Controls.Add($button)}}
 if($Operation -in @('By Performer','By Studio','By Parent Studio')){$page.Add_Resize({param($sender,$e) $v=$script:SubjectViews[$sender.Name];$v.Grid.Height=[Math]::Max(220,[int](($sender.ClientSize.Height-58)*0.58))})}
 $page.Add_Enter({param($sender,$e) if($script:IsConnected -and (Get-Command Invoke-SubjectOperation -ErrorAction SilentlyContinue)){Invoke-SubjectOperation $sender.Name 'Enter'}})
}
