function Get-ToolkitClickedPerformers($Grid,[int]$RowIndex,[int]$ColumnIndex){
 if($Grid.Name -eq 'Performers|Duplicate Finder'){return}
 if($RowIndex -lt 0 -or $ColumnIndex -lt 0){return}
 $row=$Grid.Rows[$RowIndex];$column=$Grid.Columns[$ColumnIndex];$cell=$row.Cells[$ColumnIndex]
 $id='';$name='';$references=@()
 if($Grid.Columns.Contains('Field') -and $column.Name -eq 'Value'){
  $field=[string]$row.Cells['Field'].Value
  if($field -eq 'Performer'){
   $name=[string]$cell.Value
   if($cell.Tag -is [string]){$id=$cell.Tag}elseif($cell.Tag.Kind -eq 'Performer'){$id=[string]$cell.Tag.Id}
  }elseif($field -eq 'Name'){
   if([object]::ReferenceEquals($Grid,$script:PerformerSearchView.Details)){$id=[string]$script:PerformerSearchView.Selected.id}
   foreach($view in $script:SubjectViews.Values){if($view.Subject -eq 'Performers' -and [object]::ReferenceEquals($Grid,$view.Details)){$id=[string]$view.Selected.id;break}}
  }
 }elseif($column.Name -in @('Name','Name1','Name2','Performer')){
  if($Grid.Columns.Contains('PerformerID')){$id=[string]$row.Cells['PerformerID'].Value}
  elseif($Grid.Columns.Contains('SubjectID') -and $script:SubjectViews[$Grid.Name].Subject -eq 'Performers'){$id=[string]$row.Cells['SubjectID'].Value}
  elseif($column.Name -eq 'Name1' -and $Grid.Columns.Contains('ID1')){$id=[string]$row.Cells['ID1'].Value}
  elseif($column.Name -eq 'Name2' -and $Grid.Columns.Contains('ID2')){$id=[string]$row.Cells['ID2'].Value}
  elseif($Grid -in @($searchGrid,$mpGrid,$miGrid,$recentGrid,$tagGrid) -and $Grid.Columns.Contains('ID')){$id=[string]$row.Cells['ID'].Value}
  elseif($Grid -eq $scenePerformerLinks -and $Grid.Columns.Contains('PerformerID')){$id=[string]$row.Cells['PerformerID'].Value}
 }elseif($column.Name -eq 'Performers'){
  if($Grid.Columns.Contains('SceneID')){$scene=Find-CachedScene ([string]$row.Cells['SceneID'].Value);$references=@($scene.performers)}
  elseif($Grid.Columns.Contains('GroupID')){$group=$script:GroupCache | Where-Object {[string]$_.id -eq [string]$row.Cells['GroupID'].Value} | Select-Object -First 1;if($group){$references=@(Get-ReplacementGroupPerformers $group)}}
  elseif($Grid.Columns.Contains('SubjectID')){
   $view=$script:SubjectViews[$Grid.Name];$record=Get-SubjectItems $view.Subject | Where-Object {[string]$_.id -eq [string]$row.Cells['SubjectID'].Value} | Select-Object -First 1
   if($view.Subject -eq 'Scenes'){$references=@($record.performers)}elseif($view.Subject -eq 'Groups' -and $record){$references=@(Get-ReplacementGroupPerformers $record)}
  }
 }
 if($id -or $name){$references+=,[pscustomobject]@{id=$id;name=$name}}
 $seen=@{}
 foreach($reference in $references){
  $performer=Find-CachedPerformer ([string]$reference.id) ([string]$reference.name)
  if($performer -and -not $seen.ContainsKey([string]$performer.id)){$seen[[string]$performer.id]=$true;$performer}
 }
}
function Invoke-ToolkitPerformerClick($Grid,[int]$RowIndex,[int]$ColumnIndex){
 $performers=@(Get-ToolkitClickedPerformers $Grid $RowIndex $ColumnIndex)
 if($performers.Count -eq 1){Show-ScenePerformerPopup $performers[0];return}
 if($performers.Count -lt 2){return}
 $chooser=New-Object ToolkitDialogWindow;$chooser.Text='Choose a performer';$chooser.Size=New-Object Drawing.Size(430,400);$chooser.StartPosition='CenterParent';$chooser.BackColor=$sceneSearchTab.BackColor;$chooser.ForeColor=$sceneSearchTab.ForeColor
 $list=New-Object Windows.Forms.ListBox;$list.Dock='Fill';$list.DisplayMember='name';$list.Font=$Grid.Font;$list.BackColor=$sceneSearchTab.BackColor;$list.ForeColor=$sceneSearchTab.ForeColor
 foreach($performer in $performers){[void]$list.Items.Add($performer)}
 $list.Add_Click({param($sender,$e) if($sender.SelectedItem){$sender.FindForm().Tag=$sender.SelectedItem;$sender.FindForm().DialogResult=[Windows.Forms.DialogResult]::OK}})
 [void]$chooser.Controls.Add($list)
 try{if($chooser.ShowDialog($form) -eq [Windows.Forms.DialogResult]::OK){Show-ScenePerformerPopup $chooser.Tag}}finally{$chooser.Dispose()}
}
function Connect-ToolkitPerformerClicks($Parent){
 foreach($control in $Parent.Controls){
  if($control -is [Windows.Forms.DataGridView] -and -not $script:PerformerClickGrids.ContainsKey($control)){
   # Existing link handlers continue to handle scene/group performer link cells.
   # Other cells and previously unwired detail panels use this shared route.
   $script:PerformerClickGrids[$control]=$true
   $control.Add_CellClick({param($sender,$e)
    if($e.RowIndex -lt 0 -or $e.ColumnIndex -lt 0){return}
    $cell=$sender.Rows[$e.RowIndex].Cells[$e.ColumnIndex]
    if($cell -is [Windows.Forms.DataGridViewLinkCell]){
     if($sender -in @($sceneSearchDetails,$sceneBrowserDetails,$tagSceneDetails,$scenePerformerLinks)){return}
     foreach($view in $script:ReplacementGroupsViews.Values){if([object]::ReferenceEquals($sender,$view.Details)){return}}
    }
    Invoke-ToolkitPerformerClick $sender $e.RowIndex $e.ColumnIndex
   })
   $control.Add_CellMouseEnter({param($sender,$e) if($e.RowIndex -lt 0 -or $e.ColumnIndex -lt 0){return};$targets=@(Get-ToolkitClickedPerformers $sender $e.RowIndex $e.ColumnIndex);if($targets.Count){$sender.Cursor=[Windows.Forms.Cursors]::Hand;$sender.Rows[$e.RowIndex].Cells[$e.ColumnIndex].ToolTipText='Click for performer information'}else{$sender.Cursor=[Windows.Forms.Cursors]::Default}})
  }
  if($control.HasChildren){Connect-ToolkitPerformerClicks $control}
 }
}
