# Remove screenshot instructions and collapse their dedicated label rows.
function Remove-ScreenshotInstructionLabels($Parent){
 foreach($control in @($Parent.Controls)){
  if($control -is [Windows.Forms.Label] -and $control.Text -match '^(Right-click the screenshot|Click a cover to enlarge; right-click|Click the picture to enlarge; double-click)'){
   if($Parent -is [Windows.Forms.TableLayoutPanel]){
    $position=$Parent.GetPositionFromControl($control)
    $others=@($Parent.Controls | Where-Object {$_ -ne $control -and $Parent.GetPositionFromControl($_).Row -eq $position.Row})
    if(-not $others.Count -and $position.Row -ge 0 -and $position.Row -lt $Parent.RowStyles.Count){$Parent.RowStyles[$position.Row].SizeType=[Windows.Forms.SizeType]::Absolute;$Parent.RowStyles[$position.Row].Height=0}
   }
   $control.Text='';$control.Visible=$false;$control.Height=0
  }
  if($control.HasChildren){Remove-ScreenshotInstructionLabels $control}
 }
}
Remove-ScreenshotInstructionLabels $form
