function Get-ToolkitDuplicateMatches($Items,$Subject){
 $seen=@{};$matches=@{}
 foreach($item in @($Items | Sort-Object id)){
  $entries=@()
  if($Subject -eq 'Scenes'){
   if(([string]$item.title).Trim()){$entries+=,[pscustomobject]@{Key=('name|'+$item.title.Trim().ToLowerInvariant());Reason='same title'}}
   foreach($file in @($item.files)){if($file.path){$filename=[IO.Path]::GetFileName([string]$file.path).Trim().ToLowerInvariant();if($filename){$entries+=,[pscustomobject]@{Key=('file|'+$filename);Reason='same filename'}}}}
  }else{
   foreach($name in @($item.name)+@($item.alias_list)+@($item.aliases)){$normalized=([string]$name).Trim().ToLowerInvariant();if($normalized){$entries+=,[pscustomobject]@{Key=('name|'+$normalized);Reason='same name or alias'}}}
  }
  foreach($entry in $entries){
   if($seen.ContainsKey($entry.Key) -and [string]$seen[$entry.Key].id -ne [string]$item.id){
    if(-not $matches.ContainsKey([string]$item.id)){
     $other=$seen[$entry.Key];$label=if($Subject -eq 'Scenes'){Get-SceneTitle $other}else{[string]$other.name}
     $matches[[string]$item.id]=[pscustomobject]@{Item=$item;Other=$other;Reason=($label+' — '+$entry.Reason)}
    }
   }else{$seen[$entry.Key]=$item}
  }
 }
 return @($matches.Values | Sort-Object -Property {$_.Item.name},{$_.Item.title},{$_.Item.id})
}
function Get-SubjectItems($Subject){switch($Subject){'Performers'{return @($script:AllPerformers)};'Scenes'{return @($script:SceneCache)};'Groups'{return @($script:GroupCache)};default{return @($script:StudioCache)}}}
function Get-SubjectScenes($Subject,$Id){
 switch($Subject){
  'Performers'{return @($script:SceneCache | Where-Object {@($_.performers | Where-Object {[string]$_.id -eq $Id}).Count})}
  'Groups'{return @(Get-ReplacementGroupScenes $Id)}
  'Scenes'{return @()}
  default{return @($script:SceneCache | Where-Object {[string]$_.studio.id -eq $Id})}
 }
}
