  Set-CelebrityImage $image $v.Picture
  if($v.BackPicture){$back=$null;if($v.Selected){$back=[pscustomobject]@{id=('group-back-'+$v.Selected.id);paths=[pscustomobject]@{image=[string]$v.Selected.back_image_path;thumbnail=''}}};Set-CelebrityImage $back $v.BackPicture}
 }
