function Open-EmbeddedStashHome {
 if(-not $script:IsConnected){$script:StashBrowserStatus.Text='Press Start & Connect first.';return}
 $address=Get-StashUrl;$uri=$null
 if(-not [uri]::TryCreate($address,[UriKind]::Absolute,[ref]$uri) -or $uri.Scheme -notin @('http','https')){$script:StashBrowserStatus.Text='Enter a valid Stash URL above.';return}
 if($script:StashBrowserReady){$script:StashBrowser.CoreWebView2.Navigate($uri.AbsoluteUri)}else{Initialize-EmbeddedStashBrowser}
}
function Initialize-EmbeddedStashBrowser {
 if($script:StashBrowserReady -or $script:StashBrowserStarting){return}
 if(-not $script:IsConnected){$script:StashBrowserStatus.Text='Press Start & Connect first.';return}
 $script:StashBrowserStarting=$true;$script:StashBrowserStatus.Text='Opening Stash inside the toolkit. Please wait...'
 try{
  $dataRoot=Join-Path $env:LOCALAPPDATA 'StashToolkit'
  $sdkRoot=Join-Path $dataRoot ('WebView2\1.0.4258.31\'+$env:PROCESSOR_ARCHITECTURE+'-'+[IntPtr]::Size)
  [void][IO.Directory]::CreateDirectory($sdkRoot)
  $architecture=if($env:PROCESSOR_ARCHITECTURE -eq 'ARM64'){'arm64'}elseif([IntPtr]::Size -eq 8){'x64'}else{'x86'}
  foreach($asset in @('Microsoft.Web.WebView2.Core.dll','Microsoft.Web.WebView2.WinForms.dll','WebView2Loader.dll')){
   $key=if($asset -eq 'WebView2Loader.dll'){$architecture+'-WebView2Loader.dll'}else{$asset}
   $target=Join-Path $sdkRoot $asset
   if(-not [IO.File]::Exists($target)){[IO.File]::WriteAllBytes($target,[Convert]::FromBase64String($script:StashBrowserAssets[$key]))}
  }
  if(-not ('StashToolkit.NativeBrowserLoader' -as [type])){
   Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;namespace StashToolkit { public static class NativeBrowserLoader { [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)] public static extern IntPtr LoadLibrary(string path); } }'
  }
  $loader=[StashToolkit.NativeBrowserLoader]::LoadLibrary((Join-Path $sdkRoot 'WebView2Loader.dll'))
  if($loader -eq [IntPtr]::Zero){throw 'The embedded browser component could not be loaded.'}
  Add-Type -Path (Join-Path $sdkRoot 'Microsoft.Web.WebView2.Core.dll')
  Add-Type -Path (Join-Path $sdkRoot 'Microsoft.Web.WebView2.WinForms.dll')
  $browser=New-Object Microsoft.Web.WebView2.WinForms.WebView2;$browser.Dock='Fill'
  $properties=New-Object Microsoft.Web.WebView2.WinForms.CoreWebView2CreationProperties;$properties.UserDataFolder=Join-Path $dataRoot 'BrowserProfile';$browser.CreationProperties=$properties
  $script:StashBrowser=$browser
  $browser.Add_CoreWebView2InitializationCompleted({param($sender,$e)
   $script:StashBrowserStarting=$false
   if(-not $e.IsSuccess){$script:StashBrowserReady=$false;$script:StashBrowserStatus.Text='Could not open the embedded browser. '+$e.InitializationException.Message;return}
   $script:StashBrowserReady=$true
   $sender.CoreWebView2.Add_HistoryChanged({param($sender,$e) $script:StashBrowserBack.Enabled=$sender.CanGoBack;$script:StashBrowserForward.Enabled=$sender.CanGoForward})
   $sender.CoreWebView2.Add_NewWindowRequested({param($sender,$e) $e.Handled=$true;$sender.Navigate($e.Uri)})
   if($script:PendingStashLink){$target=$script:PendingStashLink;$script:PendingStashLink=$null;$sender.CoreWebView2.Navigate($target)}else{Open-EmbeddedStashHome}
  })
  $browser.Add_NavigationStarting({param($sender,$e) $script:StashBrowserStatus.Text='Loading Stash...'})
  $browser.Add_NavigationCompleted({param($sender,$e) if($e.IsSuccess){$script:StashBrowserStatus.Text=[string]$sender.Source}else{$script:StashBrowserStatus.Text='Could not load Stash. Check the connection and press Reload. ('+$e.WebErrorStatus+')'}})
  $script:StashBrowserHost.Controls.Clear();[void]$script:StashBrowserHost.Controls.Add($browser)
  [void]$browser.EnsureCoreWebView2Async($null)
 }catch{
  $script:StashBrowserStarting=$false;$script:StashBrowserReady=$false
  $script:StashBrowserStatus.Text='Could not open Stash inside the toolkit. '+$_.Exception.Message+' Install the Microsoft Edge WebView2 Runtime if it is missing.'
 }
}
$tabStash.Add_Enter({if(-not $script:StashBrowserReady){Initialize-EmbeddedStashBrowser}})
$script:StashBrowserBack.Add_Click({if($script:StashBrowserReady -and $script:StashBrowser.CoreWebView2.CanGoBack){$script:StashBrowser.CoreWebView2.GoBack()}})
$script:StashBrowserForward.Add_Click({if($script:StashBrowserReady -and $script:StashBrowser.CoreWebView2.CanGoForward){$script:StashBrowser.CoreWebView2.GoForward()}})
$stashBrowserReload.Add_Click({if($script:StashBrowserReady){$script:StashBrowser.Reload()}else{Initialize-EmbeddedStashBrowser}})
