# Narrow gaps are painted between the rounded headers rather than blank tabs.
foreach($gap in @($tabs.TabPages | Where-Object {$_.Name -like 'ToolkitTabGap*'})){$tabs.TabPages.Remove($gap)}
function Draw-RoundedToolkitTab($Control,$Event){
 $page=$Control.TabPages[$Event.Index];$rect=$Control.GetTabRect($Event.Index)
 $background=New-Object Drawing.SolidBrush($Control.BackColor)
 $clear=$rect;$clear.Inflate(1,1);$Event.Graphics.FillRectangle($background,$clear);$background.Dispose()
 if($page.Name -eq 'StashTabSpacer' -or $page.Name -eq 'ToolkitTabGapAbout'){return}
 $rect.Inflate(-2,-1)
 if($rect.Width -le 0 -or $rect.Height -le 0){return}
 $path=New-Object Drawing.Drawing2D.GraphicsPath
 $radius=[Math]::Min(7,[Math]::Min($rect.Width/2,$rect.Height/2));$diameter=[single]($radius*2)
 $path.AddArc([single]$rect.Left,[single]$rect.Top,$diameter,$diameter,180,90)
 $path.AddLine([single]($rect.Left+$radius),[single]$rect.Top,[single]($rect.Right-$radius),[single]$rect.Top)
 $path.AddArc([single]($rect.Right-$diameter),[single]$rect.Top,$diameter,$diameter,270,90)
 $path.AddLine([single]$rect.Right,[single]($rect.Top+$radius),[single]$rect.Right,[single]$rect.Bottom)
 $path.AddLine([single]$rect.Right,[single]$rect.Bottom,[single]$rect.Left,[single]$rect.Bottom)
 $path.AddLine([single]$rect.Left,[single]$rect.Bottom,[single]$rect.Left,[single]($rect.Top+$radius))
 $path.CloseFigure()
 $colour=if($Event.Index -eq $Control.SelectedIndex){[Drawing.Color]::White}else{[Drawing.Color]::FromArgb(233,238,242)}
 $brush=New-Object Drawing.SolidBrush($colour)
 $oldSmoothing=$Event.Graphics.SmoothingMode;$Event.Graphics.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias
 $Event.Graphics.FillPath($brush,$path)
 $pen=New-Object Drawing.Pen([Drawing.Color]::FromArgb(155,174,188))
 $Event.Graphics.DrawPath($pen,$path);$Event.Graphics.SmoothingMode=$oldSmoothing
 $brush.Dispose();$pen.Dispose();$path.Dispose()
 $allowed=($Control -ne $tabs -or $script:TopTabsUnlocked -or $page -eq $tabHome)
 $foreground=if($allowed){[Drawing.Color]::Black}else{[Drawing.Color]::Gray}
 $flags=[Windows.Forms.TextFormatFlags]::HorizontalCenter -bor [Windows.Forms.TextFormatFlags]::VerticalCenter
 [Windows.Forms.TextRenderer]::DrawText($Event.Graphics,$page.Text,$Control.Font,$rect,$foreground,$flags)
}
function Round-ToolkitTabHeaders($Parent){
 foreach($control in $Parent.Controls){
  if($control -is [Windows.Forms.TabControl]){
   $control.DrawMode=[Windows.Forms.TabDrawMode]::OwnerDrawFixed
   if($control -ne $tabs){$control.Add_DrawItem({param($sender,$e) Draw-RoundedToolkitTab $sender $e})}
   $control.Invalidate()
  }
  if($control.HasChildren){Round-ToolkitTabHeaders $control}
 }
}
