$script:BrowserSearchViews=@{}
function Get-ToolkitBrowserResults($Subject){
 $v=$script:BrowserSearchViews[$Subject]
 $items=if($Subject -eq 'Scenes'){@($script:SceneCache)}else{@($script:GroupCache)}
 if(-not $v -or -not $v.Query.Text.Trim()){return $items}
 $query=$v.Query.Text.Trim();$mode=[string]$v.Choice.SelectedItem
 $likeQuery='*'+(ConvertTo-ToolkitLikePattern $query)+'*'
 return @($items | Where-Object {
  $item=$_
  $name=if($Subject -eq 'Scenes'){Get-SceneTitle $item}else{[string]$item.name}
  $performers=if($Subject -eq 'Scenes'){@($item.performers.name) -join ', '}else{@((Get-ReplacementGroupPerformers $item).name) -join ', '}
  $tags=@($item.tags.name) -join ', '
  $groups=if($Subject -eq 'Scenes'){@($item.groups | ForEach-Object {$_.group.name}) -join ', '}else{''}
  $text=switch($mode){
   'Title' {$name};'Name' {$name};'Performer' {$performers};'Studio' {$item.studio.name};'Tag' {$tags};'Group' {$groups};'Director' {$item.director}
   default {"$name $performers $($item.studio.name) $tags $groups $($item.director) $($item.aliases -join ' ')"}
  }
  [string]$text -like $likeQuery
 })
}
function Invoke-ToolkitBrowserAction($Subject,$Action){
 $v=$script:BrowserSearchViews[$Subject]
 if($Action -in @('CSV','HTML')){
  $filename='stash-'+$Subject.ToLower()+'-browser'
  if($Action -eq 'CSV'){Export-GridCsv $v.Grid ($filename+'.csv')}else{Export-GridHtml $v.Grid ($filename+'.html') ('Stash '+$Subject+' - Browser')}
  return
 }
 if(-not $script:IsConnected){$status.Text='Press Start & Connect first.';return}
 if($Action -eq 'ShowAll'){$v.Query.Clear()}
 if($Subject -eq 'Scenes'){Refresh-SceneBrowserList}else{Invoke-ReplacementGroupOperation 'Group Browser'}
}
foreach($subject in @('Scenes','Groups')){
 $page=if($subject -eq 'Scenes'){$sceneBrowserTab}else{$script:ReplacementGroupsViews['Group Browser'].Page}
 $grid=if($subject -eq 'Scenes'){$sceneBrowserGrid}else{$script:ReplacementGroupsViews['Group Browser'].Grid}
