 $v=@{Page=$page;Grid=$grid;Query=$map[$sceneSearchBox];Choice=$map[$sceneFilter]}
 $script:BrowserSearchViews[$subject]=$v
 $v.Choice.Items.Clear()
 $choices=if($subject -eq 'Scenes'){@('Everything','Title','Performer','Studio','Tag','Group')}else{@('Everything','Name','Performer','Studio','Tag','Director')}
 [void]$v.Choice.Items.AddRange($choices);$v.Choice.SelectedIndex=0
 foreach($pair in @(@($sceneSearchButton,'Search'),@($sceneRefreshButton,'ShowAll'),@($sceneSearchExportCsv,'CSV'),@($sceneSearchExportHtml,'HTML'))){
  $button=$map[$pair[0]];$button.Name=$subject+'|'+$pair[1]
  $button.Add_Click({param($sender,$e) $parts=$sender.Name.Split('|');Invoke-ToolkitBrowserAction $parts[0] $parts[1]})
 }
 $v.Query.Name=$subject;$v.Query.Add_KeyDown({param($sender,$e) if($e.KeyCode -eq 'Enter'){$e.SuppressKeyPress=$true;Invoke-ToolkitBrowserAction $sender.Name 'Search'}})
 $oldContent=@($page.Controls)
 $layout=New-Object Windows.Forms.TableLayoutPanel;$layout.Dock='Fill';$layout.ColumnCount=1;$layout.RowCount=2;$layout.Margin=New-Object Windows.Forms.Padding(0)
 [void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',52)));[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Percent',100)))
 $hostPanel=New-Object Windows.Forms.Panel;$hostPanel.Dock='Fill'
 foreach($control in $oldContent){[void]$hostPanel.Controls.Add($control)}
 [void]$layout.Controls.Add($toolbar,0,0);[void]$layout.Controls.Add($hostPanel,0,1);[void]$page.Controls.Add($layout)
}
