function Open-StashToolkitLink([string]$Url){
 if(-not $script:IsConnected){$status.Text='Press Start & Connect first.';return}
 $uri=$null
 if(-not [uri]::TryCreate($Url,[UriKind]::Absolute,[ref]$uri) -or $uri.Scheme -notin @('http','https')){return}
 $script:PendingStashLink=$uri.AbsoluteUri
 $tabs.SelectedTab=$tabStash
 if($script:StashBrowserReady){$script:PendingStashLink=$null;$script:StashBrowser.CoreWebView2.Navigate($uri.AbsoluteUri)}
 elseif(-not $script:StashBrowserStarting){Initialize-EmbeddedStashBrowser}
 $status.Text='Opened Stash in the Stash tab.'
}
function Hide-StashCommandWindow([string]$ExecutablePath){
 try{
  $processes=@(Get-CimInstance Win32_Process -Filter "Name='stash-win.exe'" -ErrorAction Stop | Where-Object {$_.ExecutablePath -eq $ExecutablePath})
  if(-not $processes.Count){return}
  # Attach from a separate hidden helper so the toolkit's own console is untouched.
  $processIds=@($processes | ForEach-Object {[int]$_.ProcessId}) -join ','
  $helper=@'
Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;public static class StashConsoleWindow { [DllImport("kernel32.dll")] public static extern bool FreeConsole(); [DllImport("kernel32.dll")] public static extern bool AttachConsole(uint id); [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow(); [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr handle,int command); }'
foreach($stashId in @(__PROCESS_IDS__)){
 [void][StashConsoleWindow]::FreeConsole()
 if([StashConsoleWindow]::AttachConsole([uint32]$stashId)){
  $window=[StashConsoleWindow]::GetConsoleWindow()
  if($window -ne [IntPtr]::Zero){[void][StashConsoleWindow]::ShowWindow($window,0)}
  [void][StashConsoleWindow]::FreeConsole()
 }
}
'@
  $helper=$helper.Replace('__PROCESS_IDS__',$processIds)
  $encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($helper))
  $powershell=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
  [void](Start-Process -FilePath $powershell -ArgumentList @('-NoProfile','-NonInteractive','-EncodedCommand',$encoded) -WindowStyle Hidden)
 }catch{
  # Window visibility is optional; Stash continues running if a window cannot be hidden.
 }
}

function Stop-ToolkitStash {
 param([switch]$ReportErrors)
 if([string]::IsNullOrWhiteSpace($script:ToolkitStashExecutable)){return}
 try{
  $running=@(Get-Process -Name 'stash-win' -ErrorAction SilentlyContinue | Where-Object {$_.Path -eq $script:ToolkitStashExecutable})
  foreach($process in $running){
   if($process.HasExited){continue}
   $closed=$false
   try{if($process.CloseMainWindow()){$closed=$process.WaitForExit(2000)}}catch{}
   if(-not $closed){
    Stop-Process -Id $process.Id -ErrorAction Stop
    if(-not $process.WaitForExit(3000)){throw 'Stash did not exit.'}
   }
  }
 }catch{if($ReportErrors){throw}}
}
$form.Add_FormClosed({Stop-ToolkitStash})

