$script:SearchResultHints=New-Object System.Collections.ArrayList
function Register-SearchResultHint($Grid,$Hint,[string]$Subject){
 if($null -eq $Grid -or $null -eq $Hint){return}
 foreach($entry in $script:SearchResultHints){if([object]::ReferenceEquals($entry.Grid,$Grid)){return}}
 [void]$script:SearchResultHints.Add([pscustomobject]@{Grid=$Grid;Hint=$Hint;Subject=$Subject.ToLower()})
 $Grid.Add_RowsAdded({param($sender,$eventArgs) Update-SearchResultHint $sender})
 $Grid.Add_RowsRemoved({param($sender,$eventArgs) Update-SearchResultHint $sender})
}
function Update-SearchResultHint($Grid){
 foreach($entry in $script:SearchResultHints){
  if([object]::ReferenceEquals($entry.Grid,$Grid)){
   $count=$Grid.Rows.Count
   if($Grid.AllowUserToAddRows -and $Grid.NewRowIndex -ge 0){$count--}
   $entry.Hint.Text="$count $($entry.Subject). Select a row for details; double-click to open in Stash."
   break
  }
 }
}
