function Resolve-UtilityTags($Tags,$Names){
 $lookup=@{}
 foreach($tag in $Tags){$lookup[([string]$tag.name).Trim()]=[string]$tag.id}
 foreach($tag in $Tags){foreach($alias in @($tag.aliases)){if($alias -and -not $lookup.ContainsKey(([string]$alias).Trim())){$lookup[([string]$alias).Trim()]=[string]$tag.id}}}
 $resolved=@();$missing=@()
 foreach($name in $Names){if($lookup.ContainsKey($name)){$resolved+=,[pscustomobject]@{Name=$name;Id=$lookup[$name]}}else{$missing+=,$name}}
 return @{Resolved=$resolved;Missing=$missing}
}
function Invoke-UtilityTagSearch {
 $v=$script:UtilityTagView
 if(-not $script:IsConnected){$v.Hint.Text='Press Connect first.';return}
 $names=@($v.SelectedTags.Items | ForEach-Object {[string]$_})
 if(-not $names.Count){$v.Hint.Text='Select at least one tag from the available list.';return}
 $utilitySearch.Enabled=$false;$form.Cursor='WaitCursor'
 try{
  $data=Invoke-StashGraphQL 'query { findTags(filter:{per_page:-1}) { tags { id name aliases } } }' @{}
  $resolution=Resolve-UtilityTags @($data.findTags.tags) $names
  $v.Results=@();$v.Names=@();$v.Grid.Rows.Clear()
  if(-not $resolution.Resolved.Count){$v.Hint.Text='No matching tags found: '+($names -join ', ');return}
  $v.MatchAll=$true;$v.Names=@($resolution.Resolved.Name)
  $ids=@($resolution.Resolved.Id | Select-Object -Unique)
  $modifier=if($v.MatchAll){'INCLUDES_ALL'}else{'INCLUDES'}
  $query=@'
query UtilityTagScenes($filter: FindFilterType, $scene_filter: SceneFilterType) {
 findScenes(filter:$filter,scene_filter:$scene_filter) {
  count scenes { id title date details files { path basename } paths { screenshot }
   studio { id name } performers { id name } tags { id name } }
 }
}
'@
  $page=1
  do{
   $data=Invoke-StashGraphQL $query @{filter=@{per_page=100;page=$page;sort='title';direction='ASC'};scene_filter=@{tags=@{value=$ids;modifier=$modifier}}}
   $batch=@($data.findScenes.scenes);$v.Results+=$batch;$page++
  }while($batch.Count -gt 0 -and $v.Results.Count -lt $data.findScenes.count)
  foreach($scene in $v.Results){
   $values=@([string]$scene.id,(Get-SceneTitle $scene),[string]$scene.date,[string]$scene.studio.name,(@($scene.performers.name) -join ', '),(@($scene.tags.name) -join ', '),[string](@($scene.files | Select-Object -First 1).path))
   [void]$v.Grid.Rows.Add([object[]]$values)
   if(-not (Find-CachedScene ([string]$scene.id))){$script:SceneCache+=$scene}
  }
  $v.Hint.Text="$($v.Results.Count) scenes. Double-click a result to open in Stash."
  if($resolution.Missing.Count){$v.Hint.Text+=' Tags not found (ignored): '+($resolution.Missing -join ', ')}
 }catch{$v.Hint.Text='Search failed: '+$_.Exception.Message}
 finally{$utilitySearch.Enabled=$true;$form.Cursor='Default'}
}
function Get-UtilityTagTextReport {
 $v=$script:UtilityTagView;$joiner=if($v.MatchAll){' AND '}else{' OR '}
 $lines=@('Stash Tag Search Results',('Generated:     '+(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')),('Tags searched: '+($v.Names -join $joiner)),('Matches found: '+$v.Results.Count),('='*70))
 foreach($scene in $v.Results){$lines+='';$lines+=[string](@($scene.files | Select-Object -First 1).path)}
 return ($lines -join "`r`n")
}
