function Get-ImageExportFilename([string]$Directory,[string]$Name,[string]$Id){
 $safe=($Name -replace '[<>:"/\\|?*\x00-\x1f]','_').Trim().TrimEnd('.')
 if(-not $safe){$safe='Image_'+$Id}
 if($safe -match '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\.|$)'){$safe='_'+$safe}
 if($safe.Length -gt 120){$safe=$safe.Substring(0,120)}
 $path=Join-Path $Directory ($safe+'.jpg');$number=2
 while(Test-Path -LiteralPath $path){$path=Join-Path $Directory ($safe+'_'+$number+'.jpg');$number++}
 return $path
}
function Save-UtilityExportImage($Item,[string]$Directory){
 if(-not $Item.image_path){return @{Status='No image';File=''}}
 $url=[string]$Item.image_path
 if($url.StartsWith('/')){$url=(Get-StashUrl)+$url}
 $lastError=''
 for($attempt=1;$attempt -le 3;$attempt++){
  $response=$null;$stream=$null;$memory=$null;$image=$null;$bitmap=$null;$graphics=$null;$temp=$null;$converted=$null
  try{
   $request=[Net.HttpWebRequest]::Create($url);$request.Timeout=15000;$request.ReadWriteTimeout=15000
   $key=Get-StashKey;if($key){$request.Headers.Add('ApiKey',$key)}
   $response=$request.GetResponse();$stream=$response.GetResponseStream();$memory=New-Object IO.MemoryStream;$stream.CopyTo($memory)
   $bytes=$memory.ToArray()
   if($bytes.Length -lt 512){return @{Status='Placeholder';File=''}}
   $path=Get-ImageExportFilename $Directory ([string]$Item.name) ([string]$Item.id)
   $memory.Position=0
   try{$image=[Drawing.Image]::FromStream($memory)}catch{
    $ffmpeg=Find-ToolkitFfmpeg
    if(-not $ffmpeg){throw 'Image decoding failed; ffmpeg is needed for this image format.'}
    $temp=Join-Path ([IO.Path]::GetTempPath()) ([guid]::NewGuid().ToString()+'.img');$converted=$temp+'.png'
    [IO.File]::WriteAllBytes($temp,$bytes)
    $process=Convert-ToolkitImageWithFfmpeg $ffmpeg $temp $converted
    if($process.ExitCode -ne 0 -or -not (Test-Path -LiteralPath $converted)){throw 'Image conversion failed'}
    $image=[Drawing.Image]::FromFile($converted)
   }
   $bitmap=New-Object Drawing.Bitmap($image.Width,$image.Height,[Drawing.Imaging.PixelFormat]::Format24bppRgb)
   $graphics=[Drawing.Graphics]::FromImage($bitmap);$graphics.Clear([Drawing.Color]::White);$graphics.DrawImage($image,0,0,$image.Width,$image.Height)
   $bitmap.Save($path,[Drawing.Imaging.ImageFormat]::Jpeg)
   return @{Status='Saved';File=$path}
  }catch{$lastError=$_.Exception.Message}
  finally{
   foreach($resource in @($graphics,$bitmap,$image,$memory,$stream,$response)){if($null -ne $resource){$resource.Dispose()}}
   foreach($file in @($temp,$converted)){if($file -and (Test-Path -LiteralPath $file)){Remove-Item -LiteralPath $file -Force}}
  }
 }
 return @{Status=('Failed: '+$lastError);File=''}
}
function Confirm-UtilityExportFolderClear([string]$Directory,[string]$Subject){
 $answer=[ToolkitMessageDialog]::Show("Clear all existing files and subfolders in the $Subject export folder before starting?`r`n`r`n$Directory",'Clear export folder?', [Windows.Forms.MessageBoxButtons]::YesNoCancel,[Windows.Forms.MessageBoxIcon]::Warning,[Windows.Forms.MessageBoxDefaultButton]::Button2)
 if($answer -eq [Windows.Forms.DialogResult]::Cancel){$script:ImageExportView.Cancel=$true;return $false}
 if($answer -ne [Windows.Forms.DialogResult]::Yes){return $false}
 $confirm=[ToolkitMessageDialog]::Show("Are you sure? This permanently deletes all files and subfolders inside:`r`n`r`n$Directory",'Confirm folder clearing',[Windows.Forms.MessageBoxButtons]::YesNoCancel,[Windows.Forms.MessageBoxIcon]::Warning,[Windows.Forms.MessageBoxDefaultButton]::Button2)
 if($confirm -eq [Windows.Forms.DialogResult]::Cancel){$script:ImageExportView.Cancel=$true;return $false}
 return ($confirm -eq [Windows.Forms.DialogResult]::Yes)
}
function Clear-UtilityExportFolder([string]$Directory){
 $resolved=(Resolve-Path -LiteralPath $Directory -ErrorAction Stop).ProviderPath
 $absolute=[IO.Path]::GetFullPath($resolved).TrimEnd('\')
 if($absolute -eq [IO.Path]::GetPathRoot($absolute).TrimEnd('\')){throw 'Choose a dedicated export folder, not a drive root.'}
 $folder=Get-Item -LiteralPath $absolute -Force -ErrorAction Stop
 if($folder.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Folder clearing is not supported for a linked folder.'}
 $entries=@(Get-ChildItem -LiteralPath $absolute -Force -ErrorAction Stop)
 foreach($entry in $entries){
  $target=[IO.Path]::GetFullPath($entry.FullName)
  if(-not $target.StartsWith($absolute+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Folder entry falls outside the selected export folder.'}
  if($entry.PSIsContainer -and -not ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)){
   $links=@(Get-ChildItem -LiteralPath $target -Recurse -Force -Attributes ReparsePoint -ErrorAction Stop)
   if($links.Count){throw 'This export folder contains linked subfolders. Keep the files or choose another export folder.'}
  }
 }
 foreach($entry in $entries){
  if($entry.PSIsContainer -and -not ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint)){Remove-Item -LiteralPath $entry.FullName -Recurse -Force -ErrorAction Stop}
  else{Remove-Item -LiteralPath $entry.FullName -Force -ErrorAction Stop}
 }
}
function Invoke-UtilityImageExport {
 $v=$script:ImageExportView
 if($v.Running){return}
 if(-not $v.Performers.Checked -and -not $v.Studios.Checked){$v.Progress.Text='Tick Performers, Studios, or both before exporting.';return}
 if(-not $script:IsConnected){$v.Progress.Text='Press Connect first.';return}
 if(($v.Performers.Checked -and -not $v.PerformerFolder.Text.Trim()) -or ($v.Studios.Checked -and -not $v.StudioFolder.Text.Trim())){$v.Progress.Text='Choose a folder for each selected subject.';return}
 $v.Running=$true;$v.Cancel=$false;$v.Grid.Rows.Clear()
 $exportRun.Enabled=$false;$exportCancel.Enabled=$true;$exportBrowse.Enabled=$false;$exportPerformers.Enabled=$false;$exportStudios.Enabled=$false;$exportFolder.Enabled=$false;$exportStudioFolder.Enabled=$false;$exportStudioBrowse.Enabled=$false
 $saved=0;$skipped=0;$failed=0;$logs=New-Object 'System.Collections.Generic.List[string]'
 try{
  $exportDirectories=@{}
  $kinds=@(if($v.Performers.Checked){'Performers'};if($v.Studios.Checked){'Studios'})
  foreach($kind in $kinds){
   if($v.Cancel){break}
   $folder=if($kind -eq 'Performers'){$v.PerformerFolder}else{$v.StudioFolder}
   $directory=[IO.Path]::GetFullPath($folder.Text.Trim());[void][IO.Directory]::CreateDirectory($directory)
   if(Confirm-UtilityExportFolderClear $directory $kind){Clear-UtilityExportFolder $directory}
   if($v.Cancel){break}
   $exportDirectories[$kind]=$directory
   $page=1; $completed=0
   do{
    $v.Progress.Text='Fetching '+$kind+'...';[Windows.Forms.Application]::DoEvents()
    if($v.Cancel){break}
    $query='query ExportImages($page:Int!){find'+$kind+'(filter:{per_page:100,page:$page}){count '+$kind.ToLower()+'{id name image_path}}}'
    $data=Invoke-StashGraphQL $query @{page=$page};$result=$data.('find'+$kind);$items=@($result.($kind.ToLower()))
    foreach($item in $items){
     [Windows.Forms.Application]::DoEvents();if($v.Cancel){break}
     $outcome=Save-UtilityExportImage $item $directory;$completed++
     if($outcome.Status -eq 'Saved'){$saved++}elseif($outcome.Status -in @('No image','Placeholder')){$skipped++}else{$failed++}
     [void]$v.Grid.Rows.Add([object[]]@([string]$kind,[string]$item.name,[string]$outcome.Status,[string]$outcome.File))
     $logs.Add("[$($outcome.Status)] $kind - $($item.name) -> $($outcome.File)")
     $v.Progress.Text="$kind $completed/$($result.count) | Saved: $saved | Skipped: $skipped | Failed: $failed"
    }
    $page++
   }while(-not $v.Cancel -and $items.Count -gt 0 -and $completed -lt $result.count)
  }
  $summary="Saved: $saved | Skipped: $skipped | Failed: $failed"
  $state=if($v.Cancel){'Cancelled'}else{'Complete'}
  foreach($kind in $exportDirectories.Keys){
  $logPath=Join-Path $exportDirectories[$kind] ($kind.ToLower()+'_export.txt')
  [IO.File]::AppendAllText($logPath,("`r`nStash Image Export | "+(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')+" | $state`r`n$summary`r`n"+(@($logs | Where-Object {$_ -like ('*] '+$kind+' - *')}) -join "`r`n")+"`r`n"),(New-Object Text.UTF8Encoding($true)))
  }
  $v.Progress.Text="$state. $summary. Logs saved in the selected folders."
  if(-not $v.Cancel){
   Show-ExportSuccess 'Images' "Saved: $saved`r`nSkipped: $skipped`r`nFailed: $failed`r`n`r`nExport logs are saved in the selected folders."
  }
 }catch{$v.Progress.Text='Export failed: '+$_.Exception.Message}
 finally{$v.Running=$false;$exportRun.Enabled=$true;$exportCancel.Enabled=$false;$exportBrowse.Enabled=$true;$exportPerformers.Enabled=$true;$exportStudios.Enabled=$true;$exportFolder.Enabled=$true;$exportStudioFolder.Enabled=$true;$exportStudioBrowse.Enabled=$true}
}
