function Filter-UtilityAvailableTags {
 $v=$script:UtilityTagView;$filter=$v.Input.Text.Trim()
 $v.Available.BeginUpdate()
 try{
  $v.Available.Items.Clear()
  foreach($tag in $v.AllTags){
   if($v.SelectedTags.Items.Contains([string]$tag.name)){continue}
   if(-not $filter -or ([string]$tag.name).IndexOf($filter,[StringComparison]::OrdinalIgnoreCase) -ge 0 -or (@($tag.aliases) -join ' ').IndexOf($filter,[StringComparison]::OrdinalIgnoreCase) -ge 0){[void]$v.Available.Items.Add([string]$tag.name)}
  }
 }finally{$v.Available.EndUpdate()}
}
function Load-UtilityAvailableTags {
 if(-not $script:IsConnected){$script:UtilityTagView.Hint.Text='Press Connect first.';return}
 $v=$script:UtilityTagView
 if($v.Loading){return}
 $v.Loading=$true
 $v.Hint.Text='Please wait — loading tags...'
 $v.Hint.Refresh()
 $v.Available.Enabled=$false;$v.SelectedTags.Enabled=$false
 $utilitySearch.Enabled=$false;$form.UseWaitCursor=$true
 [Windows.Forms.Application]::DoEvents()
 try{
  $data=Invoke-StashGraphQL 'query { findTags(filter:{per_page:-1}) { tags { id name aliases } } }' @{}
  $v=$script:UtilityTagView;$v.AllTags=@($data.findTags.tags | Sort-Object name)
  # Refresh selected objects and drop tags removed from Stash.
  $selectedNames=@($v.SelectedTags.Items | ForEach-Object {[string]$_})
  $v.SelectedTags.Items.Clear()
  foreach($tag in $v.AllTags){if([string]$tag.name -in $selectedNames){[void]$v.SelectedTags.Items.Add([string]$tag.name)}}
  Filter-UtilityAvailableTags
  $v.Hint.Text="$($v.AllTags.Count) available tags."
 }catch{$script:UtilityTagView.Hint.Text='Could not load tags: '+$_.Exception.Message}
 finally{
  $v.Loading=$false;$v.Available.Enabled=$true;$v.SelectedTags.Enabled=$true
  $utilitySearch.Enabled=$true;$form.UseWaitCursor=$false
 }
}
function Add-UtilitySelectedTag($Tag){
 if($null -eq $Tag){return}
 $v=$script:UtilityTagView
  $name=if($Tag -is [string]){$Tag}else{[string]$Tag.name}
 if(-not $name -or $name -notin @($v.AllTags | ForEach-Object {[string]$_.name})){return}
 if(-not $v.SelectedTags.Items.Contains($name)){[void]$v.SelectedTags.Items.Add($name);Filter-UtilityAvailableTags}
 $v.Hint.Text="$($v.SelectedTags.Items.Count) tags selected."
}
$availableTags.Add_MouseClick({param($sender,$e) $index=$sender.IndexFromPoint($e.Location);if($index -ge 0){Add-UtilitySelectedTag $sender.Items[$index]}})
