function Select-ImageExportFolder($Field){
 $dialog=New-Object Windows.Forms.FolderBrowserDialog
 try{
  $location=$Field.Text.Trim()
  if($location){
   $location=[IO.Path]::GetFullPath($location)
   $dialog.SelectedPath=$location
   if($dialog.PSObject.Properties['InitialDirectory']){
    $dialog.InitialDirectory=$location
    $dialog.AutoUpgradeEnabled=$true
   }else{
    # Classic tree picker honours SelectedPath directly rather than its parent.
    if($dialog.PSObject.Properties['AutoUpgradeEnabled']){$dialog.AutoUpgradeEnabled=$false}
   }
  }
  if($dialog.ShowDialog($form) -eq 'OK'){$Field.Text=$dialog.SelectedPath}
 }catch{[void][ToolkitMessageDialog]::Show($_.Exception.Message,'Choose Folder','OK','Error')}
 finally{$dialog.Dispose()}
}
# Single-file tools adapted from stash_toolkit_gui.py.
function Test-UtilitySingleFile([string]$Path){
 try{
  $normalized=$Path.Replace('/','\')
  if(-not (Test-Path -LiteralPath $normalized -PathType Leaf)){throw 'File not accessible on this computer'}
  $directory=[IO.Path]::GetDirectoryName($normalized)
  $files=@(Get-ChildItem -LiteralPath $directory -File -Force -ErrorAction Stop)
  return @{Single=($files.Count -eq 1);Path=$normalized;Error=''}
 }catch{return @{Single=$false;Path=$Path;Error=$_.Exception.Message}}
}
