 $hint=New-Object Windows.Forms.Label;$hint.Dock='Fill';$hint.ForeColor=[Drawing.Color]::White;$hint.Text=$Help;$hint.Padding=New-Object Windows.Forms.Padding(8,4,8,0)
 $grid=New-Object Windows.Forms.DataGridView;$grid.Dock='Fill';$grid.ReadOnly=$true;$grid.AllowUserToAddRows=$false;$grid.AutoSizeColumnsMode='Fill';$grid.BackgroundColor=[Drawing.Color]::FromArgb(8,31,47)
 $grid.DefaultCellStyle.BackColor=[Drawing.Color]::FromArgb(12,37,53);$grid.DefaultCellStyle.ForeColor=[Drawing.Color]::White
 $grid.EnableHeadersVisualStyles=$false;$grid.RowHeadersVisible=$false;$grid.GridColor=[Drawing.Color]::FromArgb(60,90,110)
