$finderRecursive=New-Object Windows.Forms.CheckBox;$finderRecursive.Text='Include nested subfolders';$finderRecursive.Checked=$true;$finderRecursive.AutoSize=$true;$finderRecursive.ForeColor=[Drawing.Color]::White
$finderScan=New-UtilityFileButton 'Scan'
