$script:SingleFileFinder.Roots=$finderRoots;$script:SingleFileFinder.Recursive=$finderRecursive
function Invoke-UtilitySingleFileScan {
 $v=$script:SingleFileFinder;$v.Grid.Rows.Clear();$seen=@{};$errors=0;$finderScan.Enabled=$false
 try{
  foreach($root in @($v.Roots.Lines | ForEach-Object {$_.Trim()} | Where-Object {$_})){
   $v.Hint.Text='Please wait — scanning '+$root;$v.Hint.Refresh();[Windows.Forms.Application]::DoEvents()
   if(-not (Test-Path -LiteralPath $root -PathType Container)){$errors++;[void]$v.Grid.Rows.Add('','',$root,'Folder unavailable');continue}
   $pending=New-Object 'System.Collections.Generic.Queue[string]';$pending.Enqueue($root)
   while($pending.Count){
    $parent=$pending.Dequeue()
    try{$folders=@(Get-ChildItem -LiteralPath $parent -Directory -Force -ErrorAction Stop)}catch{$errors++;continue}
    foreach($folder in $folders){
     if($folder.Attributes -band [IO.FileAttributes]::ReparsePoint){continue}
     if($seen.ContainsKey($folder.FullName)){continue};$seen[$folder.FullName]=$true
     if($v.Recursive.Checked){$pending.Enqueue($folder.FullName)}
     try{$files=@(Get-ChildItem -LiteralPath $folder.FullName -File -Force -ErrorAction Stop)}catch{$errors++;continue}
     if($files.Count -eq 1){[void]$v.Grid.Rows.Add($folder.FullName,$files[0].Name,$files[0].FullName,'Match')}
    }
    [Windows.Forms.Application]::DoEvents()
   }
  }
  $count=@($v.Grid.Rows | Where-Object {$_.Cells['Status'].Value -eq 'Match'}).Count
  $v.Hint.Text="$count single-file folders found. $errors folders unavailable."
 }catch{$v.Hint.Text='Scan failed: '+$_.Exception.Message}finally{$finderScan.Enabled=$true}
}
function Export-UtilitySingleFilePaths($Grid,[string]$Name){
 $paths=@($Grid.Rows | Where-Object {$_.Cells['Status'].Value -eq 'Match'} | ForEach-Object {[string]$_.Cells['FullPath'].Value})
 if(-not $paths.Count){[void][ToolkitMessageDialog]::Show('No matching file paths to export.','Export TXT','OK','Information');return}
 $dialog=New-Object Windows.Forms.SaveFileDialog;$dialog.Filter='Text files (*.txt)|*.txt';$dialog.FileName=$Name
 try{if($dialog.ShowDialog($form) -eq 'OK'){[IO.File]::WriteAllText($dialog.FileName,($paths -join "`r`n`r`n"),(New-Object Text.UTF8Encoding($false)));Show-ExportSuccess 'TXT'}}finally{$dialog.Dispose()}
}
$finderAdd.Add_Click({$dialog=New-Object Windows.Forms.FolderBrowserDialog;try{if($dialog.ShowDialog($form) -eq 'OK'){$finderRoots.AppendText("`r`n"+$dialog.SelectedPath)}}finally{$dialog.Dispose()}})
$finderScan.Add_Click({Invoke-UtilitySingleFileScan})
