# Populate the default Scene Browser when the top-level Scenes tab is selected.
function Populate-SelectedSceneBrowser {
 if(-not $script:IsConnected -or $tabs.SelectedTab -ne $tabScenes -or $sceneTabs.SelectedTab -ne $sceneBrowserTab){return}
 if($script:SceneBrowserPopulating){return}
 # Already filled for this connection: leave the list and the selection alone.
 if($sceneBrowserGrid.Rows.Count -and $script:SceneBrowserLoadedKey -eq $script:ToolkitConnectionId){return}
 $script:SceneBrowserPopulating=$true
 try{
  if(-not $script:SceneCacheLoaded){[void](Load-SceneCache)}
  Refresh-SceneBrowserList
  $sceneBrowserGrid.Refresh()
 }finally{$script:SceneBrowserPopulating=$false}
}
$tabs.Add_SelectedIndexChanged({Populate-SelectedSceneBrowser})
$tabScenes.Add_Enter({Populate-SelectedSceneBrowser})
$btnConnect.Add_Click({Populate-SelectedSceneBrowser})
# Browser lists populate on selection, not only when their child controls gain focus.
function Populate-OtherSelectedBrowser {
 if(-not $script:IsConnected -or $script:OtherBrowserPopulating){return}
 $script:OtherBrowserPopulating=$true
 try{
  if($tabs.SelectedTab -eq $tabGroups -and $script:GroupsTabs.SelectedTab.Text -eq 'Group Browser'){
   Invoke-ReplacementGroupOperation 'Group Browser' 'Enter'
  }elseif($tabs.SelectedTab -eq $tabPerformers -and $performerTabs.SelectedTab.Text -like '*Browser'){
   Invoke-SubjectOperation $performerTabs.SelectedTab.Name 'Enter'
  }elseif($tabs.SelectedTab -eq $tabStudios -and $script:StudioTabs.SelectedTab.Text -like '*Browser'){
   Invoke-SubjectOperation $script:StudioTabs.SelectedTab.Name 'Enter'
  }
 }finally{$script:OtherBrowserPopulating=$false}
}
