$performerTabs.Add_SelectedIndexChanged({Populate-OtherSelectedBrowser})
$script:StudioTabs.Add_SelectedIndexChanged({Populate-OtherSelectedBrowser})
$script:GroupsTabs.Add_SelectedIndexChanged({Populate-OtherSelectedBrowser})
