# Loading feedback for browser lists, including search and Show All.
$script:BrowserLoadingDepth=0
$script:BrowserLoadingActions=@{}
function Begin-BrowserLoading([string]$Subject){
 $script:BrowserLoadingDepth++
 if($script:BrowserLoadingDepth -gt 1){return}
 $script:BrowserLoadingWindow=New-Object ToolkitDialogWindow
 $script:BrowserLoadingWindow.Text='Loading records'
 $script:BrowserLoadingWindow.AutoScaleMode='Dpi'
 $script:BrowserLoadingWindow.ClientSize=New-Object Drawing.Size(560,190)
 $script:BrowserLoadingWindow.StartPosition='CenterScreen'
 $script:BrowserLoadingWindow.FormBorderStyle='None';$script:BrowserLoadingWindow.ControlBox=$false
 $script:BrowserLoadingWindow.BackColor=[Drawing.ColorTranslator]::FromHtml('#102D3E')
 $script:BrowserLoadingWindow.ForeColor=[Drawing.Color]::White
 $layout=New-Object Windows.Forms.TableLayoutPanel
 $layout.Dock='Fill';$layout.Padding=New-Object Windows.Forms.Padding(24,20,24,20);$layout.ColumnCount=1;$layout.RowCount=3
 [void]$layout.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle('Percent',100)))
 [void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Percent',45)))
 [void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Percent',35)))
 [void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Percent',20)))
 $label=New-Object Windows.Forms.Label;$label.Dock='Fill';$label.TextAlign='MiddleLeft';$label.Margin=New-Object Windows.Forms.Padding(0)
 $label.Text="Loading $($Subject.ToLower()) records…"
 $label.Font=New-Object Drawing.Font('Segoe UI',14,[Drawing.FontStyle]::Bold)
 $detail=New-Object Windows.Forms.Label;$detail.Dock='Fill';$detail.TextAlign='MiddleLeft';$detail.Margin=New-Object Windows.Forms.Padding(0)
 $detail.Text='Please wait. Large lists may take a moment to appear.'
 $detail.Font=New-Object Drawing.Font('Segoe UI',10)
 $progress=New-Object Windows.Forms.ProgressBar;$progress.Dock='Fill';$progress.Margin=New-Object Windows.Forms.Padding(0,6,0,0);$progress.Style='Marquee';$progress.MarqueeAnimationSpeed=30
 [void]$layout.Controls.Add($label,0,0)
 [void]$layout.Controls.Add($detail,0,1)
 [void]$layout.Controls.Add($progress,0,2)
 $border=New-Object Windows.Forms.Panel
 $border.Dock='Fill';$border.Padding=New-Object Windows.Forms.Padding(2)
 $border.BackColor=[Drawing.ColorTranslator]::FromHtml('#8ECBE6')
 $layout.BackColor=$script:BrowserLoadingWindow.BackColor
 [void]$border.Controls.Add($layout)
 [void]$script:BrowserLoadingWindow.Controls.Add($border)
 $script:BrowserLoadingWindow.Show($form);$script:BrowserLoadingWindow.Refresh()
 [Windows.Forms.Application]::DoEvents()
}
function End-BrowserLoading {
 $script:BrowserLoadingDepth=[Math]::Max(0,$script:BrowserLoadingDepth-1)
 if($script:BrowserLoadingDepth -eq 0 -and $script:BrowserLoadingWindow){
  $script:BrowserLoadingWindow.Close();$script:BrowserLoadingWindow.Dispose();$script:BrowserLoadingWindow=$null
 }
}
function Refresh-SceneBrowserList {
 if($script:BrowserLoadingActions['Scenes']){return}
 if(-not $script:IsConnected){Refresh-SceneBrowserListCore;return}
 $script:BrowserLoadingActions['Scenes']=$true
 try{Begin-BrowserLoading 'Scenes';Refresh-SceneBrowserListCore}
 finally{End-BrowserLoading;$script:BrowserLoadingActions['Scenes']=$false}
}
function Invoke-ReplacementGroupOperation([string]$Operation,[string]$Action='Run'){
 if($Operation -eq 'Group Browser' -and $Action -eq 'Enter' -and $script:IsConnected){
  $groupBrowserView=$script:ReplacementGroupsViews['Group Browser']
  if($groupBrowserView.Grid.Rows.Count -and $groupBrowserView.LoadedKey -eq $script:ToolkitConnectionId){return}
 }
 if($Operation -ne 'Group Browser' -or $Action -in @('CSV','HTML') -or -not $script:IsConnected){Invoke-ReplacementGroupOperationCore $Operation $Action;return}
 if($script:BrowserLoadingActions['Groups']){return}
 $script:BrowserLoadingActions['Groups']=$true
 try{Begin-BrowserLoading 'Groups';Invoke-ReplacementGroupOperationCore $Operation $Action;$script:ReplacementGroupsViews['Group Browser'].LoadedKey=$script:ToolkitConnectionId}
 finally{End-BrowserLoading;$script:BrowserLoadingActions['Groups']=$false}
}
function Invoke-SubjectOperation($Key,$Action='Run'){
 $view=$script:SubjectViews[$Key]
 if($Action -eq 'Enter' -and $view.Operation -like '*Browser' -and $script:IsConnected -and $view.Grid.Rows.Count -and $view.LoadedKey -eq $script:ToolkitConnectionId){return}
 if($view.Operation -notlike '*Browser' -or $Action -in @('CSV','HTML') -or -not $script:IsConnected){Invoke-SubjectOperationCore $Key $Action;return}
 if($script:BrowserLoadingActions[$Key]){return}
 $script:BrowserLoadingActions[$Key]=$true
 try{Begin-BrowserLoading $view.Subject;Invoke-SubjectOperationCore $Key $Action;$view.LoadedKey=$script:ToolkitConnectionId}
 finally{End-BrowserLoading;$script:BrowserLoadingActions[$Key]=$false}
}
