function Choose-MaintenanceFile($Save,$Filter,$DefaultName=$null){
 if($Save){$d=New-Object Windows.Forms.SaveFileDialog}else{$d=New-Object Windows.Forms.OpenFileDialog}
 $d.Filter=$Filter;if($Save -and $DefaultName){$d.FileName=[string]$DefaultName}
 try{if($d.ShowDialog($form) -eq 'OK'){return $d.FileName}}finally{$d.Dispose()}
