function Invoke-MaintenanceAction($Action){try{& $Action}catch{[void][ToolkitMessageDialog]::Show($_.Exception.Message,'Utilities','OK','Error')}}
$script:BackupUtility=New-MaintenancePage 'Backup Settings' 'Save connection settings and local Stash configuration. Restore while disconnected; restart Stash to apply its configuration.' @('Item','Result')
[void](Add-MaintenanceButton $script:BackupUtility 'Back Up Settings' {
 Invoke-MaintenanceAction {
 $path=Choose-MaintenanceFile $true 'Settings backup (*.json)|*.json';if(-not $path){return}
 $configs=@();foreach($p in @(Get-ToolkitStashConfigPaths)){if(Test-Path -LiteralPath $p){$configs+=@{Path=$p;Content=[IO.File]::ReadAllText($p)}}}
 @{Version=1;Url=(Get-StashUrl);ApiKey=(Get-StashKey);Configs=$configs}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $path -Encoding UTF8
 $script:BackupUtility.Grid.Rows.Clear();[void]$script:BackupUtility.Grid.Rows.Add('Backup saved',$path)
 $script:BackupUtility.Hint.Text='Backup saved. It contains connection credentials; store it privately.'
 }
})
[void](Add-MaintenanceButton $script:BackupUtility 'Restore Settings' {
 Invoke-MaintenanceAction {
 if($script:IsConnected){throw 'Disconnect before restoring settings.'}
 $path=Choose-MaintenanceFile $false 'Settings backup (*.json)|*.json';if(-not $path){return}
 $data=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json
 if($data.Version -ne 1){throw 'Unsupported backup format.'}
 $allowed=@(Get-ToolkitStashConfigPaths)
 foreach($c in $data.Configs){if($c.Path -notin $allowed){throw 'Backup contains an unrecognised configuration location.'}}
 if([ToolkitMessageDialog]::Show('Restore these settings and replace the backed-up Stash configuration files? Existing files will be copied to .bak first.','Restore Settings','YesNo','Question') -ne 'Yes'){return}
 foreach($c in $data.Configs){if(Test-Path -LiteralPath $c.Path){Copy-Item -LiteralPath $c.Path -Destination ($c.Path+'.bak') -Force};[void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($c.Path));[IO.File]::WriteAllText($c.Path,[string]$c.Content)}
 $txtUrl.Text=[string]$data.Url;$txtKey.Text=[string]$data.ApiKey
 $script:BackupUtility.Grid.Rows.Clear();[void]$script:BackupUtility.Grid.Rows.Add('Restored','Restart Stash to apply its configuration.')
 }
})
$script:DiagnosticsUtility=New-MaintenancePage 'Connection Diagnostics' 'Check server access, authentication and image download access.' @('Check','Result')
[void](Add-MaintenanceButton $script:DiagnosticsUtility 'Run Checks' {
 $v=$script:DiagnosticsUtility;$v.Grid.Rows.Clear();$v.Hint.Text='Please wait — checking connection…';$v.Hint.Refresh()
 try{$uri=[uri](Get-StashUrl);if($uri.Scheme -notin @('http','https')){throw 'Use an HTTP or HTTPS address.'};[void]$v.Grid.Rows.Add('Server address','Valid')}catch{[void]$v.Grid.Rows.Add('Server address',$_.Exception.Message);return}
 try{[void](Invoke-WebRequest -Uri (Get-StashUrl) -TimeoutSec 15 -UseBasicParsing);[void]$v.Grid.Rows.Add('Server access','Reachable')}catch{[void]$v.Grid.Rows.Add('Server access',$_.Exception.Message)}
 try{$d=Invoke-StashGraphQL 'query { findPerformers(filter:{per_page:1}) { count performers { image_path } } }';[void]$v.Grid.Rows.Add('API authentication','Successful');$image=@($d.findPerformers.performers)[0].image_path
 if($image){if($image -notmatch '^https?://'){$image=(Get-StashUrl)+'/'+$image.TrimStart('/')};$r=Invoke-WebRequest -Uri $image -Headers @{ApiKey=(Get-StashKey)} -TimeoutSec 15 -UseBasicParsing;[void]$v.Grid.Rows.Add('Image download',"HTTP $($r.StatusCode)")}else{[void]$v.Grid.Rows.Add('Image download','No sample image available')}}catch{[void]$v.Grid.Rows.Add('API / image access',$_.Exception.Message)}
 $v.Hint.Text='Checks complete.'
})

