$script:StorageUtility=New-MaintenancePage 'Storage Breakdown' 'See how much disk space your library uses, in total and broken down by studio or performer. Uses the scene cache already loaded at Connect -- Connect again first if you have added new scenes since.' @('Name','Scenes','Total Size')
$storageGroupBy=New-Object Windows.Forms.ComboBox;$storageGroupBy.DropDownStyle='DropDownList';$storageGroupBy.Size=New-Object Drawing.Size(160,30)
[void]$storageGroupBy.Items.AddRange(@('By Studio','By Performer'));$storageGroupBy.SelectedIndex=0
[void]$script:StorageUtility.Bar.Controls.Add($storageGroupBy)
function Get-ToolkitSceneSize($Scene){
 $sum=[double]0
 foreach($file in @($Scene.files)){if($file.size){$sum+=[double]$file.size}}
 return $sum
}
function Update-StorageBreakdown {
 $v=$script:StorageUtility
 if(-not $script:IsConnected){throw 'Press Start & Connect first, so the library cache can load.'}
 $v.Grid.Rows.Clear()
 $groups=@{};$grandTotal=[double]0
 foreach($scene in @($script:SceneCache)){
  $size=Get-ToolkitSceneSize $scene
  $grandTotal+=$size
  if([string]$storageGroupBy.SelectedItem -eq 'By Performer'){
   $names=@($scene.performers | ForEach-Object {[string]$_.name});if(-not $names.Count){$names=@('(No performer)')}
  } else {
   $names=@($(if($scene.studio){[string]$scene.studio.name}else{'(No studio)'}))
  }
  foreach($name in $names){
   if(-not $groups.ContainsKey($name)){$groups[$name]=@{Count=0;Size=[double]0}}
   $groups[$name].Count++
   $groups[$name].Size+=$size
  }
 }
 foreach($key in ($groups.Keys | Sort-Object {$groups[$_].Size} -Descending)){
  [void]$v.Grid.Rows.Add($key,$groups[$key].Count,(Format-SceneFileSize $groups[$key].Size))
 }
 $v.Hint.Text="Total library size: $(Format-SceneFileSize $grandTotal) across $($script:SceneCache.Count) scenes."
}
[void](Add-MaintenanceButton $script:StorageUtility 'Calculate' { Invoke-MaintenanceAction { Update-StorageBreakdown } })
[void](Add-MaintenanceButton $script:StorageUtility 'Export CSV' { Export-GridCsv $script:StorageUtility.Grid 'stash-storage-breakdown.csv' })
[void](Add-MaintenanceButton $script:StorageUtility 'Export HTML' { Export-GridHtml $script:StorageUtility.Grid 'stash-storage-breakdown.html' 'Stash - Storage Breakdown' })

# Utilities -> Library Checklist: exports an Excel workbook listing Studios,
# Movie Scenes (Groups), Full Movies (local folders below) and Stars, each
# with a "Have ?" column, plus a small summary count box -- in the same
# layout as the user's own hand-built checklist spreadsheet. Written as raw
# OOXML (a plain zip of XML parts) so no PowerShell module needs installing.
$script:ToolkitXlsxContentTypes=@'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>
'@
$script:ToolkitXlsxRootRels=@'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>
'@
$script:ToolkitXlsxWorkbook=@'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Movies &amp; Clips" sheetId="1" r:id="rId1"/></sheets></workbook>
'@
$script:ToolkitXlsxWorkbookRels=@'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>
'@
$script:ToolkitXlsxStyles=@'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="3"><font><sz val="11"/><color rgb="FF000000"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FF000000"/><name val="Calibri"/></font></fonts><fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF8ECBE6"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF2F2F2"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color rgb="FFBFBFBF"/></left><right style="thin"><color rgb="FFBFBFBF"/></right><top style="thin"><color rgb="FFBFBFBF"/></top><bottom style="thin"><color rgb="FFBFBFBF"/></bottom><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="6"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1"/><xf numFmtId="0" fontId="2" fillId="3" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="0" fillId="3" borderId="1" xfId="0" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>
'@
function ConvertTo-ToolkitXmlSafeText([string]$Text) {
 if([string]::IsNullOrEmpty($Text)){return ''}
 $clean=[regex]::Replace($Text,'[\x00-\x08\x0B\x0C\x0E-\x1F]','')
 return $clean -replace '&','&amp;' -replace '<','&lt;' -replace '>','&gt;'
}
function Get-ToolkitLibraryChecklistFolders {
 return @($script:LibraryChecklistUtility.Folders.Lines | ForEach-Object {$_.Trim()} | Where-Object {$_})
}
function Get-ToolkitLibraryChecklistCoversFolder {
 return [string]$script:LibraryChecklistUtility.CoversFolder.Text.Trim()
}
function Get-ToolkitFullMovieList([string[]]$Folders,[string]$CoversFolder) {
 # Full movie files live in plain folders named after the movie (no cover
 # inside); the front/back cover images live separately, one subfolder per
 # movie, under $CoversFolder -- e.g. "<CoversFolder>\Pirates\Pirates (Front).jpg".
 # The Full Movies folders include a trailing "(YYYY)" release year that the
 # Movie Covers folder names never do (e.g. "Pirates (2005)" vs "Pirates"), so
 # try an exact-name match first and fall back to the name with that year
 # suffix stripped off.
 $results=@()
 foreach($folder in $Folders){
  if([string]::IsNullOrWhiteSpace($folder) -or -not (Test-Path -LiteralPath $folder -PathType Container)){continue}
  foreach($dir in @(Get-ChildItem -LiteralPath $folder -Directory -Force -ErrorAction SilentlyContinue)){
   $have=$false
   if(-not [string]::IsNullOrWhiteSpace($CoversFolder)){
    $coverDir=Join-Path $CoversFolder $dir.Name
    if(-not (Test-Path -LiteralPath $coverDir -PathType Container)){
     $baseName=($dir.Name -replace '\s*\(\d{4}\)\s*$','').Trim()
     if($baseName -and $baseName -ne $dir.Name){$coverDir=Join-Path $CoversFolder $baseName}
    }
    if(Test-Path -LiteralPath $coverDir -PathType Container){
     $front=@(Get-ChildItem -LiteralPath $coverDir -File -Force -ErrorAction SilentlyContinue | Where-Object {$_.BaseName -match '(?i)front' -and $_.Extension -match '^\.(jpg|jpeg|png|bmp)$'})
     $have=($front.Count -gt 0)
    }
   }
   $results+=[pscustomobject]@{Name=$dir.Name;Have=$have}
  }
 }
 return @($results | Sort-Object Name)
}
function Get-ToolkitChecklistEntries($Items,[string]$ImageProperty) {
 return @($Items | ForEach-Object {[pscustomobject]@{Name=[string]$_.name;Have=(-not [string]::IsNullOrWhiteSpace([string]($_.$ImageProperty)))}} | Sort-Object Name)
}
function Get-ToolkitChecklistCellPair([string]$NameCol,[string]$HaveCol,[int]$Row,$Entry) {
 $name=ConvertTo-ToolkitXmlSafeText $Entry.Name
 $have=if($Entry.Have){'Yes'}else{'No'}
 # s="2" (Name) is the plain bordered cell; s="5" (Have Logo/Cover/Picture) is
 # the same bordered cell but centered, so the Yes/No sits in the middle.
 return '<c r="'+$NameCol+$Row+'" t="inlineStr" s="2"><is><t>'+$name+'</t></is></c><c r="'+$HaveCol+$Row+'" t="inlineStr" s="5"><is><t>'+$have+'</t></is></c>'
}
function New-ToolkitChecklistSheetXml($Studios,$MovieScenes,$FullMovies,$Stars) {
 $maxRows=[Math]::Max(4,[Math]::Max([Math]::Max($Studios.Count,$MovieScenes.Count),[Math]::Max($FullMovies.Count,$Stars.Count)))
 $sb=New-Object Text.StringBuilder
 [void]$sb.Append('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><dimension ref="B2:Q'+($maxRows+2)+'"/><sheetViews><sheetView tabSelected="1" workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="15"/><cols>')
 foreach($col in @(@(2,32),@(3,14),@(4,3),@(5,50),@(6,14),@(7,3),@(8,30),@(9,14),@(10,3),@(11,18),@(12,3),@(13,14),@(16,16),@(17,10))){
  [void]$sb.Append('<col min="'+$col[0]+'" max="'+$col[0]+'" width="'+$col[1]+'" customWidth="1"/>')
 }
 [void]$sb.Append('</cols><sheetData><row r="2">')
 foreach($h in @(@('B','Studios'),@('C','Have Logo ?'),@('E','Movie Scenes'),@('F','Have Cover ?'),@('H','Full Movies'),@('I','Have Cover ?'),@('K','Stars'),@('M','Have Picture ?'),@('P','Category'),@('Q','Count'))) {
  [void]$sb.Append('<c r="'+$h[0]+'2" t="inlineStr" s="1"><is><t>'+$h[1]+'</t></is></c>')
 }
 [void]$sb.Append('</row>')
 $stats=@(@('Studios',$Studios.Count),@('Movie Scenes',$MovieScenes.Count),@('Full Movies',$FullMovies.Count),@('Stars',$Stars.Count))
 for($i=0;$i -lt $maxRows;$i++){
  $r=$i+3
  [void]$sb.Append('<row r="'+$r+'">')
  if($i -lt $Studios.Count){[void]$sb.Append((Get-ToolkitChecklistCellPair 'B' 'C' $r $Studios[$i]))}
  if($i -lt $MovieScenes.Count){[void]$sb.Append((Get-ToolkitChecklistCellPair 'E' 'F' $r $MovieScenes[$i]))}
  if($i -lt $FullMovies.Count){[void]$sb.Append((Get-ToolkitChecklistCellPair 'H' 'I' $r $FullMovies[$i]))}
  if($i -lt $Stars.Count){[void]$sb.Append((Get-ToolkitChecklistCellPair 'K' 'M' $r $Stars[$i]))}
  if($i -lt $stats.Count){
   [void]$sb.Append('<c r="P'+$r+'" t="inlineStr" s="3"><is><t>'+$stats[$i][0]+'</t></is></c><c r="Q'+$r+'" s="4"><v>'+$stats[$i][1]+'</v></c>')
  }
  [void]$sb.Append('</row>')
 }
 [void]$sb.Append('</sheetData></worksheet>')
 return $sb.ToString()
}
function Save-ToolkitXlsxPackage([string]$Path,$Parts) {
 Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue
 if(Test-Path -LiteralPath $Path){Remove-Item -LiteralPath $Path -Force}
 $fs=[IO.File]::Open($Path,[IO.FileMode]::Create)
 try{
  $zip=New-Object IO.Compression.ZipArchive($fs,[IO.Compression.ZipArchiveMode]::Create)
  try{
   $enc=New-Object Text.UTF8Encoding($false)
   foreach($name in $Parts.Keys){
    $entry=$zip.CreateEntry($name,[IO.Compression.CompressionLevel]::Optimal)
    $es=$entry.Open()
    try{$bytes=$enc.GetBytes([string]$Parts[$name]);$es.Write($bytes,0,$bytes.Length)}finally{$es.Dispose()}
   }
  }finally{$zip.Dispose()}
 }finally{$fs.Dispose()}
}
function Export-ToolkitLibraryChecklist([string]$Path) {
 if(-not $script:IsConnected){throw 'Press Start & Connect first, so Studios, Groups and Performers can load from Stash.'}
 if(-not $script:StudioCacheLoaded){[void](Load-StudioCache)}
 if(-not $script:GroupCacheLoaded){[void](Load-GroupCache)}
 if(-not $script:AllPerformers.Count){[void](Load-AllPerformers)}
 $studios=Get-ToolkitChecklistEntries $script:StudioCache 'image_path'
 $movieScenes=Get-ToolkitChecklistEntries $script:GroupCache 'front_image_path'
 $stars=Get-ToolkitChecklistEntries $script:AllPerformers 'image_path'
 $fullMovies=Get-ToolkitFullMovieList (Get-ToolkitLibraryChecklistFolders) (Get-ToolkitLibraryChecklistCoversFolder)
 $sheetXml=New-ToolkitChecklistSheetXml $studios $movieScenes $fullMovies $stars
 $parts=[ordered]@{
  '[Content_Types].xml'=$script:ToolkitXlsxContentTypes
  '_rels/.rels'=$script:ToolkitXlsxRootRels
  'xl/workbook.xml'=$script:ToolkitXlsxWorkbook
  'xl/_rels/workbook.xml.rels'=$script:ToolkitXlsxWorkbookRels
  'xl/styles.xml'=$script:ToolkitXlsxStyles
  'xl/worksheets/sheet1.xml'=$sheetXml
 }
 Save-ToolkitXlsxPackage $Path $parts
 return [pscustomobject]@{Studios=$studios;MovieScenes=$movieScenes;FullMovies=$fullMovies;Stars=$stars}
}
$script:LibraryChecklistUtility=New-MaintenancePage 'Library Checklist' 'Builds an Excel checklist of your Studios, Movie Scenes (Groups), Full Movies (the folders below) and Stars, each with a "Have ?" column -- auto-filled from Stash images, and for Full Movies from the front cover in the covers folder below -- plus a summary count box. Connect to Stash first.' @('Category','Count','With Image / Cover')
