$script:LibraryChecklistUtility.CoversFolder=$checklistCoversFolder
$checklistBrowseCovers=New-UtilityFileButton 'Covers Folder'
[void]$script:LibraryChecklistUtility.Bar.Controls.AddRange(@($checklistFolders,$checklistAddFolder,$checklistCoversFolder,$checklistBrowseCovers))
$checklistAddFolder.Add_Click({$dialog=New-Object Windows.Forms.FolderBrowserDialog;try{if($dialog.ShowDialog($form) -eq 'OK'){$checklistFolders.AppendText("`r`n"+$dialog.SelectedPath)}}finally{$dialog.Dispose()}})
$checklistBrowseCovers.Add_Click({$dialog=New-Object Windows.Forms.FolderBrowserDialog;if($checklistCoversFolder.Text.Trim()){$dialog.SelectedPath=$checklistCoversFolder.Text.Trim()};try{if($dialog.ShowDialog($form) -eq 'OK'){$checklistCoversFolder.Text=$dialog.SelectedPath}}finally{$dialog.Dispose()}})
function Update-ToolkitLibraryChecklistPreview {
 $v=$script:LibraryChecklistUtility
 if(-not $script:IsConnected){throw 'Press Start & Connect first, so the library cache can load.'}
 if(-not $script:StudioCacheLoaded){[void](Load-StudioCache)}
 if(-not $script:GroupCacheLoaded){[void](Load-GroupCache)}
 if(-not $script:AllPerformers.Count){[void](Load-AllPerformers)}
 $studios=Get-ToolkitChecklistEntries $script:StudioCache 'image_path'
 $movieScenes=Get-ToolkitChecklistEntries $script:GroupCache 'front_image_path'
 $stars=Get-ToolkitChecklistEntries $script:AllPerformers 'image_path'
 $fullMovies=Get-ToolkitFullMovieList (Get-ToolkitLibraryChecklistFolders) (Get-ToolkitLibraryChecklistCoversFolder)
 $v.Grid.Rows.Clear()
 foreach($pair in @(@('Studios',$studios),@('Movie Scenes',$movieScenes),@('Full Movies',$fullMovies),@('Stars',$stars))){
  $have=@($pair[1] | Where-Object Have).Count
  [void]$v.Grid.Rows.Add($pair[0],$pair[1].Count,"$have of $($pair[1].Count)")
 }
 $v.Hint.Text='Preview built. Use Export Excel to save the checklist workbook.'
}
[void](Add-MaintenanceButton $script:LibraryChecklistUtility 'Build Checklist' { Invoke-MaintenanceAction { Update-ToolkitLibraryChecklistPreview } })
[void](Add-MaintenanceButton $script:LibraryChecklistUtility 'Export Excel' { Invoke-MaintenanceAction {
