 if(-not $path){return}
 if(-not $path.ToLower().EndsWith('.xlsx')){$path+='.xlsx'}
 $result=Export-ToolkitLibraryChecklist $path
 $script:LibraryChecklistUtility.Hint.Text="Exported: Studios $($result.Studios.Count), Movie Scenes $($result.MovieScenes.Count), Full Movies $($result.FullMovies.Count), Stars $($result.Stars.Count)."
 Show-ExportSuccess 'Excel'
}})

