$script:RandomExtra.Loading=$false
function Ensure-RandomExtraScenes {
 $v=$script:RandomExtra
 if($v.Loading){return}
 if(-not $script:IsConnected){$v.Hint.Text='Connect to Stash first to use Random Scene Picker.';return}
 if(-not $script:SceneCache.Count){
  $v.Loading=$true
  try{
   $v.Hint.Text='Please wait — loading scenes…';$v.Hint.Refresh()
   Begin-BrowserLoading 'Scenes'
   [void](Load-SceneCache)
   Update-RandomExtraFilters
  }finally{End-BrowserLoading;$v.Loading=$false}
 }
 if(-not $script:SceneCache.Count){$v.Hint.Text='No scenes are available.'}
 else{$v.Hint.Text='Choose optional filters and click Pick Random Scene to view its details and screenshot.'}
}
$script:RandomExtra.Page.Add_Enter({Ensure-RandomExtraScenes;Update-RandomExtraFilters})
