$extrasTabs.Add_SelectedIndexChanged({if($extrasTabs.SelectedTab -eq $script:RandomExtra.Page){Ensure-RandomExtraScenes;Update-RandomExtraFilters}})
$btnConnect.Add_Click({if($tabs.SelectedTab -eq $tabExtras -and $extrasTabs.SelectedTab -eq $script:RandomExtra.Page){Ensure-RandomExtraScenes;Update-RandomExtraFilters}})
