# Creative Extras.
function Get-ExtraImage([string]$Url){
 if(-not $Url){return $null};if($Url -notmatch '^https?://'){$Url=(Get-StashUrl)+'/'+$Url.TrimStart('/')}
 $request=[Net.HttpWebRequest]::Create($Url);$request.Headers['ApiKey']=Get-StashKey;$request.Timeout=15000;$request.ReadWriteTimeout=15000
 $response=$null;$stream=$null;$memory=$null;$img=$null;$temp=$null;$converted=$null
 try{
  $response=$request.GetResponse();$stream=$response.GetResponseStream();$memory=New-Object IO.MemoryStream;$stream.CopyTo($memory);$bytes=$memory.ToArray();$memory.Position=0
  try{$img=[Drawing.Image]::FromStream($memory)}catch{
   $ffmpeg=Find-ToolkitFfmpeg
   if(-not $ffmpeg){throw 'This screenshot format needs FFmpeg to decode it.'}
   $temp=Join-Path ([IO.Path]::GetTempPath()) ('ToolkitImage-'+[guid]::NewGuid().ToString('N')+'.img');$converted=$temp+'.png';[IO.File]::WriteAllBytes($temp,$bytes)
   $si=New-Object Diagnostics.ProcessStartInfo;$si.FileName=$ffmpeg;$si.Arguments='-hide_banner -loglevel error -i "'+$temp+'" -frames:v 1 -y "'+$converted+'"';$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardError=$true
   $process=New-Object Diagnostics.Process;$process.StartInfo=$si
   try{[void]$process.Start();$errorRead=$process.StandardError.ReadToEndAsync();if(-not $process.WaitForExit(15000)){$process.Kill();throw 'Screenshot decoding timed out.'};$errorText=$errorRead.GetAwaiter().GetResult();if($process.ExitCode -ne 0 -or -not (Test-Path -LiteralPath $converted)){throw 'Screenshot data could not be decoded.'}}finally{$process.Dispose()}
   $img=[Drawing.Image]::FromFile($converted)
  }
  return (New-Object Drawing.Bitmap($img))
 }finally{
  foreach($resource in @($img,$memory,$stream,$response)){if($resource){$resource.Dispose()}}
  foreach($file in @($temp,$converted)){if($file -and (Test-Path -LiteralPath $file)){Remove-Item -LiteralPath $file -Force}}
 }
}
