 $bitmap=New-Object Drawing.Bitmap(1280,(400+240*[Math]::Ceiling($scenes.Count/4.0)));$g=[Drawing.Graphics]::FromImage($bitmap);$font=New-Object Drawing.Font('Segoe UI',11);$title=New-Object Drawing.Font('Segoe UI',20,[Drawing.FontStyle]::Bold);$fmt=New-Object Drawing.StringFormat;$fmt.Alignment='Center';$fmt.LineAlignment='Center';$fmt.Trimming='EllipsisWord';$g.Clear([Drawing.Color]::FromArgb(16,45,62));$g.DrawString($name,$title,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF(10,5,1260,65)),$fmt)
 $g.DrawString(($scenes.Count.ToString()+' scenes'),$font,[Drawing.Brushes]::LightGray,(New-Object Drawing.RectangleF(10,365,1260,28)),$fmt)
 try{try{Begin-BrowserLoading 'Collage';
 $portrait=$null
