 }catch{$g.DrawString('Performer image unavailable',$font,[Drawing.Brushes]::LightGray,(New-Object Drawing.RectangleF(10,80,1260,280)),$fmt)}finally{if($portrait){$portrait.Dispose()}}
 for($i=0;$i -lt $scenes.Count;$i++){$v.Hint.Text="Creating collage image $($i+1) of $($scenes.Count)…";$v.Hint.Refresh();[Windows.Forms.Application]::DoEvents();$img=$null;try{$img=Get-ExtraImage $scenes[$i].paths.screenshot}catch{$v.FailedImages++};if(-not $img){$x=($i%4)*320;$y=400+240*[Math]::Floor($i/4);$g.DrawString('Screenshot unavailable',$font,[Drawing.Brushes]::LightGray,(New-Object Drawing.RectangleF($x,$y,320,180)),$fmt);$g.DrawString([string]$scenes[$i].title,$font,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF($x,($y+185),320,50)),$fmt)};try{if($img){$x=($i%4)*320;$y=400+240*[Math]::Floor($i/4);$scale=[Math]::Min(320/$img.Width,180/$img.Height);$w=[int]($img.Width*$scale);$h=[int]($img.Height*$scale);$g.DrawImage($img,[int]($x+(320-$w)/2),[int]($y+(180-$h)/2),$w,$h);$g.DrawString([string]$scenes[$i].title,$font,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF($x,($y+185),320,50)),$fmt)}}finally{if($img){$img.Dispose()}}}}finally{End-BrowserLoading};$old=$v.Picture.Image;$v.Picture.Image=New-Object Drawing.Bitmap($bitmap);if($old){$old.Dispose()};$v.SaveName='Performer Collage - '+($name -replace '[<>:"/\\|?*]','_')+'.jpg';$v.Hint.Text='Collage ready. Use Save Image to keep it.';if($v.FailedImages){$v.Hint.Text+=' '+$v.FailedImages+' screenshots could not be loaded.'}}finally{$g.Dispose();$bitmap.Dispose();$font.Dispose();$title.Dispose();$fmt.Dispose();$v.Running=$false}
 }})
