function Set-GalleryTurnCover {
 $v=$script:GalleryExtra;$group=$v.OpenGroup
 $url=if($v.CoverSide -eq 'Front'){$group.front_image_path}else{$group.back_image_path}
 $newImage=$null
 if($url){$newImage=Get-ExtraImage $url}
 $old=$v.CoverPicture.Image;$v.CoverPicture.Image=$newImage;if($old){$old.Dispose()}
 $v.CoverHeading.Text=$v.CoverSide
