}
function Fit-GalleryWindowTitle {
 $v=$script:GalleryExtra
 if($v.FittingTitle -or -not $v.CoverFrame -or $v.CoverFrame.IsDisposed){return}
 $v.FittingTitle=$true;$g=$null;$font=$null
 try{
  $frame=$v.CoverFrame
  if($frame.ClientSize.Width -lt 100){return}
  $g=$frame.CreateGraphics();$font=New-Object Drawing.Font('Segoe UI',11)
  $width=[Math]::Max(40,$frame.ClientSize.Width-70)
  $size=$g.MeasureString([string]$frame.Text,$font)
  $pointSize=[single]11
  if($size.Width -gt $width){$pointSize=[single][Math]::Max(1,11*$width/$size.Width*0.96)}
  if([Math]::Abs($frame.Font.Size-$pointSize) -gt 0.1){
   # Child controls inherit this font; never dispose it while they may still use it.
   $frame.Font=New-Object Drawing.Font('Segoe UI',$pointSize)
  }
 }finally{if($font){$font.Dispose()};if($g){$g.Dispose()};$v.FittingTitle=$false}
}
function Open-GalleryGroup($Group,$SourceControl=$null){
 if(-not $script:SceneScreenshotNSFW){return}
 $v=$script:GalleryExtra
 if(-not $v.CoverWindow -or $v.CoverWindow.IsDisposed){
