  $picture=New-Object Windows.Forms.PictureBox;$picture.Dock='Fill';$picture.SizeMode='Zoom';$picture.Cursor=[Windows.Forms.Cursors]::Hand;Register-ToolkitImage $picture
  $turn=New-Object Windows.Forms.Label;$turn.Text='↻ Click Image to Turn Cover';$turn.Dock='Fill';$turn.TextAlign='MiddleCenter';$turn.ForeColor=[Drawing.Color]::White;$picture.Add_MouseClick({param($sender,$e)if($e.Button -eq 'Left'){Switch-GalleryTurnCover}})
  [void]$layout.Controls.Add($heading,0,0);[void]$layout.Controls.Add($picture,0,1);[void]$layout.Controls.Add($turn,0,2)
  $frame=New-Object Windows.Forms.GroupBox;$frame.Dock='Fill';$frame.ForeColor=[Drawing.Color]::White;$frame.Padding=New-Object Windows.Forms.Padding(12,22,12,12);$frame.Font=New-Object Drawing.Font('Segoe UI',11)
  [void]$frame.Controls.Add($layout);[void]$window.Controls.Add($frame);$v.CoverFrame=$frame;$window.Add_Resize({Fit-GalleryWindowTitle})
  $v.CoverWindow=$window;$v.CoverPicture=$picture;$v.CoverHeading=$heading
  $window.Add_FormClosing({
   param($sender,$e)
   $v=$script:GalleryExtra
   if($v.ClosingAnimation -or -not $v.OriginControl -or $v.OriginControl.IsDisposed -or $form.IsDisposed){return}
   $v.ClosingAnimation=$true
   try{
    $origin=$v.OriginControl
    while($origin.Parent -and $origin -isnot [Windows.Forms.GroupBox]){$origin=$origin.Parent}
    $target=$origin.RectangleToScreen($origin.ClientRectangle);$start=$sender.Bounds
    $target=New-Object Drawing.Rectangle(($target.X+[int](($target.Width-120)/2)),($target.Y+[int](($target.Height-140)/2)),120,140)
    for($step=1;$step -le 40;$step++){
     $t=$step/40.0;$ease=$t*$t*(3-2*$t)
     $sender.Bounds=New-Object Drawing.Rectangle([int]($start.X+($target.X-$start.X)*$ease),[int]($start.Y+($target.Y-$start.Y)*$ease),[int]($start.Width+($target.Width-$start.Width)*$ease),[int]($start.Height+($target.Height-$start.Height)*$ease))
     $sender.PerformLayout();$v.CoverPicture.Refresh();$sender.Refresh();[Windows.Forms.Application]::DoEvents();if($sender.IsDisposed){break};Start-Sleep -Milliseconds 25
    }
   }finally{$v.ClosingAnimation=$false}
  })
  $window.Add_FormClosed({$v=$script:GalleryExtra;[void]$script:ToolkitImages.Remove($v.CoverPicture);if($v.CoverPicture.Image){$v.CoverPicture.Image.Dispose();$v.CoverPicture.Image=$null};$v.CoverWindow=$null})
 }
 $v.OriginControl=$SourceControl;$v.OpenGroup=$Group;$v.CoverFrame.Text=[string]$Group.name;$v.CoverSide='Front';Fit-GalleryWindowTitle;Set-GalleryTurnCover
 if(-not $v.CoverWindow.Visible){
  $window=$v.CoverWindow
  if($SourceControl -and -not $SourceControl.IsDisposed){
   $origin=$SourceControl
   while($origin.Parent -and $origin -isnot [Windows.Forms.GroupBox]){$origin=$origin.Parent}
   $start=$origin.RectangleToScreen($origin.ClientRectangle)
   $area=[Windows.Forms.Screen]::FromControl($SourceControl).WorkingArea
   $target=New-Object Drawing.Rectangle(($area.Left+[int](($area.Width-$window.Width)/2)),($area.Top+[int](($area.Height-$window.Height)/2)),$window.Width,$window.Height)
   $startWidth=120;$startHeight=140
   $start=New-Object Drawing.Rectangle(($start.X+[int](($start.Width-$startWidth)/2)),($start.Y+[int](($start.Height-$startHeight)/2)),$startWidth,$startHeight)
   $window.StartPosition='Manual';$window.Bounds=$start;$window.Show($form)
   for($step=1;$step -le 40;$step++){
    $t=$step/40.0;$ease=$t*$t*(3-2*$t)
    $window.Bounds=New-Object Drawing.Rectangle([int]($start.X+($target.X-$start.X)*$ease),[int]($start.Y+($target.Y-$start.Y)*$ease),[int]($start.Width+($target.Width-$start.Width)*$ease),[int]($start.Height+($target.Height-$start.Height)*$ease))
    $window.PerformLayout();$v.CoverPicture.Refresh();$window.Refresh();[Windows.Forms.Application]::DoEvents();if($window.IsDisposed){break};Start-Sleep -Milliseconds 25
   }
   if(-not $window.IsDisposed){$window.Bounds=$target}
  }else{$window.Show($form)}
 }else{$v.CoverWindow.Activate()}
}
function Center-ExtraGallery {
 $v=$script:GalleryExtra;if($v.Centering -or -not $v.Panel -or $v.Panel.IsDisposed){return}
 $v.Centering=$true
 try{
  $width=$v.Panel.ClientSize.Width
  if($v.Panel.VerticalScroll.Visible){$width-=[Windows.Forms.SystemInformation]::VerticalScrollBarWidth}
  $cellWidth=476;$columns=[Math]::Max(1,[Math]::Floor($width/$cellWidth))
  if($v.Panel.Controls.Count){$columns=[Math]::Min($columns,$v.Panel.Controls.Count)}
  $space=[Math]::Max(0,[int](($width-$columns*$cellWidth)/2))
  if($v.Panel.Padding.Left -ne $space){$v.Panel.Padding=New-Object Windows.Forms.Padding($space,0,$space,0)}
 }finally{$v.Centering=$false}
}
$script:GalleryExtra.Panel.Add_Resize({Center-ExtraGallery})
$script:GalleryExtra.Hint.TextAlign='MiddleCenter'
function Populate-ExtraGallery {
 param([switch]$Force)
 $v=$script:GalleryExtra;if($v.Running){return};if(-not $script:IsConnected){$v.Hint.Text='Connect to Stash first.';return}
 $loadKey=[string]$script:ToolkitConnectionId
 if(-not $Force -and $v.LoadedKey -eq $loadKey -and $v.Panel.Controls.Count){Center-ExtraGallery;return}
 $v.Running=$true
 try{Begin-BrowserLoading 'Covers';if(-not $script:GroupCache.Count){[void](Load-GroupCache)}
 foreach($card in @($v.Panel.Controls)){foreach($pic in @(Get-GalleryPictures $card)){[void]$script:ToolkitImages.Remove($pic);[void]$script:PicturePreviewControls.Remove($pic);if($pic.Image){$pic.Image.Dispose()}};$card.Dispose()};$v.Panel.Controls.Clear()
 $groups=@($script:GroupCache|Sort-Object name)
 foreach($group in $groups){
  $section=New-Object Windows.Forms.GroupBox;$section.Text=[string]$group.name;$section.ForeColor=[Drawing.Color]::White;$section.Size=New-Object Drawing.Size(460,370);$section.Margin=New-Object Windows.Forms.Padding(8);$section.Tag=$group;$section.Cursor=[Windows.Forms.Cursors]::Hand;$section.Add_Click({param($sender,$e) Invoke-MaintenanceAction {Open-GalleryGroup $sender.Tag $sender}})
  $covers=New-Object Windows.Forms.TableLayoutPanel;$covers.Dock='Fill';$covers.ColumnCount=2;$covers.RowCount=1;$covers.Padding=New-Object Windows.Forms.Padding(6)
  [void]$covers.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle('Percent',50)));[void]$covers.ColumnStyles.Add((New-Object Windows.Forms.ColumnStyle('Percent',50)))
  $column=0
  foreach($side in @('Front','Back')){
   $url=if($side -eq 'Front'){$group.front_image_path}else{$group.back_image_path}
   $card=New-Object Windows.Forms.Panel;$card.Dock='Fill'
   $label=New-Object Windows.Forms.Label;$label.Dock='Bottom';$label.Height=32;$label.TextAlign='MiddleCenter';$label.ForeColor=[Drawing.Color]::White;$label.Text=$side;$label.Tag=$group;$label.Cursor=[Windows.Forms.Cursors]::Hand;$label.Add_Click({param($sender,$e) Invoke-MaintenanceAction {Open-GalleryGroup $sender.Tag $sender}})
   $pic=New-Object Windows.Forms.PictureBox;$pic.Dock='Fill';$pic.SizeMode='Zoom';$pic.Tag=$group;$pic.Cursor=[Windows.Forms.Cursors]::Hand;$pic.Add_MouseClick({param($sender,$e)if($e.Button -eq 'Left'){Invoke-MaintenanceAction {Open-GalleryGroup $sender.Tag $sender}}});Register-ToolkitImage $pic
   try{if($url){$pic.Image=Get-ExtraImage $url}else{$label.Text+=' (no cover)'}}catch{$label.Text+=' (unavailable)'}
   [void]$card.Controls.Add($pic);[void]$card.Controls.Add($label);[void]$covers.Controls.Add($card,$column,0);$column++
  }
  [void]$section.Controls.Add($covers);[void]$v.Panel.Controls.Add($section);[Windows.Forms.Application]::DoEvents()
 };$v.Hint.Text="Showing all $($script:GroupCache.Count) groups. Click a group to view and turn its covers.";Center-ExtraGallery;$v.LoadedKey=$loadKey
 }finally{End-BrowserLoading;$v.Running=$false}
}
