function Get-QuizLeaderboardPath {
 return (Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'StashToolkit\quiz-leaderboard.json')
}
function Read-QuizLeaderboard {
 $path=Get-QuizLeaderboardPath
 if(-not (Test-Path -LiteralPath $path)){return @()}
 return @(ConvertFrom-ToolkitJsonArray (Get-Content -LiteralPath $path -Raw -ErrorAction Stop))
}
function Show-QuizLeaderboard {
 Invoke-MaintenanceAction {
  $entries=@(Read-QuizLeaderboard|Sort-Object @{Expression={[int]$_.Score};Descending=$true},@{Expression={$_.Date};Descending=$false})
  $window=New-Object ToolkitDialogWindow;$window.Text='Quiz Leaderboard';$window.ClientSize=New-Object Drawing.Size(740,540);$window.StartPosition='CenterScreen';$window.BackColor=[Drawing.Color]::FromArgb(16,45,62);$window.ControlBox=$false
  $layout=New-Object Windows.Forms.TableLayoutPanel;$layout.Dock='Fill';$layout.Padding=New-Object Windows.Forms.Padding(24);$layout.RowCount=4;$layout.ColumnCount=1
  [void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',62)));[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',60)));[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Percent',100)));[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',54)))
  $heading=New-Object Windows.Forms.Label;$heading.Text='★ QUIZ LEADERBOARD ★';$heading.Dock='Fill';$heading.TextAlign='MiddleCenter';$heading.Font=New-Object Drawing.Font('Segoe UI',19,[Drawing.FontStyle]::Bold);$heading.ForeColor=[Drawing.Color]::FromArgb(142,203,230)
  $summary=New-Object Windows.Forms.Label;$summary.Dock='Fill';$summary.TextAlign='MiddleCenter';$summary.Font=New-Object Drawing.Font('Segoe UI',11);$summary.ForeColor=[Drawing.Color]::White
  if($entries.Count){$summary.Text="$($entries.Count) saved scores · Highest score: $($entries[0].Score) / 10`r`nCan you reach the top?"}else{$summary.Text="No scores yet — yours could be the first!`r`nComplete a quiz and choose to add your score."}
  $grid=New-SceneGrid;$grid.RowHeadersVisible=$false;$grid.AutoSizeRowsMode='AllCells';$grid.DefaultCellStyle.WrapMode='True'
  foreach($column in @('Rank','Name','Score','Date')){[void]$grid.Columns.Add($column,$column)}
  $grid.Columns['Rank'].FillWeight=14;$grid.Columns['Name'].FillWeight=46;$grid.Columns['Score'].FillWeight=18;$grid.Columns['Date'].FillWeight=22
  $rank=0;foreach($entry in $entries){$rank++;$idx=$grid.Rows.Add($rank,[string]$entry.Name,([string]$entry.Score+' / 10'),([datetime]$entry.Date).ToString('dd MMM yyyy'));if($rank -le 3){$grid.Rows[$idx].DefaultCellStyle.BackColor=[Drawing.Color]::FromArgb(31,70,90);$grid.Rows[$idx].DefaultCellStyle.ForeColor=[Drawing.Color]::White}}
  $close=New-UtilityFileButton 'Back to Quiz';$close.Anchor='None';$close.DialogResult='OK';$window.AcceptButton=$close;$window.CancelButton=$close
  [void]$layout.Controls.Add($heading,0,0);[void]$layout.Controls.Add($summary,0,1);[void]$layout.Controls.Add($grid,0,2);[void]$layout.Controls.Add($close,0,3);[void]$window.Controls.Add($layout)
  try{[void]$window.ShowDialog($form)}finally{$window.Dispose()}
 }
}
function Confirm-QuizLeaderboardEntry {
 $window=New-Object ToolkitDialogWindow;$window.Text='Add Your Score';$window.ControlBox=$false;$window.ClientSize=New-Object Drawing.Size(560,330);$window.StartPosition='CenterScreen';$window.BackColor=[Drawing.Color]::FromArgb(16,45,62);$window.ForeColor=[Drawing.Color]::White
 $layout=New-Object Windows.Forms.TableLayoutPanel;$layout.Dock='Fill';$layout.Padding=New-Object Windows.Forms.Padding(24);$layout.ColumnCount=1;$layout.RowCount=4
 foreach($height in @(60,80,60,82)){[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',$height)))}
 $heading=New-Object Windows.Forms.Label;$heading.Text='★ Claim your place ★';$heading.Dock='Fill';$heading.TextAlign='MiddleCenter';$heading.Font=New-Object Drawing.Font('Segoe UI',20,[Drawing.FontStyle]::Bold);$heading.ForeColor=[Drawing.Color]::FromArgb(142,203,230)
 $score=New-Object Windows.Forms.Label;$score.Text="$($script:QuizExtra.Score) / 10";$score.Dock='Fill';$score.TextAlign='MiddleCenter';$score.Font=New-Object Drawing.Font('Segoe UI',32,[Drawing.FontStyle]::Bold)
 $message=New-Object Windows.Forms.Label;$message.Text="Add this score to the leaderboard?`r`nYou’ll choose a display name next.";$message.Dock='Fill';$message.TextAlign='MiddleCenter';$message.Font=New-Object Drawing.Font('Segoe UI',12)
 $buttons=New-Object Windows.Forms.FlowLayoutPanel;$buttons.Dock='Fill';$buttons.Padding=New-Object Windows.Forms.Padding(70,16,0,0)
 $yes=New-UtilityFileButton 'Add My Score';$yes.DialogResult='Yes';$yes.BackColor=[Drawing.Color]::FromArgb(28,108,60)
 $no=New-UtilityFileButton 'Not Now';$no.DialogResult='No';$window.AcceptButton=$yes;$window.CancelButton=$no
 [void]$buttons.Controls.AddRange(@($yes,$no));[void]$layout.Controls.Add($heading,0,0);[void]$layout.Controls.Add($score,0,1);[void]$layout.Controls.Add($message,0,2);[void]$layout.Controls.Add($buttons,0,3);[void]$window.Controls.Add($layout)
 try{return $window.ShowDialog($form)}finally{$window.Dispose()}
