function Offer-QuizLeaderboard {
 if((Confirm-QuizLeaderboardEntry) -ne 'Yes'){return}
 $window=New-Object ToolkitDialogWindow;$window.Text='Leaderboard Name';$window.ControlBox=$false;$window.ClientSize=New-Object Drawing.Size(560,330);$window.StartPosition='CenterScreen';$window.BackColor=[Drawing.Color]::FromArgb(16,45,62)
 $heading=New-Object Windows.Forms.Label;$heading.Text='★ Make your mark ★';$heading.ForeColor=[Drawing.Color]::FromArgb(142,203,230);$heading.Font=New-Object Drawing.Font('Segoe UI',20,[Drawing.FontStyle]::Bold);$heading.TextAlign='MiddleCenter';$heading.SetBounds(24,20,512,50)
 $summary=New-Object Windows.Forms.Label;$summary.Text="Your score: $($script:QuizExtra.Score) / 10";$summary.ForeColor=[Drawing.Color]::White;$summary.Font=New-Object Drawing.Font('Segoe UI',13);$summary.TextAlign='MiddleCenter';$summary.SetBounds(24,75,512,36)
 $label=New-Object Windows.Forms.Label;$label.Text='Choose your leaderboard name';$label.ForeColor=[Drawing.Color]::White;$label.Font=New-Object Drawing.Font('Segoe UI',11);$label.SetBounds(30,130,500,30)
 $name=New-Object Windows.Forms.TextBox;$name.SetBounds(30,168,500,34);$name.Font=New-Object Drawing.Font('Segoe UI',14);$name.MaxLength=60
 $note=New-Object Windows.Forms.Label;$note.Text='Use a name or nickname — up to 60 characters.';$note.ForeColor=[Drawing.Color]::LightGray;$note.SetBounds(30,210,500,25)
 $save=New-UtilityFileButton 'Save My Score';$save.SetBounds(110,260,165,36);$save.Enabled=$false
 $cancel=New-UtilityFileButton 'Not Now';$cancel.SetBounds(285,260,165,36);$cancel.DialogResult='Cancel'
 [void]$window.Controls.AddRange(@($heading,$summary,$note))
 $name.Add_TextChanged({$save.Enabled=-not [string]::IsNullOrWhiteSpace($name.Text)}.GetNewClosure())
 $save.Add_Click({if(-not [string]::IsNullOrWhiteSpace($name.Text)){$window.DialogResult='OK'}}.GetNewClosure())
 $window.AcceptButton=$save;$window.CancelButton=$cancel;[void]$window.Controls.AddRange(@($label,$name,$save,$cancel))
 try{
  if($window.ShowDialog($form) -ne 'OK'){return}
  $displayName=$name.Text.Trim()
  Invoke-MaintenanceAction {
   $entries=@(Read-QuizLeaderboard);$entries+=[pscustomobject]@{Name=$displayName;Score=[int]$script:QuizExtra.Score;Date=(Get-Date).ToString('o')}
   $path=Get-QuizLeaderboardPath;[void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path))
   $json=ConvertTo-Json -InputObject @($entries) -Depth 4
   $temp=$path+'.tmp';[IO.File]::WriteAllText($temp,$json,(New-Object Text.UTF8Encoding($true)));Move-Item -LiteralPath $temp -Destination $path -Force
   Show-QuizLeaderboard
  }
 }finally{$window.Dispose()}
}
function Clear-QuizDisplay {
 $v=$script:QuizExtra;$old=$v.Picture.Image;$v.Picture.Image=$null;if($old){$old.Dispose()}
 foreach($button in @($v.Answers.Controls)){$button.Dispose()};$v.Answers.Controls.Clear()
 $v.Feedback.Text='';$v.Feedback.BackColor=[Drawing.Color]::Transparent;$v.ScoreLabel.Text=''
}
function Clear-CompletedQuiz {
 $v=$script:QuizExtra
 $old=$v.Picture.Image;$v.Picture.Image=$null;if($old){$old.Dispose()}
 foreach($button in @($v.Answers.Controls)){$button.Dispose()};$v.Answers.Controls.Clear()
 $v.Feedback.Text='';$v.Feedback.BackColor=[Drawing.Color]::Transparent
 $v.Score=0;$v.Total=0;$v.Question=0;$v.UsedTitles=@();$v.MixedPool=$null;$v.Answered=$true
 Update-QuizRunningScore
 $v.StartButton.Text='Start Quiz';$v.StartButton.Enabled=$true
 $v.Hint.Text='Press Start Quiz for a new 10-question round.'
}
function Show-QuizResults {
 $v=$script:QuizExtra;$score=[int]$v.Score
 $window=New-Object ToolkitDialogWindow;$window.Text='Quiz Complete';$window.ClientSize=New-Object Drawing.Size(560,380);$window.StartPosition='CenterScreen';$window.BackColor=[Drawing.Color]::FromArgb(16,45,62);$window.ForeColor=[Drawing.Color]::White
 $layout=New-Object Windows.Forms.TableLayoutPanel;$layout.Dock='Fill';$layout.Padding=New-Object Windows.Forms.Padding(28);$layout.ColumnCount=1;$layout.RowCount=5
 foreach($height in @(46,105,35,82,56)){[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',$height)))}
 $heading=New-Object Windows.Forms.Label;$heading.Text='QUIZ COMPLETE';$heading.Dock='Fill';$heading.TextAlign='MiddleCenter';$heading.Font=New-Object Drawing.Font('Segoe UI',15,[Drawing.FontStyle]::Bold)
 $scoreLabel=New-Object Windows.Forms.Label;$scoreLabel.Text="$score / 10";$scoreLabel.Dock='Fill';$scoreLabel.TextAlign='MiddleCenter';$scoreLabel.Font=New-Object Drawing.Font('Segoe UI',42,[Drawing.FontStyle]::Bold);$scoreLabel.ForeColor=[Drawing.Color]::FromArgb(142,203,230)
 $bar=New-Object Windows.Forms.ProgressBar;$bar.Dock='Fill';$bar.Maximum=10;$bar.Value=$score;$bar.Margin=New-Object Windows.Forms.Padding(30,8,30,8)
 $message=New-Object Windows.Forms.Label;$message.Dock='Fill';$message.TextAlign='MiddleCenter';$message.Font=New-Object Drawing.Font('Segoe UI',12)
 $comment=if($score -eq 10){'Perfect score! You know your library.'}elseif($score -ge 8){'Great round! Almost a perfect score.'}elseif($score -ge 5){'Good effort! Try another round to beat it.'}else{'A tricky round! Try again and beat your score.'}
 $message.Text="$comment`r`n$($score*10)% correct · $(10-$score) incorrect"
 $button=New-UtilityFileButton 'Back to Quiz';$button.Anchor='None';$button.DialogResult='OK';$button.Add_Click({Clear-QuizDisplay});$window.AcceptButton=$button;$window.CancelButton=$button
 [void]$layout.Controls.Add($heading,0,0);[void]$layout.Controls.Add($scoreLabel,0,1);[void]$layout.Controls.Add($bar,0,2);[void]$layout.Controls.Add($message,0,3);[void]$layout.Controls.Add($button,0,4);[void]$window.Controls.Add($layout)
 try{[void]$window.ShowDialog($form)}finally{$window.Dispose()}
}
function Update-QuizRunningScore {
 $v=$script:QuizExtra;$wrong=$v.Total-$v.Score
 $v.ScoreLabel.Text="Score: $($v.Score) correct · $wrong incorrect · $($v.Total) of 10 answered"
 if($v.Total){$percent=[int][Math]::Round(100*$v.Score/$v.Total);$v.ScoreLabel.Text+=" · $percent% correct"}
 $v.ScoreLabel.Refresh()
}
