[void]$quizContent.Controls.Add($script:QuizExtra.Feedback,0,3)
function Center-QuizAnswers {
 $v=$script:QuizExtra;if($v.CenteringAnswers -or -not $v.Answers -or $v.Answers.IsDisposed){return}
 $v.CenteringAnswers=$true
 try{
  $width=$v.Answers.ClientSize.Width;$cell=426
  $columns=[Math]::Max(1,[Math]::Floor($width/$cell))
  if($v.Answers.Controls.Count){$columns=[Math]::Min($columns,$v.Answers.Controls.Count)}
  $space=[Math]::Max(0,[int](($width-$columns*$cell)/2))
  if($v.Answers.Padding.Left -ne $space){$v.Answers.Padding=New-Object Windows.Forms.Padding($space,0,$space,0)}
 }finally{$v.CenteringAnswers=$false}
}
$script:QuizExtra.Answers.Add_Resize({Center-QuizAnswers})
function Get-MixedQuizPool {
 Ensure-CreativeScenes
 $pool=@()
 foreach($item in $script:SceneCache){if($item.title -and $item.paths.screenshot){$pool+=[pscustomobject]@{Key='Scenes|'+$item.id;title=$item.title;Subject='Scenes';Url=$item.paths.screenshot}}}
 foreach($item in $script:AllPerformers){if($item.name -and $item.image_path){$pool+=[pscustomobject]@{Key='Performers|'+$item.id;title=$item.name;Subject='Performers';Url=$item.image_path}}}
 if(-not $script:CelebrityImages.Count){$script:CelebrityImages=@(Get-CelebrityImages)}
 foreach($item in $script:CelebrityImages){
  $name=Get-CelebrityImageName $item
  if($name -and $name -ne 'Unknown' -and $item.paths.image){
   $pool+=[pscustomobject]@{Key='Images|'+$item.id;title=$name;Subject='Images';Url=$item.paths.image}
  }
 }
 return @($pool|Sort-Object Subject,title -Unique)
}
$script:QuizExtra.UsedTitles=@()
$script:QuizExtra.Question=0
$script:QuizExtra.StartButton=Add-MaintenanceButton $script:QuizExtra 'Start Quiz' {
 if(-not $script:SceneScreenshotNSFW){
  Show-QuizSafetyNotice
  return
 }
 Invoke-MaintenanceAction {
  Ensure-CreativeScenes;$v=$script:QuizExtra
  if($v.Total -ge 10){$v.Score=0;$v.Total=0;$v.Question=0;$v.UsedTitles=@();$v.MixedPool=$null;Update-QuizRunningScore}
  if(-not $v.MixedPool){
   try{Begin-BrowserLoading 'Quiz';$v.MixedPool=Get-MixedQuizPool}finally{End-BrowserLoading}
   $subjects=@($v.MixedPool|Group-Object Subject|Where-Object Count -ge 2|ForEach-Object{$_.Name})
   if(-not $subjects.Count){throw 'The quiz needs at least two named images in a category.'}
   $schedule=@();for($i=0;$i -lt 10;$i++){$schedule+=$subjects[$i%$subjects.Count]};$v.Schedule=@($schedule|Sort-Object {Get-Random})
  }
  $subject=$v.Schedule[$v.Question]
  $pool=@($v.MixedPool|Where-Object Subject -eq $subject)
  $remaining=@($pool|Where-Object{$_.Key -notin $v.UsedTitles});if(-not $remaining.Count){$remaining=$pool}
  $answer=$remaining|Get-Random
  $others=@($pool|Where-Object{$_.title -ne $answer.title}|Get-Random -Count ([Math]::Min(3,$pool.Count-1)))
  $choices=@(@($answer)+$others|Sort-Object {Get-Random})
  $newImage=Get-ExtraImage $answer.Url
  $v.Feedback.Text='';$v.Feedback.BackColor=[Drawing.Color]::Transparent;$v.CorrectTitle=$answer.title;$v.UsedTitles+=@($answer.Key);$v.Question++;$v.Answered=$false
  $old=$v.Picture.Image;$v.Picture.Image=$newImage;if($old){$old.Dispose()}
  foreach($b in @($v.Answers.Controls)){$b.Dispose()};$v.Answers.Controls.Clear()
  foreach($scene in $choices){
   $b=New-UtilityFileButton ([string]$scene.title);$b.Size=New-Object Drawing.Size(420,110);$b.Padding=New-Object Windows.Forms.Padding(10,8,10,8);$b.TextAlign='MiddleCenter';$b.Tag=$scene.title
   $b.Add_Click({
    param($sender,$e)$v=$script:QuizExtra;if($v.Answered){return}
    $v.Answered=$true;$v.Total++
    if($sender.Tag -eq $v.CorrectTitle){
     $v.Score++;$result='Correct!';$v.Feedback.Text='✓ Correct';$v.Feedback.BackColor=[Drawing.Color]::FromArgb(28,108,60)
     $sender.BackColor=[Drawing.Color]::FromArgb(28,108,60)
    }else{
     $result='Answer: '+$v.CorrectTitle;$v.Feedback.Text='✗ Incorrect — Correct answer: '+$v.CorrectTitle;$v.Feedback.BackColor=[Drawing.Color]::FromArgb(150,40,40)
     $sender.BackColor=[Drawing.Color]::FromArgb(150,40,40)
     foreach($choice in $v.Answers.Controls){if($choice.Tag -eq $v.CorrectTitle){$choice.BackColor=[Drawing.Color]::FromArgb(28,108,60)}}
    }
    Update-QuizRunningScore;foreach($button in $v.Answers.Controls){$button.Enabled=$false}
    if($v.Total -eq 10){
     $v.Hint.Text="Quiz complete. Your score: $($v.Score) out of 10."
     $v.StartButton.Text='Play Again';$v.StartButton.Enabled=$true
     Show-QuizResults;try{Offer-QuizLeaderboard}finally{Clear-CompletedQuiz}
    }else{$v.Hint.Text="$result  Click Next Question to continue.";$v.StartButton.Text='Next Question';$v.StartButton.Enabled=$true}
   });[void]$v.Answers.Controls.Add($b)
  }
  Center-QuizAnswers;$questionText=if($subject -eq 'Images'){'Who is this?'}else{'Which '+$subject.TrimEnd('s').ToLower()+' is this?'};$v.Hint.Text="Question $($v.Question) of 10. $questionText";$v.StartButton.Enabled=$false
 }
}
[void](Add-MaintenanceButton $script:QuizExtra 'Leaderboard' {Show-QuizLeaderboard})
$script:QuizExtra.WasActive=$false
$script:QuizExtra.ResumePrompt=$false
function Check-QuizReturn {
 $v=$script:QuizExtra
 $active=($tabs.SelectedTab -eq $tabExtras -and $extrasTabs.SelectedTab -eq $v.Page)
 if($active -and -not $v.WasActive){
  $v.WasActive=$true
  if($v.Question -gt 0 -and $v.Total -lt 10 -and -not $v.ResumePrompt){
   $v.ResumePrompt=$true
   try{
    $window=New-Object ToolkitDialogWindow;$window.ControlBox=$false;$window.ClientSize=New-Object Drawing.Size(540,260);$window.StartPosition='CenterScreen';$window.BackColor=[Drawing.Color]::FromArgb(16,45,62)
    $heading=New-Object Windows.Forms.Label;$heading.Text='Your quiz is waiting';$heading.Font=New-Object Drawing.Font('Segoe UI',19,[Drawing.FontStyle]::Bold);$heading.ForeColor=[Drawing.Color]::FromArgb(142,203,230);$heading.TextAlign='MiddleCenter';$heading.SetBounds(20,20,500,50)
    $text=New-Object Windows.Forms.Label;$text.Text="You answered $($v.Total) of 10 questions.`r`nContinue this round or exit the quiz?";$text.ForeColor=[Drawing.Color]::White;$text.Font=New-Object Drawing.Font('Segoe UI',12);$text.TextAlign='MiddleCenter';$text.SetBounds(20,85,500,70)
    $continue=New-UtilityFileButton 'Continue Quiz';$continue.SetBounds(95,180,170,36);$continue.DialogResult='Yes'
    $new=New-UtilityFileButton 'Exit Quiz';$new.SetBounds(275,180,170,36);$new.DialogResult='No'
    $window.AcceptButton=$continue;$window.CancelButton=$continue;[void]$window.Controls.AddRange(@($heading,$text,$continue,$new))
    try{$choice=$window.ShowDialog($form)}finally{$window.Dispose()}
    if($choice -eq 'No'){
     Clear-CompletedQuiz

    }
   }finally{$v.ResumePrompt=$false}
  }
 }elseif(-not $active){$v.WasActive=$false}
}
