# Creative and organisational additions.
function Get-ToolkitUserDataPath($Name){$dir=Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'StashToolkit';[void][IO.Directory]::CreateDirectory($dir);return (Join-Path $dir $Name)}
function Read-ToolkitUserData($Name){$p=Get-ToolkitUserDataPath $Name;if(Test-Path -LiteralPath $p){return @(ConvertFrom-ToolkitJsonArray (Get-Content -LiteralPath $p -Raw))};return @()}
function Save-ToolkitUserData($Name,$Data){$p=Get-ToolkitUserDataPath $Name;$json=ConvertTo-Json -InputObject @($Data) -Depth 8;[IO.File]::WriteAllText($p+'.tmp',$json,(New-Object Text.UTF8Encoding($true)));Move-Item -LiteralPath ($p+'.tmp') -Destination $p -Force}
function New-AdditionPage($Target,$Title,$Help,$Columns){$previous=$utilityTabs;$utilityTabs=$Target;try{return (New-MaintenancePage $Title $Help $Columns)}finally{$utilityTabs=$previous}}
function Add-ChoiceControl($View,$Width=400){$c=New-Object Windows.Forms.ComboBox;$c.Width=$Width;$c.DropDownStyle='DropDownList';$c.DisplayMember='Label';[void]$View.Bar.Controls.Add($c);$View.Choice=$c;return $c}
function Set-AdditionImageArea($View){$l=$View.Page.Controls[0];$l.Controls.Remove($View.Grid);$p=New-Object Windows.Forms.PictureBox;$p.Dock='Fill';$p.SizeMode='Zoom';$p.BackColor=[Drawing.Color]::FromArgb(5,20,31);Register-ToolkitImage $p;[void]$l.Controls.Add($p,0,2);$View.Picture=$p;return $p}
function Set-AdditionImage($View,$Bitmap){$old=$View.Picture.Image;$View.Picture.Image=$Bitmap;if($old){$old.Dispose()};$View.Picture.Refresh()}
function Populate-SceneChoice($View){Ensure-CreativeScenes;$previousSelection=$View.Choice.Text;$View.Choice.Items.Clear();foreach($scene in @($script:SceneCache|Sort-Object title)){[void]$View.Choice.Items.Add([pscustomobject]@{Label=(Get-SceneTitle $scene);Record=$scene})};if($View.Choice.Items.Count){$View.Choice.SelectedIndex=0;for($i=0;$i -lt $View.Choice.Items.Count;$i++){if($View.Choice.Items[$i].Label -eq $previousSelection){$View.Choice.SelectedIndex=$i;break}}}}
function Populate-PerformerChoice($View){Ensure-CreativeScenes;$previousSelection=$View.Choice.Text;$View.Choice.Items.Clear();foreach($name in @($script:SceneCache|ForEach-Object{$_.performers}|ForEach-Object{$_.name}|Where-Object{$_}|Sort-Object -Unique)){[void]$View.Choice.Items.Add([pscustomobject]@{Label=$name})};if($View.Choice.Items.Count){$View.Choice.SelectedIndex=0;for($i=0;$i -lt $View.Choice.Items.Count;$i++){if($View.Choice.Items[$i].Label -eq $previousSelection){$View.Choice.SelectedIndex=$i;break}}}}
function Save-AdditionImage($View){if(-not $View.Picture.Image){throw 'Create an image first.'};$name=([string]$View.SaveName -replace '[<>:"/\\|?*]','_');$p=Choose-MaintenanceFile $true 'JPEG image|*.jpg' $name;if($p){$View.Picture.Image.Save($p,[Drawing.Imaging.ImageFormat]::Jpeg);$View.Hint.Text='Image saved.';Show-ExportSuccess 'Image'}}
function New-ShowcaseBitmap($Title,$Records,$Celebrity=$false){
 $count=$Records.Count;if(-not $count){throw 'Choose at least one item.'}
 $b=New-Object Drawing.Bitmap(1280,(100+240*[Math]::Ceiling($count/4.0)));$g=[Drawing.Graphics]::FromImage($b);$f=New-Object Drawing.Font('Segoe UI',11);$tf=New-Object Drawing.Font('Segoe UI',20,[Drawing.FontStyle]::Bold);$fmt=New-Object Drawing.StringFormat;$fmt.Alignment='Center';$fmt.LineAlignment='Center';$fmt.Trimming='EllipsisWord';$success=$false
 try{$g.Clear([Drawing.Color]::FromArgb(16,45,62));$g.DrawString($Title,$tf,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF(20,5,1240,80)),$fmt)
 for($i=0;$i -lt $count;$i++){$r=$Records[$i];$url=if($Celebrity){$r.paths.image}else{$r.paths.screenshot};$label=if($Celebrity){Get-CelebrityImageName $r}else{Get-SceneTitle $r};$img=$null;try{$img=Get-ExtraImage $url}catch{};$x=($i%4)*320;$y=100+240*[Math]::Floor($i/4)
 try{if($img){$scale=[Math]::Min(320/$img.Width,180/$img.Height);$w=[int]($img.Width*$scale);$h=[int]($img.Height*$scale);$g.DrawImage($img,[int]($x+(320-$w)/2),[int]($y+(180-$h)/2),$w,$h)}else{$g.DrawString('Image unavailable',$f,[Drawing.Brushes]::LightGray,(New-Object Drawing.RectangleF($x,$y,320,180)),$fmt)};$g.DrawString($label,$f,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF($x,($y+185),320,50)),$fmt)}finally{if($img){$img.Dispose()}};[Windows.Forms.Application]::DoEvents()};$success=$true;return $b
 }finally{$g.Dispose();$f.Dispose();$tf.Dispose();$fmt.Dispose();if(-not $success){$b.Dispose()}}
}
