}
function Resize-VisualTimeline {
 $v=$script:TimelineAddition;if($v.Sizing){return};$v.Sizing=$true
 try{
  $width=[Math]::Max(290,$v.Panel.ClientSize.Width-55);$columns=[Math]::Max(1,[Math]::Floor(($width-24)/292))
  foreach($section in $v.Panel.Controls){$flow=$section.Tag;$section.Width=$width;$flow.Width=$width-24;$section.Height=62+[int][Math]::Ceiling($flow.Controls.Count/[double]$columns)*280;$flow.Height=$section.Height-52}
