function Show-VisualPerformerTimeline {
 $v=$script:TimelineAddition;if($v.Rendering){return};$v.Rendering=$true
 try{
  Ensure-CreativeScenes;$name=$v.Choice.Text;if(-not $name){throw 'Choose a performer.'}
  Begin-BrowserLoading 'Timeline';Clear-VisualTimeline;$v.Grid.Rows.Clear()
  $records=@($script:SceneCache|Where-Object{$name -in @($_.performers|ForEach-Object{$_.name})}|Sort-Object date,title)
  $years=[ordered]@{}
  foreach($r in $records){$year=if($r.date){([string]$r.date).Substring(0,[Math]::Min(4,([string]$r.date).Length))}else{'Undated'};if(-not $years.Contains($year)){$years[$year]=New-Object Collections.ArrayList};[void]$years[$year].Add($r)}
  $orderedYears=@($years.Keys|Where-Object {$_ -ne 'Undated'}|Sort-Object -Descending:($v.Order.SelectedIndex -eq 1));if($years.Contains('Undated')){$orderedYears+=@('Undated')};foreach($year in $orderedYears){
   $section=New-Object Windows.Forms.GroupBox;$section.Text="$year  •  $($years[$year].Count) scenes";$section.ForeColor=[Drawing.Color]::FromArgb(142,203,230);$section.Font=New-Object Drawing.Font('Segoe UI',14,[Drawing.FontStyle]::Bold);$section.Margin=New-Object Windows.Forms.Padding(0,8,0,16)
   $flow=New-Object Windows.Forms.FlowLayoutPanel;$flow.Location=New-Object Drawing.Point(12,38);$flow.WrapContents=$true;$section.Tag=$flow;[void]$section.Controls.Add($flow)
   foreach($r in $years[$year]){
    [void]$v.Grid.Rows.Add($year,$r.date,(Get-SceneTitle $r),$r.id)
    $card=New-Object Windows.Forms.Panel;$card.Size=New-Object Drawing.Size(280,268);$card.Margin=New-Object Windows.Forms.Padding(6);$card.BackColor=[Drawing.Color]::FromArgb(16,45,62)
    $picture=New-Object Windows.Forms.PictureBox;$picture.SetBounds(0,0,280,158);$picture.SizeMode='Zoom';$picture.AccessibleName=Get-SceneTitle $r;$picture.Tag=@{SceneID=[string]$r.id};Register-ToolkitImage $picture
    try{$picture.Image=Get-ExtraImage $r.paths.screenshot}catch{}
    $date=New-Object Windows.Forms.Label;$date.SetBounds(10,166,260,28);$date.Text=[string]$r.date;$date.ForeColor=[Drawing.Color]::FromArgb(142,203,230);$date.Font=New-Object Drawing.Font('Segoe UI',10)
    $title=New-Object Windows.Forms.Label;$title.SetBounds(10,198,260,60);$title.Text=Get-SceneTitle $r;$title.ForeColor=[Drawing.Color]::White;$title.Font=New-Object Drawing.Font('Segoe UI',10);$title.AutoEllipsis=$false
    [void]$card.Controls.AddRange(@($picture,$date,$title));[void]$flow.Controls.Add($card)
    $v.Hint.Text="Loading timeline: $($v.Grid.Rows.Count) scenes for $name…";$v.Hint.Refresh();[Windows.Forms.Application]::DoEvents()
   }
   [void]$v.Panel.Controls.Add($section)
  }
  Resize-VisualTimeline;Connect-LargePicturePreviews $v.Panel;$v.Hint.Text="$($records.Count) scenes for $name, grouped by year. Click a screenshot to enlarge it."
 }finally{End-BrowserLoading;$v.Rendering=$false}
}
