  $accent=New-Object Drawing.SolidBrush([Drawing.Color]::FromArgb(80,210,220));$panelBrush=New-Object Drawing.SolidBrush([Drawing.Color]::FromArgb(18,30,40));$pen=New-Object Drawing.Pen([Drawing.Color]::FromArgb(80,210,220),2)
