   $g.FillRectangle($accent,50,850,900,6)
   $titleRect=New-Object Drawing.RectangleF(60,890,880,180);$titleText=Get-SceneTitle $r
   $fmt.Trimming='None'
   while($g.MeasureString($titleText,$titleFont,880,$fmt).Height -gt 180 -and $titleFont.Size -gt 8){$size=$titleFont.Size-1;$titleFont.Dispose();$titleFont=New-Object Drawing.Font('Segoe UI',$size,[Drawing.FontStyle]::Bold)}
   [ToolkitPosterText]::Draw($g,$titleText,$titleFont,[Drawing.Brushes]::White,$titleRect,$fmt)
