   [ToolkitPosterText]::Draw($g,$people,$font,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF(60,1112,880,95)),$fmt)
   $g.DrawLine($pen,200,1225,800,1225)
   [ToolkitPosterText]::Draw($g,'STUDIO',$labelFont,$accent,(New-Object Drawing.RectangleF(60,1240,550,24)),$fmt)
   [ToolkitPosterText]::Draw($g,(Get-SceneStudioText $r),$font,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF(60,1275,550,60)),$fmt)
   [ToolkitPosterText]::Draw($g,'RELEASE DATE',$labelFont,$accent,(New-Object Drawing.RectangleF(640,1240,300,24)),$fmt)
   [ToolkitPosterText]::Draw($g,[string]$r.date,$font,[Drawing.Brushes]::White,(New-Object Drawing.RectangleF(640,1275,300,60)),$fmt)
   [ToolkitPosterText]::Draw($g,'STASH TOOLKIT',$labelFont,[Drawing.Brushes]::LightGray,(New-Object Drawing.RectangleF(60,1348,880,24)),$fmt)
   Set-AdditionImage $v (New-Object Drawing.Bitmap($b));$v.SaveName=$titleText+' - Poster.jpg';$v.Hint.Text='Poster ready to save.'
  }finally{$background.Dispose();$accent.Dispose();$panelBrush.Dispose();$pen.Dispose();$labelFont.Dispose();$brandFont.Dispose()}
 }finally{$img.Dispose();$g.Dispose();$b.Dispose();$font.Dispose();$titleFont.Dispose();$fmt.Dispose()}
}})
