function Get-ToolkitHtmlContext($Grid,[string]$DefaultName,[string]$Title){
 if($script:TimelineAddition -and [object]::ReferenceEquals($Grid,$script:TimelineAddition.Grid)){
  return @{Subject='Scenes';Operation='Performer Timeline';Title='Performer Timeline — '+$script:TimelineAddition.Choice.Text;Description='Scenes in chronological order, grouped by year.';Filters=[ordered]@{Performer=$script:TimelineAddition.Choice.Text}}
 }

 return (Get-ToolkitHtmlContextCore $Grid $DefaultName $Title)
}
$componentCheckButton=$script:DependencyAddition.Bar.Controls | Where-Object {$_.Text -eq 'Check Components'} | Select-Object -First 1
if($componentCheckButton){$componentCheckButton.Size=New-Object Drawing.Size(230,34)}
# Browsers lead each section, with By Performer immediately beside them.
foreach($sectionTabs in @($sceneTabs,$script:GroupsTabs,$performerTabs,$script:StudioTabs)){
 [void]$sectionTabs.Handle
 $browser=@($sectionTabs.TabPages | Where-Object {$_.Text -like '*Browser'}) | Select-Object -First 1
 $byPerformer=@($sectionTabs.TabPages | Where-Object {$_.Text -eq 'By Performer'}) | Select-Object -First 1
 if($browser){$sectionTabs.TabPages.Remove($browser);$sectionTabs.TabPages.Insert(0,$browser)}
 if($byPerformer){$sectionTabs.TabPages.Remove($byPerformer);$sectionTabs.TabPages.Insert($(if($browser){1}else{0}),$byPerformer)}
 if($browser){$sectionTabs.SelectedTab=$browser}
}
foreach($entry in @(@($sceneTabs,'Scenes'),@($script:GroupsTabs,'Groups'))){
 $target=$entry[0];$duplicate=$script:SubjectViews[$entry[1]+'|Duplicate Finder'].Page
 if($target.TabPages.Contains($duplicate)){$target.TabPages.Remove($duplicate)}
 $recent=@($target.TabPages|Where-Object Text -eq 'Recently Added')|Select-Object -First 1
 [void]$target.TabPages.Insert(($target.TabPages.IndexOf($recent)+1),$duplicate)
}
# Keep By Studio immediately before the requested neighbouring tab.
foreach($entry in @(@($sceneTabs,'By Performer'),@($script:GroupsTabs,'By Performer'),@($performerTabs,'Search'))){
 $sectionTabs=$entry[0];$targetText=$entry[1]
 $studio=@($sectionTabs.TabPages | Where-Object {$_.Text -eq 'By Studio'}) | Select-Object -First 1
 $target=@($sectionTabs.TabPages | Where-Object {$_.Text -eq $targetText}) | Select-Object -First 1
 if($studio -and $target){$sectionTabs.TabPages.Remove($studio);$sectionTabs.TabPages.Insert($sectionTabs.TabPages.IndexOf($target),$studio)}
}

