function New-AboutText([string]$Text,[single]$Size=10,[Drawing.FontStyle]$Style=[Drawing.FontStyle]::Regular,$Colour=$null){
 $label=New-Object Windows.Forms.Label
 $label.Text=$Text;$label.Font=New-Object Drawing.Font('Segoe UI',$Size,$Style);$label.UseMnemonic=$false
 $label.ForeColor=if($Colour){$Colour}else{$aboutTextColour};$label.BackColor=[Drawing.Color]::Transparent
 $label.AutoSize=$true
 return $label
}
function Measure-AboutText($Label,[int]$Width){
 $flags=[Windows.Forms.TextFormatFlags]::WordBreak -bor [Windows.Forms.TextFormatFlags]::NoPrefix
 return [Windows.Forms.TextRenderer]::MeasureText($Label.Text,$Label.Font,(New-Object Drawing.Size($Width,100000)),$flags).Height
}
function Set-AboutWrappedText($Label,[int]$Width){$Label.AutoSize=$false;$Label.Width=$Width;$Label.Height=(Measure-AboutText $Label $Width)+4}

