function Update-AboutLayout {
 if($script:AboutLayingOut -or $aboutScroll.ClientSize.Width -le 0){return}
 $script:AboutLayingOut=$true
 $aboutScroll.SuspendLayout();$aboutContent.SuspendLayout()
 try{
  $client=$aboutScroll.ClientSize.Width
  $side=[Math]::Max(24,[int]($client*0.04))
  $width=[Math]::Max(760,$client-($side*2))
  $left=[Math]::Max(16,[int](($client-$width)/2))
  $gap=16
  $centre={param($Control,[int]$Top) $Control.Location=New-Object Drawing.Point(([int]($left+($width-$Control.Width)/2)),$Top)}
  $y=24
  & $centre $aboutLogoBox $y;$y+=$aboutLogoBox.Height+8
  & $centre $aboutName $y;$y+=$aboutName.Height+6
  $leadWidth=[Math]::Min($width,900);Set-AboutWrappedText $aboutLead $leadWidth
  & $centre $aboutLead $y;$y+=$aboutLead.Height+16
  & $centre $aboutBar $y;$y+=$aboutBar.Height+20
  & $centre $aboutActions $y;$y+=$aboutActions.Height+36
  $aboutSectionHeading.Location=New-Object Drawing.Point($left,$y);$y+=$aboutSectionHeading.Height+10

  $columns=if($width -ge 1150){3}else{2}
  $cardWidth=[int][Math]::Floor(($width-$gap*($columns-1))/$columns)
  $rowTop=$y
  for($index=0;$index -lt $script:AboutCards.Count;$index+=$columns){
   $rowCards=@($script:AboutCards[$index..([Math]::Min($index+$columns,$script:AboutCards.Count)-1)])
   $rowHeight=0
   foreach($part in $rowCards){
    $inner=$cardWidth-4-36
    $part.Icon.Location=New-Object Drawing.Point(22,14)
    $part.Name.Location=New-Object Drawing.Point((22+$part.Icon.Width+6),14)
    $titleBottom=14+[Math]::Max($part.Icon.Height,$part.Name.Height)
    Set-AboutWrappedText $part.Body $inner
    $part.Body.Location=New-Object Drawing.Point(22,($titleBottom+8))
    $part.Tags.MaximumSize=New-Object Drawing.Size($inner,0)
    $part.Tags.Location=New-Object Drawing.Point(20,($part.Body.Bottom+10))
    $needed=$part.Tags.Location.Y+$part.Tags.PreferredSize.Height+14
    $rowHeight=[Math]::Max($rowHeight,$needed)
   }
   for($column=0;$column -lt $rowCards.Count;$column++){
    $rowCards[$column].Card.Bounds=New-Object Drawing.Rectangle(($left+$column*($cardWidth+$gap)),$rowTop,$cardWidth,$rowHeight)
   }
   $rowTop+=$rowHeight+$gap
  }
  $y=$rowTop+4
  Set-AboutWrappedText $aboutNote $width
  $aboutNote.Location=New-Object Drawing.Point($left,$y);$y+=$aboutNote.Height+28

  $creditsWidth=[Math]::Max(340,[int]($width*0.3))
  $newsWidth=$width-$creditsWidth-$gap
  $newsHeading.Location=New-Object Drawing.Point(24,18)
  $ny=$newsHeading.Bottom+12
  foreach($item in $script:AboutNews){
   $item.Dot.Location=New-Object Drawing.Point(22,$ny)
   $item.Version.Location=New-Object Drawing.Point(50,$ny)
   Set-AboutWrappedText $item.Text ($newsWidth-74)
   $item.Text.Location=New-Object Drawing.Point(50,($item.Version.Bottom+2))
   $ny=$item.Text.Bottom+12
  }
  $newsHeight=$ny+8
  $creditsVersion.Location=New-Object Drawing.Point(([int](($creditsWidth-$creditsVersion.Width)/2)),18)
  $aboutCredits.MaximumSize=New-Object Drawing.Size(($creditsWidth-24),0)
  $aboutCredits.Location=New-Object Drawing.Point(([int](($creditsWidth-$aboutCredits.Width)/2)),($creditsVersion.Bottom+10))
  $creditsHeight=$aboutCredits.Bottom+20
  $footerHeight=[Math]::Max($newsHeight,$creditsHeight)
  $newsCard.Bounds=New-Object Drawing.Rectangle($left,$y,$newsWidth,$footerHeight)
  $creditsCard.Bounds=New-Object Drawing.Rectangle(($left+$newsWidth+$gap),$y,$creditsWidth,$footerHeight)
  $y+=$footerHeight+32

  $aboutContent.Size=New-Object Drawing.Size([Math]::Max($client,$left+$width+16),$y)
  $aboutContent.Location=New-Object Drawing.Point($aboutScroll.AutoScrollPosition.X,$aboutScroll.AutoScrollPosition.Y)
 }finally{$aboutContent.ResumeLayout();$aboutScroll.ResumeLayout();$script:AboutLayingOut=$false}
}
