function New-ToolkitIcon([string]$Name,[Drawing.Color]$Colour,[int]$Size){
 # Draws a 24x24 Tabler outline icon at any size with smooth round strokes.
 if($Size -lt 8){$Size=8}
 $bitmap=New-Object Drawing.Bitmap($Size,$Size)
 $graphics=[Drawing.Graphics]::FromImage($bitmap)
 $path=New-Object Drawing.Drawing2D.GraphicsPath
 $pen=New-Object Drawing.Pen($Colour,[single](2.0*$Size/24.0))
 try{
  $graphics.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias
  $graphics.PixelOffsetMode=[Drawing.Drawing2D.PixelOffsetMode]::HighQuality
  $pen.StartCap=[Drawing.Drawing2D.LineCap]::Round;$pen.EndCap=[Drawing.Drawing2D.LineCap]::Round;$pen.LineJoin=[Drawing.Drawing2D.LineJoin]::Round
  $k=$Size/24.0;$x=[single]0;$y=[single]0;$startX=[single]0;$startY=[single]0
  foreach($command in ([string]$script:ToolkitIconPaths[$Name]).Split(';')){
   $part=$command.Split(' ')
   switch($part[0]){
    'M' {$path.StartFigure();$x=[single]([double]$part[1]*$k);$y=[single]([double]$part[2]*$k);$startX=$x;$startY=$y}
    'L' {$nx=[single]([double]$part[1]*$k);$ny=[single]([double]$part[2]*$k);$path.AddLine($x,$y,$nx,$ny);$x=$nx;$y=$ny}
    'C' {$nx=[single]([double]$part[5]*$k);$ny=[single]([double]$part[6]*$k);$path.AddBezier($x,$y,[single]([double]$part[1]*$k),[single]([double]$part[2]*$k),[single]([double]$part[3]*$k),[single]([double]$part[4]*$k),$nx,$ny);$x=$nx;$y=$ny}
    'Z' {$path.CloseFigure();$x=$startX;$y=$startY}
   }
  }
  $graphics.DrawPath($pen,$path)
 }finally{$pen.Dispose();$path.Dispose();$graphics.Dispose()}
 return $bitmap
}
function Set-ToolkitIconImage($Control,[string]$Name,[Drawing.Color]$Colour,[int]$Size){
 $old=$Control.Image;$Control.Image=New-ToolkitIcon $Name $Colour $Size;if($old){$old.Dispose()}
}
