# Everything on Home scales with the window (and the display DPI), so the
# layout keeps the same proportions on any screen size.
$script:HomeScale=1.0
$script:HomeDpi=1.0
function Get-HomeDpiFactor {
 # Windows PowerShell 5.1 reports DeviceDpi as 96 even on scaled displays, while
 # text is still drawn at the real scaling. Use whichever figure is higher.
 # Never create window handles here: doing so before the window is shown
 # breaks its layout. The desktop's own scaling is read instead.
 $dpi=96.0
 try{if($tabHome.IsHandleCreated -and $tabHome.DeviceDpi -gt $dpi){$dpi=[double]$tabHome.DeviceDpi}}catch{}
 try{$graphics=[Drawing.Graphics]::FromHwnd([IntPtr]::Zero);try{if($graphics.DpiX -gt $dpi){$dpi=[double]$graphics.DpiX}}finally{$graphics.Dispose()}}catch{}
 return $dpi/96.0
}
$script:HomeDpi=Get-HomeDpiFactor
$script:HomeFonts=New-Object System.Collections.ArrayList
function Register-HomeFont($Control,[string]$Family,[single]$Size,[Drawing.FontStyle]$Style=[Drawing.FontStyle]::Regular){
 [void]$script:HomeFonts.Add(@{Control=$Control;Family=$Family;Size=$Size;Style=$Style})
 $Control.Font=Get-HomeFont $Family $Size $Style
}
# Fonts are cached and reused: creating new ones on every resize, click and
# search used up Windows' drawing resources, which shows as clipped text and
# black boxes.
$script:HomeFontCache=@{}
function Get-HomeFont([string]$Family,[single]$Size,[Drawing.FontStyle]$Style=[Drawing.FontStyle]::Regular){
 $points=[Math]::Round($Size*$script:HomeScale,1)
 $key="$Family|$points|$([int]$Style)"
 if(-not $script:HomeFontCache.ContainsKey($key)){$script:HomeFontCache[$key]=New-Object Drawing.Font($Family,[single]$points,$Style)}
 return $script:HomeFontCache[$key]
}
function Get-HomePx([double]$Value){return [int][Math]::Round($Value*$script:HomeScale*$script:HomeDpi)}

function Find-ToolkitTabPage($TabControl,[string]$Text){
 if($null -eq $TabControl){return $null}
 foreach($page in $TabControl.TabPages){if($page.Text -eq $Text){return $page}}
 return $null
}
function Select-ToolkitGridRow($Grid,[string]$Column,[string]$Id){
 if($null -eq $Grid -or -not $Grid.Columns.Contains($Column)){return}
 $visible=@($Grid.Columns | Where-Object {$_.Visible} | Sort-Object DisplayIndex) | Select-Object -First 1
 foreach($row in $Grid.Rows){
  if([string]$row.Cells[$Column].Value -eq $Id){
   $Grid.ClearSelection()
   if($visible){$Grid.CurrentCell=$row.Cells[$visible.Index]}
   $row.Selected=$true
   try{$Grid.FirstDisplayedScrollingRowIndex=$row.Index}catch{}
   break
  }
 }
}

