function Update-HomeSearchLayout {
 $height=$homeSearchHost.ClientSize.Height;$width=$homeSearchHost.ClientSize.Width
 if($height -le 0 -or $width -le 0){return}
 $homeSearchIcon.Location=New-Object Drawing.Point((Get-HomePx 16),([int](($height-$homeSearchIcon.Height)/2)))
 $homeSearchButton.Location=New-Object Drawing.Point(($width-$homeSearchButton.Width-(Get-HomePx 10)),([int](($height-$homeSearchButton.Height)/2)))
 $homeSearchClear.Location=New-Object Drawing.Point(($homeSearchButton.Left-$homeSearchClear.Width-12),([int](($height-$homeSearchClear.Height)/2)))
 $boxLeft=$homeSearchIcon.Right+8
 $homeSearchBox.Location=New-Object Drawing.Point($boxLeft,([int](($height-$homeSearchBox.Height)/2)))
 $homeSearchBox.Width=[Math]::Max(80,$homeSearchClear.Left-12-$boxLeft)
 $homePlaceholder.Location=New-Object Drawing.Point(($boxLeft-2),([int](($height-$homePlaceholder.Height)/2)))
}
