# Draw the search bar as a smooth white rounded rectangle on the page colour.
try{[Windows.Forms.Control].GetProperty('DoubleBuffered',[Reflection.BindingFlags]'Instance,NonPublic').SetValue($homeSearchHost,$true,$null)}catch{}
$homeSearchHost.Add_Paint({param($sender,$e)
 $width=$sender.ClientSize.Width-1;$height=$sender.ClientSize.Height-1
 if($width -le 0 -or $height -le 0){return}
 $radius=[float][Math]::Min([double](Get-HomePx 14),$height/2.0)
 $path=New-RoundedPath (New-Object Drawing.RectangleF(0,0,$width,$height)) $radius
 $brush=New-Object Drawing.SolidBrush([Drawing.Color]::White)
 try{$e.Graphics.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias;$e.Graphics.FillPath($brush,$path)}
 finally{$brush.Dispose();$path.Dispose()}
})

