 $script:HomeSelectedKey=$Key;$section=$script:HomeSections[$Key]
 $homePreviewStrip.BackColor=$section.Colour;$homePreviewIcon.ForeColor=$section.Colour
 $iconSize=Get-HomePx 48;$homePreviewIcon.Size=New-Object Drawing.Size($iconSize,$iconSize);Set-ToolkitIconImage $homePreviewIcon $section.IconName $section.Colour $iconSize
 $homePreviewTitle.Text=$section.Title;$homePreviewText.Text=$section.Text
 foreach($old in @($homeJumps.Controls)){$old.Dispose()};$homeJumps.Controls.Clear()
 $available=@(foreach($jump in $section.Jumps){if(Find-ToolkitTabPage $section.SubTabs $jump){$jump}})
 foreach($jump in $available){
  $chip=New-Object Windows.Forms.Button;$chip.Text=$jump;$chip.Tag="$Key|$jump"
  $chip.FlatStyle='Flat';$chip.UseVisualStyleBackColor=$false;$chip.BackColor=$homeHoverColour;$chip.ForeColor=[Drawing.Color]::White
  $chip.FlatAppearance.BorderColor=[Drawing.Color]::FromArgb(60,110,140);$chip.FlatAppearance.MouseOverBackColor=$homeSelectedColour
  $chip.Font=Get-HomeFont 'Segoe UI' 11.5;$chip.AutoSize=$true;$chip.AutoSizeMode='GrowAndShrink';$chip.Padding=New-Object Windows.Forms.Padding((Get-HomePx 10),(Get-HomePx 4),(Get-HomePx 10),(Get-HomePx 4));$chip.Margin=New-Object Windows.Forms.Padding(0,0,(Get-HomePx 10),(Get-HomePx 10));$chip.Cursor=[Windows.Forms.Cursors]::Hand
  $chip.Add_Click({param($sender,$e) $parts=([string]$sender.Tag).Split('|');Open-ToolkitSection $parts[0] $parts[1]})
  [void]$homeJumps.Controls.Add($chip)
 }
 $homeJumpHeading.Visible=($available.Count -gt 0);$homeJumps.Visible=($available.Count -gt 0)
 $homeNotice.Visible=-not $script:HomeEnabled
