 $card=New-Object Windows.Forms.Panel;$card.Dock='Fill';$card.BackColor=$homeCardColour;$cardRightMargin=if($cardIndex % 2 -eq 0){(Get-HomePx 12)}else{0};$card.Margin=New-Object Windows.Forms.Padding(0,0,$cardRightMargin,(Get-HomePx 12))
 $top=New-Object Windows.Forms.Panel;$top.Dock='Top';$top.Height=3;$top.BackColor=$section.Colour
 $flow=New-Object Windows.Forms.FlowLayoutPanel;$flow.Dock='Fill';$flow.FlowDirection='TopDown';$flow.WrapContents=$false;$flow.AutoScroll=$true;$flow.BackColor=$homeCardColour;$flow.Padding=New-Object Windows.Forms.Padding(16,12,16,12)
