function Show-HomePreviewMode {$homeResults.Visible=$false;$homePreview.Visible=$true}
function Open-HomeResult($Target){
 try{
  switch($Target.Kind){
   'Scene' {Open-TimelineSceneBrowser $Target.Id}
   'Performer' {
    Open-ToolkitSection 'Performers' 'Search'
    $view=$script:PerformerSearchView;$view.Choice.SelectedIndex=0;$view.Query.Text=$Target.Name
    Invoke-ReplacementPerformerSearch;Select-ToolkitGridRow $view.Grid 'PerformerID' $Target.Id
   }
   'Group' {
    Open-ToolkitSection 'Groups' 'Group Browser'
    $view=$script:BrowserSearchViews['Groups'];$view.Choice.SelectedIndex=0;$view.Query.Text=$Target.Name
    Invoke-ToolkitBrowserAction 'Groups' 'Search';Select-ToolkitGridRow $view.Grid 'GroupID' $Target.Id
   }
   'Studio' {
    Open-ToolkitSection 'Studios' 'Studio Browser'
    $view=$script:SubjectViews['Studios|Studio Browser'];$view.Choice.SelectedIndex=0;$view.Query.Text=$Target.Name
    Invoke-SubjectOperation 'Studios|Studio Browser' 'Run';Select-ToolkitGridRow $view.Grid 'SubjectID' $Target.Id
   }
   'All' {
    switch($Target.Section){
     'Scenes' {Open-ToolkitSection 'Scenes' 'Scene Browser';$view=$script:BrowserSearchViews['Scenes'];$view.Choice.SelectedIndex=1;$view.Query.Text=$Target.Name;Invoke-ToolkitBrowserAction 'Scenes' 'Search'}
     'Performers' {Open-ToolkitSection 'Performers' 'Search';$view=$script:PerformerSearchView;$view.Choice.SelectedIndex=0;$view.Query.Text=$Target.Name;Invoke-ReplacementPerformerSearch}
     'Groups' {Open-ToolkitSection 'Groups' 'Group Browser';$view=$script:BrowserSearchViews['Groups'];$view.Choice.SelectedIndex=1;$view.Query.Text=$Target.Name;Invoke-ToolkitBrowserAction 'Groups' 'Search'}
     'Studios' {Open-ToolkitSection 'Studios' 'Studio Browser';$view=$script:SubjectViews['Studios|Studio Browser'];$view.Choice.SelectedIndex=1;$view.Query.Text=$Target.Name;Invoke-SubjectOperation 'Studios|Studio Browser' 'Run'}
    }
   }
  }
 }catch{[void][ToolkitMessageDialog]::Show($_.Exception.Message,'Home search','OK','Error')}
}
function Add-HomeResultCard([string]$Kind,[object[]]$Items,[string]$Query){
 $flow=$script:HomeResultCards[$Kind];$section=$script:HomeSections[$Kind]
 $flow.SuspendLayout()
 foreach($old in @($flow.Controls)){foreach($picture in @($old.Controls | Where-Object {$_ -is [Windows.Forms.PictureBox]})){if($picture.Image){$picture.Image.Dispose()}};$old.Dispose()};$flow.Controls.Clear()
 $rowWidth=[Math]::Max(160,$flow.ClientSize.Width-$flow.Padding.Horizontal-4)
 $header=New-Object Windows.Forms.FlowLayoutPanel;$header.AutoSize=$true;$header.WrapContents=$false;$header.BackColor=$homeCardColour;$header.Margin=New-Object Windows.Forms.Padding(0,0,0,(Get-HomePx 8))
 $headerIconSize=Get-HomePx 24
 $headerIcon=New-Object Windows.Forms.PictureBox;$headerIcon.Size=New-Object Drawing.Size($headerIconSize,$headerIconSize);$headerIcon.Image=New-ToolkitIcon $section.IconName $section.Colour $headerIconSize;$headerIcon.Margin=New-Object Windows.Forms.Padding(0,(Get-HomePx 3),(Get-HomePx 10),0)
 $headerText=New-Object Windows.Forms.Label;$headerText.Text="$($section.Title)  ($($Items.Count))";$headerText.Font=Get-HomeFont 'Segoe UI' 13.5 ([Drawing.FontStyle]::Bold);$headerText.ForeColor=[Drawing.Color]::White;$headerText.AutoSize=$true;$headerText.BackColor=$homeCardColour;$headerText.Margin=New-Object Windows.Forms.Padding(0)
 [void]$header.Controls.AddRange(@($headerIcon,$headerText))
 [void]$flow.Controls.Add($header)
 if(-not $Items.Count){$none=New-Object Windows.Forms.Label;$none.Text='No matches';$none.Font=Get-HomeFont 'Segoe UI' 11.5 ([Drawing.FontStyle]::Italic);$none.ForeColor=$homeTextColour;$none.AutoSize=$true;$none.BackColor=$homeCardColour;[void]$flow.Controls.Add($none)}
 foreach($match in @($Items | Select-Object -First 6)){
  $row=New-Object Windows.Forms.Panel;$row.Size=New-Object Drawing.Size($rowWidth,(Get-HomePx 36));$row.Margin=New-Object Windows.Forms.Padding(0,0,0,2);$row.BackColor=$homeCardColour
  $name=New-Object Windows.Forms.Label;$name.Text=$match.Name;$name.Dock='Fill';$name.TextAlign='MiddleLeft';$name.AutoEllipsis=$true;$name.UseMnemonic=$false;$name.Font=Get-HomeFont 'Segoe UI' 12;$name.ForeColor=$homeAccent;$name.Cursor=[Windows.Forms.Cursors]::Hand;$name.Tag=$match;$name.BackColor=$homeCardColour
  $detail=New-Object Windows.Forms.Label;$detail.Text=$match.Detail;$detail.Dock='Right';$detail.AutoSize=$true;$detail.Padding=New-Object Windows.Forms.Padding((Get-HomePx 8),(Get-HomePx 9),0,0);$detail.Font=Get-HomeFont 'Segoe UI' 10;$detail.ForeColor=$homeTextColour;$detail.BackColor=$homeCardColour
  $name.Add_Click({param($sender,$e) Open-HomeResult $sender.Tag})
  $name.Add_MouseEnter({param($sender,$e) $sender.ForeColor=[Drawing.Color]::White})
  $name.Add_MouseLeave({param($sender,$e) $sender.ForeColor=$homeAccent})
  [void]$row.Controls.Add($name);[void]$row.Controls.Add($detail)
  [void]$flow.Controls.Add($row)
 }
 if($Items.Count -gt 6){
  $all=New-Object Windows.Forms.Label;$all.Text="Show all $($Items.Count) in $($section.Title)  →";$all.Font=Get-HomeFont 'Segoe UI' 11.5 ([Drawing.FontStyle]::Bold);$all.ForeColor=$homeAccent;$all.AutoSize=$true;$all.BackColor=$homeCardColour;$all.Cursor=[Windows.Forms.Cursors]::Hand;$all.Margin=New-Object Windows.Forms.Padding(0,8,0,0)
  $all.Tag=[pscustomobject]@{Kind='All';Section=$Kind;Name=$Query}
  $all.Add_Click({param($sender,$e) Open-HomeResult $sender.Tag})
  [void]$flow.Controls.Add($all)
 }
 $flow.ResumeLayout()
}
function Invoke-HomeSearch {
 $homeSearchTimer.Stop()
 $query=$homeSearchBox.Text.Trim()
 if(-not $script:HomeEnabled -or $query.Length -lt 2){Show-HomePreviewMode;return}
 $compare=[StringComparison]::OrdinalIgnoreCase
 $scenes=New-Object Collections.ArrayList
 foreach($scene in @($script:SceneCache)){
  $title=Get-SceneTitle $scene
  if($title.IndexOf($query,$compare) -ge 0){[void]$scenes.Add([pscustomobject]@{Kind='Scene';Id=[string]$scene.id;Name=$title;Detail=$(if($scene.date){([string]$scene.date).Substring(0,[Math]::Min(4,([string]$scene.date).Length))}else{''})})}
 }
 $performers=New-Object Collections.ArrayList
 foreach($performer in @($script:AllPerformers)){
  $name=[string]$performer.name
  if($name.IndexOf($query,$compare) -ge 0){[void]$performers.Add([pscustomobject]@{Kind='Performer';Id=[string]$performer.id;Name=$name;Detail="$([int]$performer.scene_count) scenes"});continue}
  $alias=@($performer.alias_list | Where-Object {([string]$_).IndexOf($query,$compare) -ge 0}) | Select-Object -First 1
  if($alias){[void]$performers.Add([pscustomobject]@{Kind='Performer';Id=[string]$performer.id;Name=$name;Detail="alias: $alias"})}
 }
 $groups=New-Object Collections.ArrayList
 foreach($group in @($script:GroupCache)){
  $name=[string]$group.name
  if($name.IndexOf($query,$compare) -ge 0 -or ([string]$group.aliases).IndexOf($query,$compare) -ge 0){[void]$groups.Add([pscustomobject]@{Kind='Group';Id=[string]$group.id;Name=$name;Detail="$([int]$group.scene_count) scenes"})}
 }
 $studios=New-Object Collections.ArrayList
 foreach($studio in @($script:StudioCache)){
  $name=[string]$studio.name
  if($name.IndexOf($query,$compare) -ge 0){[void]$studios.Add([pscustomobject]@{Kind='Studio';Id=[string]$studio.id;Name=$name;Detail="$([int]$studio.scene_count) scenes"})}
 }
 $homeResults.SuspendLayout()
 Add-HomeResultCard 'Scenes' @($scenes | Sort-Object Name) $query
 Add-HomeResultCard 'Performers' @($performers | Sort-Object Name) $query
 Add-HomeResultCard 'Groups' @($groups | Sort-Object Name) $query
 Add-HomeResultCard 'Studios' @($studios | Sort-Object Name) $query
 $total=$scenes.Count+$performers.Count+$groups.Count+$studios.Count
 $homeResultsSummary.Text=if($total){"$total matches across your library for '$query'. Click a name to open it."}else{"No matches for '$query'. Try a shorter word or part of a name."}
 $homeResults.ResumeLayout()
 $homePreview.Visible=$false;$homeResults.Visible=$true
}
$homeSearchTimer=New-Object Windows.Forms.Timer;$homeSearchTimer.Interval=300
$homeSearchTimer.Add_Tick({Invoke-HomeSearch})
$homeSearchBox.Add_TextChanged({
 $hasText=$homeSearchBox.Text.Length -gt 0
 $homePlaceholder.Visible=-not $hasText;$homeSearchClear.Visible=$hasText
 if(-not $hasText){$homeSearchTimer.Stop();Show-HomePreviewMode}else{$homeSearchTimer.Stop();$homeSearchTimer.Start()}
})
$homeSearchBox.Add_KeyDown({param($sender,$e)
 if($e.KeyCode -eq 'Enter'){$e.SuppressKeyPress=$true;Invoke-HomeSearch}
 elseif($e.KeyCode -eq 'Escape'){$e.SuppressKeyPress=$true;$homeSearchBox.Clear()}
})
$homeSearchBox.Add_KeyPress({param($sender,$e) if(-not $script:HomeEnabled){$e.Handled=$true}})
$homePlaceholder.Add_Click({$homeSearchBox.Focus()})
$homeSearchClear.Add_Click({$homeSearchBox.Clear();$homeSearchBox.Focus()})
$homeSearchButton.Add_Click({Invoke-HomeSearch})
# The Search button keeps square corners; clipping it to a rounded region could hide it.
$form.Add_FormClosed({$homeSearchTimer.Dispose()})

