# Locks or unlocks Home with the connection (called by Connect, Disconnect and Stop).
function Set-HomeNavigationEnabled {
 param([bool]$Enabled)
 $script:HomeEnabled=$Enabled
 $homeSearchBox.ReadOnly=-not $Enabled;$homeSearchBox.BackColor=[Drawing.Color]::White
 $homePlaceholder.Text=if($Enabled){'Search scenes, performers, groups and studios'}else{'Connect to Stash to search your library'}
 if(-not $Enabled -and $homeSearchBox.Text){$homeSearchBox.Clear()}
 Update-HomeSearchLayout
 Show-HomePreviewMode
 Show-HomePreview $script:HomeSelectedKey
}
Set-HomeNavigationEnabled $script:IsConnected
function Update-HomeLayout {
 if($script:HomeLayingOut){return}
 $width=$tabHome.ClientSize.Width;$height=$tabHome.ClientSize.Height
 if($width -le 0 -or $height -le 0){return}
 # Use the scaling of the screen Home is on now (it changes when the window
 # moves to another monitor or Windows display scaling is changed).
 $currentDpi=Get-HomeDpiFactor
 if([Math]::Abs($currentDpi-$script:HomeDpi) -gt 0.01){$script:HomeDpi=$currentDpi;$script:HomeScaled=$false}
 $script:HomeLayingOut=$true
 $tabHome.SuspendLayout()
 try{
  $scale=[Math]::Round([Math]::Max(1.0,[Math]::Min(1.55,[Math]::Min($width/(1300.0*$script:HomeDpi),$height/(720.0*$script:HomeDpi)))),2)
  if([Math]::Abs($scale-$script:HomeScale) -ge 0.04 -or -not $script:HomeScaled){
   $script:HomeScale=$scale;$script:HomeScaled=$true
   foreach($entry in $script:HomeFonts){$entry.Control.Font=Get-HomeFont $entry.Family $entry.Size $entry.Style}
   $homeRoot.Padding=New-Object Windows.Forms.Padding((Get-HomePx 18))
   $homeRoot.ColumnStyles[0].Width=Get-HomePx 270
   $homeSidebar.Padding=New-Object Windows.Forms.Padding((Get-HomePx 10),(Get-HomePx 12),(Get-HomePx 10),(Get-HomePx 12))
   $homeSidebar.Margin=New-Object Windows.Forms.Padding(0,0,(Get-HomePx 18),0)
   $homeBrand.Height=Get-HomePx 62
   $homeBrandLogo.Bounds=New-Object Drawing.Rectangle((Get-HomePx 8),(Get-HomePx 12),(Get-HomePx 40),(Get-HomePx 38))
   foreach($heading in $script:HomeNavHeadings){$heading.Margin=New-Object Windows.Forms.Padding((Get-HomePx 10),(Get-HomePx 16),0,(Get-HomePx 6))}
   foreach($nav in $script:HomeNavItems.Values){$nav.Item.Height=Get-HomePx 46;$nav.Icon.Width=Get-HomePx 50;Set-ToolkitIconImage $nav.Icon $nav.IconName $nav.Colour (Get-HomePx 22)}
   Set-ToolkitIconImage $homeBrandLogo 'box' $homeAccent (Get-HomePx 34)
   $searchIconSize=Get-HomePx 22
   $homeSearchIcon.Size=New-Object Drawing.Size($searchIconSize,$searchIconSize);Set-ToolkitIconImage $homeSearchIcon 'search' ([Drawing.Color]::FromArgb(95,94,90)) $searchIconSize
   $homeSearchClear.Size=New-Object Drawing.Size($searchIconSize,$searchIconSize);Set-ToolkitIconImage $homeSearchClear 'x' ([Drawing.Color]::FromArgb(95,94,90)) $searchIconSize
   $homeMain.RowStyles[0].Height=Get-HomePx 66
   $homeSearchHost.Margin=New-Object Windows.Forms.Padding(0,0,0,(Get-HomePx 16))
   $homeSearchButton.MinimumSize=New-Object Drawing.Size((Get-HomePx 120),(Get-HomePx 38))
   $homePreviewStrip.Width=Get-HomePx 5
   $homePreviewFlow.Padding=New-Object Windows.Forms.Padding((Get-HomePx 40),(Get-HomePx 34),(Get-HomePx 40),(Get-HomePx 34))
   $homePreviewTitle.Margin=New-Object Windows.Forms.Padding(0,(Get-HomePx 4),0,(Get-HomePx 10))
   $homeJumpHeading.Margin=New-Object Windows.Forms.Padding(0,(Get-HomePx 30),0,(Get-HomePx 12))
   $homeNotice.Margin=New-Object Windows.Forms.Padding(0,(Get-HomePx 24),0,0)
   $homeResults.RowStyles[0].Height=Get-HomePx 40
   Show-HomePreview $script:HomeSelectedKey
   if($homeResults.Visible){Invoke-HomeSearch}
   $script:HomeNeedsRepaint=$true
  }
  $navWidth=[Math]::Max(120,$homeSidebar.ClientSize.Width-$homeSidebar.Padding.Horizontal-2)
  $homeBrand.Width=$navWidth;$homeBrandName.Location=New-Object Drawing.Point(($homeBrandLogo.Right+(Get-HomePx 8)),[int](($homeBrand.Height-$homeBrandName.Height)/2))
  foreach($nav in $script:HomeNavItems.Values){$nav.Item.Width=$navWidth}
  Update-HomeSearchLayout
  Update-HomePreviewWidths
 }catch{
  $script:HomeScaled=$false
  try{
   $logFolder=Join-Path $script:ToolkitDataFolder 'Logs';[void][IO.Directory]::CreateDirectory($logFolder)
   [IO.File]::AppendAllText((Join-Path $logFolder 'Home-Layout.log'),("[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] PowerShell $($PSVersionTable.PSVersion) | tab $($tabHome.ClientSize.Width)x$($tabHome.ClientSize.Height) | scale $script:HomeScale | dpi $script:HomeDpi`r`n$($_.Exception.Message)`r`n$($_.ScriptStackTrace)`r`n`r`n"))
  }catch{}
 }finally{
  $tabHome.ResumeLayout($true);$script:HomeLayingOut=$false
  if($script:HomeNeedsRepaint){$script:HomeNeedsRepaint=$false;$homeRoot.PerformLayout();$tabHome.Invalidate($true);$tabHome.Update()}
 }
}
$tabHome.Add_Resize({Update-HomeLayout})
$form.Add_DpiChanged({
 $script:HomeScaled=$false
 try{[void]$form.BeginInvoke([Action]{Update-HomeLayout;if($aboutScroll){Update-AboutLayout}})}catch{Update-HomeLayout}
})
$homeSidebar.Add_Resize({Update-HomeLayout})
$tabs.Add_SelectedIndexChanged({if($tabs.SelectedTab -eq $tabHome){Update-HomeLayout}})
$tabs.Add_SelectedIndexChanged({if($tabs.SelectedTab -eq $tabHome -and $script:HomeEnabled -and -not $homeSearchBox.Text){$homeSearchBox.Focus()}})
$form.Add_Shown({$script:HomeScaled=$false;$script:HomeDpi=Get-HomeDpiFactor;$homeRoot.PerformLayout();Update-HomeLayout;$tabHome.Invalidate($true)})
# --- End Home ---

