 $script:ToolkitSettings.StashUrl=$txtUrl.Text.Trim()
 if($exportFolder.Text.Trim()){$script:ToolkitSettings.PerformerExportFolder=$exportFolder.Text.Trim()}
 if($exportStudioFolder.Text.Trim()){$script:ToolkitSettings.StudioExportFolder=$exportStudioFolder.Text.Trim()}
 if($finderRoots.Text.Trim()){$script:ToolkitSettings.FinderRoots=$finderRoots.Text.Trim()}
 if($script:LibraryChecklistUtility.Folders.Text.Trim()){$script:ToolkitSettings.LibraryChecklistFolders=$script:LibraryChecklistUtility.Folders.Text.Trim()}
 if($script:LibraryChecklistUtility.CoversFolder.Text.Trim()){$script:ToolkitSettings.MovieCoversFolder=$script:LibraryChecklistUtility.CoversFolder.Text.Trim()}
 Save-ToolkitSettings
})

[void]$form.ShowDialog()











































